INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24572750-df7d-4576-bdfe-928bf9dac33c', '送方城韋明府', '送方城韋明府', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["遙思葭菼際，寥落楚人行。","高鳥長淮水，平蕪故郢城。","使車聽雉乳，縣鼓應雞鳴。","若見州從事，無嫌手板迎。"]', '["遙思葭菼際，寥落楚人行。","高鸟长淮水，平蕪故郢城。","使车听雉乳，縣鼓應雞鳴。","若见州從事，無嫌手板迎。"]', '诗', 'shi', '', NULL, '送方城韋明府 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9350d236-229a-4651-b41d-bfbd6c032ab6', '送李員外賢郎', '送李員外賢郎', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["少年何處去，負米上銅梁。","借問阿戎父，知爲童子郎。","魚牋請詩賦，橦布作衣裳。","薏苡扶衰病，歸來幸可將。"]', '["少年何处去，負米上銅梁。","借问阿戎父，知爲童子郎。","鱼牋請诗賦，橦布作衣裳。","薏苡扶衰病，归来幸可將。"]', '诗', 'shi', '', NULL, '送李員外賢郎 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('263b4a33-fd51-47e1-b49a-d84dd99a2e0f', '送梓州李使君', '送梓州李使君', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["萬壑樹參天，千山響杜鵑。","山中一夜雨，樹杪百重泉。","漢女輸橦布，巴人訟芋田。","文翁翻教授，不敢倚先賢。"]', '["万壑樹參天，千山响杜鵑。","山中一夜雨，樹杪百重泉。","漢女輸橦布，巴人訟芋田。","文翁翻教授，不敢倚先賢。"]', '诗', 'shi', '', NULL, '送梓州李使君 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('421ddc1d-95a0-40a6-97c2-014d3d97c210', '送張五諲歸宣城', '送張五諲归宣城', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["五湖千萬里，況復五湖西。","漁浦南陵郭，人家春穀谿。","欲歸江淼淼，未到草萋萋。","憶想蘭陵鎮，可宜猿更啼。"]', '["五湖千万里，況复五湖西。","漁浦南陵郭，人家春穀谿。","欲归江淼淼，未到草萋萋。","憶想蘭陵鎮，可宜猿更啼。"]', '诗', 'shi', '', NULL, '送張五諲歸宣城 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('694bd102-5a6f-47a2-97d1-27fabf6b1399', '送友人南歸', '送友人南归', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["萬里春應盡，三江雁亦稀。","連天漢水廣，孤客郢城歸。","鄖國稻苗秀，楚人菰米肥。","懸知倚門望，遙識老萊衣。"]', '["万里春應尽，三江雁亦稀。","連天漢水廣，孤客郢城归。","鄖国稻苗秀，楚人菰米肥。","懸知倚门望，遙識老萊衣。"]', '诗', 'shi', '', NULL, '送友人南歸 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73fa0e49-e214-4a99-9c59-d020beb7e18e', '送賀遂員外外甥', '送賀遂員外外甥', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["南國有歸舟，荆門泝上流。","蒼茫葭菼外，雲水與昭丘。","檣帶城烏去，江連暮雨愁。","猿聲不可聽，莫待楚山秋。"]', '["南国有归舟，荆门泝上流。","蒼茫葭菼外，云水與昭丘。","檣带城烏去，江連暮雨愁。","猿声不可听，莫待楚山秋。"]', '诗', 'shi', '', NULL, '送賀遂員外外甥 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4787f534-eb1a-4c3b-a785-6e36eadf9f45', '送楊長史赴果州', '送楊长史赴果州', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["襃斜不容幰，之子去何之。","鳥道一千里，猿聲十二時。","官橋祭酒客，山木女郎祠。","別後同明月，君應聽子規。"]', '["襃斜不容幰，之子去何之。","鸟道一千里，猿声十二时。","官橋祭酒客，山木女郎祠。","別後同明月，君應听子規。"]', '诗', 'shi', '', NULL, '送楊長史赴果州 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21a94a4d-4363-406a-8455-45434aa80f7c', '送邢桂州', '送邢桂州', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["鐃吹喧京口，風波下洞庭。","赭圻將赤岸，擊汰復揚舲。","日落江湖白，潮來天地青。","明珠歸合浦，應逐使臣星。"]', '["鐃吹喧京口，风波下洞庭。","赭圻將赤岸，擊汰复揚舲。","日落江湖白，潮来天地青。","明珠归合浦，應逐使臣星。"]', '诗', 'shi', '', NULL, '送邢桂州 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0673da1-9ab0-4ca7-a262-3bdcd45c6f32', '送宇文三赴河西充行軍司馬', '送宇文三赴河西充行軍司马', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["橫吹雜繁笳，邊風捲塞沙。","還聞田司馬，更逐李輕車。","蒲類成秦地，莎車屬漢家。","當令犬戎國，朝聘學昆邪。"]', '["橫吹杂繁笳，邊风捲塞沙。","還闻田司马，更逐李轻车。","蒲類成秦地，莎车屬漢家。","當令犬戎国，朝聘学昆邪。"]', '诗', 'shi', '', NULL, '送宇文三赴河西充行軍司馬 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5a33e9a-00ff-486e-b4e4-d52eba32f9f9', '送孫二', '送孫二', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["郊外誰相送，夫君道術親。","書生鄒魯客，才子洛陽人。","祖席依寒草，行車起暮塵。","山川何寂寞，長望淚沾巾。"]', '["郊外誰相送，夫君道術親。","书生鄒魯客，才子洛陽人。","祖席依寒草，行车起暮塵。","山川何寂寞，长望泪沾巾。"]', '诗', 'shi', '', NULL, '送孫二 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('840dc45d-0273-411b-b52d-4e9568469537', '送崔三往密州覲省', '送崔三往密州覲省', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["南陌去悠悠，東郊不少留。","同懷扇枕戀，獨念倚門愁。","路遶天山雪，家臨海樹秋。","魯連功未報，且莫蹈滄洲。"]', '["南陌去悠悠，东郊不少留。","同懷扇枕戀，独念倚门愁。","路遶天山雪，家臨海樹秋。","魯連功未報，且莫蹈滄洲。"]', '诗', 'shi', '', NULL, '送崔三往密州覲省 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31555526-5589-474b-b33a-fcfb3381111c', '送孟六歸襄陽', '送孟六归襄陽', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["杜門不復出，久與世情疎。","以此爲良策，勸君歸舊廬。","醉歌田舍酒，笑讀古人書。","好是一生事，無勞獻子虛。"]', '["杜门不复出，久與世情疎。","以此爲良策，勸君归旧廬。","醉歌田舍酒，笑读古人书。","好是一生事，無勞獻子虛。"]', '诗', 'shi', '', NULL, '送孟六歸襄陽 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4766aeff-eb87-4444-9a72-e55d7e835f3e', '初出濟州別城中故人', '初出濟州別城中故人', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["微官易得罪，謫去濟川陰。","執政方持法，明君照此心。","閭閻河潤上，井邑海雲深。","縱有歸來日，各愁年鬢侵。"]', '["微官易得罪，謫去濟川陰。","執政方持法，明君照此心。","閭閻河潤上，井邑海云深。","縱有归来日，各愁年鬢侵。"]', '诗', 'shi', '', NULL, '初出濟州別城中故人 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a527e41-ccaf-442c-98ea-99ab9b11a3bf', '與盧象集朱家', '與盧象集朱家', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["主人能愛客，終日有逢迎。","貰得新豐酒，復聞秦女箏。","柳條疎客舍，槐葉下秋城。","語笑且爲樂，吾將達此生。"]', '["主人能愛客，終日有逢迎。","貰得新豐酒，复闻秦女箏。","柳條疎客舍，槐葉下秋城。","語笑且爲乐，吾將達此生。"]', '诗', 'shi', '', NULL, '與盧象集朱家 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('557a9515-893f-47a8-bb20-a386c086ae16', '登裴秀才迪小臺', '登裴秀才迪小台', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["端居不出戶，滿目望雲山。","落日鳥邊下，秋原人外閑。","遙知遠林際，不見此簷間。","好客多乘月，應門莫上關。"]', '["端居不出戶，满目望云山。","落日鸟邊下，秋原人外闲。","遙知远林際，不见此簷间。","好客多乘月，應门莫上关。"]', '诗', 'shi', '', NULL, '登裴秀才迪小臺 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bc50082-4b70-443f-8c86-2026f52fbbfd', '遊李山人所居因題屋壁', '游李山人所居因題屋壁', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["世上皆如夢，狂來止自歌。","問年松樹老，有地竹林多。","藥倩韓康賣，門容尚子過。","翻嫌枕席上，無那白雲何。"]', '["世上皆如梦，狂来止自歌。","问年松樹老，有地竹林多。","藥倩韓康賣，门容尚子過。","翻嫌枕席上，無那白云何。"]', '诗', 'shi', '', NULL, '遊李山人所居因題屋壁 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f78c57ff-c6a6-4a18-9412-3024660d7cd0', '看花', '看花', '69b62f4f-75d4-45b0-9f94-d46b992151d7', '唐', '["莫怪出門先驟馬，暮年常怨看花遲。","可憐盡日春山下，似雪如雲一萬枝。"]', '["莫怪出门先驟马，暮年常怨看花遲。","可怜尽日春山下，似雪如云一万枝。"]', '诗', 'shi', '', NULL, '看花 何元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbe1dc97-2607-4a70-a751-9e3ad31210e9', '句', '句', '69b62f4f-75d4-45b0-9f94-d46b992151d7', '唐', '["一望白雲千萬斷，箏聲日暮出花林。","門外夕陽寒映竹，洞中秋水暗連山。","鐘聲半夜香山雨，散入前林楓葉秋。","寺臨飛鳥青山遠，徑轉幽蘿白日長。","黃昏人到鐘聲裏，雲起龍池不見山。","客來惆悵僧禪後，月出松門滿地霜。","朔風寒日笳聲急，萬里遼城一段雲。","滿山月色連溪下，林葉蕭蕭一夜霜。","秦客訪花驚出洞，庾公看月誤登樓。"]', '["一望白云千万斷，箏声日暮出花林。","门外夕陽寒映竹，洞中秋水暗連山。","鐘声半夜香山雨，散入前林楓葉秋。","寺臨飞鸟青山远，徑轉幽蘿白日长。","黄昏人到鐘声裏，云起龙池不见山。","客来惆悵僧禪後，月出松门满地霜。","朔风寒日笳声急，万里遼城一段云。","满山月色連溪下，林葉蕭蕭一夜霜。","秦客訪花驚出洞，庾公看月誤登楼。"]', '诗', 'shi', '', NULL, '句 何元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('740c1743-61f4-4694-908b-6737af54523d', '春夜宿雲際寺', '春夜宿云際寺', '4db60f8b-4a9a-4518-ac73-d818914b6baa', '唐', '["境靜聞鐘聲易響，庭高見月影難沈。","青山解隔塵中事，流水能清物外心。"]', '["境静闻鐘声易响，庭高见月影难沈。","青山解隔塵中事，流水能清物外心。"]', '诗', 'shi', '', NULL, '春夜宿雲際寺 斐公衍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32f67de2-74f6-4cd6-810f-9a587913d4af', '句', '句', '4db60f8b-4a9a-4518-ac73-d818914b6baa', '唐', '["碧澗水流高殿影，青蘿風散晚鐘聲。","數片殘雲歸洞口，孤輪晴月挂山頭。"]', '["碧澗水流高殿影，青蘿风散晚鐘声。","數片殘云归洞口，孤輪晴月挂山头。"]', '诗', 'shi', '', NULL, '句 斐公衍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ba636ab-c4b0-4a0f-83ed-dd7a5b4c37cc', '聽琴', '听琴', '0f85dd17-e51a-4239-a7a0-ce2d265cbe89', '唐', '["絃中恨起湘山遠，指下情多楚峽流。","危檻曲終雲影曙，高樓風定燭光秋。"]', '["絃中恨起湘山远，指下情多楚峽流。","危檻曲終云影曙，高楼风定燭光秋。"]', '诗', 'shi', '', NULL, '聽琴 蘇替 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53dc188c-b67b-4e38-a59d-667eca3b351a', '賞春', '賞春', 'bfd3a3bb-87f4-49fa-90e2-b98b6328d4b9', '唐', '["暖日當頭催展菜，和風次第遣開花。","呼童遠取溪心水，待客來煎柳眼茶。"]', '["暖日當头催展菜，和风次第遣开花。","呼童远取溪心水，待客来煎柳眼茶。"]', '诗', 'shi', '', NULL, '賞春 路半千 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('513f5985-8d0d-46fe-9552-1f87ce640a04', '句', '句', 'bfd3a3bb-87f4-49fa-90e2-b98b6328d4b9', '唐', '["蒼翠暗消三暑熱，孤高能鎖四時煙。","綠楊近浦堪垂釣，翠竹當軒好韻琴。","百舌乍啼鶯學語，分明聽在指頭邊。"]', '["蒼翠暗消三暑熱，孤高能鎖四时煙。","綠楊近浦堪垂釣，翠竹當軒好韻琴。","百舌乍啼鶯学語，分明听在指头邊。"]', '诗', 'shi', '', NULL, '句 路半千 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3a5be94-820f-45d8-97f3-206d21ea3023', '句', '句', '8c9bcadb-a667-4969-8e1b-08d12d879280', '唐', '["玉貌自宜雙黛翠，桃花獨笑一枝春。","秋水未鳴遊女佩，寒雲空滿望夫山。","黃閣暮蟲羅戶牗，紫庭春草遍階墀。","綠耳半蔓湘浦竹，驪文亂點武陵花。","遼陽客路千峰引，薊北鄉心片月知。","山雲渺渺川程遠，木葉蕭蕭鴈過初。","回鴈不傳鄉信去，秋風偏向客衣寒。","千峰黛色因晴出，百谷泉聲欲暮寒。","黛色迥臨滄海上，泉聲遙落白雲中。","喜遇近臣楊得意，慙非詞客馬相如。","秋迎曉月鴻聲早，日暎深山水氣寒。"]', '["玉貌自宜雙黛翠，桃花独笑一枝春。","秋水未鳴游女佩，寒云空满望夫山。","黄閣暮蟲羅戶牗，紫庭春草遍階墀。","綠耳半蔓湘浦竹，驪文亂点武陵花。","遼陽客路千峰引，薊北乡心片月知。","山云渺渺川程远，木葉蕭蕭鴈過初。","回鴈不傳乡信去，秋风偏向客衣寒。","千峰黛色因晴出，百谷泉声欲暮寒。","黛色迥臨滄海上，泉声遙落白云中。","喜遇近臣楊得意，慙非词客马相如。","秋迎晓月鴻声早，日暎深山水氣寒。"]', '诗', 'shi', '', NULL, '句 賀蘭暹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('618d535c-598c-409a-a42d-55c3f23f3b50', '句', '句', '2ce41c5d-2e86-4585-9ccf-ea5409f13d46', '唐', '["霜墜中天衣覺冷，月臨虛牗紙偏明。","春風暗翦庭前樹，夜雨偷穿石上苔。","曲水兩行排鴈齒，斜橋一道蹈龍鱗。","山深野客如禪客，夜久松聲似雨聲。","花疑漢女啼妝淚，水似吳娃笑弄箏。"]', '["霜墜中天衣覺冷，月臨虛牗紙偏明。","春风暗翦庭前樹，夜雨偷穿石上苔。","曲水兩行排鴈齒，斜橋一道蹈龙鱗。","山深野客如禪客，夜久松声似雨声。","花疑漢女啼妝泪，水似吳娃笑弄箏。"]', '诗', 'shi', '', NULL, '句 傅溫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee1ab06d-b324-4c5b-b753-7c456868315e', '句', '句', '094555f1-152d-4e7d-8fc7-97b9124b16b5', '唐', '["花映晝天當戶日，樹搖晴暮上階煙。","驚飛沙鳥紛紛雪，候信雲帆片片風。","鳳唱一拋琴瑟韻，霓裳長謝綺羅春。","秋澄上水無藏影，春泛遊雲不繫心。","老松不見千年鶴，殘雪猶疑六月花。"]', '["花映晝天當戶日，樹搖晴暮上階煙。","驚飞沙鸟紛紛雪，候信云帆片片风。","鳳唱一拋琴瑟韻，霓裳长謝綺羅春。","秋澄上水無藏影，春泛游云不繫心。","老松不见千年鹤，殘雪猶疑六月花。"]', '诗', 'shi', '', NULL, '句 曹戵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e3918d8-62ce-464b-a6c6-7995e6bdc915', '句', '句', '2879218b-9339-4795-ab63-7ffd65bcfc14', '唐', '["三行故柳藏鴉樹，一帶長波灌竹泉。","千門竹影聯春色，一段和光徹翠微。","西陵古木年年老，南陌風光日日新。","百寶鏡輪金翡翠，五雲絲網玉蜘蛛。"]', '["三行故柳藏鴉樹，一带长波灌竹泉。","千门竹影聯春色，一段和光徹翠微。","西陵古木年年老，南陌风光日日新。","百寶镜輪金翡翠，五云絲網玉蜘蛛。"]', '诗', 'shi', '', NULL, '句 陳素風 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1a1ff68-af19-46ca-bf34-3e0f3e7594db', '句', '句', 'd006c141-ca7a-4cbc-918c-6d9322c5ea93', '唐', '["窗竹閑陰秋水薄，砌苔新色曉嵐鮮。","不待江□移入座，便開三峽水來聲。","芳字八行清露重，珠牋一片碧雲輕。"]', '["窗竹闲陰秋水薄，砌苔新色晓嵐鲜。","不待江□移入座，便开三峽水来声。","芳字八行清露重，珠牋一片碧云轻。"]', '诗', 'shi', '', NULL, '句 唐樞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('879a4911-0d8f-4798-8a56-d227e785b075', '句', '句', '6dfc1807-7831-4add-9154-0ce65b3c4afd', '唐', '["三春種樹梅兼李，十月看書雪替螢。","原公舊路唯三徑，潘岳新年已二毛。","山底採薇雲不厭，洞中栽樹鶴先知。"]', '["三春種樹梅兼李，十月看书雪替螢。","原公旧路唯三徑，潘岳新年已二毛。","山底採薇云不厭，洞中栽樹鹤先知。"]', '诗', 'shi', '', NULL, '句 溫達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8093a0b-6fe1-4dbe-8b64-4d0db3b7fa56', '句', '句', '65b5e230-6621-4bda-8a09-bba6fb3785f8', '唐', '["三徑雨來煙草合，一邱琴後濁醪傾。","共話世情塵藹藹，每嗟人事水潺潺。"]', '["三徑雨来煙草合，一邱琴後濁醪傾。","共話世情塵藹藹，每嗟人事水潺潺。"]', '诗', 'shi', '', NULL, '句 盧條 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b26c70e3-c04c-4f45-9ef7-fcf673f42b07', '句', '句', '33804cd9-7ca6-4e30-a5b2-c06a7aac435d', '唐', '["紫籜粉成應漸密，白雲岑起未全高。","慙愧交親問生事，一溪雲鳥滿牀書。"]', '["紫籜粉成應漸密，白云岑起未全高。","慙愧交親问生事，一溪云鸟满牀书。"]', '诗', 'shi', '', NULL, '句 崔行檢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e80064b6-d3e5-4d20-abe7-60c9275d929f', '句', '句', 'dacd4fa1-b6f0-484d-b4a0-26a053148d76', '唐', '["門前蕭索青松老，雲裏逍遙白鶴閑。","波瀾晴泛三春色，桃李爭開兩岸芳。"]', '["门前蕭索青松老，云裏逍遙白鹤闲。","波瀾晴泛三春色，桃李爭开兩岸芳。"]', '诗', 'shi', '', NULL, '句 陳上卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8ffeb82-5d61-4c74-bacc-b4883ac448a6', '句', '句', 'ab183f93-3e7f-4396-a336-de1b7b60c889', '唐', '["莫驚此地逢春早，祗爲長安近日邊。"]', '["莫驚此地逢春早，祗爲长安近日邊。"]', '诗', 'shi', '', NULL, '句 王幹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbb5bd2b-cf77-40d4-852b-ee8bf64ed44a', '句', '句', 'd4feb4be-a80f-4815-a3eb-8f233b813130', '唐', '["仍憐一夜春風急，開盡瑤池萬樹花。"]', '["仍怜一夜春风急，开尽瑤池万樹花。"]', '诗', 'shi', '', NULL, '句 樊寔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a1c76ca-80a1-4287-9426-58f88edadb10', '句', '句', '21e46e46-ae0e-4cda-93fa-e44c60734faa', '唐', '["已被夭桃歡來醉，麯塵絲樹恨何人。"]', '["已被夭桃歡来醉，麯塵絲樹恨何人。"]', '诗', 'shi', '', NULL, '句 張殷衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d46e4f1-5c3a-436a-b376-7bacb9f4cdf9', '句', '句', 'bdb5798b-5267-45b8-b47a-5ef25f55257c', '唐', '["藤拂石溪流水淨，風來雲寺過鐘微。"]', '["藤拂石溪流水淨，风来云寺過鐘微。"]', '诗', 'shi', '', NULL, '句 殷穆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adaf34f4-56bc-4f09-a5b2-849fd10bc12b', '句', '句', '350a1c24-1687-45a2-8914-27769780b916', '唐', '["千花苑外韶芳暖，一鳥山邊翠色寒。"]', '["千花苑外韶芳暖，一鸟山邊翠色寒。"]', '诗', 'shi', '', NULL, '句 解叔祿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44453641-b5bc-4375-b254-354c4c65dca3', '句', '句', 'af4c857d-2587-4b7a-99be-4d86daf1088a', '唐', '["炎氣擁爲衣上火，汗光流出腹中湯。"]', '["炎氣擁爲衣上火，汗光流出腹中湯。"]', '诗', 'shi', '', NULL, '句 石嚴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3321c4d5-a6a0-42c3-b1da-c9791d43297b', '句', '句', 'd62c090e-2ced-40da-8d4a-cc8ae9a21e65', '唐', '["銅街陌柳條條翠，金谷園花片片燃。"]', '["銅街陌柳條條翠，金谷园花片片燃。"]', '诗', 'shi', '', NULL, '句 張野人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ddb256c-92da-46aa-85c0-a9dda021c6f6', '句', '句', 'e71ba1eb-c8d4-4918-bf35-7f9411e66ac5', '唐', '["明月開時山夜白，暖泉流處草冬青。"]', '["明月开时山夜白，暖泉流处草冬青。"]', '诗', 'shi', '', NULL, '句 衛填 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f892f15d-b50c-46ac-b0cd-56f122feea7b', '句', '句', '5c5d9529-a998-4ed8-a62d-cb62787eeeb8', '唐', '["寒光乍退風猶切，春色新行柳未知。"]', '["寒光乍退风猶切，春色新行柳未知。"]', '诗', 'shi', '', NULL, '句 虞搆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01bdc025-acc0-44bb-a543-556f4968d943', '句', '句', 'e56f1091-63b0-4960-b8d9-40ea6bf94d47', '唐', '["寒氣乍凝空有露，秋風不動水無波。"]', '["寒氣乍凝空有露，秋风不动水無波。"]', '诗', 'shi', '', NULL, '句 崔幢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d63c5f81-bd14-4393-a5d9-13bf9464b9f2', '句', '句', '85c41c5b-456c-46d0-9828-a1e76adcd326', '唐', '["撩亂客心眠不得，秋庭一夜月中行。"]', '["撩亂客心眠不得，秋庭一夜月中行。"]', '诗', 'shi', '', NULL, '句 李淮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02a78a22-8b4e-47cd-8189-2638712a5778', '句', '句', '950c20a2-1f1f-4c13-ae38-eafac0f3b9da', '唐', '["秋月夜閑聞案曲，金風吹落玉簫聲。"]', '["秋月夜闲闻案曲，金风吹落玉簫声。"]', '诗', 'shi', '', NULL, '句 金雲卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe0f0330-6db6-4116-b466-c435f8249e92', '句', '句', '0ce46d9c-d7a8-485e-9cf5-839f1d9a25bf', '唐', '["簾前對酒閑無事，待得分明似鏡時。"]', '["簾前对酒闲無事，待得分明似镜时。"]', '诗', 'shi', '', NULL, '句 楊郁伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cd6d166-f4f3-4403-bcb6-466d83411a1e', '句', '句', 'd3fe5147-a359-4e61-b92a-4795428c1f5c', '唐', '["風向銀燈花燼落，月臨珠箔玉鉤垂。"]', '["风向銀灯花燼落，月臨珠箔玉鉤垂。"]', '诗', 'shi', '', NULL, '句 李伯良 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc79c645-1ad3-4baa-af8e-7623ba1d97c9', '句', '句', 'b00e666f-773b-44a6-8edc-2111d9d4c6b2', '唐', '["白玉飛泉千仞雪，青松蔽日一林風。"]', '["白玉飞泉千仞雪，青松蔽日一林风。"]', '诗', 'shi', '', NULL, '句 林逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cc7468f-88d7-4a5e-83fe-f0ddbaf7c6e8', '句', '句', 'ddf10265-1481-43a2-adf7-49227132ef11', '唐', '["霜霑雲夢千巖雪，鴈度吳江萬木秋。"]', '["霜霑云梦千巖雪，鴈度吳江万木秋。"]', '诗', 'shi', '', NULL, '句 長孫鎰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0f20252-f630-416e-8870-fb925fbae481', '句', '句', '5dd27ce0-cbec-46fa-9e28-f9e24bd35695', '唐', '["蛾遶燈輪千燄動，鶴飛雲路一聲長。"]', '["蛾遶灯輪千燄动，鹤飞云路一声长。"]', '诗', 'shi', '', NULL, '句 戴寥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3e4c4ac-2277-4ca8-9e67-0e5d0012f9a4', '句', '句', 'c3fc8cc5-0ac6-4900-9904-020d78fe836c', '唐', '["隔門借問人誰在，一樹桃花笑不應。"]', '["隔门借问人誰在，一樹桃花笑不應。"]', '诗', 'shi', '', NULL, '句 豆盧岑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af87249f-1fcc-49b3-95f7-e08dd95a8f4a', '句', '句', '237a3213-4a1e-4774-9035-e1fe58521eed', '唐', '["黃紙遠承新詔命，青袍遙謝舊山峯。"]', '["黄紙远承新詔命，青袍遙謝旧山峯。"]', '诗', 'shi', '', NULL, '句 沈寧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6ef1ad9-7c70-4246-9471-16ccc3bbd684', '句', '句', 'b465b971-779a-4c83-b7ed-9a09c16f9b7c', '唐', '["澹蕩和風催去袖，搖揚淑景照離樽。"]', '["澹蕩和风催去袖，搖揚淑景照離樽。"]', '诗', 'shi', '', NULL, '句 李許 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf55fd44-13ea-4725-a5e4-55f7d83cc63c', '句', '句', '40bbe63c-62a2-4057-afb0-308ffec6ad7b', '唐', '["孤舟發處沙鷗起，明月落時江水寒。"]', '["孤舟發处沙鷗起，明月落时江水寒。"]', '诗', 'shi', '', NULL, '句 顧効古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47b631c4-82a1-44e3-b25a-7ef2aa86774a', '句', '句', '85037f77-8778-4450-bf9f-ace04a397447', '唐', '["杯浮綠酒邀君醉，筆落紅牋寫我心。"]', '["杯浮綠酒邀君醉，笔落紅牋寫我心。"]', '诗', 'shi', '', NULL, '句 盧邕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('460f31de-51f2-4ff1-8dd7-9d69dbb32e5f', '句', '句', '14ae3f51-7b2e-4d56-a587-dddd641d242b', '唐', '["人過遠村秋日晚，鳥飛平野暮天空。"]', '["人過远村秋日晚，鸟飞平野暮天空。"]', '诗', 'shi', '', NULL, '句 李潭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e011ba11-e774-449f-970b-bc7078eda02a', '句', '句', '130ea9d0-b5ce-48be-9546-7031747a0ad0', '唐', '["山頭落日催歸馬，河畔垂楊纜醉船。"]', '["山头落日催归马，河畔垂楊纜醉船。"]', '诗', 'shi', '', NULL, '句 鄭明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e41067d-081a-4cbf-bf82-d4bf33f2e2f1', '句', '句', 'b490cead-7d06-4474-8f30-4ff14d3a4e16', '唐', '["頻醉管絃三月暮，遠尋花柳五湖來。"]', '["頻醉管絃三月暮，远尋花柳五湖来。"]', '诗', 'shi', '', NULL, '句 王有初 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b933994-767b-4a3e-8b70-67b4c32cdb92', '句', '句', 'e83542fc-dd88-48de-873b-82b547de8c95', '唐', '["指下黃金星未曙，七條絃上夜烏啼。"]', '["指下黄金星未曙，七條絃上夜烏啼。"]', '诗', 'shi', '', NULL, '句 周存孺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97e0ea68-3531-4203-9a23-9c2971612d63', '句', '句', '24188c91-1fd0-4953-aee4-ea291fadbedc', '唐', '["看看舞罷輕雲去，應赴襄王夢裏期。"]', '["看看舞罷轻云去，應赴襄王梦裏期。"]', '诗', 'shi', '', NULL, '句 張牙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9acfd523-77fa-41a0-9aa3-89558f6c796c', '句', '句', 'fa79555e-84ba-4f1f-aad6-1efda0452c6e', '唐', '["煙消門外青山近，露重窗前綠竹低。"]', '["煙消门外青山近，露重窗前綠竹低。"]', '诗', 'shi', '', NULL, '句 鄭師冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a62ca4f-054a-4cd0-94c7-33f6f6ff0584', '句', '句', 'f15db0ef-c917-45ad-b8c1-497fcf01dfda', '唐', '["聞說靜中偏愛竹，自看疎密種秋煙。"]', '["闻说静中偏愛竹，自看疎密種秋煙。"]', '诗', 'shi', '', NULL, '句 章嶰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('620b6c6f-f5d3-40c0-8cba-55700cfb53cd', '句', '句', '5bf65597-5136-4038-a543-45f45e32bbcd', '唐', '["回風向曉平湖上，引得荷花隔浦香。"]', '["回风向晓平湖上，引得荷花隔浦香。"]', '诗', 'shi', '', NULL, '句 崔建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d34410a-0699-4fc0-b25e-c676d2b57219', '句', '句', 'cd5b666e-1c03-49d2-b434-3c5f09e3d9c6', '唐', '["明主十徵何謝病，煙霞不許作堯臣。"]', '["明主十徵何謝病，煙霞不許作堯臣。"]', '诗', 'shi', '', NULL, '句 朴昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a48fc968-4a6f-4c2c-94cd-5a81f7124802', '句', '句', 'd07cec49-c7f7-4aad-8665-b1a27024275d', '唐', '["秋水漲來舟去速，夜雲收盡月行遲。"]', '["秋水漲来舟去速，夜云收尽月行遲。"]', '诗', 'shi', '', NULL, '句 郢展 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b5fbf4c-851e-4af7-b3e5-f59a3b43424f', '句', '句', '682a6ae4-ef14-44d9-bf1a-b6dfa394f96e', '唐', '["林外雪消山色靜，窗前春淺竹聲泉。"]', '["林外雪消山色静，窗前春淺竹声泉。"]', '诗', 'shi', '', NULL, '句 韋振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('938c9eac-51b4-47d9-9e44-29bec2d7fa3f', '句', '句', 'e0f5bfec-a8ce-4209-affe-5b90fa5a2a8c', '唐', '["西風暮雨驚殘夢，應是巫山寄恨來。"]', '["西风暮雨驚殘梦，應是巫山寄恨来。"]', '诗', 'shi', '', NULL, '句 漢皓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e544cbb2-cf74-4798-b0ef-44e9b9138a5e', '句', '句', 'a5271356-549c-456e-9ba5-1e7762479239', '唐', '["風起竹間螢影亂，月明江上笛聲多。","夜靜檻前調綠綺，日高窗下戴烏紗。","漁艇遠飄滄海上，草堂深鎖白雲間。","柴門半掩潮光裏，野徑斜分草色中。"]', '["风起竹间螢影亂，月明江上笛声多。","夜静檻前調綠綺，日高窗下戴烏紗。","漁艇远飄滄海上，草堂深鎖白云间。","柴门半掩潮光裏，野徑斜分草色中。"]', '诗', 'shi', '', NULL, '句 道彥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cb5379f-a632-4b75-ada8-9a18628dfdca', '句', '句', '808e71d1-e0fc-4606-a382-4104d2e32ba3', '唐', '["千里放心隨野鶴，五湖乘興狎沙鷗。"]', '["千里放心隨野鹤，五湖乘兴狎沙鷗。"]', '诗', 'shi', '', NULL, '句 冀金 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16f6a810-0357-4f7d-959a-c6ebb77f128d', '句', '句', '3356414d-a418-4cba-bb49-3df961bfb0f6', '唐', '["風姿豔態應無比，爛熳當春一樹芳。"]', '["风姿豔態應無比，爛熳當春一樹芳。"]', '诗', 'shi', '', NULL, '句 子泰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1b27034-071b-47b8-873c-626933c0b488', '句', '句', '07956a48-0725-49db-9899-487df25c3d03', '唐', '["遠聲歷歷風和水，近色青青竹映松。"]', '["远声歷歷风和水，近色青青竹映松。"]', '诗', 'shi', '', NULL, '句 紹伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('170af452-5a52-48cc-95d1-d8aaab53ef7e', '句', '句', '2c01b78c-a327-453b-9b1f-629c23c964ac', '唐', '["破暗衣珠明有焰，照窗心月凈無塵。"]', '["破暗衣珠明有焰，照窗心月凈無塵。"]', '诗', 'shi', '', NULL, '句 郁回 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f92c91e0-7015-482a-bd22-e648b7b37725', '句', '句', '7eb6ec2f-5550-4011-8bdc-36f2af12a9b4', '唐', '["林間縱有殘花在，留到明朝不是春。"]', '["林间縱有殘花在，留到明朝不是春。"]', '诗', 'shi', '', NULL, '句 季方 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40a659c0-3ae2-4bbe-b9ab-7bb019b8a895', '句', '句', '0e0c9913-9ecf-4f40-b2aa-51d8afa8bb11', '唐', '["盡日不歸花路晚，綠楊樓下醉如泥。","月上西陵千里闊，漁舟夜火隔沙明。"]', '["尽日不归花路晚，綠楊楼下醉如泥。","月上西陵千里闊，漁舟夜火隔沙明。"]', '诗', 'shi', '', NULL, '句 李侍御 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('536dade1-ad26-4bb7-a91d-392a7c3e8ea8', '句', '句', '8029e8a8-0c15-4a49-8bbf-ebcb0a68495f', '唐', '["今年閏在春三月，剩見金陵一月花。"]', '["今年閏在春三月，剩见金陵一月花。"]', '诗', 'shi', '', NULL, '句 陸侍御 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a3953f0-cfc3-4205-aef1-b0098d20153c', '句', '句', '509d1d08-1b89-41ac-9e15-c84a24abb270', '唐', '["長醉金陵前殿酒，偏聞玉樹後庭花。"]', '["长醉金陵前殿酒，偏闻玉樹後庭花。"]', '诗', 'shi', '', NULL, '句 盧秀才 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1068c6c-b101-4efc-9ca2-cfecd60f1bbb', '句', '句', '34dfda6b-d93a-4027-bb40-29030a718531', '唐', '["精明合浦珠相似，斷割昆吾劒不如。"]', '["精明合浦珠相似，斷割昆吾劒不如。"]', '诗', 'shi', '', NULL, '句 真元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc87318c-a921-4662-a097-08c8d00a48f6', '句', '句', '6d74bcf8-1150-4902-89ea-4d773c61b359', '唐', '["鷹隼風高隨草去，旌旗日晚傍山來。"]', '["鷹隼风高隨草去，旌旗日晚傍山来。"]', '诗', 'shi', '', NULL, '句 真幹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1aa79f3d-ea1e-43ce-b9f8-b7fbe376379b', '句', '句', '691a6625-5947-43d1-8735-21dffb398cd6', '唐', '["湖上青山今欲買，白雲無主問何人。"]', '["湖上青山今欲買，白云無主问何人。"]', '诗', 'shi', '', NULL, '句 久則 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39ee21e1-7b4a-42ee-b0f8-57229566e832', '句', '句', '99ceefa8-eb71-4313-82ad-da3d3bea6ffd', '唐', '["騎䯅春風離漢苑，心懸秋月照吳關。"]', '["騎䯅春风離漢苑，心懸秋月照吳关。"]', '诗', 'shi', '', NULL, '句 去奢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5af0deb-bd14-484d-8c22-a4a8c92aad84', '句', '句', '43d28026-ee00-4a4b-a0ee-cd882fab61ad', '唐', '["千點暮山三楚盡，一泓寒水九江斜。"]', '["千点暮山三楚尽，一泓寒水九江斜。"]', '诗', 'shi', '', NULL, '句 良人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbc0ad63-e560-451a-a15c-28de29c97dff', '句', '句', 'e4d61063-cd58-4927-befe-e8bce450fb89', '唐', '["借問夜來丹竈畔，幾多風水落絲桐。"]', '["借问夜来丹竈畔，幾多风水落絲桐。"]', '诗', 'shi', '', NULL, '句 宋休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf9c638e-41cc-4068-b365-3c6820b4d0ea', '句', '句', '76a57005-2cab-4bea-996c-934e6a2f8662', '唐', '["五色雲中鳴玉磬，千花臺上禮金仙。"]', '["五色云中鳴玉磬，千花台上禮金仙。"]', '诗', 'shi', '', NULL, '句 清閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33ba807b-ab65-498e-93f6-e1ed11818966', '句', '句', '5f8695cb-7c34-443d-9c42-5ffdb3b570cf', '唐', '["洞中仙草嚴冬綠，江外靈山臘月青。"]', '["洞中仙草嚴冬綠，江外靈山臘月青。"]', '诗', 'shi', '', NULL, '句 靈業 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3faeb87-ce88-4455-b9ab-c308d4634084', '句', '句', 'a8ca615b-c96c-4b2e-8fd9-680836f9a97e', '唐', '["霜霑草逕寒風急，鴈度秋林落葉頻。"]', '["霜霑草逕寒风急，鴈度秋林落葉頻。"]', '诗', 'shi', '', NULL, '句 大閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a64b37d-63fe-45fe-b831-7356624b9982', '句', '句', '05126587-75d5-47f6-b038-5566288ea87e', '唐', '["綠蘿翦作三春柳，紅錦裁成二月花。"]', '["綠蘿翦作三春柳，紅錦裁成二月花。"]', '诗', 'shi', '', NULL, '句 奉蚌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('add85a26-6caf-4763-97e7-6a02560b90f9', '海陽泉', '海陽泉', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["人誰無耽愛，各亦有所偏。","於吾喜尚中，不厭千萬泉。","誠知湟水曲，遠在南海壖。","自從得海陽，便欲終老焉。","怪石狀五岳，旋迴枕深淵。","激繁似湧雲，靜同冰鏡懸。","吾欲以海陽，跨於河洛間。","使彼雲林客，來遊皆忘還。"]', '["人誰無耽愛，各亦有所偏。","於吾喜尚中，不厭千万泉。","誠知湟水曲，远在南海壖。","自從得海陽，便欲終老焉。","怪石狀五岳，旋迴枕深淵。","激繁似湧云，静同冰镜懸。","吾欲以海陽，跨於河洛间。","使彼云林客，来游皆忘還。"]', '诗', 'shi', '', NULL, '海陽泉 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('403c7a2b-60e1-40c6-a140-3c5ef4edda34', '曲石鳧', '曲石鳧', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["爲愛水石奇，不厭湖畔行。","每登曲石鳧，則有遠興生。","𢼨差半湖□，宛若龍象形。","又如瑯琊臺，□盤枕滄溟。","醉人入島來，將醉強爲醒。","扣船復搖棹，學歌漁父聲。","呼我上酒船，更深江海情。"]', '["爲愛水石奇，不厭湖畔行。","每登曲石鳧，則有远兴生。","𢼨差半湖□，宛若龙象形。","又如瑯琊台，□盤枕滄溟。","醉人入島来，將醉強爲醒。","扣船复搖棹，学歌漁父声。","呼我上酒船，更深江海情。"]', '诗', 'shi', '', NULL, '曲石鳧 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a930cdc-ff52-4f42-9e58-48c8b692034b', '望遠亭', '望远亭', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["泛湖勞水戲，飲漱厭清瀾。","來登望遠亭，心目又不閑。","孤峯入座□，高嶺橫前軒。","更復歡長風，蕭寥窗戶間。","外物能擾人，吾將息其端。","歸來湖中館，□戶聊自安。"]', '["泛湖勞水戲，饮漱厭清瀾。","来登望远亭，心目又不闲。","孤峯入座□，高嶺橫前軒。","更复歡长风，蕭寥窗戶间。","外物能擾人，吾將息其端。","归来湖中館，□戶聊自安。"]', '诗', 'shi', '', NULL, '望遠亭 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d827bbc7-2b82-4437-b81b-5e174dcdc134', '石上閣', '石上閣', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["水石引我去，南湖復東壑。","不厭隨竹陰，來登石上閣。","磴道通石門，欹崖斷如鑿。","飛梁架峯頭，夭矯虹霓若。","下視竹木杪，仰見懸泉落。","水聲兼松吹，音響參衆樂。","時時爲霧雨，飄灑溼簾箔。","吾欲棄簪纓，於茲守寂寞。"]', '["水石引我去，南湖复东壑。","不厭隨竹陰，来登石上閣。","磴道通石门，欹崖斷如鑿。","飞梁架峯头，夭矯虹霓若。","下視竹木杪，仰见懸泉落。","水声兼松吹，音响參衆乐。","时时爲霧雨，飄灑溼簾箔。","吾欲棄簪纓，於茲守寂寞。"]', '诗', 'shi', '', NULL, '石上閣 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7960bed-e9f1-4bda-8547-d4441d20f40d', '石上閣', '石上閣', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["石上搆層閣，便以石爲柱。","千載□棟梁，豈有□危懼。","苔壁絕人蹤，虹橋橫鳥路。","攀涉愜所懷，幽奇未嘗遇。","迥然半空裏，物象競相助。","雲外見孤峯，林端懸瀑布。","引望無不通，茲焉倍多趣。","徒□欲忘歸，衣裳溼煙霧。"]', '["石上搆層閣，便以石爲柱。","千載□棟梁，豈有□危懼。","苔壁絕人蹤，虹橋橫鸟路。","攀涉愜所懷，幽奇未嘗遇。","迥然半空裏，物象競相助。","云外见孤峯，林端懸瀑布。","引望無不通，茲焉倍多趣。","徒□欲忘归，衣裳溼煙霧。"]', '诗', 'shi', '', NULL, '石上閣 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a327b9a1-b7fd-4968-9629-14ccaeeba574', '海陽湖', '海陽湖', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["吾漲海陽泉，以爲海陽湖。","千峯在水中，狀類皆自殊。","有如三神山，蒼蒼海上孤。","又似洲島中，忽然見龍魚。","引船過石間，隨興得所如。","每有愜心處，沈吟復躊躇。","吾恐天地間，怪異如此無。"]', '["吾漲海陽泉，以爲海陽湖。","千峯在水中，狀類皆自殊。","有如三神山，蒼蒼海上孤。","又似洲島中，忽然见龙鱼。","引船過石间，隨兴得所如。","每有愜心处，沈吟复躊躇。","吾恐天地间，怪異如此無。"]', '诗', 'shi', '', NULL, '海陽湖 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18e7a88d-bf1b-429f-8b94-c1d6a26bdf9a', '海陽湖', '海陽湖', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["閑遊愛湖廣，湖廣叢怪石。","迴合萬里勢，□□□□□。","綠動若無底，波澄涵雲碧。","鎔水復何如，昆池吾不易。","茲境多所尚，親鄰道與釋。","外望雖異門，中間不相隔。","開鑿盡天然，智者留奇跡。","我願長此遊，誰言一朝夕。"]', '["闲游愛湖廣，湖廣叢怪石。","迴合万里勢，□□□□□。","綠动若無底，波澄涵云碧。","鎔水复何如，昆池吾不易。","茲境多所尚，親鄰道與釋。","外望雖異门，中间不相隔。","开鑿尽天然，智者留奇跡。","我願长此游，誰言一朝夕。"]', '诗', 'shi', '', NULL, '海陽湖 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad2c9baa-86e8-46d6-bed1-b67032d5c2e9', '盤石', '盤石', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["海陽泉上山，巉巉盡殊狀。","忽然有平石，盤薄千峯上。","寒泉匝石流，懸注幾千丈。","有時厭泉湖，愛臨一長望。","意出天地間，因爲逸民唱。"]', '["海陽泉上山，巉巉尽殊狀。","忽然有平石，盤薄千峯上。","寒泉匝石流，懸注幾千丈。","有时厭泉湖，愛臨一长望。","意出天地间，因爲逸民唱。"]', '诗', 'shi', '', NULL, '盤石 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6deb4308-0057-4c80-9ebf-1058617b1533', '盤石', '盤石', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["下山復上山，山勢凌雲空。","有石圓且平，疑是□□功。","清淺繞細泉，陰森倚長松。","幕幕生青苔，亭亭對遠峯。","朝來暮未歸，愛□□□□。"]', '["下山复上山，山勢凌云空。","有石圓且平，疑是□□功。","清淺繞細泉，陰森倚长松。","幕幕生青苔，亭亭对远峯。","朝来暮未归，愛□□□□。"]', '诗', 'shi', '', NULL, '盤石 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96794408-6f3c-47b3-87a2-f220755833a6', '湖下溪', '湖下溪', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["海陽湖下溪，夾峯多異石。","數步□□□，溶溶似雲白。","竹陰入□裏，更覺溪已碧。","吾欲漱斯流，長爲避時客。"]', '["海陽湖下溪，夾峯多異石。","數步□□□，溶溶似云白。","竹陰入□裏，更覺溪已碧。","吾欲漱斯流，长爲避时客。"]', '诗', 'shi', '', NULL, '湖下溪 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4eb9bf37-08a1-42c3-ba70-0b347fbf2d47', '湖下溪', '湖下溪', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["湖水下爲溪，溪小趣更幽。","窈窕林中迴，清泠石上流。","掩映成碧潭，遊戲見白鷗。","岸傍古樹根，往往疑潛虬。","野情隨所適，世事何沈浮。"]', '["湖水下爲溪，溪小趣更幽。","窈窕林中迴，清泠石上流。","掩映成碧潭，游戲见白鷗。","岸傍古樹根，往往疑潛虬。","野情隨所適，世事何沈浮。"]', '诗', 'shi', '', NULL, '湖下溪 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f409370-fc92-4064-8e82-ffb9cf70a2fd', '夕陽洞', '夕陽洞', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["順山高幾許，亭亭似人蹲。","左右自迴抱，抱中有清源。","異石匝階墀，巉巉快四軒。","憑几見城邑，一峯當石門。","自從得茲洞，愛之忘朝昏。","吾欲老於此，便爲海陽人。","誰爲高世者，與我能修鄰。"]', '["順山高幾許，亭亭似人蹲。","左右自迴抱，抱中有清源。","異石匝階墀，巉巉快四軒。","憑几见城邑，一峯當石门。","自從得茲洞，愛之忘朝昏。","吾欲老於此，便爲海陽人。","誰爲高世者，與我能修鄰。"]', '诗', 'shi', '', NULL, '夕陽洞 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42036caf-49a8-4ae5-b6d1-a01ba961c5a6', '遊海門峽', '游海门峽', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["沿流二十里，始到海門山。","仰視見兩崖，有如萬蓋懸。","逐上幾千仞，猶未窮絕顛。","上有外士家，半巖得湖泉。","湖□昏且來，意其通海焉。","忽此見靈怪，踟蹰不能旋。","開襟當海風，目送歸海船。","恨不到羅浮，丹溪尋列仙。"]', '["沿流二十里，始到海门山。","仰視见兩崖，有如万蓋懸。","逐上幾千仞，猶未窮絕顛。","上有外士家，半巖得湖泉。","湖□昏且来，意其通海焉。","忽此见靈怪，踟蹰不能旋。","开襟當海风，目送归海船。","恨不到羅浮，丹溪尋列仙。"]', '诗', 'shi', '', NULL, '遊海門峽 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fb84910-bb96-4a44-9be0-066444a6a2b1', '句', '句', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["月知溪靜尋常入，雲愛山高且暮歸。","風吹帆席隨雲卷，鳥壓花枝覆水低。","匹馬路傍乘月別，孤帆波上入雲飛。","蹴踘場邊芳草短，鞦韆樹下落花多。","看樹只愁花落盡，聽鶯不覺馬行遲。","攜樽藉草情無極，對水看雲興有餘。","文戰不曾眉得白，酒醖長覺面先紅。","風裏一聲天上落，世人皆向五雲看。","仙花又別三千歲，暮雨已迷十二峯。","滿枝帶露將何似，曾見瓊樓素面啼。","翠葉偃風如翦彩，紅花含露似啼妝。","青蘿帶霧依松古，綠竹含煙泛水光。","書吏優遊山色裏，琴堂閑冷水聲中。","鐘鳴月下長洲苑，露溼殘花鳥亂啼。","花攢屋上紅珠顆，筍滿籬根紫玉簪。","花舞野塘鋪地錦，鳥鳴江樹送春聲。"]', '["月知溪静尋常入，云愛山高且暮归。","风吹帆席隨云卷，鸟壓花枝覆水低。","匹马路傍乘月別，孤帆波上入云飞。","蹴踘場邊芳草短，鞦韆樹下落花多。","看樹只愁花落尽，听鶯不覺马行遲。","携樽藉草情無極，对水看云兴有餘。","文戰不曾眉得白，酒醖长覺面先紅。","风裏一声天上落，世人皆向五云看。","仙花又別三千歲，暮雨已迷十二峯。","满枝带露將何似，曾见瓊楼素面啼。","翠葉偃风如翦彩，紅花含露似啼妝。","青蘿带霧依松古，綠竹含煙泛水光。","书吏優游山色裏，琴堂闲冷水声中。","鐘鳴月下长洲苑，露溼殘花鸟亂啼。","花攢屋上紅珠顆，筍满籬根紫玉簪。","花舞野塘鋪地錦，鸟鳴江樹送春声。"]', '诗', 'shi', '', NULL, '句 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96fdf055-b6c6-4ab1-800e-7262c770af3f', '遊仙窟詩 贈崔十孃', '游仙窟诗 贈崔十孃', '13cd2bd5-9610-4248-af2c-d3cb4d00f548', '唐', '["今朝忽見渠姿首，不覺殷勤著心口。","令人頻作許叮嚀，渠家太劇難求守。","端坐剩心驚，愁來益不平。","看時未必相看死，難時那許太難生。","沈吟處幽室，相思轉成疾。","自恨往還疎，誰肯交遊密。","夜夜空知心失眼，朝朝無便投膠漆。","園裏花開不避人，閨中面子翻羞出。","如今寸步阻天津，伊處留心更覓新。","莫言長有千金面，終歸變作一抄塵。","生前有日但爲樂，死後無春更著人。","祗可徜徉一生意，何須負持百年身。"]', '["今朝忽见渠姿首，不覺殷勤著心口。","令人頻作許叮嚀，渠家太劇难求守。","端坐剩心驚，愁来益不平。","看时未必相看死，难时那許太难生。","沈吟处幽室，相思轉成疾。","自恨往還疎，誰肯交游密。","夜夜空知心失眼，朝朝無便投膠漆。","园裏花开不避人，閨中面子翻羞出。","如今寸步阻天津，伊处留心更覓新。","莫言长有千金面，終归变作一抄塵。","生前有日但爲乐，死後無春更著人。","祗可徜徉一生意，何須負持百年身。"]', '诗', 'shi', '', NULL, '遊仙窟詩 贈崔十孃 張文成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dd82a35-8e1d-4b97-9cb1-ba1ba7da2af2', '遊仙窟詩 又贈十孃', '游仙窟诗 又贈十孃', '13cd2bd5-9610-4248-af2c-d3cb4d00f548', '唐', '["薰香四面合，光色兩邊披。","錦障劃然卷，羅帷垂半欹。","紅顏雜綠黛，無處不相宜。","豔色浮妝粉，含香亂口脂。","鬢欺蟬鬢非成鬢，眉笑蛾眉不見眉。","見許實娉婷，何處不輕盈。","可憐嬌裏面，可愛語中聲。","婀娜腰支細細許，䁠䀨眼子長長馨。","巧兒舊來攜未得，畫匠迎生模不成。","相看未相識，傾城復傾國。","迎風帔子鬱金香，照日裙裾石榴色。","口上珊瑚耐拾取，頰裏芙蓉堪摘得。","聞名腹肚已猖狂，見面精神更迷惑。","心肝恰欲摧，踊躍不能裁。","徐行步步香風散，欲語時時梅子開。","靨疑織女留星去，眉似姮娥送月來。","含嬌窈窕迎前出，忍笑嫈嫇返卻回。"]', '["薰香四面合，光色兩邊披。","錦障劃然卷，羅帷垂半欹。","紅顏杂綠黛，無处不相宜。","豔色浮妝粉，含香亂口脂。","鬢欺蟬鬢非成鬢，眉笑蛾眉不见眉。","见許實娉婷，何处不轻盈。","可怜嬌裏面，可愛語中声。","婀娜腰支細細許，䁠䀨眼子长长馨。","巧兒旧来携未得，畫匠迎生模不成。","相看未相識，傾城复傾国。","迎风帔子鬱金香，照日裙裾石榴色。","口上珊瑚耐拾取，頰裏芙蓉堪摘得。","闻名腹肚已猖狂，见面精神更迷惑。","心肝恰欲摧，踊躍不能裁。","徐行步步香风散，欲語时时梅子开。","靨疑织女留星去，眉似姮娥送月来。","含嬌窈窕迎前出，忍笑嫈嫇返卻回。"]', '诗', 'shi', '', NULL, '遊仙窟詩 又贈十孃 張文成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('271db649-cf67-4c3e-aafd-eecd874e57a5', '遊仙窟詩 詠崔五嫂', '游仙窟诗 詠崔五嫂', '13cd2bd5-9610-4248-af2c-d3cb4d00f548', '唐', '["奇異妍雅，貌特驚新。","眉間月出疑爭夜，頰上花開似鬬春。","細腰偏愛轉，笑臉特宜嚬。","真成物外奇稀物，實是人間斷絶人。","自然能舉止，可念無方比。","能令公子百重生，巧使王孫千迴死。","黑雲裁兩鬢，白雪分雙齒。","織成錦繡騏驎兒，判繡裙腰鸚鵡子。","觸處盡開懷，何曾有不佳。","機關大雅妙，行步絕𡟛娃。","傍人一一丹羅韈，侍婢三三綠線鞵。","黃龍透入黃金釧，白燕飛來白玉釵。"]', '["奇異妍雅，貌特驚新。","眉间月出疑爭夜，頰上花开似鬬春。","細腰偏愛轉，笑臉特宜嚬。","真成物外奇稀物，實是人间斷絶人。","自然能舉止，可念無方比。","能令公子百重生，巧使王孫千迴死。","黑云裁兩鬢，白雪分雙齒。","织成錦繡騏驎兒，判繡裙腰鸚鵡子。","觸处尽开懷，何曾有不佳。","機关大雅妙，行步絕𡟛娃。","傍人一一丹羅韈，侍婢三三綠線鞵。","黄龙透入黄金釧，白燕飞来白玉釵。"]', '诗', 'shi', '', NULL, '遊仙窟詩 詠崔五嫂 張文成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2893058c-de87-4b31-9753-5ac056a456ec', '遊仙窟詩 詠雙樹', '游仙窟诗 詠雙樹', '13cd2bd5-9610-4248-af2c-d3cb4d00f548', '唐', '["新華發兩樹，分香遍一林。","迎風轉細影，向日動輕陰。","戲蜂時隱見，飛蝶遠追尋。","承聞欲採摘，若箇動君心。"]', '["新华發兩樹，分香遍一林。","迎风轉細影，向日动轻陰。","戲蜂时隐见，飞蝶远追尋。","承闻欲採摘，若箇动君心。"]', '诗', 'shi', '', NULL, '遊仙窟詩 詠雙樹 張文成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('044ac4dd-dc8a-40e1-b66a-264e3794a2a4', '遊仙窟詩 詠雙樹荅文成', '游仙窟诗 詠雙樹荅文成', '35e21b9d-22a8-4673-8098-fccc38d4fc55', '唐', '["暫遊雙樹下，遙見兩枝芳。","向日俱翻影，迎風竝散香。","戲蝶扶丹萼，遊蜂入紫房。","人今總摘取，各著一邊箱。"]', '["暫游雙樹下，遙见兩枝芳。","向日俱翻影，迎风竝散香。","戲蝶扶丹萼，游蜂入紫房。","人今總摘取，各著一邊箱。"]', '诗', 'shi', '', NULL, '遊仙窟詩 詠雙樹荅文成 崔十孃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa1eecf2-6057-4b74-adec-6e7db0b7b33e', '遊仙窟詩 詠花', '游仙窟诗 詠花', '13cd2bd5-9610-4248-af2c-d3cb4d00f548', '唐', '["風吹遍樹紫，日照滿地丹。","若爲交暫折，擎就掌中看。"]', '["风吹遍樹紫，日照满地丹。","若爲交暫折，擎就掌中看。"]', '诗', 'shi', '', NULL, '遊仙窟詩 詠花 張文成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('729ccced-6852-44aa-90d5-aa952e7fab2f', '遊仙窟詩 詠花', '游仙窟诗 詠花', '35e21b9d-22a8-4673-8098-fccc38d4fc55', '唐', '["映水俱知笑，成蹊竟不言。","即今無自在，高下任渠攀。"]', '["映水俱知笑，成蹊竟不言。","即今無自在，高下任渠攀。"]', '诗', 'shi', '', NULL, '遊仙窟詩 詠花 崔十孃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2eecc300-b3e9-4168-b8b3-27a6f6e3c54c', '遊仙窟詩 遊後園', '游仙窟诗 游後园', '13cd2bd5-9610-4248-af2c-d3cb4d00f548', '唐', '["昔時過小苑，今朝戲後園。","兩歲梅花匝，三春柳色繁。","水明魚影靜，林翠鳥歌喧。","何須杏樹嶺，即是桃花源。"]', '["昔时過小苑，今朝戲後园。","兩歲梅花匝，三春柳色繁。","水明鱼影静，林翠鸟歌喧。","何須杏樹嶺，即是桃花源。"]', '诗', 'shi', '', NULL, '遊仙窟詩 遊後園 張文成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e45ea9d-3d99-415f-9682-b707f616f239', '遊仙窟詩 遊後園', '游仙窟诗 游後园', '35e21b9d-22a8-4673-8098-fccc38d4fc55', '唐', '["梅蹊命道士，桃澗佇神仙。","舊魚成大劒，新龜類小錢。","水湄唯見柳，池曲且生蓮。","欲知賞心處，桃花落眼前。"]', '["梅蹊命道士，桃澗佇神仙。","旧鱼成大劒，新龟類小錢。","水湄唯见柳，池曲且生蓮。","欲知賞心处，桃花落眼前。"]', '诗', 'shi', '', NULL, '遊仙窟詩 遊後園 崔十孃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e062740a-1ef6-4155-97bb-1909c7f67109', '遊仙窟詩 遊後園', '游仙窟诗 游後园', '1ed77dba-13b4-437a-96e0-905ba092a40f', '唐', '["極目遊芳苑，相將對花林。","露凈山光出，池鮮樹影沈。","落花時泛酒，歌鳥或鳴琴。","是時日將夕，攜樽就樹陰。"]', '["極目游芳苑，相將对花林。","露凈山光出，池鲜樹影沈。","落花时泛酒，歌鸟或鳴琴。","是时日將夕，携樽就樹陰。"]', '诗', 'shi', '', NULL, '遊仙窟詩 遊後園 崔五嫂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abf2e343-d272-4509-9f0b-dd68e46582d6', '遊仙窟詩 代蜂子答十孃', '游仙窟诗 代蜂子答十孃', '13cd2bd5-9610-4248-af2c-d3cb4d00f548', '唐', '["觸處尋芳樹，都慮少物華。","試從香處覓，正值可憐花。"]', '["觸处尋芳樹，都慮少物华。","試從香处覓，正值可怜花。"]', '诗', 'shi', '', NULL, '遊仙窟詩 代蜂子答十孃 張文成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f76e61f-912a-4308-b2dc-d419a3f51b38', '遊仙窟詩 別文成', '游仙窟诗 別文成', '35e21b9d-22a8-4673-8098-fccc38d4fc55', '唐', '["別時終是別，春心不值春。","羞見孤鸞影，悲看一騎塵。","翠柳開眉色，紅桃亂臉新。","此時君不在，嬌鶯弄殺人。"]', '["別时終是別，春心不值春。","羞见孤鸾影，悲看一騎塵。","翠柳开眉色，紅桃亂臉新。","此时君不在，嬌鶯弄殺人。"]', '诗', 'shi', '', NULL, '遊仙窟詩 別文成 崔十孃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ae0dc2d-c794-4329-b3e2-ef0afc68d0fd', '遊仙窟詩 別文成', '游仙窟诗 別文成', '1ed77dba-13b4-437a-96e0-905ba092a40f', '唐', '["此時經一去，誰知隔幾年。","雙鳧傷別緒，獨鶴慘離絃。","怨起移酲後，愁生落醉前。","若使人心密，莫惜馬蹄穿。"]', '["此时經一去，誰知隔幾年。","雙鳧傷別緒，独鹤慘離絃。","怨起移酲後，愁生落醉前。","若使人心密，莫惜马蹄穿。"]', '诗', 'shi', '', NULL, '遊仙窟詩 別文成 崔五嫂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aab30de0-434f-42ce-809c-ce09462c7d66', '遊仙窟詩 別十孃', '游仙窟诗 別十孃', '13cd2bd5-9610-4248-af2c-d3cb4d00f548', '唐', '["忽然聞道別，愁來不自禁。","眼下千行淚，腸懸一寸心。","兩劒俄分匣，雙鳧忽異林。","慇懃惜玉體，勿使外人侵。"]', '["忽然闻道別，愁来不自禁。","眼下千行泪，腸懸一寸心。","兩劒俄分匣，雙鳧忽異林。","慇懃惜玉體，勿使外人侵。"]', '诗', 'shi', '', NULL, '遊仙窟詩 別十孃 張文成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adc71e29-b959-4b09-a297-082a1623fd34', '遊仙窟詩 揚州青銅鏡留與十孃', '游仙窟诗 揚州青銅镜留與十孃', '13cd2bd5-9610-4248-af2c-d3cb4d00f548', '唐', '["仙人好負局，隱士屢潛觀。","映水菱花散，臨風竹影寒。","月下時驚鵲，池邊獨舞鸞。","若道人心變，從渠照膽看。"]', '["仙人好負局，隐士屢潛观。","映水菱花散，臨风竹影寒。","月下时驚鵲，池邊独舞鸾。","若道人心变，從渠照膽看。"]', '诗', 'shi', '', NULL, '遊仙窟詩 揚州青銅鏡留與十孃 張文成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ceb5d266-e41d-4d9b-b49d-fe831ba96d8c', '遊仙窟詩 手中扇贈文成', '游仙窟诗 手中扇贈文成', '35e21b9d-22a8-4673-8098-fccc38d4fc55', '唐', '["合歡遊璧水，同心侍華闕。","颯颯似朝風，團團如夜月。","鸞姿侵霧起，鶴影排空發。","希君掌中握，勿使恩情歇。"]', '["合歡游璧水，同心侍华闕。","颯颯似朝风，團團如夜月。","鸾姿侵霧起，鹤影排空發。","希君掌中握，勿使恩情歇。"]', '诗', 'shi', '', NULL, '遊仙窟詩 手中扇贈文成 崔十孃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b072fc1c-3d34-4aac-9f5a-389492301441', '遊仙窟詩 送張郎', '游仙窟诗 送張郎', '36d8a6c4-3c7c-4bfe-849a-bfc3651f45e4', '唐', '["丈夫存行跡，慇懃爲數來。","莫作浮萍草，逐浪不知迴。"]', '["丈夫存行跡，慇懃爲數来。","莫作浮萍草，逐浪不知迴。"]', '诗', 'shi', '', NULL, '遊仙窟詩 送張郎 香兒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26250798-9b7b-4b4e-92c2-abd9aae686b7', '遊仙窟詩 贈十孃', '游仙窟诗 贈十孃', '13cd2bd5-9610-4248-af2c-d3cb4d00f548', '唐', '["人去悠悠隔兩天，未審迢迢度幾年。","縱使身遊萬里外，終歸意在十孃邊。"]', '["人去悠悠隔兩天，未審迢迢度幾年。","縱使身游万里外，終归意在十孃邊。"]', '诗', 'shi', '', NULL, '遊仙窟詩 贈十孃 張文成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52a31a6f-766d-416e-aca8-9cfad2acade3', '遊仙窟詩 答文成', '游仙窟诗 答文成', '35e21b9d-22a8-4673-8098-fccc38d4fc55', '唐', '["天涯地角知何處，玉體紅顏難再遇。","但令翅羽爲人生，會些高飛共君去。"]', '["天涯地角知何处，玉體紅顏难再遇。","但令翅羽爲人生，會些高飞共君去。"]', '诗', 'shi', '', NULL, '遊仙窟詩 答文成 崔十孃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65721ef6-7ad2-406d-909f-2fde56aa0084', '原', '原', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["王粲銷憂日，江淹起恨年。","帶川遙綺錯，分隰迥阡眠。","膴膴橫周甸，莓莓闕晉田。","方知急難響，長在鶺鴒篇。"]', '["王粲銷憂日，江淹起恨年。","带川遙綺錯，分隰迥阡眠。","膴膴橫周甸，莓莓闕晉田。","方知急难响，长在鶺鴒篇。"]', '诗', 'shi', '', NULL, '原 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6fd124d-a2c7-40b6-a54f-0cc7543791cc', '河', '河', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["河出崑崙中，長波接漢空。","桃花生馬頰，竹箭入龍宮。","德水千年變，榮光五色通。","若披蘭葉檢，還沐土皇風。"]', '["河出崑崙中，长波接漢空。","桃花生马頰，竹箭入龙宮。","德水千年变，榮光五色通。","若披蘭葉檢，還沐土皇风。"]', '诗', 'shi', '', NULL, '河 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21dc9c0a-2c78-4268-8d76-58c50cc4c611', '檄', '檄', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["羽檄本宣明，由來敷木聲。","聯翩通漢國，迢遞入燕營。","毛義持書去，張儀韞璧行。","曹風雖覺愈，陳草始知名。"]', '["羽檄本宣明，由来敷木声。","聯翩通漢国，迢遞入燕營。","毛義持书去，張儀韞璧行。","曹风雖覺愈，陳草始知名。"]', '诗', 'shi', '', NULL, '檄 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f502d35-815f-4bb8-acf1-bae384137560', '戈', '戈', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["富父舂喉日，殷辛漂杵年。","曉霜含白刃，落影駐琱鋋。","夕擯金門側，朝提玉塞前。","願隨龍影度，橫陣彗雲邊。"]', '["富父舂喉日，殷辛漂杵年。","晓霜含白刃，落影駐琱鋋。","夕擯金门側，朝提玉塞前。","願隨龙影度，橫陣彗云邊。"]', '诗', 'shi', '', NULL, '戈 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8a1acb9-a691-4f29-bc84-cb6cb9abe539', '簫', '簫', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["虞舜調清管，王褒賦雅音。","參差橫鳳翼，搜索動猿吟。","靈鶴時來到，仙人幸見尋。","爲聽楊柳曲，行役幾傷心。"]', '["虞舜調清管，王褒賦雅音。","參差橫鳳翼，搜索动猿吟。","靈鹤时来到，仙人幸见尋。","爲听楊柳曲，行役幾傷心。"]', '诗', 'shi', '', NULL, '簫 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8eac90c7-4a21-4bbb-926e-42821178d108', '素', '素', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["濯手天津女，纖腰洛浦妃。","魚腸遠方至，鴈足上林飛。","妙奪鮫綃色，光騰月扇輝。","非君下路去，誰賞故人機。"]', '["濯手天津女，纖腰洛浦妃。","鱼腸远方至，鴈足上林飞。","妙奪鮫綃色，光腾月扇輝。","非君下路去，誰賞故人機。"]', '诗', 'shi', '', NULL, '素 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a41c3fc8-666f-4d0f-859a-90ceebedf1b7', '題梵書（伯三九八六）', '題梵书（伯三九八六）', 'b557108e-ce30-47e3-b23e-8fc8f49fd6ae', '唐', '["毫（鶴）立蛇形勢未休，五天文字鬼神愁。","支那弟子無言語，穿耳胡僧笑點頭。","（〖1〗這首詩雖不見《全唐詩》和《全唐詩逸》，在敦煌本沒有出現以前，是曾經廣泛流傳的。","依余所知，最早的是一○七七年陝西咸甯縣臥龍寺的石刻本，但題太宗，不作玄宗。","一三○八年河南登封縣的刻石，又題玄宗，不作太宗。","敦煌本標題作《玄宗題梵書》，證明這首詩在唐末已經流傳，而且證明在唐末是題玄宗作的。","石刻資料見於王昶的《金石萃編》卷一三七，錄附於後。","）。"]', '["毫（鹤）立蛇形勢未休，五天文字鬼神愁。","支那弟子無言語，穿耳胡僧笑点头。","（〖1〗這首诗雖不见《全唐诗》和《全唐诗逸》，在敦煌本沒有出現以前，是曾經廣泛流傳的。","依余所知，最早的是一○七七年陝西咸甯縣臥龙寺的石刻本，但題太宗，不作玄宗。","一三○八年河南登封縣的刻石，又題玄宗，不作太宗。","敦煌本標題作《玄宗題梵书》，證明這首诗在唐末已經流傳，而且證明在唐末是題玄宗作的。","石刻資料见於王昶的《金石萃編》卷一三七，錄附於後。","）。"]', '诗', 'shi', '', NULL, '題梵書（伯三九八六） 唐明皇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('026ded1c-0b0c-40bb-8f00-8ef1d6819b1e', '唵字贊（義靜三藏於西天取得此梵書「唵」字，所在之地，一切鬼神，見聞者無不驚怖。）', '唵字贊（義静三藏於西天取得此梵书「唵」字，所在之地，一切鬼神，见闻者無不驚怖。）', 'b557108e-ce30-47e3-b23e-8fc8f49fd6ae', '唐', '["鶴立蛇行勢未休，五天文字鬼神愁。","儒門弟子無人識，穿耳胡僧笑點頭。","（〖1〗京兆住持十方福應禪院講經論傳戒沙門惟果立石。","〖2〗大宋丁巳熙寧十年〖一○七七〗八月二十六日安石師刊。","）。"]', '["鹤立蛇行勢未休，五天文字鬼神愁。","儒门弟子無人識，穿耳胡僧笑点头。","（〖1〗京兆住持十方福應禪院講經論傳戒沙门惟果立石。","〖2〗大宋丁巳熙寧十年〖一○七七〗八月二十六日安石師刊。","）。"]', '诗', 'shi', '', NULL, '唵字贊（義靜三藏於西天取得此梵書「唵」字，所在之地，一切鬼神，見聞者無不驚怖。） 唐明皇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1d76f18-ca54-433a-bae0-68d65786d57a', '佛教梵文唵字唐玄宗書並讀（原刻石在河南登封，還有御製《老子讚》。） 一', '佛教梵文唵字唐玄宗书並读（原刻石在河南登封，還有御製《老子讚》。） 一', 'b557108e-ce30-47e3-b23e-8fc8f49fd6ae', '唐', '["鶴立蛇形勢未休，五天文字鬼神愁。","龍盤梵質層峯峭，鳳展翔儀乙卷收。","正覺印同真聖道，邪魔交秘絕蹤由。","儒門弟子應難識，碧眼胡僧笑點頭。","（〖1〗至大元年〖一三○八〗中元日法三灑掃太原祖昭立石，德淵刻。","〖2〗按石本以外，鈔本的流傳應該更多，筆記和方志內還有一些徵引。","我所見到的有正德《中牟縣志》卷七，登載著唐太宗《題梵菴篆符》云：）。"]', '["鹤立蛇形勢未休，五天文字鬼神愁。","龙盤梵質層峯峭，鳳展翔儀乙卷收。","正覺印同真聖道，邪魔交秘絕蹤由。","儒门弟子應难識，碧眼胡僧笑点头。","（〖1〗至大元年〖一三○八〗中元日法三灑掃太原祖昭立石，德淵刻。","〖2〗按石本以外，鈔本的流傳應該更多，笔記和方志內還有一些徵引。","我所见到的有正德《中牟縣志》卷七，登載著唐太宗《題梵菴篆符》云：）。"]', '诗', 'shi', '', NULL, '佛教梵文唵字唐玄宗書並讀（原刻石在河南登封，還有御製《老子讚》。） 一 唐明皇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee418f41-39c8-4cfa-ab8f-a94fcb09419b', '佛教梵文唵字唐玄宗書並讀（原刻石在河南登封，還有御製《老子讚》。） 二', '佛教梵文唵字唐玄宗书並读（原刻石在河南登封，還有御製《老子讚》。） 二', 'b557108e-ce30-47e3-b23e-8fc8f49fd6ae', '唐', '["鶴立蛇形勢未休，五尺文字鬼神愁。","儒門弟子無人識，穿耳胡僧笑點頭。","（〖1〗現在根據最古的敦煌本補入，而把所知所見的石本刻本作爲附錄，以便參攷。","）。"]', '["鹤立蛇形勢未休，五尺文字鬼神愁。","儒门弟子無人識，穿耳胡僧笑点头。","（〖1〗現在根據最古的敦煌本補入，而把所知所见的石本刻本作爲附錄，以便參攷。","）。"]', '诗', 'shi', '', NULL, '佛教梵文唵字唐玄宗書並讀（原刻石在河南登封，還有御製《老子讚》。） 二 唐明皇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85d6cff5-9f3f-4995-b8ea-884dc9d03979', '度大臾（庾）嶺（其二伯三六一九）', '度大臾（庾）嶺（其二伯三六一九）', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["城邊問官使：「早晚發西京？來日河橋柳，春條幾寸生？昆池水合淥，御苑草應青？」緩緩從頭說，教人眼暫明。","（按《度大臾嶺》二首，《全唐詩》僅載「其一」，茲補「其二」。","）。"]', '["城邊问官使：「早晚發西京？来日河橋柳，春條幾寸生？昆池水合淥，御苑草應青？」緩緩從头说，教人眼暫明。","（按《度大臾嶺》二首，《全唐诗》僅載「其一」，茲補「其二」。","）。"]', '诗', 'shi', '', NULL, '度大臾（庾）嶺（其二伯三六一九） 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb298b3c-6949-450d-9dca-01e72919410f', '', '', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d24578fd-65c6-490f-aa49-9866576f0638', '責躬詩（斯二七一七下同）', '責躬诗（斯二七一七下同）', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["嘗聞古人說：「正直神不欺。","」忠義恆獨守，堅貞每自持。","効官已十載，理劇猶未期，獄聽除苛慘，刑章息滯疑。","豈得保世業，諒以答明時；顧無白玉玷，忽負蒼蠅詩。","扃固（錮）非所恥，幽寃誰爲辭！楚囚應積[□]，秦繫亦銜悲。","永夜振衣坐，故人不在茲。","流靈自蕪漫，芳草獨葳蕤。","日月行無舍，平生志莫追。","山林如道喪，州縣豈心期？","助思紛何在，清神悵不怡。","自憐暗成事，感歎興此詞。"]', '["嘗闻古人说：「正直神不欺。","」忠義恆独守，堅貞每自持。","効官已十載，理劇猶未期，獄听除苛慘，刑章息滯疑。","豈得保世業，諒以答明时；顧無白玉玷，忽負蒼蠅诗。","扃固（錮）非所恥，幽寃誰爲辞！楚囚應積[□]，秦繫亦銜悲。","永夜振衣坐，故人不在茲。","流靈自蕪漫，芳草独葳蕤。","日月行無舍，平生志莫追。","山林如道喪，州縣豈心期？","助思紛何在，清神悵不怡。","自怜暗成事，感歎兴此词。"]', '诗', 'shi', '', NULL, '責躬詩（斯二七一七下同） 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76a778ea-6aeb-46db-96dc-8cc5586ed23d', '暮秋書懷', '暮秋书懷', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["首夏別京輔，杪秋滯三河。","沉沉蓬萊閣，日夕鄉思多。","霜剪涼墀蕙，風捎幽渚荷。","歲芳坐淪歇，感此至微歌。","（〖1〗按這一首，《全唐詩》卷三一作爲魏徵的詩，而《珠英集》作崔湜；《珠英集》應可據，故仍補入崔湜名下。","第七句「淪歌」有誤，依《全唐詩》應作歇。","）。"]', '["首夏別京輔，杪秋滯三河。","沉沉蓬萊閣，日夕乡思多。","霜剪涼墀蕙，风捎幽渚荷。","歲芳坐淪歇，感此至微歌。","（〖1〗按這一首，《全唐诗》卷三一作爲魏徵的诗，而《珠英集》作崔湜；《珠英集》應可據，故仍補入崔湜名下。","第七句「淪歌」有誤，依《全唐诗》應作歇。","）。"]', '诗', 'shi', '', NULL, '暮秋書懷 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34d12f77-9f60-4527-ba72-162036e2cffc', '雜詩', '杂诗', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["鵲巢惡木巔，常窘一枝息；寧知猗（椅）[一]（原卷作「椅」）梧鳳，亦欲此栖宿！喈喈多好音，矯矯奮輕翼，上林豈不成，（蔣禮鴻〖簡稱「蔣」〗、項楚〖簡稱「項」〗皆云：「成」當作「茂」。","原卷作「茂」。","）胡爲戀幽仄？","處陋仍莫保，居華固陵偪，下流不可居[二]斯言可佩服。","（[一]俞平伯先生云：「『猗梧』當作『椅梧』。","《詩·定之方中》：『椅桐梓漆。","』」[二]劉盼遂先生云：「司馬遷《報任少卿書》云：負下未易居，下游多謗議，此合爲一句。","」）。"]', '["鵲巢惡木巔，常窘一枝息；寧知猗（椅）[一]（原卷作「椅」）梧鳳，亦欲此栖宿！喈喈多好音，矯矯奮轻翼，上林豈不成，（蔣禮鴻〖簡稱「蔣」〗、項楚〖簡稱「項」〗皆云：「成」當作「茂」。","原卷作「茂」。","）胡爲戀幽仄？","处陋仍莫保，居华固陵偪，下流不可居[二]斯言可佩服。","（[一]俞平伯先生云：「『猗梧』當作『椅梧』。","《诗·定之方中》：『椅桐梓漆。","』」[二]劉盼遂先生云：「司马遷《報任少卿书》云：負下未易居，下游多謗議，此合爲一句。","」）。"]', '诗', 'shi', '', NULL, '雜詩 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86d89182-c101-40df-9b8b-7cab7f877caf', '九龍潭作', '九龙潭作', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["弱齡聞茲山，夢寐嘗所適。","迨[□][一]此躋覽，（蔣云：「闕文應在『此』字下。","」）依然是疇昔。","結侶尋絕徑，周流觀奇迹。","茲逢世所希，環令佨窮壁。","（「令佨」，蔣、項皆校作「合抱」。","項釋此句云：「謂九龍潭四面爲絕壁所環抱也。","」）上有龍泉湧，百丈[□]潨射。","伏溜至陰溝，盤渴沸嵌石。","（「盤渴」，蔣、項皆校作「盤渦」。","）逶迤環汀嶼，熠㷿洞金碧。","（「熠㷿」，蔣、項皆校作「熠爚」。","「洞」，項校作「洄」。","）石蔓下離縷，雲蘿上綿冪。","翫極不云厭，徘徊忽惡夕。","清瀬飛絲篁，茂草代茵席。","冷然聞鳳吹，（「冷然」，蔣、項皆校作「泠然。","」）髣髴覯雲藉（際）[二]。","（「雲藉」，蔣云「藉」爲「舄」字音近之借。","舉《風俗通義》載王喬故事爲證。","）顧音攜手人，誰爲挂冠客？（[一]句內脫一字，不知應在何處？茲依韻補於此。","[二]俞云：「『雲藉』疑當作『雲籍』，仙籍之意。","如改『際』字，失叶。","」）。"]', '["弱齡闻茲山，梦寐嘗所適。","迨[□][一]此躋覽，（蔣云：「闕文應在『此』字下。","」）依然是疇昔。","結侶尋絕徑，周流观奇迹。","茲逢世所希，环令佨窮壁。","（「令佨」，蔣、項皆校作「合抱」。","項釋此句云：「謂九龙潭四面爲絕壁所环抱也。","」）上有龙泉湧，百丈[□]潨射。","伏溜至陰溝，盤渴沸嵌石。","（「盤渴」，蔣、項皆校作「盤渦」。","）逶迤环汀嶼，熠㷿洞金碧。","（「熠㷿」，蔣、項皆校作「熠爚」。","「洞」，項校作「洄」。","）石蔓下離縷，云蘿上綿冪。","翫極不云厭，徘徊忽惡夕。","清瀬飞絲篁，茂草代茵席。","冷然闻鳳吹，（「冷然」，蔣、項皆校作「泠然。","」）髣髴覯云藉（際）[二]。","（「云藉」，蔣云「藉」爲「舄」字音近之借。","舉《风俗通義》載王喬故事爲證。","）顧音携手人，誰爲挂冠客？（[一]句內脫一字，不知應在何处？茲依韻補於此。","[二]俞云：「『云藉』疑當作『云籍』，仙籍之意。","如改『際』字，失叶。","」）。"]', '诗', 'shi', '', NULL, '九龍潭作 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba468d98-b39a-4222-9e9a-0dffba3bd70e', '幽居（斯五五五。下同）', '幽居（斯五五五。下同）', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["澗戶風前竹，山空月下琴。","（項疑「山空」爲「山窗」之誤。","）唯餘兩□□，應盡百年心。"]', '["澗戶风前竹，山空月下琴。","（項疑「山空」爲「山窗」之誤。","）唯餘兩□□，應尽百年心。"]', '诗', 'shi', '', NULL, '幽居（斯五五五。下同） 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('762ce354-dc3c-4ea5-b585-8b71360262dd', '寺中觀臥像', '寺中观臥像', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["淨宇流金□，直誠翳寶床。","自應歸寂滅，非是倦津梁。"]', '["淨宇流金□，直誠翳寶床。","自應归寂滅，非是倦津梁。"]', '诗', 'shi', '', NULL, '寺中觀臥像 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af38a8de-fe2b-48aa-a15d-ddd709b86967', '詠漢武帝（斯二七一七下同）', '詠漢武帝（斯二七一七下同）', 'efabfbd9-153d-4b78-9136-a6a5d4f9d9e9', '唐', '["漢家中葉盛，六世有雄才。","廐馬三十萬，國容何壯裁（哉）！東歷瑯琊郡，北上單于臺。","好僊復寵戰，莫救茂陵●[一]。","（蔣云「●」以作隈爲是，「隈」有敗壞之義。","）（[一]「●」字不可識，疑當作「隈」。","劉云：「『隈』當是煨之誤。」","《說文》：煨，燼餘火也。","茂陵雖未聞焚燒之事，然陳沈烱《經通天臺奏漢武帝表》云：「茂陵玉椀，遂出人間，雲凌故基，與原田而每每；扶風餘趾，帶陵阜而芒芒」，亦正是茂陵煨燼的寫照了。","）。"]', '["漢家中葉盛，六世有雄才。","廐马三十万，国容何壯裁（哉）！东歷瑯琊郡，北上單于台。","好僊复寵戰，莫救茂陵●[一]。","（蔣云「●」以作隈爲是，「隈」有敗壞之義。","）（[一]「●」字不可識，疑當作「隈」。","劉云：「『隈』當是煨之誤。」","《说文》：煨，燼餘火也。","茂陵雖未闻焚燒之事，然陳沈烱《經通天台奏漢武帝表》云：「茂陵玉椀，遂出人间，云凌故基，與原田而每每；扶风餘趾，带陵阜而芒芒」，亦正是茂陵煨燼的寫照了。","）。"]', '诗', 'shi', '', NULL, '詠漢武帝（斯二七一七下同） 王無競 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d8e4563-8ca8-4e04-8e20-3c447be67061', '駕幸長安奉使先往檢察', '駕幸长安奉使先往檢察', 'efabfbd9-153d-4b78-9136-a6a5d4f9d9e9', '唐', '["奉使至京邑，戒塗歷險夷。","首旬發定鼎[一]，再信過灞池。","河山壯關輔，金火遞雄雌。","文物淪霸運，靈符啟聖青。","宸扆闊臨御，巡幸順謳思。","城闕生光彩，草樹含榮滋。","緹綺（騎）[二]紛沓襲，翠旗曳葳蕤。","童幼聞明主，耆老感盛儀。","輪袂交隱隱，廛陌滿熙熙。","微臣昧所識，觀俗書此詞。","（[一]劉云：「定鼎見《左傳》，成王定鼎於郟鄏，此處用以代表洛陽。","又考唐代洛陽城郭南而第二門名定鼎門，爲西行必由門戶。","」[二]依劉校。","）。"]', '["奉使至京邑，戒塗歷險夷。","首旬發定鼎[一]，再信過灞池。","河山壯关輔，金火遞雄雌。","文物淪霸運，靈符啟聖青。","宸扆闊臨御，巡幸順謳思。","城闕生光彩，草樹含榮滋。","緹綺（騎）[二]紛沓襲，翠旗曳葳蕤。","童幼闻明主，耆老感盛儀。","輪袂交隐隐，廛陌满熙熙。","微臣昧所識，观俗书此词。","（[一]劉云：「定鼎见《左傳》，成王定鼎於郟鄏，此处用以代表洛陽。","又考唐代洛陽城郭南而第二门名定鼎门，爲西行必由门戶。","」[二]依劉校。","）。"]', '诗', 'shi', '', NULL, '駕幸長安奉使先往檢察 王無競 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90aa8a94-85d4-45bd-963f-ed0551460210', '滅胡', '滅胡', 'efabfbd9-153d-4b78-9136-a6a5d4f9d9e9', '唐', '["漢軍屢北喪，胡馬遂南駈。","羽書夜驚急，邊柝亂傳呼。","鬬軍卻不進，關城勢已孤。","黃雲塞沙落，（項云「落」當作「路」。","蔣云「落」爲「聚落」、「村落」之「落」。","）白刃斷交衢。","朔霧圍未解，鑿山泉尚枯。","伏波塞後援，都尉失前途。","亭障多墮毀，金鏃無金（全）[一]軀。","獨有山東客，上書圖滅胡。","（[一]俞云：「第二『金』是『全』之誤。","」）。"]', '["漢軍屢北喪，胡马遂南駈。","羽书夜驚急，邊柝亂傳呼。","鬬軍卻不進，关城勢已孤。","黄云塞沙落，（項云「落」當作「路」。","蔣云「落」爲「聚落」、「村落」之「落」。","）白刃斷交衢。","朔霧圍未解，鑿山泉尚枯。","伏波塞後援，都尉失前途。","亭障多墮毀，金鏃無金（全）[一]軀。","独有山东客，上书圖滅胡。","（[一]俞云：「第二『金』是『全』之誤。","」）。"]', '诗', 'shi', '', NULL, '滅胡 王無競 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48b11008-7807-402b-84eb-720ddb6cdcea', '君子有所思行', '君子有所思行', 'efabfbd9-153d-4b78-9136-a6a5d4f9d9e9', '唐', '["北上登渭原，南下望咸陽。","秦帝昔所據，按劍朝侯王。","踐山𪟖（劃）郊郭，濬流固墉隍。","左右羅將相，甲館臨康莊。","曲臺連閣道，錦幕接洞房。","荆國徵艷色，邯鄲選名倡。","一彈入雲漢，再歌斷君腸。","自矜青春日，王顏𢗞容光。","（「王顏」，蔣、項皆云當作「玉顏」。","「𢗞」，蔣云當作「恡」，惜也。","原卷作「恡」。","）安知綠苔滿，羅袖坐霑霜。","聲侈遽衰歇，盛愛且離傷。","豈唯毒身世，朝國亦淪亡。","（「朝國」，項疑當作「邦國」。","）物盈道先忌，（「物盈」，項云當作「惡盈」。","）履謙宇允臧。","獨有東陵子，種瓜青門旁。","（[一]俞云：「『𢗞』乃『恡』之簡體，即『悋，吝』。","」劉云：「當作『怯』。","」）。"]', '["北上登渭原，南下望咸陽。","秦帝昔所據，按劍朝侯王。","踐山𪟖（劃）郊郭，濬流固墉隍。","左右羅將相，甲館臨康莊。","曲台連閣道，錦幕接洞房。","荆国徵艷色，邯鄲選名倡。","一彈入云漢，再歌斷君腸。","自矜青春日，王顏𢗞容光。","（「王顏」，蔣、項皆云當作「玉顏」。","「𢗞」，蔣云當作「恡」，惜也。","原卷作「恡」。","）安知綠苔满，羅袖坐霑霜。","声侈遽衰歇，盛愛且離傷。","豈唯毒身世，朝国亦淪亡。","（「朝国」，項疑當作「邦国」。","）物盈道先忌，（「物盈」，項云當作「惡盈」。","）履謙宇允臧。","独有东陵子，種瓜青门旁。","（[一]俞云：「『𢗞』乃『恡』之簡體，即『悋，吝』。","」劉云：「當作『怯』。","」）。"]', '诗', 'shi', '', NULL, '君子有所思行 王無競 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d0cd728-56f2-41da-a1cc-12e4fb8a2dbe', '度嶺（二首。斯五五五） 一', '度嶺（二首。斯五五五） 一', '279468d4-48db-402e-9185-d8eb7a150748', '唐', '["嶺南流水嶺南流，嶺北遊人望嶺頭。","感念鄉園不可□，肝腹（腸）一斷一廻愁。"]', '["嶺南流水嶺南流，嶺北游人望嶺头。","感念乡园不可□，肝腹（腸）一斷一廻愁。"]', '诗', 'shi', '', NULL, '度嶺（二首。斯五五五） 一 閻朝隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd2e1b96-2dd3-4e6a-8705-ebce89553b61', '度嶺（二首。斯五五五） 二', '度嶺（二首。斯五五五） 二', '279468d4-48db-402e-9185-d8eb7a150748', '唐', '["千重江水萬重山，毒瘴□氛道路間。","（「□氛」，項云闕字當是「氳」字。","）迴首俛眉但下淚，不知何處是鄉關。","（〖1〗這兩首詩的詩題辨不出來。","《舊唐書》卷一百九十中《文苑傳》，說「張易之伏誅〖神龍元年，七○五〗，坐徙嶺外」。","《新唐書》卷二百二《文藝傳》，又說他「景龍〖七○七--七○九〗初，自崖州遇赦還」。","這兩首詩應該是他「遇赦還」時候作的。","王仲聞先生云：「唐芮挺章《國秀集》卷上載宋之問七古一首，題云：《端州驛見杜審言王無竭沈佺青閻朝隱有題慨然成詠》。","朝隱這兩首詩，殆即爲端州題壁，都是他們南徙時所作，也就都是宋之問所見的那些詩。","」〖項考此二詩爲南徙時過大庾嶺作。","與端州題壁詩無關。","〗）。"]', '["千重江水万重山，毒瘴□氛道路间。","（「□氛」，項云闕字當是「氳」字。","）迴首俛眉但下泪，不知何处是乡关。","（〖1〗這兩首诗的诗題辨不出来。","《旧唐书》卷一百九十中《文苑傳》，说「張易之伏誅〖神龙元年，七○五〗，坐徙嶺外」。","《新唐书》卷二百二《文藝傳》，又说他「景龙〖七○七--七○九〗初，自崖州遇赦還」。","這兩首诗應該是他「遇赦還」时候作的。","王仲闻先生云：「唐芮挺章《国秀集》卷上載宋之问七古一首，題云：《端州驛见杜審言王無竭沈佺青閻朝隐有題慨然成詠》。","朝隐這兩首诗，殆即爲端州題壁，都是他們南徙时所作，也就都是宋之问所见的那些诗。","」〖項考此二诗爲南徙时過大庾嶺作。","與端州題壁诗無关。","〗）。"]', '诗', 'shi', '', NULL, '度嶺（二首。斯五五五） 二 閻朝隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7817e697-f704-4146-9319-7bc34ee1af20', '送友人向恬（括）[一]（原卷作「括」。）州（斯二七一七）', '送友人向恬（括）[一]（原卷作「括」。）州（斯二七一七）', '4127d5c0-8b35-4ecf-b88f-dfafc0073f02', '唐', '["委迤吳山雲，演漾洞庭水。","青楓既愁人，白頻（蘋）亦靡靡。","送君出京國，孤舟眇江氾。","（「江氾」，蔣云當作「江汜」。","）浮陽怨芳歲，況乃別行子。","括蒼漲海壖，斯路天台[□]。","我有巖中念，遙寄四明裏。","（[一]劉云：「『恬』乃『括』之誤，今浙江麗水，唐避德宗諱改處州。","」）。"]', '["委迤吳山云，演漾洞庭水。","青楓既愁人，白頻（蘋）亦靡靡。","送君出京国，孤舟眇江氾。","（「江氾」，蔣云當作「江汜」。","）浮陽怨芳歲，況乃別行子。","括蒼漲海壖，斯路天台[□]。","我有巖中念，遙寄四明裏。","（[一]劉云：「『恬』乃『括』之誤，今浙江丽水，唐避德宗諱改处州。","」）。"]', '诗', 'shi', '', NULL, '送友人向恬（括）[一]（原卷作「括」。）州（斯二七一七） 李適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d41b6773-7e2e-4c43-8d20-26b33f411017', '九日至江州問王使君（斯五五五）', '九日至江州问王使君（斯五五五）', '41885324-7aab-40d5-9f60-d2d3a49f5ea3', '唐', '["九日尋（潯）陽縣，門門有菊花。","□□今送酒，（蔣云：「闕文二當爲『白衣』。","」）若箇是陶家？","（〖1〗按王使君疑指王勃，所以《全唐詩》卷五六把這一首編入王勃名下，恐怕不對。","《全唐詩》的文字不盡相同，錄出以便參閱。","〖項云：「唐代『使君』乃是對刺史的尊稱。","王勃幷未擔任過這類官職。","整『王使君』當另有其人。","蓋王姓江州刺史也。","」「或是王勃道出江州時。","寫給王姓刺史的。","」〗）。"]', '["九日尋（潯）陽縣，门门有菊花。","□□今送酒，（蔣云：「闕文二當爲『白衣』。","」）若箇是陶家？","（〖1〗按王使君疑指王勃，所以《全唐诗》卷五六把這一首編入王勃名下，恐怕不对。","《全唐诗》的文字不尽相同，錄出以便參閱。","〖項云：「唐代『使君』乃是对刺史的尊稱。","王勃幷未擔任過這類官職。","整『王使君』當另有其人。","蓋王姓江州刺史也。","」「或是王勃道出江州时。","寫給王姓刺史的。","」〗）。"]', '诗', 'shi', '', NULL, '九日至江州問王使君（斯五五五） 蔡孚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dfd7481-431a-4f4c-87e3-f22f8faee2a9', '九日', '九日', '41885324-7aab-40d5-9f60-d2d3a49f5ea3', '唐', '["九日重陽節，開門有菊花。"]', '["九日重陽節，开门有菊花。"]', '诗', 'shi', '', NULL, '九日 蔡孚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90e6b2bd-069d-4dc5-9312-657142fa8d30', '雜詩（伯三七七一。下同）', '杂诗（伯三七七一。下同）', '7902da67-399b-4060-aac6-d860d7122958', '唐', '["蹔借金鎚秤，銜涕訴恩波。","君情將妾怨，稱取謂誰多？","秋吹綾紈索[一]，（「綾」原卷作「淩」。","）空閨生網羅。","不期《流水引》，翻作《斷腸歌》？","（[一]俞云：「『綾紈索』三字不可解，必有誤字。","按下句句法，『綾』字當是一個動詞，疑當作『陵紈素』。","」）。"]', '["蹔借金鎚秤，銜涕訴恩波。","君情將妾怨，稱取謂誰多？","秋吹綾紈索[一]，（「綾」原卷作「淩」。","）空閨生網羅。","不期《流水引》，翻作《斷腸歌》？","（[一]俞云：「『綾紈索』三字不可解，必有誤字。","按下句句法，『綾』字當是一個动词，疑當作『陵紈素』。","」）。"]', '诗', 'shi', '', NULL, '雜詩（伯三七七一。下同） 喬備 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00809229-fe6e-48c6-9783-38a1cab1dfe1', '秋夜巫山', '秋夜巫山', '7902da67-399b-4060-aac6-d860d7122958', '唐', '["巫峽徘徊雨，陽臺潭[一]蕩雲。","江山空窈窕，朝暮自氛氳。","螢色寒秋露，猿啼清夜聞。","唯憐夢魂遠，腸斷思紛紛。","（[一]俞云：「『潭』當作『澹』。","」劉云：「潭蕩雙聲字。","」）。"]', '["巫峽徘徊雨，陽台潭[一]蕩云。","江山空窈窕，朝暮自氛氳。","螢色寒秋露，猿啼清夜闻。","唯怜梦魂远，腸斷思紛紛。","（[一]俞云：「『潭』當作『澹』。","」劉云：「潭蕩雙声字。","」）。"]', '诗', 'shi', '', NULL, '秋夜巫山 喬備 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bcc31b2-eb4e-4ef2-8393-8f7db818f4a9', '死馬賦（伯三六一九）', '死马賦（伯三六一九）', '2db6e325-dd83-4eb1-ac3f-9c88f134f464', '唐', '["連山四望何高高，良馬本代君子勞；燕地冰堅傷凍骨，胡天霜縮落縮寒毛。","願君迴來鄉山道，道傍青青饒美草；鞭策尋途未敢迷，希君少留卷（養）[二]疲老。","（「卷」，原卷作「養」。","）君其去去途未窮，悲鳴羸臥此山中；桃花零落三春月，桂枝摧折九秋風。","昔是浮光疑曳練，常時躡景如流電；長揪塵闇形影遙，（「長揪」，蔣、項皆云當作「長楸」。","）上策（林）[三]（「策」，原卷作「葉」。","）日明蹤跡偏（徧）。","漢女[四]彈弦怨離別，楚王興歌苦征戰；赤血霑霑（君）[五]君不知，白骨辭君君不見。","少年馳射出幽幷，高秋搖落重橫行；雲中想見遊龍影，月下思聞飛鵲聲。","千里相思浩如失，一代英雄從此畢；鹽車垂耳不知年，粧樓畫眉寧記日？","高門待封杳無期，遷喬題柱即長辭；（「遷喬」，蔣校作「僊橋」，指成都昇僊橋，用《華陽國志》載司馬相如事。","）八駿馳名終已矣，千金賣（買）骨復何時？","（[一]劉希夷的詩在敦煌卷子裏面傳鈔的不少，如《白頭老翁》〖《全唐詩》作《代悲白頭翁》〗有三個寫本，並且題着劉希夷的名字。","和《死馬賦》寫在同一卷子〖伯三六一九〗上的，還有《擣衣篇》和《北邙篇》〖《全唐詩》作《洛川懷古》〗，《擣衣篇》也題着劉希夷的名字。","此題作「劉希移」，誤。","[二]依俞、劉說。","[三]依劉校。","[四]劉云：「漢女謂烏孫公主，見石崇《王明君辭序》。","」[五]依俞校。","）。"]', '["連山四望何高高，良马本代君子勞；燕地冰堅傷凍骨，胡天霜縮落縮寒毛。","願君迴来乡山道，道傍青青饒美草；鞭策尋途未敢迷，希君少留卷（養）[二]疲老。","（「卷」，原卷作「養」。","）君其去去途未窮，悲鳴羸臥此山中；桃花零落三春月，桂枝摧折九秋风。","昔是浮光疑曳練，常时躡景如流電；长揪塵闇形影遙，（「长揪」，蔣、項皆云當作「长楸」。","）上策（林）[三]（「策」，原卷作「葉」。","）日明蹤跡偏（徧）。","漢女[四]彈弦怨離別，楚王兴歌苦征戰；赤血霑霑（君）[五]君不知，白骨辞君君不见。","少年驰射出幽幷，高秋搖落重橫行；云中想见游龙影，月下思闻飞鵲声。","千里相思浩如失，一代英雄從此畢；鹽车垂耳不知年，粧楼畫眉寧記日？","高门待封杳無期，遷喬題柱即长辞；（「遷喬」，蔣校作「僊橋」，指成都昇僊橋，用《华陽国志》載司马相如事。","）八駿驰名終已矣，千金賣（買）骨复何时？","（[一]劉希夷的诗在敦煌卷子裏面傳鈔的不少，如《白头老翁》〖《全唐诗》作《代悲白头翁》〗有三個寫本，並且題着劉希夷的名字。","和《死马賦》寫在同一卷子〖伯三六一九〗上的，還有《擣衣篇》和《北邙篇》〖《全唐诗》作《洛川懷古》〗，《擣衣篇》也題着劉希夷的名字。","此題作「劉希移」，誤。","[二]依俞、劉说。","[三]依劉校。","[四]劉云：「漢女謂烏孫公主，见石崇《王明君辞序》。","」[五]依俞校。","）。"]', '诗', 'shi', '', NULL, '死馬賦（伯三六一九） 劉希移 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14e7127f-7e01-4dd1-a83a-66bb3708cb18', '北邙篇（[一]伯二六七三斯二○四九伯二五四四）', '北邙篇（[一]伯二六七三斯二○四九伯二五四四）', '2db6e325-dd83-4eb1-ac3f-9c88f134f464', '唐', '["南橋昏曉人萬萬[二]，北邙新故塚千千。","自爲驕奢彼都邑，何圖零落此山顛。","（「爲」，蔣、項皆云通「謂」字。","）不知虛魄尋[三]歸路，但見殭屍委墓田。","青松樂飲無容色，白骨生台（苔）[四]有歲年。","地久□松摧爲薪，（項云闕字應是「青」字。","）天長[五]白骨化爲塵。","碧山明月徒自曉，黃居闇室不知晨。","（「黃居」，蔣云當作「黃泉」。","）漢家城廓（郭）[六]帝王州[七]，晉國衣棺（冠）車馬流。","金國（谷）清（青）春珠騎（綺）舞，同（銅）堦碧樹玉人遊，雲起清盈驕畫閣，水堂明逈弄仙舟。","始憶斷歌催一代，（「斷歌」，項云當作「短歌」。","）娥（俄）悲長夜歷千秋。","秋楓至兮冬雪明，春兩息兮夏雲生。","墨池沙枯通草萬（蔓）[八]，粧樓凡（瓦）[九]盡向林傾。","古篋重書宜筆跡，崩（路）[一○]臺鶴胃若弦聲。","（「篋」，項云當作「{𥫗/巫/八}」，同「策」，謂簡書。","「重書」，項云當作「蟲書」。","「宜」，項云當作「疑」，與「若」「同義對舉」。","）不信草經延墓（暮）[一一]齒，（「草經」，項疑當作「丹」，「丹經」與「青史」爲對。","）惟求清（青）史列虛銘（名）。","嗚呼哀哉洛陽道，相斯（思）相望蓬萊島，玉顏暉暉並是春，人髪青青未嘗老。","星簾捲兮月牎開，鏡花搖兮山樹逈。","（「迥」，蔣、項皆云當作「迴」。","）仙衣窈窕風吹去，雨蓋飛（霏）[一二]微舞遶來。","（「雨蓋」，蔣項皆云當作「羽蓋」。","）與君攜手三山頂，如何冥寞久泉臺。","（「如何」，項云當乙作「何如」。","「久」，項云當作「九」，「九泉」與「三山」爲對。","）（[一]敦煌所出凡三寫本：甲本伯二六七三，乙本斯二○四九，丙本伯二五四四。","丙卷書法極惡劣。","[二]乙丙兩卷並作「暮暮」。","[三]「尋」乙丙兩卷並作「若」。","[四]王云：「『台』應作『苔』，杜甫詩：古人白骨生青苔。","」[五]「白骨」至「天長」十六字，乙丙兩卷並缺。","[六]郭及下「冠」字並依王仲聞先生校。","[七]「州」乙丙兩卷並作「世」。","[八][九][一一][一二]並依劉校。","[一○]「崩」乙丙兩卷並作「路」。","劉云：「當作『露』。","」）。"]', '["南橋昏晓人万万[二]，北邙新故塚千千。","自爲驕奢彼都邑，何圖零落此山顛。","（「爲」，蔣、項皆云通「謂」字。","）不知虛魄尋[三]归路，但见殭屍委墓田。","青松乐饮無容色，白骨生台（苔）[四]有歲年。","地久□松摧爲薪，（項云闕字應是「青」字。","）天长[五]白骨化爲塵。","碧山明月徒自晓，黄居闇室不知晨。","（「黄居」，蔣云當作「黄泉」。","）漢家城廓（郭）[六]帝王州[七]，晉国衣棺（冠）车马流。","金国（谷）清（青）春珠騎（綺）舞，同（銅）堦碧樹玉人游，云起清盈驕畫閣，水堂明逈弄仙舟。","始憶斷歌催一代，（「斷歌」，項云當作「短歌」。","）娥（俄）悲长夜歷千秋。","秋楓至兮冬雪明，春兩息兮夏云生。","墨池沙枯通草万（蔓）[八]，粧楼凡（瓦）[九]尽向林傾。","古篋重书宜笔跡，崩（路）[一○]台鹤胃若弦声。","（「篋」，項云當作「{𥫗/巫/八}」，同「策」，謂簡书。","「重书」，項云當作「蟲书」。","「宜」，項云當作「疑」，與「若」「同義对舉」。","）不信草經延墓（暮）[一一]齒，（「草經」，項疑當作「丹」，「丹經」與「青史」爲对。","）惟求清（青）史列虛銘（名）。","嗚呼哀哉洛陽道，相斯（思）相望蓬萊島，玉顏暉暉並是春，人髪青青未嘗老。","星簾捲兮月牎开，镜花搖兮山樹逈。","（「迥」，蔣、項皆云當作「迴」。","）仙衣窈窕风吹去，雨蓋飞（霏）[一二]微舞遶来。","（「雨蓋」，蔣項皆云當作「羽蓋」。","）與君携手三山頂，如何冥寞久泉台。","（「如何」，項云當乙作「何如」。","「久」，項云當作「九」，「九泉」與「三山」爲对。","）（[一]敦煌所出凡三寫本：甲本伯二六七三，乙本斯二○四九，丙本伯二五四四。","丙卷书法極惡劣。","[二]乙丙兩卷並作「暮暮」。","[三]「尋」乙丙兩卷並作「若」。","[四]王云：「『台』應作『苔』，杜甫诗：古人白骨生青苔。","」[五]「白骨」至「天长」十六字，乙丙兩卷並缺。","[六]郭及下「冠」字並依王仲闻先生校。","[七]「州」乙丙兩卷並作「世」。","[八][九][一一][一二]並依劉校。","[一○]「崩」乙丙兩卷並作「路」。","劉云：「當作『露』。","」）。"]', '诗', 'shi', '', NULL, '北邙篇（[一]伯二六七三斯二○四九伯二五四四） 劉希移 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c60496bf-3e78-42af-b07f-5b4e85b20a30', '長門怨（[一]伯三一九五二七四八）', '长门怨（[一]伯三一九五二七四八）', '731e9b49-ee20-4ff8-bd91-ec0de109c10a', '唐', '["長安[二]桂殿倚空城，每至黃昏愁轉盈，舊來偏得君王意，今是無端寵愛輕。","窈窕容華爲誰惜，長門一閉無行跡，聞道他人更可憐，懸知欲垢終無益。","（「垢」，蔣、項皆云當作「妬」。","二本原卷此字作「姤」。","）星移北斗露凄凄，羅幔䄡䄡風入閨，（「䄡䄡」，項云當作「襜襜」）孤燈欲滅留殘焰，明月初團照夜啼。","向月唯須影調逐，不如纔（疇）[三]昔同今（八）屋，雲浮彫練此城[四]遊，（「練」，蔣疑當作「棟」，項云當是「闌」字的形訛。","「彫闌」同「雕欄」。","）花綴珠衾紫臺宿。","自從捐棄在深宮，君處芳音更不通，黃今（金）買得《長門賦》，祇爲寒床夜夜空。","（[一]《樂府詩集》卷四十二載《長門怨》二十七首，作者二十三人，不及魏奉古。","這首《長門怨》，好像宋代已經不很流傳了。","[二]「長安」原卷作「長門」依伯二七四八號寫本改。","[三]依俞說。","[四]俞云：「此城疑北城，但未敢定。","」）。"]', '["长安[二]桂殿倚空城，每至黄昏愁轉盈，旧来偏得君王意，今是無端寵愛轻。","窈窕容华爲誰惜，长门一閉無行跡，闻道他人更可怜，懸知欲垢終無益。","（「垢」，蔣、項皆云當作「妬」。","二本原卷此字作「姤」。","）星移北斗露凄凄，羅幔䄡䄡风入閨，（「䄡䄡」，項云當作「襜襜」）孤灯欲滅留殘焰，明月初團照夜啼。","向月唯須影調逐，不如纔（疇）[三]昔同今（八）屋，云浮彫練此城[四]游，（「練」，蔣疑當作「棟」，項云當是「闌」字的形訛。","「彫闌」同「雕欄」。","）花綴珠衾紫台宿。","自從捐棄在深宮，君处芳音更不通，黄今（金）買得《长门賦》，祇爲寒床夜夜空。","（[一]《乐府诗集》卷四十二載《长门怨》二十七首，作者二十三人，不及魏奉古。","這首《长门怨》，好像宋代已經不很流傳了。","[二]「长安」原卷作「长门」依伯二七四八號寫本改。","[三]依俞说。","[四]俞云：「此城疑北城，但未敢定。","」）。"]', '诗', 'shi', '', NULL, '長門怨（[一]伯三一九五二七四八） 魏奉古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c169822-fbf9-4cc0-ade4-fcb945e1a05e', '次河神廟虞參軍船先發余阻風不進寒夜旅泊（斯二七一七下同）', '次河神廟虞參軍船先發余阻风不進寒夜旅泊（斯二七一七下同）', '0536a467-982d-4f42-8c39-94abb9d9dfe1', '唐', '["朝謁馮夷詞（祠），夕投投孟津渚。","風長川淼漫，河闊舟容與。","迴首望歸途，連山曖相拒。","落帆遵逈岸，輟榜依孤嶼。","復值驚彼（波）息，戒徒候前侶。","川路雖未遙，心期頓爲阻。","沉沉落日暮，切切涼飈舉。","白露濕寒葭，蒼烟晦平楚。","啼猿響巖谷，淚鶴聞河溆。","此時懷故人，依然愴行旅。","何當欣既覯，鬱陶共君敍。"]', '["朝謁馮夷词（祠），夕投投孟津渚。","风长川淼漫，河闊舟容與。","迴首望归途，連山曖相拒。","落帆遵逈岸，輟榜依孤嶼。","复值驚彼（波）息，戒徒候前侶。","川路雖未遙，心期頓爲阻。","沉沉落日暮，切切涼飈舉。","白露濕寒葭，蒼烟晦平楚。","啼猿响巖谷，泪鹤闻河溆。","此时懷故人，依然愴行旅。","何當欣既覯，鬱陶共君敍。"]', '诗', 'shi', '', NULL, '次河神廟虞參軍船先發余阻風不進寒夜旅泊（斯二七一七下同） 劉知幾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63e84be7-734e-41a9-b173-4a79de070797', '讀《漢書》作', '读《漢书》作', '0536a467-982d-4f42-8c39-94abb9d9dfe1', '唐', '["漢王有天下，欻起布衣中。","奮飛出草澤，嘯咤馭羣雄。","淮陰既附鳯，黥彭亦攀龍，一朝逢運會，南面皆王公。","魚得自忘筌，鳥盡必藏弓，咄嗟罹鼎俎，赤族無遺蹤。","智裁（哉）張子房，處世獨爲工；功成薄愛（受）[一]賞，（「愛」，蔣云當作「爵」。","）高舉追赤松。","知止信無辱，身安道亦隆，悠悠[千]載後，擊抃（柝）[二]仰遺風。","（「擊抃」，蔣、項皆云「抃」字不誤。","）（[一][二]並依俞說。","劉云：「左思《詠史》，功成不受爵。","」）。"]', '["漢王有天下，欻起布衣中。","奮飞出草澤，嘯咤馭羣雄。","淮陰既附鳯，黥彭亦攀龙，一朝逢運會，南面皆王公。","鱼得自忘筌，鸟尽必藏弓，咄嗟罹鼎俎，赤族無遺蹤。","智裁（哉）張子房，处世独爲工；功成薄愛（受）[一]賞，（「愛」，蔣云當作「爵」。","）高舉追赤松。","知止信無辱，身安道亦隆，悠悠[千]載後，擊抃（柝）[二]仰遺风。","（「擊抃」，蔣、項皆云「抃」字不誤。","）（[一][二]並依俞说。","劉云：「左思《詠史》，功成不受爵。","」）。"]', '诗', 'shi', '', NULL, '讀《漢書》作 劉知幾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aab41025-4350-4ee5-ae77-71dd10dd3913', '詠史', '詠史', '0536a467-982d-4f42-8c39-94abb9d9dfe1', '唐', '["汎汎水中蓱，離離岸傍草，逐浪高復下，從風起還倒。","人生不若茲，處世安可保？","遽瑗仕衛國，屈伸隨世道；方朔隱漢朝，易農以爲寶。","飲啄得其性，從容成壽考。","南國有狂生，形容獨枯槁，作賦刺椒蘭，投江溺流潦。","達人無不可，委軍（運）推蒼昊；何爲明白（自）銷[一]，取譏於楚老？","（[一]、王云：「『軍』疑應作『運』『白』疑應作『自』，用《漢書·龔勝傳》語。","」）。"]', '["汎汎水中蓱，離離岸傍草，逐浪高复下，從风起還倒。","人生不若茲，处世安可保？","遽瑗仕衛国，屈伸隨世道；方朔隐漢朝，易農以爲寶。","饮啄得其性，從容成壽考。","南国有狂生，形容独枯槁，作賦刺椒蘭，投江溺流潦。","達人無不可，委軍（運）推蒼昊；何爲明白（自）銷[一]，取譏於楚老？","（[一]、王云：「『軍』疑應作『運』『白』疑應作『自』，用《漢书·龔勝傳》語。","」）。"]', '诗', 'shi', '', NULL, '詠史 劉知幾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01ca06cb-3a38-4948-b995-257d4d08785c', '昭君怨（其三。斯五五五）', '昭君怨（其三。斯五五五）', '11c95f86-6a85-4e81-9f65-3460b19b8e7f', '唐', '["萬里胡風急，三秋[□]漢初。","唯望南去雁，不肯爲傳書。","（按這詩的其一、其二、其四三首已載《全唐詩》，故僅補「其三」一首。","）。"]', '["万里胡风急，三秋[□]漢初。","唯望南去雁，不肯爲傳书。","（按這诗的其一、其二、其四三首已載《全唐诗》，故僅補「其三」一首。","）。"]', '诗', 'shi', '', NULL, '昭君怨（其三。斯五五五） 東方虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54f5b888-797c-4037-bf80-90cb08fa3434', '成（城）南宴（斯五五五）', '成（城）南宴（斯五五五）', '92c32022-4645-4e50-9f25-33821cf4d610', '唐', '["禦（御）宿上林春欲盡，殘花弱柳任風吹。","鬬雞走馬□□□，樂煞長安遊俠兒。"]', '["禦（御）宿上林春欲尽，殘花弱柳任风吹。","鬬雞走马□□□，乐煞长安游俠兒。"]', '诗', 'shi', '', NULL, '成（城）南宴（斯五五五） 李行言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75e4f4e7-fd1f-4ce2-892f-3c9efedba600', '宴盧十四南園得園韻（伯三七七一下同）', '宴盧十四南园得园韻（伯三七七一下同）', '1497e36b-6fa0-4c96-a6af-49d09942f33e', '唐', '["超遙乘暇景，灑散絕浮喧。","寫望峯雲出，開襟夏木繁。","野人憐狎鳥，遊子愛芳蓀。","臥篠低臨席，驚流注滿園。","□然林下意，琴酌坐忘言。"]', '["超遙乘暇景，灑散絕浮喧。","寫望峯云出，开襟夏木繁。","野人怜狎鸟，游子愛芳蓀。","臥篠低臨席，驚流注满园。","□然林下意，琴酌坐忘言。"]', '诗', 'shi', '', NULL, '宴盧十四南園得園韻（伯三七七一下同） 元希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4f5f7d8-629c-406e-b962-baf7efd628fb', '贈皇甫侍御赴都（其二）', '贈皇甫侍御赴都（其二）', '1497e36b-6fa0-4c96-a6af-49d09942f33e', '唐', '["猗嗟衆珍，以況君子。","公侯之胄，必復其始。","香器長材，溫儀峻峙。","顯此元明，於斯備矣。","（按此詩凡八首，已載《全唐詩》。","惟「其二」缺末兩句，故依《珠英集》補全之。","）。"]', '["猗嗟衆珍，以況君子。","公侯之胄，必复其始。","香器长材，溫儀峻峙。","显此元明，於斯備矣。","（按此诗凡八首，已載《全唐诗》。","惟「其二」缺末兩句，故依《珠英集》補全之。","）。"]', '诗', 'shi', '', NULL, '贈皇甫侍御赴都（其二） 元希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('155d79c6-3d0c-46cf-9af0-5061e5f5692c', '秋夜讌徐四山亭（伯三七七一）', '秋夜讌徐四山亭（伯三七七一）', '2c6f7538-27b1-4952-8ee8-2b240022c44b', '唐', '["卷言北山岑，（「卷言」，項云當作「眷言」。","）非謂靡遠尋。","庭際有幽石，自然保遐心。","月下池涼（涼池）[一]彩，（「下池」，蔣項皆云二字當互乙。","蔣云「月池」與「風竹」相對，項云「涼彩」猶冷光也。","）風竹來清音。","樽酒古籍人意，蒼蒼寒露深。","（[一]池涼二字當互倒，深是動詞。","劉云：「『池』管作『遲』，待也。","」）。"]', '["卷言北山岑，（「卷言」，項云當作「眷言」。","）非謂靡远尋。","庭際有幽石，自然保遐心。","月下池涼（涼池）[一]彩，（「下池」，蔣項皆云二字當互乙。","蔣云「月池」與「风竹」相对，項云「涼彩」猶冷光也。","）风竹来清音。","樽酒古籍人意，蒼蒼寒露深。","（[一]池涼二字當互倒，深是动词。","劉云：「『池』管作『遲』，待也。","」）。"]', '诗', 'shi', '', NULL, '秋夜讌徐四山亭（伯三七七一） 楊齊悊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3650f2d2-92e2-4f0a-b138-eaf4aa2a068d', '奉使松府（伯三七七一。下同）', '奉使松府（伯三七七一。下同）', 'd00ba6cc-2267-469b-af31-f00225e83ff3', '唐', '["蜀山固地險，（項云「固」當作「匝」，形近而訛。","）漢水接天平。","波濤去東別[一]，林嶂隱西傾[二]。","露白蓬根斷，風秋草葉鳴。","孤舟忽不見，垂淚坐盈盈。","（[一]劉云：「東別謂大別也。","《禹貢》漢水又區爲滄浪之水，至於大別。","」[二]劉云：「西傾謂西傾山。","」）。"]', '["蜀山固地險，（項云「固」當作「匝」，形近而訛。","）漢水接天平。","波濤去东別[一]，林嶂隐西傾[二]。","露白蓬根斷，风秋草葉鳴。","孤舟忽不见，垂泪坐盈盈。","（[一]劉云：「东別謂大別也。","《禹貢》漢水又區爲滄浪之水，至於大別。","」[二]劉云：「西傾謂西傾山。","」）。"]', '诗', 'shi', '', NULL, '奉使松府（伯三七七一。下同） 胡皓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b2ca32e-7c6d-45e6-8e2d-708a615f5a61', '夜行黃花川', '夜行黄花川', 'd00ba6cc-2267-469b-af31-f00225e83ff3', '唐', '["的的（旳旳）夜綿綿，斜斗歷高天。","露浩空山月，風秋洞壑泉。","飢鼯啼遠樹，暗鳥宿長川。"]', '["的的（旳旳）夜綿綿，斜斗歷高天。","露浩空山月，风秋洞壑泉。","飢鼯啼远樹，暗鸟宿长川。"]', '诗', 'shi', '', NULL, '夜行黃花川 胡皓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88774b71-50aa-4c15-9d93-be2099d9221b', '奉天田明府席餞別', '奉天田明府席餞別', 'd00ba6cc-2267-469b-af31-f00225e83ff3', '唐', '["屬城富才雄，文園餞席同。","此席何所餞？徭役五原中。","疾沙亂飛雪，連車條轉蓬。","雁歸寒塞近，客散祖亭空。","日夕不遑次，蕭條鳴朔風。"]', '["屬城富才雄，文园餞席同。","此席何所餞？徭役五原中。","疾沙亂飞雪，連车條轉蓬。","雁归寒塞近，客散祖亭空。","日夕不遑次，蕭條鳴朔风。"]', '诗', 'shi', '', NULL, '奉天田明府席餞別 胡皓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b90f5158-2d28-404b-acf2-86272ea4cd2f', '答徐四蕭關別醉後見投', '答徐四蕭关別醉後见投', 'd00ba6cc-2267-469b-af31-f00225e83ff3', '唐', '["蕭關城南隴入雲，蕭關城北海生荒[一]。","（蔣云：「荒」即「塵」字草書之誤。","）咄嗟塞外同爲客，滿酌杯中一送君。","（[一]劉云：「『荒』字不叶韻，不知是何字誤？","」）。"]', '["蕭关城南隴入云，蕭关城北海生荒[一]。","（蔣云：「荒」即「塵」字草书之誤。","）咄嗟塞外同爲客，满酌杯中一送君。","（[一]劉云：「『荒』字不叶韻，不知是何字誤？","」）。"]', '诗', 'shi', '', NULL, '答徐四蕭關別醉後見投 胡皓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfa5a23c-1308-4c76-9c25-6cd132afcdc9', '春悲行（伯三七七一下同）', '春悲行（伯三七七一下同）', 'd00ba6cc-2267-469b-af31-f00225e83ff3', '唐', '["夜鵲南飛倦，鳴雞屢送晨，忽聞芳歲道（到），今日故園春。","試上亭臺望，葐蒀（氛氳）江樹新。","（項云「葐蒀」爲草木茂盛之貌，不煩改。","）旳旳韶陽蕚，迢迢佳麗人，音容曠不接，景物徒相因。","別怨如流水，移恩念積薪，垂淚三危露，心斵[一]（「斵」，原卷作「斷」。","）二京塵。","遠役鴻爲伴，荒亭鬼作隣，吾生殊卉木，顦顇此江濱。","（[一]俞云：「『心斵』疑『心斷』。","」）。"]', '["夜鵲南飞倦，鳴雞屢送晨，忽闻芳歲道（到），今日故园春。","試上亭台望，葐蒀（氛氳）江樹新。","（項云「葐蒀」爲草木茂盛之貌，不煩改。","）旳旳韶陽蕚，迢迢佳丽人，音容曠不接，景物徒相因。","別怨如流水，移恩念積薪，垂泪三危露，心斵[一]（「斵」，原卷作「斷」。","）二京塵。","远役鴻爲伴，荒亭鬼作隣，吾生殊卉木，顦顇此江濱。","（[一]俞云：「『心斵』疑『心斷』。","」）。"]', '诗', 'shi', '', NULL, '春悲行（伯三七七一下同） 胡皓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6814928-84c3-43d0-8c00-e0373f7371e7', '渝州逢故人（「渝州」，原作「滁州」，從原卷改。）', '渝州逢故人（「渝州」，原作「滁州」，從原卷改。）', 'd00ba6cc-2267-469b-af31-f00225e83ff3', '唐', '["共是他鄉客，俱爲失路人。","自憐蓬髪改，不掩柳條春。"]', '["共是他乡客，俱爲失路人。","自怜蓬髪改，不掩柳條春。"]', '诗', 'shi', '', NULL, '渝州逢故人（「渝州」，原作「滁州」，從原卷改。） 胡皓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91c421a1-f97b-4f7b-bc6e-6d2674892e3a', '感春', '感春', 'd00ba6cc-2267-469b-af31-f00225e83ff3', '唐', '["試登高臺春，伏檻弄陽旭。","紆寂融密思，韶和洗紛矚。","林暖花意紅，墀薰草情綠。","感物深自負，萋萋楊□□。","（〖1〗右三首，載於伯三七七一《珠英集》殘卷的開端。","原共五首，不著撰人。","第四首《奉天田明府席餞別》第五首《答徐四蕭關別醉後見投》與後重出。","已據重出部份的題名載入胡皓詩內。","因疑前三首亦胡皓所作，故附於此。","即非胡皓所作，亦必爲其他《珠英》學士的作品。","）。"]', '["試登高台春，伏檻弄陽旭。","紆寂融密思，韶和洗紛矚。","林暖花意紅，墀薰草情綠。","感物深自負，萋萋楊□□。","（〖1〗右三首，載於伯三七七一《珠英集》殘卷的开端。","原共五首，不著撰人。","第四首《奉天田明府席餞別》第五首《答徐四蕭关別醉後见投》與後重出。","已據重出部份的題名載入胡皓诗內。","因疑前三首亦胡皓所作，故附於此。","即非胡皓所作，亦必爲其他《珠英》学士的作品。","）。"]', '诗', 'shi', '', NULL, '感春 胡皓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53f18b68-b234-4e53-9d61-ee745c536566', '詠螢（斯五五五）', '詠螢（斯五五五）', '394e26a1-3ca6-4b91-b5e2-32a0d646ac6f', '唐', '["旳旳黃金色，□□白玉輝。","既能明自□，□用暗中飛。","（蔣云兩句當作：「既能明自照，何用暗中飛？","」與杜甫《倦夜》句式同。","）。"]', '["旳旳黄金色，□□白玉輝。","既能明自□，□用暗中飞。","（蔣云兩句當作：「既能明自照，何用暗中飞？","」與杜甫《倦夜》句式同。","）。"]', '诗', 'shi', '', NULL, '詠螢（斯五五五） 蘇晉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a25229bd-a72b-4d6d-a83b-d234738af8e7', '揚子江夜宴（伯三六一九）', '揚子江夜宴（伯三六一九）', '181c8f3f-39df-4f86-8488-91810ee13064', '唐', '["楚水夜潮平，仙舟燼燭明。","美人歌一曲，坐客不勝情。","羅幕香風倦，紗巾舞袖輕；遨遊正得意，雲雨莫來迎。"]', '["楚水夜潮平，仙舟燼燭明。","美人歌一曲，坐客不勝情。","羅幕香风倦，紗巾舞袖轻；遨游正得意，云雨莫来迎。"]', '诗', 'shi', '', NULL, '揚子江夜宴（伯三六一九） 蔡希寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed223f71-efc4-4457-b27d-3e49ff709b32', '度巴硤（伯三六一九[一]）', '度巴硤（伯三六一九[一]）', 'f48b5408-126d-4e8d-af9c-3d91a7c24766', '唐', '["客從巴硤度（水渡）[二]，傳子（爾）訴（泝）行舟。","是日風波濟（霽）（蔣云「濟」有「止」意，《莊子》、《淮南子》中均有〖風濟〗的用法，不必改。","），高塘（堂）[三]雨半收。","青山滿蜀道，渌（綠）水向荆州。","不作書相慰（問），何（誰）能散（慰）別愁。","（皎然《詩式》卷三引「青山滿蜀道，渌水向荆州」二句，作「崔顥《別人》」。","）（[一]按原卷載詩三首：一《綵雲篇》，二《度巴峽》，三《秋夜泊江渚》。","第一首題下有李邕名。","檢《全唐詩》第一第三兩首正是李邕作，但第一首詩題作「詠雲」，第三首殘。","[二]按此詩見《全唐詩》二函九冊，謂爲崔顥作，題作『贈盧八象』。","故此據敦煌卷先用互著例載入李邕，然後據《全唐詩》校其異文，凡九事。","茲作說明於第一事下。","[三]俞云：「『高塘』應作『高唐』，兩本俱誤。","」）。"]', '["客從巴硤度（水渡）[二]，傳子（爾）訴（泝）行舟。","是日风波濟（霽）（蔣云「濟」有「止」意，《莊子》、《淮南子》中均有〖风濟〗的用法，不必改。","），高塘（堂）[三]雨半收。","青山满蜀道，渌（綠）水向荆州。","不作书相慰（问），何（誰）能散（慰）別愁。","（皎然《诗式》卷三引「青山满蜀道，渌水向荆州」二句，作「崔顥《別人》」。","）（[一]按原卷載诗三首：一《綵云篇》，二《度巴峽》，三《秋夜泊江渚》。","第一首題下有李邕名。","檢《全唐诗》第一第三兩首正是李邕作，但第一首诗題作「詠云」，第三首殘。","[二]按此诗见《全唐诗》二函九冊，謂爲崔顥作，題作『贈盧八象』。","故此據敦煌卷先用互著例載入李邕，然後據《全唐诗》校其異文，凡九事。","茲作说明於第一事下。","[三]俞云：「『高塘』應作『高唐』，兩本俱誤。","」）。"]', '诗', 'shi', '', NULL, '度巴硤（伯三六一九[一]） 李邕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3045d728-ed06-4040-8218-a63a9bc470f9', '□□（伯三八八五[一]三六一九） 一', '□□（伯三八八五[一]三六一九） 一', 'f48b5408-126d-4e8d-af9c-3d91a7c24766', '唐', '["忽（傳）[二]聞天子訪沉淪，萬里迢迢遠赴（懷書西入）秦。","早□（知）不用無媒客，悔度（恨別）江南楊柳春。","（原卷題爲李邕作。","按此詩亦見伯三六一九卷，亦無題。","[二]此詩又見《全唐詩》第十一函第八冊，載入無名氏二。","有異文四事，旁注者皆是。","又原卷題李邕，自當有據，可正《全唐詩》入無名氏之誤。","）。"]', '["忽（傳）[二]闻天子訪沉淪，万里迢迢远赴（懷书西入）秦。","早□（知）不用無媒客，悔度（恨別）江南楊柳春。","（原卷題爲李邕作。","按此诗亦见伯三六一九卷，亦無題。","[二]此诗又见《全唐诗》第十一函第八冊，載入無名氏二。","有異文四事，旁注者皆是。","又原卷題李邕，自當有據，可正《全唐诗》入無名氏之誤。","）。"]', '诗', 'shi', '', NULL, '□□（伯三八八五[一]三六一九） 一 李邕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9fd7c7d-17bd-4beb-bc24-d07823989496', '□□（伯三八八五[一]三六一九） 二', '□□（伯三八八五[一]三六一九） 二', 'f48b5408-126d-4e8d-af9c-3d91a7c24766', '唐', '["□□（明時）[一]奉遣出（別）皇（黃）州，行至漢陽南渡頭。","春風不解傳鄉信，江月偏能照客愁。","（[一]此第二首，又見伯二五五五卷，校其缺字異文三事。","又「渡頭」作「度」，「鄉信」作「香」，不及原卷〖伯三八八五〗之善。","）。"]', '["□□（明时）[一]奉遣出（別）皇（黄）州，行至漢陽南渡头。","春风不解傳乡信，江月偏能照客愁。","（[一]此第二首，又见伯二五五五卷，校其缺字異文三事。","又「渡头」作「度」，「乡信」作「香」，不及原卷〖伯三八八五〗之善。","）。"]', '诗', 'shi', '', NULL, '□□（伯三八八五[一]三六一九） 二 李邕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5afab607-f9f2-4494-9b2b-8d80c825f06c', '寒食篇（伯三六○八[一]）', '寒食篇（伯三六○八[一]）', '26a5f963-1c48-4dcb-8aa2-7f37bdb3bb05', '唐', '["天運四時成一年，八節相迎盡可憐，秋貴重陽冬貴臘，不如寒食在春前。","禁火初從太原起，風俗流傳幾千祀，算取去冬至時，一百五日今朝是。","今年寒食勝常春，總緣天子在東巡，能令氣色隨河洛，斗覺風光商競逐人。","上陽遙見青春見[二]，（「遙見」，原卷作「遙望」。","）洛水橫流遶城殿，波上樓臺列岸明，風光所吹皆流遍。","畫閣盈盈出半天，依稀雲裏見鞦韆，來疑神女從雲下，去似恆娥到月邊。","金閨待看紅粧早，先過陌上垂楊好，花場共鬬汝南鷄，春遊遍[三]在東郊道。","（「遍」，項云應作「偏」。","）千金寶帳綴流蘇，簸瓌[四]還坐錦筵鋪，莫愁光景重窗闇，自有金瓶照乘珠。","心移向者遊遨處，乘舟欲騁凌波步，池中弄水白鷼飛，樹下拋球彩鸎去。","別殿前臨走馬臺，金鞍更送彩毬來。","毬落畫樓攀柳取，枝[五]□（「枝□」，原卷作「枝搖」。","）香徑踏花迴。","良辰更重宜三月，能成晝夜芳菲節，今夜無明月作燈，街衢遊賞何曾歇。","南有龍門對洛城，車馬傾都滿路行，縱使遨遊今日罷，明朝上（尚）自有清明。","（[一]按這一卷子上載《夜燒篇》與《寒食篇》，詩調相同，並無作者姓氏。","攷《全唐詩》王冷然有《夜光篇》，就是《夜燒篇》。","因疑《寒食篇》亦王冷然作，因暫題王冷然名。","[二]劉云：「第二『見』字讀爲『現』。","」[三]劉云：「疑『徧』。","」[四]劉云：「『瓌』當是『瓊』字之誤，骰子叫瓊。","」[五]劉云：「『枝』當作『杖』，即擊球杖。","」）。"]', '["天運四时成一年，八節相迎尽可怜，秋貴重陽冬貴臘，不如寒食在春前。","禁火初從太原起，风俗流傳幾千祀，算取去冬至时，一百五日今朝是。","今年寒食勝常春，總緣天子在东巡，能令氣色隨河洛，斗覺风光商競逐人。","上陽遙见青春见[二]，（「遙见」，原卷作「遙望」。","）洛水橫流遶城殿，波上楼台列岸明，风光所吹皆流遍。","畫閣盈盈出半天，依稀云裏见鞦韆，来疑神女從云下，去似恆娥到月邊。","金閨待看紅粧早，先過陌上垂楊好，花場共鬬汝南鷄，春游遍[三]在东郊道。","（「遍」，項云應作「偏」。","）千金寶帳綴流蘇，簸瓌[四]還坐錦筵鋪，莫愁光景重窗闇，自有金瓶照乘珠。","心移向者游遨处，乘舟欲騁凌波步，池中弄水白鷼飞，樹下拋球彩鸎去。","別殿前臨走马台，金鞍更送彩毬来。","毬落畫楼攀柳取，枝[五]□（「枝□」，原卷作「枝搖」。","）香徑踏花迴。","良辰更重宜三月，能成晝夜芳菲節，今夜無明月作灯，街衢游賞何曾歇。","南有龙门对洛城，车马傾都满路行，縱使遨游今日罷，明朝上（尚）自有清明。","（[一]按這一卷子上載《夜燒篇》與《寒食篇》，诗調相同，並無作者姓氏。","攷《全唐诗》王冷然有《夜光篇》，就是《夜燒篇》。","因疑《寒食篇》亦王冷然作，因暫題王冷然名。","[二]劉云：「第二『见』字读爲『現』。","」[三]劉云：「疑『徧』。","」[四]劉云：「『瓌』當是『瓊』字之誤，骰子叫瓊。","」[五]劉云：「『枝』當作『杖』，即擊球杖。","」）。"]', '诗', 'shi', '', NULL, '寒食篇（伯三六○八[一]） 王冷然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36373444-1ca8-43c3-8285-6d64d02f6ed0', '馴鴿篇（幷序。伯二五五二下同）', '馴鴿篇（幷序。伯二五五二下同）', '4835e3a8-cb3e-406b-bd92-c7fe981bca5b', '唐', '["君不見賈誼寰中推逸才，⿰亻丸香坐處館常開。","（⿰亻丸，蔣、項皆云應作「仇」。","仇香爲後漢人，曾任主簿，此處借指賈季良。","）栖鸞未即冲天去，馴鴿先能聽□□。","（蔣云闕文爲「事來」二字，「聽事」即「廳事」。","）亦聞無角巢君屋，諸處不栖如[一]擇林[二]。","（「林」，原作「木」。","）寧隨賀鷰空繞梁，爲逐遷鸎俱□□，風窻月戶清節凉，撫翼和鳴君子旁。","雙影時時臨硯水，輕毛片片落書□。","（蔣云闕文當爲「窗」字。","）□君德，輝彩鮮鮮生羽翼；感君心，靈慶昭昭相應深。","何必淮南投小吏，飛來□□化爲金[三]。","（[一]俞云：「『如』疑『知』。","」[二]劉云：「『林』當作『木』與屋爲韻。」","《世說新語·語言篇》：李弘度說：「窮猿奔林，豈暇擇木。","」[三]劉云：「《搜神記》張灝爲梁相，有鵲化爲一圓石，灝破之得一金印。","」）。"]', '["君不见賈誼寰中推逸才，⿰亻丸香坐处館常开。","（⿰亻丸，蔣、項皆云應作「仇」。","仇香爲後漢人，曾任主簿，此处借指賈季良。","）栖鸾未即冲天去，馴鴿先能听□□。","（蔣云闕文爲「事来」二字，「听事」即「廳事」。","）亦闻無角巢君屋，諸处不栖如[一]擇林[二]。","（「林」，原作「木」。","）寧隨賀鷰空繞梁，爲逐遷鸎俱□□，风窻月戶清節凉，撫翼和鳴君子旁。","雙影时时臨硯水，轻毛片片落书□。","（蔣云闕文當爲「窗」字。","）□君德，輝彩鲜鲜生羽翼；感君心，靈慶昭昭相應深。","何必淮南投小吏，飞来□□化爲金[三]。","（[一]俞云：「『如』疑『知』。","」[二]劉云：「『林』當作『木』與屋爲韻。」","《世说新語·語言篇》：李弘度说：「窮猿奔林，豈暇擇木。","」[三]劉云：「《搜神記》張灝爲梁相，有鵲化爲一圓石，灝破之得一金印。","」）。"]', '诗', 'shi', '', NULL, '馴鴿篇（幷序。伯二五五二下同） 李昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdfe174e-7592-4beb-a924-6c1ced36f433', '塞上聽彈胡笳作（幷序）', '塞上听彈胡笳作（幷序）', '4835e3a8-cb3e-406b-bd92-c7fe981bca5b', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, '塞上聽彈胡笳作（幷序） 李昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('061b5fe2-b247-4d80-88fb-c76b48027e5e', '題雍丘崔明府丹竈（伯二五六七。下同）', '題雍丘崔明府丹竈（伯二五六七。下同）', '4835e3a8-cb3e-406b-bd92-c7fe981bca5b', '唐', '["聞君小邑蹔鳴絃，隱几灰心有歲年。","白石既燒應化鶴，黃金未熟且烹鮮。","鑪中近染三花氣，樹裏新飛五色煙。","伊尹即今須負鼎，王喬何事欲冲天。"]', '["闻君小邑蹔鳴絃，隐几灰心有歲年。","白石既燒應化鹤，黄金未熟且烹鲜。","鑪中近染三花氣，樹裏新飞五色煙。","伊尹即今須負鼎，王喬何事欲冲天。"]', '诗', 'shi', '', NULL, '題雍丘崔明府丹竈（伯二五六七。下同） 李昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4cbc085-d4d1-4b0c-b2af-de5365d7dd3e', '睢陽送韋參軍還汾上（此公元昆任睢陽參軍）', '睢陽送韋參軍還汾上（此公元昆任睢陽參軍）', '4835e3a8-cb3e-406b-bd92-c7fe981bca5b', '唐', '["世業重籯金，青春映士林，文華兩孫楚，兄弟二曾參。","竹抱盧門[一]暗，山銜晉國深，預知汾水上，一雁有遺音。","（[一]劉云：「盧門見《左傳》，宋國門名，此用以表睢陽。","」）（〖1〗右李昂詩四首，同寫一卷上，但不在一處，原卷今亦裂爲兩截。","前兩首在前截〖伯二五五二〗之末，題李昂名，其爲李昂作無疑。","後兩首與《戚夫人楚舞歌》均在後截〖伯二五六七〗，並無撰人姓氏，因《唐詩紀事》以《楚舞歌》爲李昂作，羅振玉因定此兩首亦爲李昂作。","《塞上聽彈胡笳》詩內的韋公可能和在睢陽送的韋參軍是一人，惑有一定關係，這也是把這兩詩定爲李昂作的一點小小旁證。","）。"]', '["世業重籯金，青春映士林，文华兩孫楚，兄弟二曾參。","竹抱盧门[一]暗，山銜晉国深，預知汾水上，一雁有遺音。","（[一]劉云：「盧门见《左傳》，宋国门名，此用以表睢陽。","」）（〖1〗右李昂诗四首，同寫一卷上，但不在一处，原卷今亦裂爲兩截。","前兩首在前截〖伯二五五二〗之末，題李昂名，其爲李昂作無疑。","後兩首與《戚夫人楚舞歌》均在後截〖伯二五六七〗，並無撰人姓氏，因《唐诗紀事》以《楚舞歌》爲李昂作，羅振玉因定此兩首亦爲李昂作。","《塞上听彈胡笳》诗內的韋公可能和在睢陽送的韋參軍是一人，惑有一定关係，這也是把這兩诗定爲李昂作的一点小小旁證。","）。"]', '诗', 'shi', '', NULL, '睢陽送韋參軍還汾上（此公元昆任睢陽參軍） 李昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7b6e221-248c-4590-911f-3e4f06bdc66b', '答韓丈[一]（「韓丈」，原卷作「韓大」。疑非韓滉。）（伯二五六七下同）', '答韓丈[一]（「韓丈」，原卷作「韓大」。疑非韓滉。）（伯二五六七下同）', '848118cd-09ab-4bb1-a9f0-c87d2f8e18e0', '唐', '["行人輩，莫相催，相看日暮何徘徊。","登孤舟，望遠水，殷勤留語勸求仕。","疇昔主司曾見知，琳琅叢中拔一枝。","且得免輪天子課，何能屈腰鄉里兒。","長安落葉酒[二]，（「落葉」，原卷作「桒落」，「桒」爲「桑」的別寫。","）或可此時望携手；官班眼（服）[三]色不相當，拂衣還作捕魚郎。","（[一]《唐詩紀事》卷十七說丘爲八十多歲的時候丁了母憂，「觀察使韓滉以致仕官給禄」，韓滉大概就是這裏的韓丈。","[二]劉云：「當是落桑酒。","」[三]依劉校。","）。"]', '["行人輩，莫相催，相看日暮何徘徊。","登孤舟，望远水，殷勤留語勸求仕。","疇昔主司曾见知，琳琅叢中拔一枝。","且得免輪天子課，何能屈腰乡里兒。","长安落葉酒[二]，（「落葉」，原卷作「桒落」，「桒」爲「桑」的別寫。","）或可此时望携手；官班眼（服）[三]色不相當，拂衣還作捕鱼郎。","（[一]《唐诗紀事》卷十七说丘爲八十多歲的时候丁了母憂，「观察使韓滉以致仕官給禄」，韓滉大概就是這裏的韓丈。","[二]劉云：「當是落桑酒。","」[三]依劉校。","）。"]', '诗', 'shi', '', NULL, '答韓丈[一]（「韓丈」，原卷作「韓大」。疑非韓滉。）（伯二五六七下同） 丘爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('356f89d3-b1d0-4b76-956b-c42e045dc4eb', '辛四臥病舟中羣公招登慈和寺', '辛四臥病舟中羣公招登慈和寺', '848118cd-09ab-4bb1-a9f0-c87d2f8e18e0', '唐', '["柳色扁舟帶水陰，聞君臥疾引登臨。","憑高始見三吳勢，望遠因知四海心。","山僧午後清禪洽，羣木晴初綠靄深。","雲外翩翩飛鳥盡，令人宛自動歸吟。"]', '["柳色扁舟带水陰，闻君臥疾引登臨。","憑高始见三吳勢，望远因知四海心。","山僧午後清禪洽，羣木晴初綠靄深。","云外翩翩飞鸟尽，令人宛自动归吟。"]', '诗', 'shi', '', NULL, '辛四臥病舟中羣公招登慈和寺 丘爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7ee04a6-8848-407f-b1d9-d00416753eb2', '對雨聞鸎', '对雨闻鸎', '848118cd-09ab-4bb1-a9f0-c87d2f8e18e0', '唐', '["垂柳街頭百丈絲，杏花林處度黃鸝。","間關正在秦箏裏，歷亂偏傷楚客時。","風傳一一聲來盡，雨濕雙雙飛去遲；羨爾能將戶客意，何如棲得上林枝。"]', '["垂柳街头百丈絲，杏花林处度黄鸝。","间关正在秦箏裏，歷亂偏傷楚客时。","风傳一一声来尽，雨濕雙雙飞去遲；羨爾能將戶客意，何如棲得上林枝。"]', '诗', 'shi', '', NULL, '對雨聞鸎 丘爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4752656e-b251-4f41-bc2c-f0ebbc5171f0', '幽渚雲', '幽渚云', '848118cd-09ab-4bb1-a9f0-c87d2f8e18e0', '唐', '["漠漠雲在渚，無心去何從。","（「何」下原卷衍「疑」字。","）青連晚湖色，澹起秋煙客（容）[一]。","（「客」，原卷作「容」，与王校合。","）渡水上下白，歸山深淺重，來爲巫峽女，去逐葛川龍。","勿爲長幽滯，當飛第一峯。","（[一]依王仲聞先生校。","）。"]', '["漠漠云在渚，無心去何從。","（「何」下原卷衍「疑」字。","）青連晚湖色，澹起秋煙客（容）[一]。","（「客」，原卷作「容」，与王校合。","）渡水上下白，归山深淺重，来爲巫峽女，去逐葛川龙。","勿爲长幽滯，當飞第一峯。","（[一]依王仲闻先生校。","）。"]', '诗', 'shi', '', NULL, '幽渚雲 丘爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('beaafbbf-ccaa-400f-8a45-6bb0fe633d22', '傷河龕老人[一]', '傷河龕老人[一]', '848118cd-09ab-4bb1-a9f0-c87d2f8e18e0', '唐', '["老人甲子難計論，耳中白毛三十根。","釣魚幾年如一日，船舷數寸青苔痕。","人生性命必歸正（止）[二]，（「正」，原卷作「止」。","）精魂傷夫[三]向流水。","（「魂」，伯二五六七卷作「魄」。","）月如鈎在輪影中，風似人來𥭳（荻）聲裏。","蒲葉高低沒釣磯，破舟仍繫綠楊枝。","水流不爲人流去，魚樂寧知人樂時。","土龕門前一行柳，獨引青絲織魚笱。","柳花漠漠飛復飛，魚笱如今落誰手。","余嗟老人多悲辛，老人昔日傷幾人；人情相掩且相歎，不喜河頭秋與春。","（[一]此詩亦見伯二五四四卷，題作《老人篇》，但差白字太多。","[二]依劉校。","[三]「精魂傷夫」伯二五四四卷作「精醜香風」，俞云：「精魂傷夫」當從伯二五四四卷作「精魄」〖「醜」是「魄」誤〗，因此四字正和下文相應。","精魄指月，下文「月如鈎在輪影中，風似人來荻聲裏」，足證「香風」二字不誤。","劉校「『夫』當爲『失』字之誤」。","）。"]', '["老人甲子难計論，耳中白毛三十根。","釣鱼幾年如一日，船舷數寸青苔痕。","人生性命必归正（止）[二]，（「正」，原卷作「止」。","）精魂傷夫[三]向流水。","（「魂」，伯二五六七卷作「魄」。","）月如鈎在輪影中，风似人来𥭳（荻）声裏。","蒲葉高低沒釣磯，破舟仍繫綠楊枝。","水流不爲人流去，鱼乐寧知人乐时。","土龕门前一行柳，独引青絲织鱼笱。","柳花漠漠飞复飞，鱼笱如今落誰手。","余嗟老人多悲辛，老人昔日傷幾人；人情相掩且相歎，不喜河头秋與春。","（[一]此诗亦见伯二五四四卷，題作《老人篇》，但差白字太多。","[二]依劉校。","[三]「精魂傷夫」伯二五四四卷作「精醜香风」，俞云：「精魂傷夫」當從伯二五四四卷作「精魄」〖「醜」是「魄」誤〗，因此四字正和下文相應。","精魄指月，下文「月如鈎在輪影中，风似人来荻声裏」，足證「香风」二字不誤。","劉校「『夫』當爲『失』字之誤」。","）。"]', '诗', 'shi', '', NULL, '傷河龕老人[一] 丘爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a12826f5-7798-4527-9c1e-b4dbac17fe4d', '謁河上公廟（伯三六一九）', '謁河上公廟（伯三六一九）', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["河上公遺跡，跡涼在道邊。","草生空廟裏，□□□□□。","□□□知聖，騰空更表仙。","孝文皇帝後，《章句》至今傳。"]', '["河上公遺跡，跡涼在道邊。","草生空廟裏，□□□□□。","□□□知聖，腾空更表仙。","孝文皇帝後，《章句》至今傳。"]', '诗', 'shi', '', NULL, '謁河上公廟（伯三六一九） 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7dae33e-003f-4f7e-9f78-2c8c7d7d7033', '', '', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2cbb821-c70e-43d5-a38f-2c6081516a2a', '城旁□□[一]伯二五六七下同', '城旁□□[一]伯二五六七下同', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["降奚能騎射，戰馬百餘匹，甲仗明寒川，霜□□□□。","□□煞單于，薄暮紅旗出。","城旁粗少年，驟馬垂長鞭，脫却□□□，□劍淪秋天。","（項云「淪」疑當作「輪」，同掄。","）匈奴不敢出，漠北開（閉）[三]甲煙。","（[一]標題殘去二三字。","按《全唐詩》昌齡有《城旁曲》，但內容與此全異。","[二]余疑「開」爲「閉」誤，俞云：「煙塵四合則虜起，今匈奴不出，故開霽也。","依平仄論亦宜平聲字，「開」字不誤。","」）。"]', '["降奚能騎射，戰马百餘匹，甲仗明寒川，霜□□□□。","□□煞單于，薄暮紅旗出。","城旁粗少年，驟马垂长鞭，脫却□□□，□劍淪秋天。","（項云「淪」疑當作「輪」，同掄。","）匈奴不敢出，漠北开（閉）[三]甲煙。","（[一]標題殘去二三字。","按《全唐诗》昌齡有《城旁曲》，但內容與此全異。","[二]余疑「开」爲「閉」誤，俞云：「煙塵四合則虜起，今匈奴不出，故开霽也。","依平仄論亦宜平声字，「开」字不誤。","」）。"]', '诗', 'shi', '', NULL, '城旁□□[一]伯二五六七下同 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2cd5bff-c88b-445c-b93b-94aea8973023', '題淨眼師房', '題淨眼師房', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["白鴿飛時日欲斜，禪房寂歷飲香茶。","傾人城，傾人國，斬新剃頭青且黑。","玉如意，金澡瓶，朱唇皓齒能誦經，吳音唤字更分明。","日暮鐘聲相送出，袈裟掛着箔簾釘。"]', '["白鴿飞时日欲斜，禪房寂歷饮香茶。","傾人城，傾人国，斬新剃头青且黑。","玉如意，金澡瓶，朱唇皓齒能誦經，吳音唤字更分明。","日暮鐘声相送出，袈裟掛着箔簾釘。"]', '诗', 'shi', '', NULL, '題淨眼師房 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62cc5942-6024-47fd-9815-b023deeea081', '弔王將軍（伯二五六七[一]）', '弔王將軍（伯二五六七[一]）', '933e8c83-c3fc-47cb-a48d-1811e605e0cc', '唐', '["漂姚[二]北伐時，深入强千里。","戰酣落日黃，軍敗鼓聲死。","嘗聞漢飛將，可奪單于壘，今與山鬼隣，殘兵哭遼水。","（殷璠天寶末編《河嶽英靈集》，收此詩於常建名下，幷在評語中引及。","原卷於陶韓名下存詩九首，其一爲《古意》。","《全唐詩》已收歸陶韓，其二即本詩，後七首均李白詩。","據此推測，此詩似非陶韓作。","）（[一]《中華文史論叢》編輯室云：「《弔王將軍》一詩《全唐詩》已收入《常建集》中。","」劉說同。","[二]漂姚指霍去病，《漢書》作「票」，或「驃」。","）。"]', '["漂姚[二]北伐时，深入强千里。","戰酣落日黄，軍敗鼓声死。","嘗闻漢飞將，可奪單于壘，今與山鬼隣，殘兵哭遼水。","（殷璠天寶末編《河嶽英靈集》，收此诗於常建名下，幷在評語中引及。","原卷於陶韓名下存诗九首，其一爲《古意》。","《全唐诗》已收归陶韓，其二即本诗，後七首均李白诗。","據此推測，此诗似非陶韓作。","）（[一]《中华文史論叢》編輯室云：「《弔王將軍》一诗《全唐诗》已收入《常建集》中。","」劉说同。","[二]漂姚指霍去病，《漢书》作「票」，或「驃」。","）。"]', '诗', 'shi', '', NULL, '弔王將軍（伯二五六七[一]） 陶翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6293174f-62cc-485b-b983-4676e47cedfd', '得遇入京（伯三八一二）', '得遇入京（伯三八一二）', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["萬里南來喜復悲，生涯何幸有歸期。","空庭葉散風搖落，舊邑人疏經亂離。","巴路千山秋水在，江花獨樹夕陽微。","爲君一話此中事，白首長沙知不知？","（按《全唐詩》內長卿詩卷五與劉隨州集卷九〖四部叢刊本〗都有這首詩，題爲「自江西歸至舊任官舍贈袁贊府自經劉展平後」，但文句異同甚多，故破格載入，兼錄集本如下：「却見同官喜後悲，此生何幸有歸期。","空庭客至逢搖落，舊邑人稀經亂離。","湘路來過迴雁處，江城臥聽擣衣時。","南方風土勞君問，賈誼長沙豈不知。","」）。"]', '["万里南来喜复悲，生涯何幸有归期。","空庭葉散风搖落，旧邑人疏經亂離。","巴路千山秋水在，江花独樹夕陽微。","爲君一話此中事，白首长沙知不知？","（按《全唐诗》內长卿诗卷五與劉隨州集卷九〖四部叢刊本〗都有這首诗，題爲「自江西归至旧任官舍贈袁贊府自經劉展平後」，但文句異同甚多，故破格載入，兼錄集本如下：「却见同官喜後悲，此生何幸有归期。","空庭客至逢搖落，旧邑人稀經亂離。","湘路来過迴雁处，江城臥听擣衣时。","南方风土勞君问，賈誼长沙豈不知。","」）。"]', '诗', 'shi', '', NULL, '得遇入京（伯三八一二） 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d3c1304-a2bf-416c-a1b3-5b51c58c050a', '詠青（伯二五六七）', '詠青（伯二五六七）', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["霧闢天光遠，春迴日道臨。","草濃河畔色，槐結路旁陰。","欲映君王史，先標胄子襟；經明如何（可）[一]拾，自有致雲心。","（《國秀集》卷下、《全唐詩》卷二○三皆收此詩爲校書郎荆冬倩之作，作孟詩恐誤。","）（[一]依劉校。","）。"]', '["霧闢天光远，春迴日道臨。","草濃河畔色，槐結路旁陰。","欲映君王史，先標胄子襟；經明如何（可）[一]拾，自有致云心。","（《国秀集》卷下、《全唐诗》卷二○三皆收此诗爲校书郎荆冬倩之作，作孟诗恐誤。","）（[一]依劉校。","）。"]', '诗', 'shi', '', NULL, '詠青（伯二五六七） 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18c18f8c-a68d-4f9e-9e9c-96d7805b7ea7', '遇崔二[一]有別（伯三八六二下同）', '遇崔二[一]有別（伯三八六二下同）', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["大國多任士[二]，（蔣、項皆云「任士」不誤，用《莊子·秋水》語。","）明時遺此人。","頤頷尚豐盈，毛骨未合迍。","逸足望千里，商歌悲四隣。","誰謂多才富，却令家道貧。","秋風吹別馬，攜手更傷神。","（[一]《適集》卷一有「效古贈崔二」，應是一人。","《贈崔二》有云：「君負縱橫才，如何尚顦顇。","」又云：「窮達自有時，夫子莫下淚。","」這次「遇崔二」，還是「明時遺此人」，所以還歎息着說「誰謂多才富，却令家道貧！」[二]「任士」劉疑「佳士」。","）。"]', '["大国多任士[二]，（蔣、項皆云「任士」不誤，用《莊子·秋水》語。","）明时遺此人。","頤頷尚豐盈，毛骨未合迍。","逸足望千里，商歌悲四隣。","誰謂多才富，却令家道貧。","秋风吹別马，携手更傷神。","（[一]《適集》卷一有「效古贈崔二」，應是一人。","《贈崔二》有云：「君負縱橫才，如何尚顦顇。","」又云：「窮達自有时，夫子莫下泪。","」這次「遇崔二」，還是「明时遺此人」，所以還歎息着说「誰謂多才富，却令家道貧！」[二]「任士」劉疑「佳士」。","）。"]', '诗', 'shi', '', NULL, '遇崔二[一]有別（伯三八六二下同） 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca3fae3b-b5ad-408c-afa9-c83bb861d6b5', '奉寄平原顏太守（幷序）', '奉寄平原顏太守（幷序）', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["皇皇平原守，駟馬出關東。","銀印垂腰下，天書在篋中。","自承到官後，高枕揚清風。","豪富已低首，逋逃還力農。","始余梁宋間，甘予（與）[一]麋鹿同。","散髮對浮雲，浩歌追釣翁，如何顧疵賤，遂肯偕窮通。","耿介出憲司，慨然見羣公，賦詩感知己，獨立争愚蒙。","金石誰不仰，波瀾殊未窮；微軀枉多價，朽木慚良工。","上將拓邊西，薄才忝從戎，豈論濟代心，願効匹夫雄。","驊騮滿長皂，弱翮依彫籠，行軍動若飛，旋斾信嚴終[二]。","屢陪投醪醉，竊賀銘山功；雖無汗馬勞，且熟沙塞空。","去去勿復道，所思積深衷。","一爲天崖（涯）[三]客，三見南飛鴻，應念蕭關外，飄颻隨轉蓬。","（[一]依俞校。","[二]劉云：「嚴助終軍也。","二人乃漢武帝時文士有武略者。","蘇東坡詩：一時冠蓋盡嚴終。","」[三]依劉校。","）。"]', '["皇皇平原守，駟马出关东。","銀印垂腰下，天书在篋中。","自承到官後，高枕揚清风。","豪富已低首，逋逃還力農。","始余梁宋间，甘予（與）[一]麋鹿同。","散髮对浮云，浩歌追釣翁，如何顧疵賤，遂肯偕窮通。","耿介出憲司，慨然见羣公，賦诗感知己，独立争愚蒙。","金石誰不仰，波瀾殊未窮；微軀枉多價，朽木慚良工。","上將拓邊西，薄才忝從戎，豈論濟代心，願効匹夫雄。","驊騮满长皂，弱翮依彫籠，行軍动若飞，旋斾信嚴終[二]。","屢陪投醪醉，竊賀銘山功；雖無汗马勞，且熟沙塞空。","去去勿复道，所思積深衷。","一爲天崖（涯）[三]客，三见南飞鴻，應念蕭关外，飄颻隨轉蓬。","（[一]依俞校。","[二]劉云：「嚴助終軍也。","二人乃漢武帝时文士有武略者。","蘇东坡诗：一时冠蓋尽嚴終。","」[三]依劉校。","）。"]', '诗', 'shi', '', NULL, '奉寄平原顏太守（幷序） 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17dfa7e6-fa10-4fa9-a689-e7c66a676a1c', '雙六頭賦送李參軍', '雙六头賦送李參軍', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["有物兮四方故城，六面砥平，白質黑文，花攢星明。","主張爾手談，決斷爾心争，推得失似關乎天命，而消息乃用乎人情。","若行之尤[一]，思之精，雖邂逅而小比[二]，（「小比」，蔣云作「小屯」是，「屯」、「亨」，皆《易》用語；項云「比」爲「北」之形訛，賭戲中敗者稱「北」，或稱「奔北」。","）必指掌而大亨。","李侯李侯保令名，無怨𥎪於垂成。","（「𥎪」，蔣、項皆云當作「敗」。","）朝影入平川，川長復垂柳[三]，（劉開揚云此二句乃誤鈔《自淇涉黃河途中作十三首》之文，當刪。","）明年有一擲分[四]，（項疑「分」字爲衍文。","）君不先鳴誰先鳴？","（[一]游國恩先生云：「『尤』字似係『久』字之誤。","」俞云：「行之尤不誤。","這是一種近乎雙六的賭具，行之尤者行之最，言他這碁走得很好，雖然有時會失着，但轉眼反手〖指掌〗間，又亨通了。","若作久，便與下文指掌大亨不合。","」[二]俞云：「『小比』疑當作『小疵』。","」劉云：「當作『小屯』。","」[三]劉云：「『柳』字不叶韻，疑是『平』之誤，此句說古練不已。","」[四]「明年有一擲分」不成句，疑「分」字是衍文。","俞云：「似亦不誤，說明年還有一擲的機會〖大約指官場的攷績等事〗，您一定便得意的。","『分』字仄聲。","」劉疑「有」當作「儻有」。","）。"]', '["有物兮四方故城，六面砥平，白質黑文，花攢星明。","主張爾手談，決斷爾心争，推得失似关乎天命，而消息乃用乎人情。","若行之尤[一]，思之精，雖邂逅而小比[二]，（「小比」，蔣云作「小屯」是，「屯」、「亨」，皆《易》用語；項云「比」爲「北」之形訛，賭戲中敗者稱「北」，或稱「奔北」。","）必指掌而大亨。","李侯李侯保令名，無怨𥎪於垂成。","（「𥎪」，蔣、項皆云當作「敗」。","）朝影入平川，川长复垂柳[三]，（劉开揚云此二句乃誤鈔《自淇涉黄河途中作十三首》之文，當刪。","）明年有一擲分[四]，（項疑「分」字爲衍文。","）君不先鳴誰先鳴？","（[一]游国恩先生云：「『尤』字似係『久』字之誤。","」俞云：「行之尤不誤。","這是一種近乎雙六的賭具，行之尤者行之最，言他這碁走得很好，雖然有时會失着，但轉眼反手〖指掌〗间，又亨通了。","若作久，便與下文指掌大亨不合。","」[二]俞云：「『小比』疑當作『小疵』。","」劉云：「當作『小屯』。","」[三]劉云：「『柳』字不叶韻，疑是『平』之誤，此句说古練不已。","」[四]「明年有一擲分」不成句，疑「分」字是衍文。","俞云：「似亦不誤，说明年還有一擲的機會〖大約指官場的攷績等事〗，您一定便得意的。","『分』字仄声。","」劉疑「有」當作「儻有」。","）。"]', '诗', 'shi', '', NULL, '雙六頭賦送李參軍 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8446984-8188-4fc3-bf8d-6fa2e36b41b1', '自武威赴臨洮謁大夫不及因書即事寄河西隴右幕下諸公（伯二五五二下同）（「巔」，蔣、劉、項皆云當作「顛」。）', '自武威赴臨洮謁大夫不及因书即事寄河西隴右幕下諸公（伯二五五二下同）（「巔」，蔣、劉、項皆云當作「顛」。）', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["浩蕩去鄉縣，飄颻瞻節旄。","揚鞭發武威，落日至臨洮。","主人未相識，客子心忉忉。","顧見征戰歸，始知士馬豪。","戈鋋耀崖谷，聲氣如風濤。","隱軫戎旅間，功業競相褒。","獻狀陳首級，饗軍烹太牢。","俘囚駈面縛，長幼隨巔毛。","（「巔」，蔣、劉、項皆云當作「顛」。","）氈裘何蒙茸，血食本羶臊。","漢將乃兒戲，秦人空自勞。","立馬眺洪河，驚風吹但白蒿。","雲屯寒色苦，雪合羣山高。","遠戍際天末，邊烽連賊壕。","我本江海遊，逝將心利逃[一]。","一朝感推薦，萬里從英旄（髦）[二]。","飛鳴蓋殊倫，俯仰忝諸曹。","鷰鴿（頷）[三]知有待，龍泉惟所操。","相士慙入幕，懷賢願同袍。","清掄揮塵尾，乘酣持蟹螯。","此行豈易酬，深意方鬱陶。","微効儻不遂，終然辭佩刀。","（[一]俞云：「『心利逃』不可解，疑當作『名利逃』。","」[二]依劉校。","[三]依俞校。","）。"]', '["浩蕩去乡縣，飄颻瞻節旄。","揚鞭發武威，落日至臨洮。","主人未相識，客子心忉忉。","顧见征戰归，始知士马豪。","戈鋋耀崖谷，声氣如风濤。","隐軫戎旅间，功業競相褒。","獻狀陳首級，饗軍烹太牢。","俘囚駈面縛，长幼隨巔毛。","（「巔」，蔣、劉、項皆云當作「顛」。","）氈裘何蒙茸，血食本羶臊。","漢將乃兒戲，秦人空自勞。","立马眺洪河，驚风吹但白蒿。","云屯寒色苦，雪合羣山高。","远戍際天末，邊烽連賊壕。","我本江海游，逝將心利逃[一]。","一朝感推薦，万里從英旄（髦）[二]。","飞鳴蓋殊倫，俯仰忝諸曹。","鷰鴿（頷）[三]知有待，龙泉惟所操。","相士慙入幕，懷賢願同袍。","清掄揮塵尾，乘酣持蟹螯。","此行豈易酬，深意方鬱陶。","微効儻不遂，終然辞佩刀。","（[一]俞云：「『心利逃』不可解，疑當作『名利逃』。","」[二]依劉校。","[三]依俞校。","）。"]', '诗', 'shi', '', NULL, '自武威赴臨洮謁大夫不及因書即事寄河西隴右幕下諸公（伯二五五二下同）（「巔」，蔣、劉、項皆云當作「顛」。） 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfdab5f3-2ada-4af1-9d4a-7afff67a1f4e', '同李司倉早春宴睢陽東亭（得花）', '同李司倉早春宴睢陽东亭（得花）', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["春臯宜晚景，芳樹雜流霞。","鸎鷰知三月，池臺稱百花。","竹根初帶笋，槐色正開牙。","且莫催行騎，歸時有月華。","。"]', '["春臯宜晚景，芳樹杂流霞。","鸎鷰知三月，池台稱百花。","竹根初带笋，槐色正开牙。","且莫催行騎，归时有月华。","。"]', '诗', 'shi', '', NULL, '同李司倉早春宴睢陽東亭（得花） 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('265fb983-0933-4bb2-93ad-ec8c869db2d6', '在哥舒大夫幕下請辭退託興奉詩（伯三八一二。下同）', '在哥舒大夫幕下請辞退託兴奉诗（伯三八一二。下同）', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["自從嫁與君，不省一日樂。","遣妾作歌舞，好時還道惡。","不是妾無堪，君家婦難作。","下堂辭君去，去後君莫錯。","（項云：「《才調集》卷六李白《寒女吟》，後幅與此詩大略相同。","」《寒女吟》收《全唐詩續補遺》李白名下，兹不重錄。","）。"]', '["自從嫁與君，不省一日乐。","遣妾作歌舞，好时還道惡。","不是妾無堪，君家婦难作。","下堂辞君去，去後君莫錯。","（項云：「《才調集》卷六李白《寒女吟》，後幅與此诗大略相同。","」《寒女吟》收《全唐诗續補遺》李白名下，兹不重錄。","）。"]', '诗', 'shi', '', NULL, '在哥舒大夫幕下請辭退託興奉詩（伯三八一二。下同） 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e979977b-e698-4a76-b540-89181852cb36', '閨情（爲落殊蕃陳上相知人）', '閨情（爲落殊蕃陳上相知人）', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["自從淪落到天涯，一片真心戀着□。","（缺字，檢原卷似應爲「查」字。","）顦顇不緣思舊國，行渧（啼）只是爲寃家。","（〖1〗右兩首，同寫在一卷上。","第一首標題作「高適在哥舒大夫幕下請辭退，託興奉詩」，疑是後人依託或擬作，細玩修辭與用意，也不像高適的作品，因爲是使用高適的故事，故附於此。","《閨情》原卷不題撰人，「顦顇不緣思舊國」，也一定不是高適的話，蓋與前一首同爲一個淪落在敦煌的文人所作，因此，也連類附及。","「爲落殊蕃陳上相知人」的閨情以後，還有四首閨情，好像是妓女的歌辭。","也不著撰人，不知是否佚詩，姑附於後：）。"]', '["自從淪落到天涯，一片真心戀着□。","（缺字，檢原卷似應爲「查」字。","）顦顇不緣思旧国，行渧（啼）只是爲寃家。","（〖1〗右兩首，同寫在一卷上。","第一首標題作「高適在哥舒大夫幕下請辞退，託兴奉诗」，疑是後人依託或擬作，細玩修辞與用意，也不像高適的作品，因爲是使用高適的故事，故附於此。","《閨情》原卷不題撰人，「顦顇不緣思旧国」，也一定不是高適的話，蓋與前一首同爲一個淪落在敦煌的文人所作，因此，也連類附及。","「爲落殊蕃陳上相知人」的閨情以後，還有四首閨情，好像是妓女的歌辞。","也不著撰人，不知是否佚诗，姑附於後：）。"]', '诗', 'shi', '', NULL, '閨情（爲落殊蕃陳上相知人） 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4413e116-18be-4c17-b9c1-eb8891418c6f', '閨情（爲落殊蕃陳上相知人） 閨情 一', '閨情（爲落殊蕃陳上相知人） 閨情 一', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["相隨萬里泣胡風，疋偶將期一世終。","早知中路生離別，悔不深憐沙磧中。"]', '["相隨万里泣胡风，疋偶將期一世終。","早知中路生離別，悔不深怜沙磧中。"]', '诗', 'shi', '', NULL, '閨情（爲落殊蕃陳上相知人） 閨情 一 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fc43627-717f-49b2-ada4-3968d56dbd62', '閨情（爲落殊蕃陳上相知人） 閨情 二', '閨情（爲落殊蕃陳上相知人） 閨情 二', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["不須推道委人猜，只是君心自不開。","今夜閨門憑莫閉，孤魂擬向夢中來。"]', '["不須推道委人猜，只是君心自不开。","今夜閨门憑莫閉，孤魂擬向梦中来。"]', '诗', 'shi', '', NULL, '閨情（爲落殊蕃陳上相知人） 閨情 二 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('995bd4ec-ccf7-4cb5-a118-30c57cdf3848', '閨情（爲落殊蕃陳上相知人） 閨情 三', '閨情（爲落殊蕃陳上相知人） 閨情 三', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["祗今桃李正堪攀，所恨枝高引手難。","原君垂下方便葉，袖卷將歸看復看。"]', '["祗今桃李正堪攀，所恨枝高引手难。","原君垂下方便葉，袖卷將归看复看。"]', '诗', 'shi', '', NULL, '閨情（爲落殊蕃陳上相知人） 閨情 三 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09aed716-c9ab-4b67-84cf-9af750523942', '閨情（爲落殊蕃陳上相知人） 閨情 四', '閨情（爲落殊蕃陳上相知人） 閨情 四', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["自處長信宮，每向孤燈泣。","閨門鎮不開，夢從何處入。","。"]', '["自处长信宮，每向孤灯泣。","閨门鎮不开，梦從何处入。","。"]', '诗', 'shi', '', NULL, '閨情（爲落殊蕃陳上相知人） 閨情 四 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c3a10b7-5781-4817-bae2-fc8604d3dea1', '登觀鵲樓（伯三六一九）', '登观鵲楼（伯三六一九）', 'c8a524e9-9b39-4424-a2c0-8d9050501f14', '唐', '["城樓多峻極，列酌恣登攀。","逈林飛鳥上，高榭代人間。","天勢圍平野，河流入斷山。","今年菊花事，併是送君還。","（暢諸作此詩，《文苑英華》卷七一○收李韓《河中鸛鵲樓集序》已稱及，宋司馬光《續詩話》、沈括《夢溪筆談》卷十五僅錄中四句，亦云暢諸作。","至《唐詩紀事》卷二七始誤爲暢當，《全唐詩》沿之。","岑仲勉《讀全唐詩札記》考證較詳，可參看。","宋人所見此詩前二句，作「迥臨飛鳥上，高謝世人間」，與此處三、四兩句稍異，蔣、均云以「臨」、「謝」爲是，「代人」即「世人」，避太宗諱改。）"]', '["城楼多峻極，列酌恣登攀。","逈林飞鸟上，高榭代人间。","天勢圍平野，河流入斷山。","今年菊花事，併是送君還。","（暢諸作此诗，《文苑英华》卷七一○收李韓《河中鸛鵲楼集序》已稱及，宋司马光《續诗話》、沈括《梦溪笔談》卷十五僅錄中四句，亦云暢諸作。","至《唐诗紀事》卷二七始誤爲暢當，《全唐诗》沿之。","岑仲勉《读全唐诗札記》考證較詳，可參看。","宋人所见此诗前二句，作「迥臨飞鸟上，高謝世人间」，與此处三、四兩句稍異，蔣、均云以「臨」、「謝」爲是，「代人」即「世人」，避太宗諱改。）"]', '诗', 'shi', '', NULL, '登觀鵲樓（伯三六一九） 暢諸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('688029b2-32fa-4e96-80c6-565efb07fc22', '秦婦吟[一]', '秦婦吟[一]', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["中和癸卯春三月，洛陽城外花如雪。","東西南北路人絶，綠楊悄悄香塵滅。","路旁忽見如花人，獨向綠楊陰下歇。","鳳側鸞欹鬢脚斜，紅攢黛歛眉心折。","「借問女郎何處來？","」含嚬欲語聲先咽。","回頭歛袂謝行人；喪亂漂淪何堪說！三年陷賊留秦地，依稀記得秦中事。","君能爲妾解金鞍，妾亦與君停玉趾。","「前年庚子臈月五，正閉金籠教鸚鵡。","斜開鸞鏡嬾梳頭，閑憑雕欄慵不語。","忽看門外起紅塵，已見街中攂金鼓。","居人走出半倉惶，朝士歸來尚疑誤。","是時西面官軍入，擬[二]向潼關爲警急；皆言博野自相持，盡道賊軍來未及。","須臾主父乘奔至，下馬入門癡似醉。","適逢紫蓋去蒙塵，已見白旗來匝地。","扶羸攜幼競相呼，上屋緣牆不知次，南鄰走入北鄰藏，東鄰走向西鄰避；北鄰諸婦咸相湊，戶外崩騰如走獸。","轟轟崐崐乾坤動，（「崐崐」，蔣云當作「輥輥」。","）萬馬雷聲從地涌。","火迸金星上九天，十二官街煙烘烔。","日輪西下寒光白，上帝無言空脈脈。","陰雲暈氣若重圍，宦者流星如血色。","紫氣潛[三]隨帝座移，妖光暗射台星拆。","（「拆」，項校作「坼」。","）家家流血如泉沸，處處寃聲聲動地。","舞伎歌姬盡暗損，（「損」，蔣、項校作「捐」。","）孾兒稚女皆生棄。","東鄰有女眉新畫，傾國傾城不知價；長戈擁得上戎車，回首香閨淚盈把[四]。","旋抽金線學縫旗，纔上雕鞍教走馬。","有時馬上見良人，不敢回眸空淚下。","西鄰有女真仙子，一寸橫波剪秋水，粧成只對鏡中春，年幼不知門外事。","一夫跳躍上金階，斜袒半肩欲相恥。","牽衣不肯出朱門，紅粉香脂刀下死。","南鄰有女不記姓，昨日良媒新納聘。","瑠瓈階上不聞行，翡翠簾間空見影。","忽看庭際刀刃鳴，身首支離在俄頃。","仰天掩面哭一聲，女弟女兄同入井。","北鄰少婦行相促，旋拆雲鬟拭眉綠。","已聞擊托壞高門，不覺攀緣上重屋。","須臾四面火光來，欲下迴梯梯又摧。","煙中大叫猶求救，梁上懸尸已作灰。","妾身幸得全刀鋸，不敢踟躕久回顧。","旋梳蟬鬢逐軍行，强展蛾眉出門去。","萬里從兹不得歸，六親自此無尋處。","一從陷賊經三載，終日驚憂心胆碎。","夜臥千重劍戟圍，朝餐一味人肝膾。","鴛幃縱入豈成歡？寶貨雖多非所愛。","蓬頭垢面狵眉赤，幾轉橫波看不得。","衣裳顛倒言語異，面上誇功彫作字。","柏臺多士盡狐精，蘭省諸郎皆鼠魅。","還將短髪戴華籫，不脫朝衣纏繡被；翻持象笏作三公，倒佩金魚爲兩史。","朝聞奏[五]對入朝堂，暮見喧呼來酒市。","一朝五鼓人驚起，呼嘯喧争如竊語[六]。","夜來探馬入皇城，昨日官軍收赤水；赤水去城一百里，朝若來兮暮應至。","兇徒馬上暗吞聲，女伴閨中潛生[七]喜。","皆言寃憤此時銷，必謂妖徒今日死，逡巡走馬傳聲急，又道官軍全陳入；大彭小彭相顧憂，二郎四郎抱鞍泣。","沉沉[八]數日無消息，必謂軍前已銜璧；簸旗掉劍却來歸，又道官軍悉敗績。","四面從茲多厄束，（「厄束」，項校作「軛束」。","）一斗黃金一升粟[九]。","尚讓廚中食木皮，黃巢机上刲人肉。","東南斷絕無糧道，溝壑漸平人漸少。","六軍門外倚殭屍，七架營中填餓殍。","（「七架」，陳寅恪校作「七萃」。","）長安寂寂金（今）何有？","廢市荒街麥苗秀。","採樵斫盡杏園花，修寨誅殘御溝柳。","華[一○]軒繡轂皆銷散，甲第朱門無一半。","含元殿上狐兔行，花萼樓前荆棘滿。","昔時繁盛皆埋沒，舉目淒涼無故物。","內庫燒爲錦繡灰，天街踏盡公卿骨。","來時曉出城東陌，城外風煙如塞色。","（「塞色」，蔣校作「墨色」。","）路旁時見遊奕軍，坡下寂無迎送客。","霸陵東望人煙絕，樹鏁（鎖）驪山金翠滅。","大道俱成棘子林，行人夜宿牆匡[一一]月。","明朝曉至三峯路，百萬人家無一戶。","破落田園但有蒿，催殘竹樹皆無主。","（「催」，項校作「摧」。","）路旁試問金天神[一二]，金天無語愁於人。","廟前古柏有殘枿[一三]，殿上金爐生暗塵。","一從狂宼陷中國，天地晦[一四]冥風雨黑；案前神水呪不成，壁上陰兵驅不得。","閑日徒歆奠饗思，（「思」，趙遂之校作「恩」。","）危時不助神通力。","我今愧恧拙爲神，且向山中深避匿；寰中簫管不曾聞，筵上犧牲無處覓。","旋教魘鬼傍鄉村，誅剥生靈過朝夕。","妾聞此語愁更愁，天遣時災非自由。","神在山中猶避難，何須責望東諸侯！前年又出揚震關，舉頭雲際見荆山。","如從地府到人間，頓覺時清天地閒。","陝州主帥忠且貞，不動干戈唯守城。","蒲津主帥能戢兵，千里晏然無戈[一五]聲。","（「戈」，蔣校作「犬」。","）朝攜寶貨無人問，夜插金釵唯獨行。","明朝又過新安東，路上乞漿逢一翁。","蒼蒼面帶苔蘚色，隱隱身藏蓬荻中。","問翁本是何鄉曲？底是寒天霜露宿？（「是」，項校作「事」。","）老翁蹔起欲陳辭，却坐支頤仰天哭。","鄉園本貫東畿縣，歲歲耕桑臨近甸；歲種良田二百壥，年輸戶稅三千[一六]萬。","小姑慣織褐絁袍，中婦能炊紅忝飯。","千度倉兮萬絲[一七]箱，黃巢過後猶殘半。","自從洛下屯師旅，日夜巡兵入村塢；匣中秋水拔青蛇，旗上高風吹白虎。","入門下馬若旋風，罄室傾囊如捲土。","家財既盡骨肉離，今日垂年一身苦。","一身苦兮何足嗟，山中更有千萬家，朝飢[一八]山上尋蓬子，夜宿霜中臥荻花！妾聞此父傷心語，竟日闌干淚如雨。","出門惟見亂梟鳴，更欲東奔何處所？","仍聞汴路舟車絕，又道彭門自相殺；野色徒銷戰士魂，河津半是寃人血。","」適聞有客金陵至，見說江南風景異。","自從大宼犯中原，戎馬不曾生四鄙，誅鋤竊盗若神功，惠愛生靈如赤子。","城壕固謢教金湯[一九]，（徐俊云：伯三三八一、斯五八三四作「斆」。","作「教」誤。","）賦稅如雲送軍壘。","奈何四海盡滔滔，湛然一境平如砥。","避難徒爲闕下人，懷安却羨江南鬼。","願君舉棹東復東，詠此長歌獻相公。","（[一]敦煌石室所出《秦婦吟》有下列九個寫本：〖甲〗斯五四七六。","〖乙〗斯六九五。","卷末題「貞明五年〖九一九〗己卯歲四月十一日敦煌羣金光明寺學仕郎安友盛寫訖。","」還有寫書詩四句：「今日寫書了，合有五升麥。","高代不可得，還是自身災。","」〖丙〗斯五四七七。","〖丁〗伯二七○○。","〖戊〗伯三三八一。","卷末題「天復五年〖九○五〗十二月十五日敦煌郡金光明寺學仕張龜寫。","」、〖己〗伯三七八○。","卷末有寫書人題記兩行。","一云：「顯德二年〖四〗丁巳歲二月十七日就家學仕郎馬富德書記」，一云：「大周顯德四年〖九五七〗二月十九日學士童兒馬富德書記。","」〖庚〗伯三九五三。","僅存二十一行半。","書法不佳。","〖辛〗伯三九一○。","〖壬〗未見。","見李盛鐸賣給日本的敦煌寫本同錄。","現在所知道的已有上述九個寫本。","從一九○七年以後，有許多學者使用這些材料，作了不少的研究，校勘和注釋的工作。","劉修業）（同志的《秦婦吟校勘續記》一文〖載《學原》第一卷第七期〗，詳細地記述了這些研究的經過，也補充了一些前人的校勘。","這次寫定，就是節取使用她的校記的。","[二]己本「擬」作「疑」。","[三]甲本「潛」作「漸」，其餘各本皆作「潛」。","[四]乙本「把」作「帊」。","各本皆作「把」，作「把」較佳。","[五]乙本戊本「奏」作「走」。","[六]各本「語」作「議」，此後己本。","[七]各本「生」或作「失」，不甚清楚。","余曾審視巴黎四本，丁戊兩本似「生」，己庚兩本作「失」。","作「生」者意義較佳。","俞云：「『失』字是。","」[八]「沉沉」卷子本寫作「{氵|/凡}{氵|/凡}」因此多有迻作「汎汎」者，誤。","[九]此句或迻作「一斗黃金一斗粟」。","按下「斗」字應作「升」，因形似改誤。","己庚兩本作「勝」，即升字。","[一○]丁本「華」作「萃」，疑是「翠」字，亦可能爲「華」之誤字。","己本作「花」，即「華」同音字。","作「華」是。","[一一]「牆匡」二字不易解。","丁本「牆」作「長」，己本作「橫」。","「匡」，亦有迻作「空」者，字形不相近。","《唐馬君起造像記》，「庭」作「𮞔」與「迬」字形相近，若依丁卷作。）"]', '["中和癸卯春三月，洛陽城外花如雪。","东西南北路人絶，綠楊悄悄香塵滅。","路旁忽见如花人，独向綠楊陰下歇。","鳳側鸾欹鬢脚斜，紅攢黛歛眉心折。","「借问女郎何处来？","」含嚬欲語声先咽。","回头歛袂謝行人；喪亂漂淪何堪说！三年陷賊留秦地，依稀記得秦中事。","君能爲妾解金鞍，妾亦與君停玉趾。","「前年庚子臈月五，正閉金籠教鸚鵡。","斜开鸾镜嬾梳头，闲憑雕欄慵不語。","忽看门外起紅塵，已见街中攂金鼓。","居人走出半倉惶，朝士归来尚疑誤。","是时西面官軍入，擬[二]向潼关爲警急；皆言博野自相持，尽道賊軍来未及。","須臾主父乘奔至，下马入门癡似醉。","適逢紫蓋去蒙塵，已见白旗来匝地。","扶羸携幼競相呼，上屋緣牆不知次，南鄰走入北鄰藏，东鄰走向西鄰避；北鄰諸婦咸相湊，戶外崩腾如走獸。","轟轟崐崐乾坤动，（「崐崐」，蔣云當作「輥輥」。","）万马雷声從地涌。","火迸金星上九天，十二官街煙烘烔。","日輪西下寒光白，上帝無言空脈脈。","陰云暈氣若重圍，宦者流星如血色。","紫氣潛[三]隨帝座移，妖光暗射台星拆。","（「拆」，項校作「坼」。","）家家流血如泉沸，处处寃声声动地。","舞伎歌姬尽暗損，（「損」，蔣、項校作「捐」。","）孾兒稚女皆生棄。","东鄰有女眉新畫，傾国傾城不知價；长戈擁得上戎车，回首香閨泪盈把[四]。","旋抽金線学縫旗，纔上雕鞍教走马。","有时马上见良人，不敢回眸空泪下。","西鄰有女真仙子，一寸橫波剪秋水，粧成只对镜中春，年幼不知门外事。","一夫跳躍上金階，斜袒半肩欲相恥。","牽衣不肯出朱门，紅粉香脂刀下死。","南鄰有女不記姓，昨日良媒新納聘。","瑠瓈階上不闻行，翡翠簾间空见影。","忽看庭際刀刃鳴，身首支離在俄頃。","仰天掩面哭一声，女弟女兄同入井。","北鄰少婦行相促，旋拆云鬟拭眉綠。","已闻擊托壞高门，不覺攀緣上重屋。","須臾四面火光来，欲下迴梯梯又摧。","煙中大叫猶求救，梁上懸尸已作灰。","妾身幸得全刀鋸，不敢踟躕久回顧。","旋梳蟬鬢逐軍行，强展蛾眉出门去。","万里從兹不得归，六親自此無尋处。","一從陷賊經三載，終日驚憂心胆碎。","夜臥千重劍戟圍，朝餐一味人肝膾。","鴛幃縱入豈成歡？寶貨雖多非所愛。","蓬头垢面狵眉赤，幾轉橫波看不得。","衣裳顛倒言語異，面上誇功彫作字。","柏台多士尽狐精，蘭省諸郎皆鼠魅。","還將短髪戴华籫，不脫朝衣纏繡被；翻持象笏作三公，倒佩金鱼爲兩史。","朝闻奏[五]对入朝堂，暮见喧呼来酒市。","一朝五鼓人驚起，呼嘯喧争如竊語[六]。","夜来探马入皇城，昨日官軍收赤水；赤水去城一百里，朝若来兮暮應至。","兇徒马上暗吞声，女伴閨中潛生[七]喜。","皆言寃憤此时銷，必謂妖徒今日死，逡巡走马傳声急，又道官軍全陳入；大彭小彭相顧憂，二郎四郎抱鞍泣。","沉沉[八]數日無消息，必謂軍前已銜璧；簸旗掉劍却来归，又道官軍悉敗績。","四面從茲多厄束，（「厄束」，項校作「軛束」。","）一斗黄金一升粟[九]。","尚讓廚中食木皮，黄巢机上刲人肉。","东南斷絕無糧道，溝壑漸平人漸少。","六軍门外倚殭屍，七架營中填餓殍。","（「七架」，陳寅恪校作「七萃」。","）长安寂寂金（今）何有？","廢市荒街麦苗秀。","採樵斫尽杏园花，修寨誅殘御溝柳。","华[一○]軒繡轂皆銷散，甲第朱门無一半。","含元殿上狐兔行，花萼楼前荆棘满。","昔时繁盛皆埋沒，舉目淒涼無故物。","內庫燒爲錦繡灰，天街踏尽公卿骨。","来时晓出城东陌，城外风煙如塞色。","（「塞色」，蔣校作「墨色」。","）路旁时见游奕軍，坡下寂無迎送客。","霸陵东望人煙絕，樹鏁（鎖）驪山金翠滅。","大道俱成棘子林，行人夜宿牆匡[一一]月。","明朝晓至三峯路，百万人家無一戶。","破落田园但有蒿，催殘竹樹皆無主。","（「催」，項校作「摧」。","）路旁試问金天神[一二]，金天無語愁於人。","廟前古柏有殘枿[一三]，殿上金爐生暗塵。","一從狂宼陷中国，天地晦[一四]冥风雨黑；案前神水呪不成，壁上陰兵驱不得。","闲日徒歆奠饗思，（「思」，趙遂之校作「恩」。","）危时不助神通力。","我今愧恧拙爲神，且向山中深避匿；寰中簫管不曾闻，筵上犧牲無处覓。","旋教魘鬼傍乡村，誅剥生靈過朝夕。","妾闻此語愁更愁，天遣时災非自由。","神在山中猶避难，何須責望东諸侯！前年又出揚震关，舉头云際见荆山。","如從地府到人间，頓覺时清天地閒。","陝州主帥忠且貞，不动干戈唯守城。","蒲津主帥能戢兵，千里晏然無戈[一五]声。","（「戈」，蔣校作「犬」。","）朝携寶貨無人问，夜插金釵唯独行。","明朝又過新安东，路上乞漿逢一翁。","蒼蒼面带苔蘚色，隐隐身藏蓬荻中。","问翁本是何乡曲？底是寒天霜露宿？（「是」，項校作「事」。","）老翁蹔起欲陳辞，却坐支頤仰天哭。","乡园本貫东畿縣，歲歲耕桑臨近甸；歲種良田二百壥，年輸戶稅三千[一六]万。","小姑慣织褐絁袍，中婦能炊紅忝飯。","千度倉兮万絲[一七]箱，黄巢過後猶殘半。","自從洛下屯師旅，日夜巡兵入村塢；匣中秋水拔青蛇，旗上高风吹白虎。","入门下马若旋风，罄室傾囊如捲土。","家財既尽骨肉離，今日垂年一身苦。","一身苦兮何足嗟，山中更有千万家，朝飢[一八]山上尋蓬子，夜宿霜中臥荻花！妾闻此父傷心語，竟日闌干泪如雨。","出门惟见亂梟鳴，更欲东奔何处所？","仍闻汴路舟车絕，又道彭门自相殺；野色徒銷戰士魂，河津半是寃人血。","」適闻有客金陵至，见说江南风景異。","自從大宼犯中原，戎马不曾生四鄙，誅鋤竊盗若神功，惠愛生靈如赤子。","城壕固謢教金湯[一九]，（徐俊云：伯三三八一、斯五八三四作「斆」。","作「教」誤。","）賦稅如云送軍壘。","奈何四海尽滔滔，湛然一境平如砥。","避难徒爲闕下人，懷安却羨江南鬼。","願君舉棹东复东，詠此长歌獻相公。","（[一]敦煌石室所出《秦婦吟》有下列九個寫本：〖甲〗斯五四七六。","〖乙〗斯六九五。","卷末題「貞明五年〖九一九〗己卯歲四月十一日敦煌羣金光明寺学仕郎安友盛寫訖。","」還有寫书诗四句：「今日寫书了，合有五升麦。","高代不可得，還是自身災。","」〖丙〗斯五四七七。","〖丁〗伯二七○○。","〖戊〗伯三三八一。","卷末題「天复五年〖九○五〗十二月十五日敦煌郡金光明寺学仕張龟寫。","」、〖己〗伯三七八○。","卷末有寫书人題記兩行。","一云：「显德二年〖四〗丁巳歲二月十七日就家学仕郎马富德书記」，一云：「大周显德四年〖九五七〗二月十九日学士童兒马富德书記。","」〖庚〗伯三九五三。","僅存二十一行半。","书法不佳。","〖辛〗伯三九一○。","〖壬〗未见。","见李盛鐸賣給日本的敦煌寫本同錄。","現在所知道的已有上述九個寫本。","從一九○七年以後，有許多学者使用這些材料，作了不少的研究，校勘和注釋的工作。","劉修業）（同志的《秦婦吟校勘續記》一文〖載《学原》第一卷第七期〗，詳細地記述了這些研究的經過，也補充了一些前人的校勘。","這次寫定，就是節取使用她的校記的。","[二]己本「擬」作「疑」。","[三]甲本「潛」作「漸」，其餘各本皆作「潛」。","[四]乙本「把」作「帊」。","各本皆作「把」，作「把」較佳。","[五]乙本戊本「奏」作「走」。","[六]各本「語」作「議」，此後己本。","[七]各本「生」或作「失」，不甚清楚。","余曾審視巴黎四本，丁戊兩本似「生」，己庚兩本作「失」。","作「生」者意義較佳。","俞云：「『失』字是。","」[八]「沉沉」卷子本寫作「{氵|/凡}{氵|/凡}」因此多有迻作「汎汎」者，誤。","[九]此句或迻作「一斗黄金一斗粟」。","按下「斗」字應作「升」，因形似改誤。","己庚兩本作「勝」，即升字。","[一○]丁本「华」作「萃」，疑是「翠」字，亦可能爲「华」之誤字。","己本作「花」，即「华」同音字。","作「华」是。","[一一]「牆匡」二字不易解。","丁本「牆」作「长」，己本作「橫」。","「匡」，亦有迻作「空」者，字形不相近。","《唐马君起造像記》，「庭」作「𮞔」與「迬」字形相近，若依丁卷作。）"]', '诗', 'shi', '', NULL, '秦婦吟[一] 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c82bb788-f5ef-46f5-9dfa-8341e072941d', '秋晴過李三山池（斯二七一七下同）', '秋晴過李三山池（斯二七一七下同）', '7de5c03a-ee9f-4d02-9365-8f9a96686037', '唐', '["山遊[□]未狎，朝隱遂爲羣。","地僻煙霞異，心閑出處分。","褰開弄晴景，披拂喜朝聞，（「聞」，蔣當作「雰」。","）野興浮黃菊，林棲臥白雲。","窺臨苔壁古，歌嘯竹亭曛。","迴想幽巖路。","知予復解紛。"]', '["山游[□]未狎，朝隐遂爲羣。","地僻煙霞異，心闲出处分。","褰开弄晴景，披拂喜朝闻，（「闻」，蔣當作「雰」。","）野兴浮黄菊，林棲臥白云。","窺臨苔壁古，歌嘯竹亭曛。","迴想幽巖路。","知予复解紛。"]', '诗', 'shi', '', NULL, '秋晴過李三山池（斯二七一七下同） 馬吉甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37ce1aac-9c8a-4afa-902b-808e9ef39104', '秋夜懷友', '秋夜懷友', '7de5c03a-ee9f-4d02-9365-8f9a96686037', '唐', '["故人在天末，空庭明月時。","白雲勞悟（寤）寐，芳樹歇華滋。","蟋蟀鳴秋草，蜘蛛弄曉絲。","菊花應可汎，留興待□□。"]', '["故人在天末，空庭明月时。","白云勞悟（寤）寐，芳樹歇华滋。","蟋蟀鳴秋草，蜘蛛弄晓絲。","菊花應可汎，留兴待□□。"]', '诗', 'shi', '', NULL, '秋夜懷友 馬吉甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f883e8a4-165a-4ff0-88a3-9651affeb2e7', '同獨孤九秋閨', '同独孤九秋閨', '7de5c03a-ee9f-4d02-9365-8f9a96686037', '唐', '["閨樹紅滋變，庭蕪白（下缺）。"]', '["閨樹紅滋变，庭蕪白（下缺）。"]', '诗', 'shi', '', NULL, '同獨孤九秋閨 馬吉甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('245de53e-c50c-45a6-ad1d-9b702eb51178', '送薛大入洛（伯三七七一下同）', '送薛大入洛（伯三七七一下同）', '7c760e70-144a-4dfc-abad-0e466971b9ca', '唐', '["驚年嗟未極，別緒復相依。","雁隨春北度，人共水東歸。","夜月臨軒盡，殘燈入曉微。","哀怨一罷曲，幽桂徒芳菲。"]', '["驚年嗟未極，別緒复相依。","雁隨春北度，人共水东归。","夜月臨軒尽，殘灯入晓微。","哀怨一罷曲，幽桂徒芳菲。"]', '诗', 'shi', '', NULL, '送薛大入洛（伯三七七一下同） 房元陽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcbf28f4-547e-4e22-9066-2b8da2ef7aa8', '秋夜彈碁鼓琴歌', '秋夜彈碁鼓琴歌', '7c760e70-144a-4dfc-abad-0e466971b9ca', '唐', '["流月泛豔兮露色圓，（「圓」，項云當作「團」。","）拂孤□兮弄清絲（絃）[一]。","幽態窈窕兮斷復連，驚風中路兮迢[二]流年。","浮榮輕薄兮欲何賢，流商激楚兮不能宣。","（[一]依劉校。","[二]俞疑「迢」當是「送」字之誤。","）。"]', '["流月泛豔兮露色圓，（「圓」，項云當作「團」。","）拂孤□兮弄清絲（絃）[一]。","幽態窈窕兮斷复連，驚风中路兮迢[二]流年。","浮榮轻薄兮欲何賢，流商激楚兮不能宣。","（[一]依劉校。","[二]俞疑「迢」當是「送」字之誤。","）。"]', '诗', 'shi', '', NULL, '秋夜彈碁鼓琴歌 房元陽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85211e57-51c0-46d3-a2f6-68fd332a26f5', '', '', '9874314b-59ae-4f4e-8a32-9ea4b7f6fd5e', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 侯休祥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23233a74-d2d0-4540-bfa9-d9772f7ea65e', '□鏡（斯五五五下同）（題中缺字，項云據首句看，應是「覽」字。）', '□镜（斯五五五下同）（題中缺字，項云據首句看，應是「覽」字。）', '9874314b-59ae-4f4e-8a32-9ea4b7f6fd5e', '唐', '["忽覽今朝鏡，殊非李（昔）[一]是容。","（「李」，原卷作「昔」。","）自看由（猶）□識，何況故人逢？","（[一]余疑「李」爲「昔」字之誤，俞云：「昔日固是，但李字與昔音形均無關係，似只可存疑，或前舊均有可能。","」）。"]', '["忽覽今朝镜，殊非李（昔）[一]是容。","（「李」，原卷作「昔」。","）自看由（猶）□識，何況故人逢？","（[一]余疑「李」爲「昔」字之誤，俞云：「昔日固是，但李字與昔音形均無关係，似只可存疑，或前旧均有可能。","」）。"]', '诗', 'shi', '', NULL, '□鏡（斯五五五下同）（題中缺字，項云據首句看，應是「覽」字。） 侯休祥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('151bfba0-7805-4f57-b3d3-994a86059c89', '塞外', '塞外', 'db93171b-aa79-4672-b92b-c2bb3e66ea78', '唐', '["塞北長寒地，由來□物華。"]', '["塞北长寒地，由来□物华。"]', '诗', 'shi', '', NULL, '塞外 梁去惑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29cab8af-523d-4309-b989-dc12de412fc0', '春夜山亭', '春夜山亭', '85470c92-3316-4c7f-975b-da8c520b0ad5', '唐', '["夜靜琴還靜，年春酒復春。","何曾山水地，風月不□□。"]', '["夜静琴還静，年春酒复春。","何曾山水地，风月不□□。"]', '诗', 'shi', '', NULL, '春夜山亭 房旭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c21e1942-71dd-4d46-adda-30393e25e054', '詠螢', '詠螢', '55fa3069-10e0-4a22-92c0-1d0ea7b9a5a3', '唐', '["□□光華淺，摶風羽翼徽。","不能欺暗室，所以帶明飛。","。"]', '["□□光华淺，摶风羽翼徽。","不能欺暗室，所以带明飞。","。"]', '诗', 'shi', '', NULL, '詠螢 樂仲卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc6047bd-a8e4-462a-9178-cbcd3df830ce', '別宋侍御', '別宋侍御', '9e1c1dd8-47c0-424a-8ea0-6b43157b3ad8', '唐', '["水國南連楚，沙場北近胡。","春風萬里別，明月兩鄉孤。"]', '["水国南連楚，沙場北近胡。","春风万里別，明月兩乡孤。"]', '诗', 'shi', '', NULL, '別宋侍御 嚴嶷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9b368fb-2140-4a90-b126-0175ed4c43d6', '七夕臥病', '七夕臥病', '000e8297-4cb4-4b1c-a154-837dc73c6137', '唐', '["玉露三秋早，反河七夕初。","不應須臥疾，爲曝腹中書。","（〖1〗鄭愿，《新唐書·宰相世系表》載爲鄭氏南祖房清河令文睿子，無仕歷。","《郎官石柱題名》其名兩見，司勳員外郎在盧象後，李嘉祐前，金部郎中在裴眺、鄭楚客間，以諸人時代推，應爲天寶、大曆間人。","）。"]', '["玉露三秋早，反河七夕初。","不應須臥疾，爲曝腹中书。","（〖1〗鄭愿，《新唐书·宰相世系表》載爲鄭氏南祖房清河令文睿子，無仕歷。","《郎官石柱題名》其名兩见，司勳員外郎在盧象後，李嘉祐前，金部郎中在裴眺、鄭楚客间，以諸人时代推，應爲天寶、大曆间人。","）。"]', '诗', 'shi', '', NULL, '七夕臥病 鄭愿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df260ca2-a64c-46df-8412-f28b1e2bc94d', '守歲', '守歲', '000e8297-4cb4-4b1c-a154-837dc73c6137', '唐', '["吾家貴主鳳樓開，故歲□更亂箭催。","願奉神仙長獻酒，請留哥（歌）吹遂（逐）[一]行□。","（[一]依劉校。","劉並疑行下所缺當是「盃」字。","）。"]', '["吾家貴主鳳楼开，故歲□更亂箭催。","願奉神仙长獻酒，請留哥（歌）吹遂（逐）[一]行□。","（[一]依劉校。","劉並疑行下所缺當是「盃」字。","）。"]', '诗', 'shi', '', NULL, '守歲 鄭愿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b7fca10-a376-4e86-97d1-11e69bf55f2e', '過王濬墓（二首）', '過王濬墓（二首）', '877ec342-2b6b-4ca3-bd69-5ee7e408c179', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, '過王濬墓（二首） 李休烈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca26858c-ce9f-4d0a-a9cd-c696090bb130', '過王濬墓（二首） 一', '過王濬墓（二首） 一', '877ec342-2b6b-4ca3-bd69-5ee7e408c179', '唐', '["青史高遺迹，黃壚掩舊封。","寧知陌上□[一]，（項云據《晉書·羊祜傳》，當補「獸」字。","）何羨水中龍。"]', '["青史高遺迹，黄壚掩旧封。","寧知陌上□[一]，（項云據《晉书·羊祜傳》，當補「獸」字。","）何羨水中龙。"]', '诗', 'shi', '', NULL, '過王濬墓（二首） 一 李休烈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42d30611-03f7-4a67-8fe9-ab1fdf72da37', '過王濬墓（二首） 二', '過王濬墓（二首） 二', '877ec342-2b6b-4ca3-bd69-5ee7e408c179', '唐', '["樵採徒爲禁，英威豈得從。","定知[□]路蟻，（項疑闕字在「路」字下。","）不畏水中龍。","（[一]劉疑「虎」字。","）。"]', '["樵採徒爲禁，英威豈得從。","定知[□]路蟻，（項疑闕字在「路」字下。","）不畏水中龙。","（[一]劉疑「虎」字。","）。"]', '诗', 'shi', '', NULL, '過王濬墓（二首） 二 李休烈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd2561bd-5e74-4b2c-9636-318b3aedfdc4', '詠暗', '詠暗', 'fc3d8ce4-d557-4252-84eb-c954f0c643a1', '唐', '["鑿壁方將□，投珠忽見疑。","始言纓可絕，誰謂室無欺。"]', '["鑿壁方將□，投珠忽见疑。","始言纓可絕，誰謂室無欺。"]', '诗', 'shi', '', NULL, '詠暗 孟嬰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c102b3b-99f2-4234-97d9-762570fef9c9', '詠鵲', '詠鵲', '0c23b0ac-0d40-4f12-b958-7b972496996b', '唐', '["繞樹棲難定，填河尚未期。","舊來能□語，試爲報歸時。"]', '["繞樹棲难定，填河尚未期。","旧来能□語，試爲報归时。"]', '诗', 'shi', '', NULL, '詠鵲 □嘉惠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d6c114a-b7fc-44c0-a6ec-529ffbaa234f', '送陳先生還嵩山', '送陳先生還嵩山', '130d8c10-3f64-46f4-ab15-13d9cbd34e7c', '唐', '["玉臺金闕□微微，仙鶴聯翩何歲歸。","欲識人間相望處，嵩高山上白雲飛。","（〖1〗《新唐書·宰相世系表》鄭氏北祖房有韞玉，爲侍御史歡子，不載仕歷，鄭珣瑜、鄭餘慶爲其從昆，知應爲貞元、元和間人。","）。"]', '["玉台金闕□微微，仙鹤聯翩何歲归。","欲識人间相望处，嵩高山上白云飞。","（〖1〗《新唐书·宰相世系表》鄭氏北祖房有韞玉，爲侍御史歡子，不載仕歷，鄭珣瑜、鄭餘慶爲其從昆，知應爲貞元、元和间人。","）。"]', '诗', 'shi', '', NULL, '送陳先生還嵩山 鄭韞玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8369b663-f67c-4d3c-8d13-490e8265dee9', '及第後讀書院詠物[一]十首上禮部李侍郎 簾鈎', '及第後读书院詠物[一]十首上禮部李侍郎 簾鈎', '2c433fbf-4d75-48ae-b2a8-c813265bc3d9', '唐', '["成器屈雖深，君門幸許臨。","卷時懷勁節，舒後抱虛心。","就曲全□保，能剛□匪侵。","倚身當盡力，不欲負工金。","（[一]原作物詠，依劉校互乙。","）。"]', '["成器屈雖深，君门幸許臨。","卷时懷勁節，舒後抱虛心。","就曲全□保，能剛□匪侵。","倚身當尽力，不欲負工金。","（[一]原作物詠，依劉校互乙。","）。"]', '诗', 'shi', '', NULL, '及第後讀書院詠物[一]十首上禮部李侍郎 簾鈎 樊鑄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97eedc19-338b-43e5-bb96-da40d1d8ad5c', '及第後讀書院詠物[一]十首上禮部李侍郎 鞭鞘', '及第後读书院詠物[一]十首上禮部李侍郎 鞭鞘', '2c433fbf-4d75-48ae-b2a8-c813265bc3d9', '唐', '["幸約策爲名，提攜道正（上）[一]行。","卜隣貞幹並，□質真繩幷。","節峻根堪託，柔多指可縈。","希看着鞭處，下下振聲明。","（[一]依劉校。","）。"]', '["幸約策爲名，提携道正（上）[一]行。","卜隣貞幹並，□質真繩幷。","節峻根堪託，柔多指可縈。","希看着鞭处，下下振声明。","（[一]依劉校。","）。"]', '诗', 'shi', '', NULL, '及第後讀書院詠物[一]十首上禮部李侍郎 鞭鞘 樊鑄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f9d18a0-6304-4f15-95f1-9b186b25fe81', '及第後讀書院詠物[一]十首上禮部李侍郎 箭括', '及第後读书院詠物[一]十首上禮部李侍郎 箭括', '2c433fbf-4d75-48ae-b2a8-c813265bc3d9', '唐', '["刻□□材圓，相成□不偏。","守規心已正，受省禮仍全。","有節通貞幹，無邪抱直弦。","向非兼羽翼，何得札俱穿。"]', '["刻□□材圓，相成□不偏。","守規心已正，受省禮仍全。","有節通貞幹，無邪抱直弦。","向非兼羽翼，何得札俱穿。"]', '诗', 'shi', '', NULL, '及第後讀書院詠物[一]十首上禮部李侍郎 箭括 樊鑄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff988a0a-afe4-4a06-ba87-c839abc3dc69', '及第後讀書院詠物[一]十首上禮部李侍郎 門扂', '及第後读书院詠物[一]十首上禮部李侍郎 门扂', '2c433fbf-4d75-48ae-b2a8-c813265bc3d9', '唐', '["扃要政攸敦，防非道久尊。","掄材矩已中，善閉契□存。","只慎樞機動，寧矝開闔恩。","自非蒙一拔，何得入龍門。"]', '["扃要政攸敦，防非道久尊。","掄材矩已中，善閉契□存。","只慎樞機动，寧矝开闔恩。","自非蒙一拔，何得入龙门。"]', '诗', 'shi', '', NULL, '及第後讀書院詠物[一]十首上禮部李侍郎 門扂 樊鑄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9845e41-ba38-4332-9ef3-c57e7592a309', '及第後讀書院詠物[一]十首上禮部李侍郎 錀匙', '及第後读书院詠物[一]十首上禮部李侍郎 錀匙', '2c433fbf-4d75-48ae-b2a8-c813265bc3d9', '唐', '["開物務便成，通幽自有程。","退藏緣遇暗，入用爲逢明。","契理關潛受，知機力不爭。","賴因相啟發，遂得振金聲。"]', '["开物務便成，通幽自有程。","退藏緣遇暗，入用爲逢明。","契理关潛受，知機力不爭。","賴因相啟發，遂得振金声。"]', '诗', 'shi', '', NULL, '及第後讀書院詠物[一]十首上禮部李侍郎 錀匙 樊鑄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('682bdadf-8d41-40a1-9c70-f6b6bee6c279', '及第後讀書院詠物[一]十首上禮部李侍郎 藥臼[一]', '及第後读书院詠物[一]十首上禮部李侍郎 藥臼[一]', '2c433fbf-4d75-48ae-b2a8-c813265bc3d9', '唐', '["器重性仍堅，登庸響即傳。","口因良藥苦，心爲中規圓。","繼務精三代，輪攻孕十全。","終齊善救理，莫謂枉陶甄。","（[一]劉云：「『臼』與『救』同，聲爲上去，故可作音源。","」）。"]', '["器重性仍堅，登庸响即傳。","口因良藥苦，心爲中規圓。","繼務精三代，輪攻孕十全。","終齊善救理，莫謂枉陶甄。","（[一]劉云：「『臼』與『救』同，声爲上去，故可作音源。","」）。"]', '诗', 'shi', '', NULL, '及第後讀書院詠物[一]十首上禮部李侍郎 藥臼[一] 樊鑄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ac80bef-9f79-40f7-8cda-37a53eef3a75', '及第後讀書院詠物[一]十首上禮部李侍郎 濾水羅', '及第後读书院詠物[一]十首上禮部李侍郎 濾水羅', '2c433fbf-4d75-48ae-b2a8-c813265bc3d9', '唐', '["經緯既縱橫，偏承啟沃情。","含虛素心淨，樂水智囊成。","密㥀（緻）[一]能藏垢，疏通自去盈。","不問垂善濾，何問下流清。","（[一]余疑「㥀」是「緻」通用俗字，或音誤。","俞云：「校作『緻』，較遠，疑當作『慎』，因濾水羅正不必密緻也。","密慎與下文疎通對文。","」按俞先生說較好。","劉校與俞同。","）。"]', '["經緯既縱橫，偏承啟沃情。","含虛素心淨，乐水智囊成。","密㥀（緻）[一]能藏垢，疏通自去盈。","不问垂善濾，何问下流清。","（[一]余疑「㥀」是「緻」通用俗字，或音誤。","俞云：「校作『緻』，較远，疑當作『慎』，因濾水羅正不必密緻也。","密慎與下文疎通对文。","」按俞先生说較好。","劉校與俞同。","）。"]', '诗', 'shi', '', NULL, '及第後讀書院詠物[一]十首上禮部李侍郎 濾水羅 樊鑄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab37945f-35ee-4adb-98bb-61fa2e3dc009', '及第後讀書院詠物[一]十首上禮部李侍郎 井轆轤', '及第後读书院詠物[一]十首上禮部李侍郎 井轆轤', '2c433fbf-4d75-48ae-b2a8-c813265bc3d9', '唐', '["有幸奉陶甄，時行即轉圓。","從繩每合轍，遇坎本（奉）[一]周旋。","□是循環正，何曾汲引偏。","已承鈞軸力，不慮墜諸泉。","（[一]依劉校。","）。"]', '["有幸奉陶甄，时行即轉圓。","從繩每合轍，遇坎本（奉）[一]周旋。","□是循环正，何曾汲引偏。","已承鈞軸力，不慮墜諸泉。","（[一]依劉校。","）。"]', '诗', 'shi', '', NULL, '及第後讀書院詠物[一]十首上禮部李侍郎 井轆轤 樊鑄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69eb713b-debc-48c6-8f58-b1304b84df2f', '及第後讀書院詠物[一]十首上禮部李侍郎 塼道', '及第後读书院詠物[一]十首上禮部李侍郎 塼道', '2c433fbf-4d75-48ae-b2a8-c813265bc3d9', '唐', '["入用因埏埴，時行任比方。","連階（下缺）。"]', '["入用因埏埴，时行任比方。","連階（下缺）。"]', '诗', 'shi', '', NULL, '及第後讀書院詠物[一]十首上禮部李侍郎 塼道 樊鑄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5b4a22d-9d2b-466a-984f-4542b7b87aeb', '及第後讀書院詠物[一]十首上禮部李侍郎 □□（伯三四八○）', '及第後读书院詠物[一]十首上禮部李侍郎 □□（伯三四八○）', '2c433fbf-4d75-48ae-b2a8-c813265bc3d9', '唐', '["鑄劍本來殺讎[一]人，懷珠本來報國士。","信知善惡皆相報，如何不肯樹桃李。","物情飜覆難可論，莫言權勢長頭[二]存。","鼎食却爲農桑子，布衣還啟丞相門。","丈夫立身須自省，知禍知福如形影。","乍可惠人一飯恩，不得唾人千里井。","（[一]原作「讎殺」，依劉校互乙。","[二]劉云：「『長頭』二字乃俗語。","『頭』，尾聲。","」）。"]', '["鑄劍本来殺讎[一]人，懷珠本来報国士。","信知善惡皆相報，如何不肯樹桃李。","物情飜覆难可論，莫言權勢长头[二]存。","鼎食却爲農桑子，布衣還啟丞相门。","丈夫立身須自省，知禍知福如形影。","乍可惠人一飯恩，不得唾人千里井。","（[一]原作「讎殺」，依劉校互乙。","[二]劉云：「『长头』二字乃俗語。","『头』，尾声。","」）。"]', '诗', 'shi', '', NULL, '及第後讀書院詠物[一]十首上禮部李侍郎 □□（伯三四八○） 樊鑄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73301ed1-90ac-47d4-9cb4-71b57578f215', '登岐州城樓', '登岐州城楼', '537711b5-aac1-4e6b-9eec-b3d8628206cd', '唐', '["岐雍三秦地，登臨實壯哉！客心關外斷，秋氣隴頭來。","歸目浮雲蔽，寒衣早雁催。","他鄉有時菊，留賞故人盃。"]', '["岐雍三秦地，登臨實壯哉！客心关外斷，秋氣隴头来。","归目浮云蔽，寒衣早雁催。","他乡有时菊，留賞故人盃。"]', '诗', 'shi', '', NULL, '登岐州城樓 皇甫斌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c436ab6b-20b3-4a59-9b95-a60ebabb5fbe', '秋夜（伯三六一九。又三八八五）', '秋夜（伯三六一九。又三八八五）', '98c9f7c9-e18f-4de4-9192-0032be090b02', '唐', '["數夜獨無歡，客心恆不安。","近城聞鼓異（易），遠寺[一]聽鐘難。","月照窗邊暖，風吹簾外寒。","齊能羅帳裏，獨坐抱琴彈。","（[一]原作「寺遠」，依劉校互乙。","）。"]', '["數夜独無歡，客心恆不安。","近城闻鼓異（易），远寺[一]听鐘难。","月照窗邊暖，风吹簾外寒。","齊能羅帳裏，独坐抱琴彈。","（[一]原作「寺远」，依劉校互乙。","）。"]', '诗', 'shi', '', NULL, '秋夜（伯三六一九。又三八八五） 桓顒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7e4d2f0-31ec-4781-8a6c-1708f7fe618a', '無題（伯三一九七）', '無題（伯三一九七）', '01e4e764-5efd-49d5-8195-92ca5af4a353', '唐', '["躺遊仙院覩靈臺，羅綺分明塑匠裁。","高綰綠鬟{髟/云}（雲）髻重，手垂羅袖牡丹開。","（「手垂」，項目疑當作「平垂」，與「高綰」爲對。","）容儀一見情難捨，玉貌重看意嬾迴。","若表懇成（誠）心所志，願將恣貌夢中來。","（「恣」，蔣、項皆云當作「姿」。","）。"]', '["躺游仙院覩靈台，羅綺分明塑匠裁。","高綰綠鬟{髟/云}（云）髻重，手垂羅袖牡丹开。","（「手垂」，項目疑當作「平垂」，與「高綰」爲对。","）容儀一见情难捨，玉貌重看意嬾迴。","若表懇成（誠）心所志，願將恣貌梦中来。","（「恣」，蔣、項皆云當作「姿」。","）。"]', '诗', 'shi', '', NULL, '無題（伯三一九七） 盧茂欽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e18f811c-17a3-487e-b435-a6381cb79c8a', '觀岳壽寺松因課留題（斯七六）', '观岳壽寺松因課留題（斯七六）', '6111bc32-599c-4deb-b8ca-4e4fe7d52935', '唐', '["植來高節歲經霜，濃翠穿雲出上方。","花界静標千樹秀，禪心閑對四時涼。","根磻蘚石龍形老，（「磻」，蔣、項皆云當作「蟠」。","）乳滴金沙琥珀香。","爲愛奇材看在盡，題詩留在遠公房。"]', '["植来高節歲經霜，濃翠穿云出上方。","花界静標千樹秀，禪心闲对四时涼。","根磻蘚石龙形老，（「磻」，蔣、項皆云當作「蟠」。","）乳滴金沙琥珀香。","爲愛奇材看在尽，題诗留在远公房。"]', '诗', 'shi', '', NULL, '觀岳壽寺松因課留題（斯七六） 劉延堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6eea6be4-7440-4134-84c3-f0e6696da634', '寓止觀中因抒感懷', '寓止观中因抒感懷', '6111bc32-599c-4deb-b8ca-4e4fe7d52935', '唐', '["伯陽宮館好煙霞，知换浮生幾歲華。","雖訪靈芝身不遠，未逢真訣道還賒。","玉清難測無窮景，金露能摧有限花。","南待總拋榮辱了，始應親近得仙家。"]', '["伯陽宮館好煙霞，知换浮生幾歲华。","雖訪靈芝身不远，未逢真訣道還賒。","玉清难測無窮景，金露能摧有限花。","南待總拋榮辱了，始應親近得仙家。"]', '诗', 'shi', '', NULL, '寓止觀中因抒感懷 劉延堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('423e0c01-5407-4c3f-8b1a-25eaf9c85d13', '登靈巖寺（伯三六一九）', '登靈巖寺（伯三六一九）', 'f40ac517-7318-4cf1-9b70-4db78c002b92', '唐', '["靈岳多奇勢，茲山負聖圖。","谷中清溜響，峯際白雲孤。","石壁連霄漢，長松落澗枯。","澄心香閣下，煩慮寂然無。","（斯三八一卷《龍興寺毗沙門天王靈驗記》，錄「大蕃歲次辛巳潤二月十五日」事，署「本寺大德僧日進附口抄」。","疑即本詩作者。","「大蕃歲次辛巳」即唐貞元十七年〖八○一〗。","龍興寺爲敦煌名剎，遺書中記載較多。","）。"]', '["靈岳多奇勢，茲山負聖圖。","谷中清溜响，峯際白云孤。","石壁連霄漢，长松落澗枯。","澄心香閣下，煩慮寂然無。","（斯三八一卷《龙兴寺毗沙门天王靈驗記》，錄「大蕃歲次辛巳潤二月十五日」事，署「本寺大德僧日進附口抄」。","疑即本诗作者。","「大蕃歲次辛巳」即唐貞元十七年〖八○一〗。","龙兴寺爲敦煌名剎，遺书中記載較多。","）。"]', '诗', 'shi', '', NULL, '登靈巖寺（伯三六一九） 沙門日進 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c987e46b-4ec1-40ae-a454-553d40735424', '秦箏怨（伯三八八五）', '秦箏怨（伯三八八五）', 'b28c3c5c-1fcc-4686-8906-4767aa15d829', '唐', '["玳瑁秦箏裏，聲聲怨別離。","只緣多苦調，欲奏淚還垂。","妾意如絃直，君心學柱移。","蹔時停不弄，音調早參差。"]', '["玳瑁秦箏裏，声声怨別離。","只緣多苦調，欲奏泪還垂。","妾意如絃直，君心学柱移。","蹔时停不弄，音調早參差。"]', '诗', 'shi', '', NULL, '秦箏怨（伯三八八五） 宋家娘子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddca4880-a42d-4a45-b3de-56508296f058', '春尋花柳得情（三八一二）', '春尋花柳得情（三八一二）', 'b28c3c5c-1fcc-4686-8906-4767aa15d829', '唐', '["美人林裏趁鵶兒，銀甲花間不覺遺。","連忙借問嬌鸚鵡，鳥鳥銜將與阿誰？。"]', '["美人林裏趁鵶兒，銀甲花间不覺遺。","連忙借问嬌鸚鵡，鸟鸟銜將與阿誰？。"]', '诗', 'shi', '', NULL, '春尋花柳得情（三八一二） 宋家娘子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59da975c-ad0a-4cc9-b249-21b056316559', '前言', '前言', '801aa8e4-9a4c-4c4e-be1f-09c0b50e8d14', '唐', '["有三（重民）據敦煌殘卷補《全唐詩》的整理工作，曾化過二十多年的心血。","按照原來計劃，全稿分爲三卷：「卷一均有作者姓氏，專補《全唐詩》；卷二均失作者姓氏，凡殘詩集依集編次，凡選詩（指單篇的）依詩編次；卷三爲敦煌人作品（詠敦煌者如《敦煌廿詠》亦入此卷）。","」其中卷一曾以《補全唐詩》爲題，發表於《中華文史論叢》一九六三年第三期。","卷二、卷三的遺稿，雖已基本就緒，則因他不幸逝世，未能最後定稿。","在他生前，曾將其中一部份請王堯同志校閱；有三逝世後，又經舒學同志整理，題爲《敦煌唐人詩集殘卷》，發表在《文物資料叢刊》第一期（一九七七年）上。","最近，我在整理有三輯錄的敦煌殘卷詩集時，又發現了《補全唐詩》卷一漏編的有作者姓氏的詩，一是李翔的《涉道詩》，據有三生前考定，李翔生活的時代比韓愈稍晚；另一即馬雲奇被吐蕃俘虜時寫的紀行詩，已收入《敦煌唐人詩集殘卷》。","此外還有原來擬編入《補全唐詩》卷二、卷三的部份已輯錄的遺稿，其中有「殘詩集」、「單篇」詩，還有「敦煌人作品」。","現依照有三生前計劃，重新整理，並將發表於《文物資料叢刊》部份亦一併輯入各卷，並改了其中未校出的錯字。","按照有三原來計劃，本拾遺編次如下：卷一殘詩集（《補全唐詩》漏編）李翔《涉道詩》（伯三八六六）廿八首馬雲奇詩集殘卷（伯二五五五）十三首卷二佚名的詩殘詩集（伯二五五五）五十九首王昭君怨諸詞人連句（伯二七四八）一首謁法門寺真身五十韵（伯三四四五）一首無題（斯五五五八）一首卷三敦煌人作品敦煌廿詠並序附一首共二十一首凡六寫本，其原編號如下：原卷（伯二七四八）、甲卷（伯三九二九）、乙卷（伯二九八三）、丙卷（伯三八七○）、丁卷（斯六一六七）、戊卷（伯二六九○背）詠敦煌詩（伯五○○七）三首每種詩題下註明所據卷子號碼，有兩個寫本者，亦一一註明，連同校記文字，附各詩之後。","詩有異文，略作校勘；原有錯字，用括號註出，不清楚的字，用方框表示。","但敦煌殘卷的詩，鈔寫多用俗字，如「軀」作「𨈬」，「鎖」作「鏁」，此外還有「總」字常作「惣」，「閉」字常作「閇」，今即逕改，不加註。","在整理工作中，借力於舒學同志的《敦煌唐人詩集殘卷》整理稿不少；馬蹄疾同志對整理工作提了建設性的意見，並爲校讀了前言；初稿寫出後，請陰法魯同志校閱，給我提出了很好的意見，並校出一些錯誤的字；《中華文史論叢》編輯同志爲此稿發表作了很多工作，謹一併在此致謝。","整理工作中所校錄文字，有不當之處，誠望指正。","劉脩業記於有三逝世五週年祭時公元一九八○年四月十六日此整理稿初次發表時，對伯二五五五卷馬雲奇詩及佚名詩的考定與分析，是採用舒學同志的原序，撮要迻錄附於詩後。","有三生前對這些詩亦有考釋，似覺得對這七十二首詩的寫作背景及所反映時代特色的考定與分析較爲符合實際，故此次編集時，已請本書責任編輯將馬雲奇及佚名詩後的說明作了修訂。","劉脩業一九八三年一月三日又記。"]', '["有三（重民）據敦煌殘卷補《全唐诗》的整理工作，曾化過二十多年的心血。","按照原来計劃，全稿分爲三卷：「卷一均有作者姓氏，專補《全唐诗》；卷二均失作者姓氏，凡殘诗集依集編次，凡選诗（指單篇的）依诗編次；卷三爲敦煌人作品（詠敦煌者如《敦煌廿詠》亦入此卷）。","」其中卷一曾以《補全唐诗》爲題，發表於《中华文史論叢》一九六三年第三期。","卷二、卷三的遺稿，雖已基本就緒，則因他不幸逝世，未能最後定稿。","在他生前，曾將其中一部份請王堯同志校閱；有三逝世後，又經舒学同志整理，題爲《敦煌唐人诗集殘卷》，發表在《文物資料叢刊》第一期（一九七七年）上。","最近，我在整理有三輯錄的敦煌殘卷诗集时，又發現了《補全唐诗》卷一漏編的有作者姓氏的诗，一是李翔的《涉道诗》，據有三生前考定，李翔生活的时代比韓愈稍晚；另一即马云奇被吐蕃俘虜时寫的紀行诗，已收入《敦煌唐人诗集殘卷》。","此外還有原来擬編入《補全唐诗》卷二、卷三的部份已輯錄的遺稿，其中有「殘诗集」、「單篇」诗，還有「敦煌人作品」。","現依照有三生前計劃，重新整理，並將發表於《文物資料叢刊》部份亦一併輯入各卷，並改了其中未校出的錯字。","按照有三原来計劃，本拾遺編次如下：卷一殘诗集（《補全唐诗》漏編）李翔《涉道诗》（伯三八六六）廿八首马云奇诗集殘卷（伯二五五五）十三首卷二佚名的诗殘诗集（伯二五五五）五十九首王昭君怨諸词人連句（伯二七四八）一首謁法门寺真身五十韵（伯三四四五）一首無題（斯五五五八）一首卷三敦煌人作品敦煌廿詠並序附一首共二十一首凡六寫本，其原編號如下：原卷（伯二七四八）、甲卷（伯三九二九）、乙卷（伯二九八三）、丙卷（伯三八七○）、丁卷（斯六一六七）、戊卷（伯二六九○背）詠敦煌诗（伯五○○七）三首每種诗題下註明所據卷子號碼，有兩個寫本者，亦一一註明，連同校記文字，附各诗之後。","诗有異文，略作校勘；原有錯字，用括號註出，不清楚的字，用方框表示。","但敦煌殘卷的诗，鈔寫多用俗字，如「軀」作「𨈬」，「鎖」作「鏁」，此外還有「總」字常作「惣」，「閉」字常作「閇」，今即逕改，不加註。","在整理工作中，借力於舒学同志的《敦煌唐人诗集殘卷》整理稿不少；马蹄疾同志对整理工作提了建設性的意见，並爲校读了前言；初稿寫出後，請陰法魯同志校閱，給我提出了很好的意见，並校出一些錯誤的字；《中华文史論叢》編輯同志爲此稿發表作了很多工作，謹一併在此致謝。","整理工作中所校錄文字，有不當之处，誠望指正。","劉脩業記於有三逝世五週年祭时公元一九八○年四月十六日此整理稿初次發表时，对伯二五五五卷马云奇诗及佚名诗的考定與分析，是採用舒学同志的原序，撮要迻錄附於诗後。","有三生前对這些诗亦有考釋，似覺得对這七十二首诗的寫作背景及所反映时代特色的考定與分析較爲符合實際，故此次編集时，已請本书責任編輯將马云奇及佚名诗後的说明作了修訂。","劉脩業一九八三年一月三日又記。"]', '诗', 'shi', '', NULL, '前言 王重民輯錄，劉脩業整理。 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f54266ff-9369-4655-920c-9a56a2a06417', '', '', '433df264-1599-46ad-b60d-a35497a0f033', '唐', '["（《涉道詩》二十八首〖伯三八六六〗）。"]', '["（《涉道诗》二十八首〖伯三八六六〗）。"]', '诗', 'shi', '', NULL, ' 李翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45ebc19f-70f0-4e18-80d3-e66aa770dae8', '看縉雲山圖', '看縉云山圖', '433df264-1599-46ad-b60d-a35497a0f033', '唐', '["謂見仙都二十年，（謂，項疑當作「未」。","）忽逢圖畫頓欣然。","雲巖不似人間世，物象翻疑洞裏天。","迥壓鰲頭當海眼，直侵鵬路倚星躔。","頂湖縱去無多地，空見霜流百丈泉。"]', '["謂见仙都二十年，（謂，項疑當作「未」。","）忽逢圖畫頓欣然。","云巖不似人间世，物象翻疑洞裏天。","迥壓鰲头當海眼，直侵鵬路倚星躔。","頂湖縱去無多地，空见霜流百丈泉。"]', '诗', 'shi', '', NULL, '看縉雲山圖 李翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9525d9ff-afb5-4d41-8282-a1ee245d52a5', '百步橋', '百步橋', '433df264-1599-46ad-b60d-a35497a0f033', '唐', '["亘險凌虛百步橋，古應從此上千（干）霄。","（「古應」，項疑當作「故應」。","）不辭宛轉峰千仞，且喜分明路一條。","銀漢攀緣知必到，月宮斟酌去非遙。","牽牛漫更勞烏鵲，歲歲填河綠頂爑（焦）。"]', '["亘險凌虛百步橋，古應從此上千（干）霄。","（「古應」，項疑當作「故應」。","）不辞宛轉峰千仞，且喜分明路一條。","銀漢攀緣知必到，月宮斟酌去非遙。","牽牛漫更勞烏鵲，歲歲填河綠頂爑（焦）。"]', '诗', 'shi', '', NULL, '百步橋 李翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5071d3f2-4f87-4842-b9fc-aff90fba57c5', '投龍池', '投龙池', '433df264-1599-46ad-b60d-a35497a0f033', '唐', '["虎眼渦盤石窟中，古今俱向此投龍。","奫淪不啻深千丈，肹（肸）蠁皆應到九重。","洞穴昔聞通地府，風雲今得遇靈蹤。","無因犯世間雷雨，池面連天拔一峰。"]', '["虎眼渦盤石窟中，古今俱向此投龙。","奫淪不啻深千丈，肹（肸）蠁皆應到九重。","洞穴昔闻通地府，风云今得遇靈蹤。","無因犯世间雷雨，池面連天拔一峰。"]', '诗', 'shi', '', NULL, '投龍池 李翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d94be113-93a0-41ff-88c5-74474f44631a', '頂湖', '頂湖', '433df264-1599-46ad-b60d-a35497a0f033', '唐', '["萬仞峰頭鑿一湖，更誰來此用功夫。","張霞鱲（鬣）是星河鯉，濯火領多日御烏。","往往風波聞下界，時時花雨護仙都。"]', '["万仞峰头鑿一湖，更誰来此用功夫。","張霞鱲（鬣）是星河鯉，濯火領多日御烏。","往往风波闻下界，时时花雨護仙都。"]', '诗', 'shi', '', NULL, '頂湖 李翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f583912d-b45d-4a3b-9299-f14eec0b33a8', '石鶴', '石鹤', '433df264-1599-46ad-b60d-a35497a0f033', '唐', '["白石孤標逸鶴形，古人隨類巧安名。","巖花落處見朱頂，夜雨來時聞唳聲。","遼海未曾重寄語，緱山今更請寬程。","若教衛懿如今在，也遣軒車到此迎。"]', '["白石孤標逸鹤形，古人隨類巧安名。","巖花落处见朱頂，夜雨来时闻唳声。","遼海未曾重寄語，緱山今更請寬程。","若教衛懿如今在，也遣軒车到此迎。"]', '诗', 'shi', '', NULL, '石鶴 李翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('952663f4-dcc2-4359-87fc-bdc6cb8ab378', '謝公石罇', '謝公石罇', '433df264-1599-46ad-b60d-a35497a0f033', '唐', '["康樂雲樓跡尚存，竹亭猶仰古窪罇。","苔封四面迷山象，露滴中心認酒痕。","巖月舊來曾伴飲，澗泉今咽共誰論。","無因訪得逃堯客，求取風瓢掛石門。"]', '["康乐云楼跡尚存，竹亭猶仰古窪罇。","苔封四面迷山象，露滴中心認酒痕。","巖月旧来曾伴饮，澗泉今咽共誰論。","無因訪得逃堯客，求取风瓢掛石门。"]', '诗', 'shi', '', NULL, '謝公石罇 李翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f72c0a42-7bfc-4a5d-bdb3-47a0ae347d91', '童子山', '童子山', '433df264-1599-46ad-b60d-a35497a0f033', '唐', '["童子山形也不孤，勢疑高拱從（聳）（僊）都。","雲生石肘如擎帔，月到巖心似捧壼。","豈可繞壇操鳯節，争教侍（持）燭秉麟鬚。","（項云「侍」字似不誤，猶「侍酒」、「侍書」之「侍」也。","）桑田若更成東海，始肯隨師化此軀。"]', '["童子山形也不孤，勢疑高拱從（聳）（僊）都。","云生石肘如擎帔，月到巖心似捧壼。","豈可繞壇操鳯節，争教侍（持）燭秉麟鬚。","（項云「侍」字似不誤，猶「侍酒」、「侍书」之「侍」也。","）桑田若更成东海，始肯隨師化此軀。"]', '诗', 'shi', '', NULL, '童子山 李翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cc56693-c573-4887-af9b-ee7a4e1d5438', '嚴尚書重浚橫泉井', '嚴尚书重浚橫泉井', '433df264-1599-46ad-b60d-a35497a0f033', '唐', '["古甃千尋鎖綠苔，老蛟曾遯（遁）此中來。","厭聆羽客提鋒入，喜見將軍杖（仗）節開。","玉液洞通甘似醴，金瓶輪下殷如雷，更聞堪療羣生疾，願倚崇欄飲一杯。","。"]', '["古甃千尋鎖綠苔，老蛟曾遯（遁）此中来。","厭聆羽客提鋒入，喜见將軍杖（仗）節开。","玉液洞通甘似醴，金瓶輪下殷如雷，更闻堪療羣生疾，願倚崇欄饮一杯。","。"]', '诗', 'shi', '', NULL, '嚴尚書重浚橫泉井 李翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c289403-1a7a-4999-abea-a2007d73c984', '許真君鐵柱', '許真君鐵柱', '433df264-1599-46ad-b60d-a35497a0f033', '唐', '["恐老蛟重作患深[一]，獨埋鐵柱至如今。","根牢直下蟠江底，勢壯長留鎮郡心。","神鬼每聞趨夜後，風雷不敢犯塘陰。","無因更走橫泉窟，壓斷祈精氣永沉。","（[一]首句有誤，疑當作「深恐老蛟重作患」。","）。"]', '["恐老蛟重作患深[一]，独埋鐵柱至如今。","根牢直下蟠江底，勢壯长留鎮郡心。","神鬼每闻趨夜後，风雷不敢犯塘陰。","無因更走橫泉窟，壓斷祈精氣永沉。","（[一]首句有誤，疑當作「深恐老蛟重作患」。","）。"]', '诗', 'shi', '', NULL, '許真君鐵柱 李翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67aaf6ce-ab3a-4b12-87b9-8cc998c5f223', '題麻姑山廟', '題麻姑山廟', '433df264-1599-46ad-b60d-a35497a0f033', '唐', '["險翠峨霄壓上游，大仙曾向此幽求。","雲埋三級壇空在，月照千尋水自流。","偃蓋鶴還清露滴，古池龍睡碧蓮秋。","桑田未必翻爲海，香火何人解繼修。"]', '["險翠峨霄壓上游，大仙曾向此幽求。","云埋三級壇空在，月照千尋水自流。","偃蓋鹤還清露滴，古池龙睡碧蓮秋。","桑田未必翻爲海，香火何人解繼修。"]', '诗', 'shi', '', NULL, '題麻姑山廟 李翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28958c31-0d3d-4757-bbf3-0511f02f2c03', '軍山前馬退石', '軍山前马退石', '433df264-1599-46ad-b60d-a35497a0f033', '唐', '["山亘南豐石亘山，石橫山路馬登難。","非論蹇步須回駕，縱使追風亦解鞍。","恐是龍宮通洞府，莫應猿嶺建星壇。","何因不許超驤輩，踏着連雲大麓端。"]', '["山亘南豐石亘山，石橫山路马登难。","非論蹇步須回駕，縱使追风亦解鞍。","恐是龙宮通洞府，莫應猿嶺建星壇。","何因不許超驤輩，踏着連云大麓端。"]', '诗', 'shi', '', NULL, '軍山前馬退石 李翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f8002ae-3229-4887-8438-03ae13fadddf', '馬明生遇王婉羅', '马明生遇王婉羅', '433df264-1599-46ad-b60d-a35497a0f033', '唐', '["徹骨金瘡分已休，謝神妃護到靈丘。","供丞（承）洞府知何地，灑掃雲房不記秋。","金鎖玉函雖照燿，寶書真篆敢規（窺）求。","龍胎未肯傳初學，又逐安期萬里游。"]', '["徹骨金瘡分已休，謝神妃護到靈丘。","供丞（承）洞府知何地，灑掃云房不記秋。","金鎖玉函雖照燿，寶书真篆敢規（窺）求。","龙胎未肯傳初学，又逐安期万里游。"]', '诗', 'shi', '', NULL, '馬明生遇王婉羅 李翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d98076a5-e805-4f4e-b53c-ab15f7eb432d', '登臨川仙臺觀南亭', '登臨川仙台观南亭', '433df264-1599-46ad-b60d-a35497a0f033', '唐', '["獨倚危欄愛景晴，古松壇殿半陰橫。","東山有路干雲險，汝水無波到底清。","歸洞鬬龍收雨脚，拂簷行雁起秋聲。","開襟正是忘機處，不覺疏鐘遍郡城。","。"]', '["独倚危欄愛景晴，古松壇殿半陰橫。","东山有路干云險，汝水無波到底清。","归洞鬬龙收雨脚，拂簷行雁起秋声。","开襟正是忘機处，不覺疏鐘遍郡城。","。"]', '诗', 'shi', '', NULL, '登臨川仙臺觀南亭 李翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de9915a8-402c-4658-a060-967242c56716', '謝梁尊師見訪不遇', '謝梁尊師见訪不遇', '433df264-1599-46ad-b60d-a35497a0f033', '唐', '["曉斸（斲）黃精晝未還（項云「斸」字不誤，不必改。","），豈知仙老降柴關。","一聲歸鶴唳江口，數片白雲遺竹間。","悵望有慚勞羽駕，差池不得禮冰顏。","秋風獨倚書齋立，遙想真暉對暮山。"]', '["晓斸（斲）黄精晝未還（項云「斸」字不誤，不必改。","），豈知仙老降柴关。","一声归鹤唳江口，數片白云遺竹间。","悵望有慚勞羽駕，差池不得禮冰顏。","秋风独倚书斋立，遙想真暉对暮山。"]', '诗', 'shi', '', NULL, '謝梁尊師見訪不遇 李翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bb4163b-fad9-4446-bd9f-1f482b1cc20e', '魏夫人歸大霍山', '魏夫人归大霍山', '433df264-1599-46ad-b60d-a35497a0f033', '唐', '["受錫南歸大霍宮，衆真同會絳房中。","裘披鳯錦千花麗，斾綽龍霞八景紅。","羽帔儼排三洞客，仙歌凝韵九天風。","元君未許人先起，更待雲璈一曲終。"]', '["受錫南归大霍宮，衆真同會絳房中。","裘披鳯錦千花丽，斾綽龙霞八景紅。","羽帔儼排三洞客，仙歌凝韵九天风。","元君未許人先起，更待云璈一曲終。"]', '诗', 'shi', '', NULL, '魏夫人歸大霍山 李翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6296651d-15d5-4f47-bb90-6cf2b1b14e62', '馮雙禮珠彈雲璈以答歌', '馮雙禮珠彈云璈以答歌', '433df264-1599-46ad-b60d-a35497a0f033', '唐', '["王母詞終薦碧桃，答歌仙子奏雲璈。","調凌空洞音初起，曲麗鈞天韵更高。","霞斷已翔煙際鶴，風生欲抃海心鰲。","瑤池侍女争回首，無隈琅英墜節毛。","（項云「無隈」當作「無限」，形近而誤。","）。"]', '["王母词終薦碧桃，答歌仙子奏云璈。","調凌空洞音初起，曲丽鈞天韵更高。","霞斷已翔煙際鹤，风生欲抃海心鰲。","瑤池侍女争回首，無隈琅英墜節毛。","（項云「無隈」當作「無限」，形近而誤。","）。"]', '诗', 'shi', '', NULL, '馮雙禮珠彈雲璈以答歌 李翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('308e2373-6855-417a-aeb1-8ea9962be459', '魏夫人受大洞真經', '魏夫人受大洞真經', '433df264-1599-46ad-b60d-a35497a0f033', '唐', '["太極仙公降上清，爲傳三十九章經。","先教稽首丞（承）明詔，次遣齋心向洞冥。","妙句只令巖下讀，真文不許世間聽。","寶函鈿軸披尋遍，始駕龍車謁帝庭。"]', '["太極仙公降上清，爲傳三十九章經。","先教稽首丞（承）明詔，次遣斋心向洞冥。","妙句只令巖下读，真文不許世间听。","寶函鈿軸披尋遍，始駕龙车謁帝庭。"]', '诗', 'shi', '', NULL, '魏夫人受大洞真經 李翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3015c3d8-71dd-4c12-955a-272ad6993d5a', '衛叔卿不賓漢武帝', '衛叔卿不賓漢武帝', '433df264-1599-46ad-b60d-a35497a0f033', '唐', '["鑾殿仙卿頓紫雲，武皇非意欲相臣。","便迴太華三峰路，不喜咸陽萬乘春。","涉險漫勞中禁使，投壺多是上清人。","猶教度世依方術，莫戀浮榮誤爾身。"]', '["鑾殿仙卿頓紫云，武皇非意欲相臣。","便迴太华三峰路，不喜咸陽万乘春。","涉險漫勞中禁使，投壺多是上清人。","猶教度世依方術，莫戀浮榮誤爾身。"]', '诗', 'shi', '', NULL, '衛叔卿不賓漢武帝 李翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d00dfa0b-316c-4478-864a-a9b6fbc900bd', '獻龍虎山張天師', '獻龙虎山張天師', '433df264-1599-46ad-b60d-a35497a0f033', '唐', '["東漢天師直下孫，久依科戒住玄門。","寰中有位逢皆拜，世上無人見不尊。","三洞吏兵潛稽首，六宮魔幻暗銷魂。","可能授與長生籙，浩劫銘肌敢忘恩。"]', '["东漢天師直下孫，久依科戒住玄门。","寰中有位逢皆拜，世上無人见不尊。","三洞吏兵潛稽首，六宮魔幻暗銷魂。","可能授與长生籙，浩劫銘肌敢忘恩。"]', '诗', 'shi', '', NULL, '獻龍虎山張天師 李翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af868f62-2f43-4ef6-ac7d-7237d2dcf4ad', '小有王君別西域總真', '小有王君別西域總真', '433df264-1599-46ad-b60d-a35497a0f033', '唐', '["從事明真入洞臺，便祛秋骨月致仙材。","絳宮玄圃皆尋遍，龜岫龍洲盡到來。","聞啟玉皇過九奏，教詔金液語千回。","謂言得道輕離別，重感師恩泣更哀。"]', '["從事明真入洞台，便祛秋骨月致仙材。","絳宮玄圃皆尋遍，龟岫龙洲尽到来。","闻啟玉皇過九奏，教詔金液語千回。","謂言得道轻離別，重感師恩泣更哀。"]', '诗', 'shi', '', NULL, '小有王君別西域總真 李翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e101ee7c-d8d2-4ffa-88a4-b8f18b9e6c4b', '寄題尋真觀', '寄題尋真观', '433df264-1599-46ad-b60d-a35497a0f033', '唐', '["見說尋真地勢雄，面臨湖北倚高峰。","奔濤入夏雷聲迅，險嶂凌秋黛色濃。","壇上步虛頻降鶴，洞中投簡數驚龍。","何勞更訪桃源路，水曲雲深千萬重。"]', '["见说尋真地勢雄，面臨湖北倚高峰。","奔濤入夏雷声迅，險嶂凌秋黛色濃。","壇上步虛頻降鹤，洞中投簡數驚龙。","何勞更訪桃源路，水曲云深千万重。"]', '诗', 'shi', '', NULL, '寄題尋真觀 李翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70b9acce-940d-490a-b47b-98f2f50356ab', '題金泉山謝自然傳後', '題金泉山謝自然傳後', '433df264-1599-46ad-b60d-a35497a0f033', '唐', '["暫謫歸天固有程，虛皇還召赴三清。","簫歌近向峰頭合，羽駕低臨洞口迎。","自换玉衣期上帝，豈關金格注生名。","門人未得隨師去，雲外空聞好住生[一]。","（[一]北京圖書館藏敦煌卷子「乃」字七四號《辭孃贊》〖伯二九一九號同〗，是出家的青年辭別父母兄弟的唱辭，如首兩句云：「兒欲入山修道去，好住孃，兄弟努力好看孃，好住孃。","」謝自然死了，弟子們不能隨他去，在離別之際所唱的「好住」聲，應該和佛教徒的「好住孃」相類似。","大概受戒的青年道徒在離別父母兄弟的時候，也有這一類的「好住」唱辭。","）。"]', '["暫謫归天固有程，虛皇還召赴三清。","簫歌近向峰头合，羽駕低臨洞口迎。","自换玉衣期上帝，豈关金格注生名。","门人未得隨師去，云外空闻好住生[一]。","（[一]北京圖书館藏敦煌卷子「乃」字七四號《辞孃贊》〖伯二九一九號同〗，是出家的青年辞別父母兄弟的唱辞，如首兩句云：「兒欲入山修道去，好住孃，兄弟努力好看孃，好住孃。","」謝自然死了，弟子們不能隨他去，在離別之際所唱的「好住」声，應該和佛教徒的「好住孃」相類似。","大概受戒的青年道徒在離別父母兄弟的时候，也有這一類的「好住」唱辞。","）。"]', '诗', 'shi', '', NULL, '題金泉山謝自然傳後 李翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4781fa5e-6ec8-48cc-a4c2-157bb3e7dfb6', '宿西山凌雲觀', '宿西山凌云观', '433df264-1599-46ad-b60d-a35497a0f033', '唐', '["掩映真居不易求，自驚何路到蓬丘。","庭心月近石壇古，海面風微山殿秋。","控鶴嶺高星半隔，伏龍崗轉水分流。"]', '["掩映真居不易求，自驚何路到蓬丘。","庭心月近石壇古，海面风微山殿秋。","控鹤嶺高星半隔，伏龙崗轉水分流。"]', '诗', 'shi', '', NULL, '宿西山凌雲觀 李翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e69b8459-17f4-4ffb-8e5c-9666aa21b597', '秋日過龍興觀墨池', '秋日過龙兴观墨池', '433df264-1599-46ad-b60d-a35497a0f033', '唐', '["獨登仙館欲從誰？聞者（有）王君舊墨池。","苔蘚已侵行履跡，窪坳猶是古來規。","竹梢聲認（識）揮毫日，殿角陰疑洗硯時。","{口歎}（歎）倚壇邊紅葉樹，霜鐘欲盡下山遲。"]', '["独登仙館欲從誰？闻者（有）王君旧墨池。","苔蘚已侵行履跡，窪坳猶是古来規。","竹梢声認（識）揮毫日，殿角陰疑洗硯时。","{口歎}（歎）倚壇邊紅葉樹，霜鐘欲尽下山遲。"]', '诗', 'shi', '', NULL, '秋日過龍興觀墨池 李翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f81b6982-1fa1-4634-943f-e16614a78185', '寄麻姑山喻供奉', '寄麻姑山喻供奉', '433df264-1599-46ad-b60d-a35497a0f033', '唐', '["羽客乘風下九天，撥雲親自揀林泉。","檐吞海魄迎真氣，路繞巖根謁古仙。","道豚（遁）早爲三洞伏，（項云「豚」應作「勝」，因「勝」字別體作「𬛊」而誤。","）詩成曾被六宮傳。","如今萬事皆輕棄，只待還丹駐鶴年。"]', '["羽客乘风下九天，撥云親自揀林泉。","檐吞海魄迎真氣，路繞巖根謁古仙。","道豚（遁）早爲三洞伏，（項云「豚」應作「勝」，因「勝」字別體作「𬛊」而誤。","）诗成曾被六宮傳。","如今万事皆轻棄，只待還丹駐鹤年。"]', '诗', 'shi', '', NULL, '寄麻姑山喻供奉 李翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e2f895b-17df-4675-ab98-07b931cab41d', '覽鍊師張殷儒詩', '覽鍊師張殷儒诗', '433df264-1599-46ad-b60d-a35497a0f033', '唐', '["石井峰高劈曙雲，雲開山露見張君。","心藏定遠握中策，袖貯懷沙江上文。","巨壑波翻鯨少敵，老松巢迥鶴難羣。","無端示我青霞句，吟斷秋風到日曛。","。"]', '["石井峰高劈曙云，云开山露见張君。","心藏定远握中策，袖貯懷沙江上文。","巨壑波翻鯨少敵，老松巢迥鹤难羣。","無端示我青霞句，吟斷秋风到日曛。","。"]', '诗', 'shi', '', NULL, '覽鍊師張殷儒詩 李翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7c2d733-2f49-466a-9bcb-23ea2279e90d', '西林寺與樵（焦）鍊師賦得階下泉', '西林寺與樵（焦）鍊師賦得階下泉', '433df264-1599-46ad-b60d-a35497a0f033', '唐', '["迴廊折漩（旋）繞空階，暗西寧舟霜瀉峭崖。","蕙帶客尋經遠澗，麻衣僧引到高齋。","流分曉月光難駐，響入清琴韵易諧。","時有真官訪衰病，每同觀聽蕩幽懷。"]', '["迴廊折漩（旋）繞空階，暗西寧舟霜瀉峭崖。","蕙带客尋經远澗，麻衣僧引到高斋。","流分晓月光难駐，响入清琴韵易諧。","时有真官訪衰病，每同观听蕩幽懷。"]', '诗', 'shi', '', NULL, '西林寺與樵（焦）鍊師賦得階下泉 李翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bd04b45-6fc0-4977-bb76-930f8b439699', '舞鳯石', '舞鳯石', '433df264-1599-46ad-b60d-a35497a0f033', '唐', '["遠見麻姑戲瑞禽，每來教舞此壇心。","基離地面三千丈，勢倚雲根一萬尋。","煙海日搖雙翅影，洞天風散九韻音。","自從越叟分明說，便想羅浮直至今。","（〖1〗上面這些詩寫辰一小冊上，線裝，僅存五葉，共二十八首。","後有殘闕，原書葉數、詩數不知多少。","總題《涉道詩》，下題撰人李翔姓名。","李翔的時代和事跡無所考，這個詩集也不見於著錄。","所歌詠酬答的都是道山道觀，當時道教的天師、尊師、鍊師、總真以及供奉和道教史上的著名人物事跡等。","這應該是一部現存最古的道徒詩集。","〖2〗詩中所表現的山名和地名，多在今江西、江蘇、浙江三省，主要是在龍虎山、茅山、天台山之間，李翔大概就是這一地區以內的人。","他的時代，大概是第九世紀末年或第十世紀初年的人。","謝自然是貞元十一年〖七九五〗十一月十二日卒於梁州西門外金泉山的，韓愈〖七六八--八二四〗有《謝自然詩》〖《昌黎先生集》卷一〗，李翔有《題謝自然傳後》〖傳爲郡守李堅所作〗，所以李翔時代，疑比韓愈稍晚。","〖日本《道教研究》第一冊刊吳其昱《李翔及其涉道詩》推定李翔爲唐高祖九世孫，江王李元祥之後，曾官莆田尉，約於咸通間在世，所據爲《新唐書》卷七○下《宗室世系表》，可備一說。","〗）。"]', '["远见麻姑戲瑞禽，每来教舞此壇心。","基離地面三千丈，勢倚云根一万尋。","煙海日搖雙翅影，洞天风散九韻音。","自從越叟分明说，便想羅浮直至今。","（〖1〗上面這些诗寫辰一小冊上，線裝，僅存五葉，共二十八首。","後有殘闕，原书葉數、诗數不知多少。","總題《涉道诗》，下題撰人李翔姓名。","李翔的时代和事跡無所考，這個诗集也不见於著錄。","所歌詠酬答的都是道山道观，當时道教的天師、尊師、鍊師、總真以及供奉和道教史上的著名人物事跡等。","這應該是一部現存最古的道徒诗集。","〖2〗诗中所表現的山名和地名，多在今江西、江蘇、浙江三省，主要是在龙虎山、茅山、天台山之间，李翔大概就是這一地區以內的人。","他的时代，大概是第九世紀末年或第十世紀初年的人。","謝自然是貞元十一年〖七九五〗十一月十二日卒於梁州西门外金泉山的，韓愈〖七六八--八二四〗有《謝自然诗》〖《昌黎先生集》卷一〗，李翔有《題謝自然傳後》〖傳爲郡守李堅所作〗，所以李翔时代，疑比韓愈稍晚。","〖日本《道教研究》第一冊刊吳其昱《李翔及其涉道诗》推定李翔爲唐高祖九世孫，江王李元祥之後，曾官莆田尉，約於咸通间在世，所據爲《新唐书》卷七○下《宗室世系表》，可備一说。","〗）。"]', '诗', 'shi', '', NULL, '舞鳯石 李翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a178a159-d4b8-4a37-b523-3d63a1ee60ed', '懷素師草書歌', '懷素師草书歌', '7ed21649-2789-460b-95dc-74a71e463407', '唐', '["懷素才年三十餘，不出湖南學草書。","大夸羲獻將齊德，功比鍾繇也不如。","疇昔闍梨名蓋代，隱秀於今墨池在，賀老遥聞怯後生，張巔（顛）不敢稱先輩。","一昨江南投亞相，盡日花堂書草障，含毫勢若斬蛟龍，㭫（握）管還同斷犀象。","興來索筆縱橫掃，滿坐詞人皆道好。","一點三峯巨石懸，長畫萬歲枯松倒。","叫噉（喊）忙忙禮不拘，萬字千行意轉殊。","紫塞傍窺鴻雁翼，醒前猶自記華章，醉後無論絹與牆，眼看筆掉頭還掉，只見文狂心不狂。","自倚能書堪入貢，一盞一回捻筆弄，壁上颼颼風雨飛，行間屹屹龍蛇動。","在身文翰兩相宜，還如明鏡對西施。","三秋月澹青江水，二月花開綠樹枝。","聞到懷書西入秦，客中相送轉相親；君王必是收狂客，寄語江潭一路人。"]', '["懷素才年三十餘，不出湖南学草书。","大夸羲獻將齊德，功比鍾繇也不如。","疇昔闍梨名蓋代，隐秀於今墨池在，賀老遥闻怯後生，張巔（顛）不敢稱先輩。","一昨江南投亞相，尽日花堂书草障，含毫勢若斬蛟龙，㭫（握）管還同斷犀象。","兴来索笔縱橫掃，满坐词人皆道好。","一点三峯巨石懸，长畫万歲枯松倒。","叫噉（喊）忙忙禮不拘，万字千行意轉殊。","紫塞傍窺鴻雁翼，醒前猶自記华章，醉後無論絹與牆，眼看笔掉头還掉，只见文狂心不狂。","自倚能书堪入貢，一盞一回捻笔弄，壁上颼颼风雨飞，行间屹屹龙蛇动。","在身文翰兩相宜，還如明镜对西施。","三秋月澹青江水，二月花开綠樹枝。","闻到懷书西入秦，客中相送轉相親；君王必是收狂客，寄語江潭一路人。"]', '诗', 'shi', '', NULL, '懷素師草書歌 馬雲奇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('453616d8-6117-4e9d-bf11-29a4db400c9f', '白雲歌（予時落殊俗隨蕃軍望之感此而作）', '白云歌（予时落殊俗隨蕃軍望之感此而作）', '7ed21649-2789-460b-95dc-74a71e463407', '唐', '["遥望白雲出海灣，變成萬狀須臾間。","忽散鳥飛趁不及，唯只清風隨往還。","生復滅兮滅復生，將欲凝兮旋已征；因悟悠悠寄寰宇，何須擾擾徇功名。","滅復生兮生復滅，左之盈兮右之缺；從來舉事皆爾爲，何不含情自怡悅。","殊方節物異長安，盛夏雲光也自寒。","遠戍只將煙正起，橫峰更似雪猶殘。","白雲片片映青山，白雲不盡青山盡。","展轉霏微度碧空，碧空不見浮雲近。","漸覺雲低駐馬看，聯綿縹渺拂征鞍。","一不一兮幾紛紛，散不散兮何漫漫。","東西南北□□馳，上下高低恣所宜。","影碧池冰螢□底，光浮綠樹霰凝枝。","欲謂白雲必從龍，飛來飛去龍不見；欲謂白雲不從龍，乍輕乍重誰能變。","一重未過一重摧，一畔縈巖一畔開。","欒巴𠹀（噀）酒應隨去，子晉吹笙定伴來。","披襟引袖遽迎風，欲□吹雲置袖中；雲飛入袖將爲滿，袖卷看雲依舊空。","雷殷殷兮雨曚曚，成陰澗下雲之功。","倏然雲晴銷四極，所潤寧知白雲力。","大賢濟世徒自勞，一朝運否誰相憶。","不知白雲何所以，年年歲歲從山起；雲收未必歸石中，石暗翻埋在雲裏。","世人遷變比白雲，白雲無心但氛氳。","白雲生滅比世人，世人有心多苦辛。","旋生旋滅何窮已，有心無心只如此。","當須體道有貞素，不用浮榮說非是。","望白雲，白雲遼亂滿空山，高低賦象非情欲，余遂感之心自閑。","望白雲，白雲天外何悠揚，既悲出塞復入塞，應亦有時還帝鄉。"]', '["遥望白云出海灣，变成万狀須臾间。","忽散鸟飞趁不及，唯只清风隨往還。","生复滅兮滅复生，將欲凝兮旋已征；因悟悠悠寄寰宇，何須擾擾徇功名。","滅复生兮生复滅，左之盈兮右之缺；從来舉事皆爾爲，何不含情自怡悅。","殊方節物異长安，盛夏云光也自寒。","远戍只將煙正起，橫峰更似雪猶殘。","白云片片映青山，白云不尽青山尽。","展轉霏微度碧空，碧空不见浮云近。","漸覺云低駐马看，聯綿縹渺拂征鞍。","一不一兮幾紛紛，散不散兮何漫漫。","东西南北□□驰，上下高低恣所宜。","影碧池冰螢□底，光浮綠樹霰凝枝。","欲謂白云必從龙，飞来飞去龙不见；欲謂白云不從龙，乍轻乍重誰能变。","一重未過一重摧，一畔縈巖一畔开。","欒巴𠹀（噀）酒應隨去，子晉吹笙定伴来。","披襟引袖遽迎风，欲□吹云置袖中；云飞入袖將爲满，袖卷看云依旧空。","雷殷殷兮雨曚曚，成陰澗下云之功。","倏然云晴銷四極，所潤寧知白云力。","大賢濟世徒自勞，一朝運否誰相憶。","不知白云何所以，年年歲歲從山起；云收未必归石中，石暗翻埋在云裏。","世人遷变比白云，白云無心但氛氳。","白云生滅比世人，世人有心多苦辛。","旋生旋滅何窮已，有心無心只如此。","當須體道有貞素，不用浮榮说非是。","望白云，白云遼亂满空山，高低賦象非情欲，余遂感之心自闲。","望白云，白云天外何悠揚，既悲出塞复入塞，應亦有时還帝乡。"]', '诗', 'shi', '', NULL, '白雲歌（予時落殊俗隨蕃軍望之感此而作） 馬雲奇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('581d92d5-ab54-4d09-bda6-9e89b4628d84', '送游大德赴甘州口號（此便代書寄呈將軍）', '送游大德赴甘州口號（此便代书寄呈將軍）', '7ed21649-2789-460b-95dc-74a71e463407', '唐', '["支公張掖去何如？異俗多嫌不寄書。","數人四海皆兄弟，爲報殷勤好在無。"]', '["支公張掖去何如？異俗多嫌不寄书。","數人四海皆兄弟，爲報殷勤好在無。"]', '诗', 'shi', '', NULL, '送游大德赴甘州口號（此便代書寄呈將軍） 馬雲奇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc2e95ed-3e49-42cc-94dc-aa3f305ae76e', '九日同諸公殊俗之作', '九日同諸公殊俗之作', '7ed21649-2789-460b-95dc-74a71e463407', '唐', '["一人歌唱數人啼，拭泪相看意轉迷。","不見書傳清（青）海北，只知魂斷隴山西。","登高乍似雲霄近，寓目仍驚草樹低。","菊酒何須頻勸酌，自然心醉已如泥。","（太常妻曰一日不齋醉如泥）。"]', '["一人歌唱數人啼，拭泪相看意轉迷。","不见书傳清（青）海北，只知魂斷隴山西。","登高乍似云霄近，寓目仍驚草樹低。","菊酒何須頻勸酌，自然心醉已如泥。","（太常妻曰一日不斋醉如泥）。"]', '诗', 'shi', '', NULL, '九日同諸公殊俗之作 馬雲奇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ca64d64-e6c3-4320-b42a-ba0ee8d5d6a8', '俯吐蕃禁門觀田判官贈向將軍真言口號（項云「俯」當作「附」，下奪「近」字，「附近」爲接近、靠近之意。）', '俯吐蕃禁门观田判官贈向將軍真言口號（項云「俯」當作「附」，下奪「近」字，「附近」爲接近、靠近之意。）', '7ed21649-2789-460b-95dc-74a71e463407', '唐', '["怪來偏得主君憐，料取分明在眼前。","說相未應驚䴏鴒，看心且愛直如弦。"]', '["怪来偏得主君怜，料取分明在眼前。","说相未應驚䴏鴒，看心且愛直如弦。"]', '诗', 'shi', '', NULL, '俯吐蕃禁門觀田判官贈向將軍真言口號（項云「俯」當作「附」，下奪「近」字，「附近」爲接近、靠近之意。） 馬雲奇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18db8c47-4cb2-4d42-b518-4e16537fee34', '題周奉御', '題周奉御', '7ed21649-2789-460b-95dc-74a71e463407', '唐', '["明王道得腹心臣，百萬人中獨一人。","階下往來三逕跡，門前桃李四時春。"]', '["明王道得腹心臣，百万人中独一人。","階下往来三逕跡，门前桃李四时春。"]', '诗', 'shi', '', NULL, '題周奉御 馬雲奇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b29bf83-e81c-4821-8000-6ba3b18cd626', '贈鄧郎將四弟', '贈鄧郎將四弟', '7ed21649-2789-460b-95dc-74a71e463407', '唐', '["把袂相歡意最濃，十年言笑得朋從。","憐君節操曾無易，只是青山一樹松。"]', '["把袂相歡意最濃，十年言笑得朋從。","怜君節操曾無易，只是青山一樹松。"]', '诗', 'shi', '', NULL, '贈鄧郎將四弟 馬雲奇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2775ca59-6375-4f03-91b1-8c73890ee69b', '同前已（以）詩代書', '同前已（以）诗代书', '7ed21649-2789-460b-95dc-74a71e463407', '唐', '["故（古）來同病總相憐，不似今人見眼前。","且隨浮俗貪趨世，肯料寒灰亦重燃。"]', '["故（古）来同病總相怜，不似今人见眼前。","且隨浮俗貪趨世，肯料寒灰亦重燃。"]', '诗', 'shi', '', NULL, '同前已（以）詩代書 馬雲奇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f8e0f98-1667-426e-865f-0719d7d509bb', '途中憶兒女之作', '途中憶兒女之作', '7ed21649-2789-460b-95dc-74a71e463407', '唐', '["髮為思鄉白，形因泣淚枯。","爾曹應有夢，知我斷腸無。"]', '["髮為思乡白，形因泣泪枯。","爾曹應有梦，知我斷腸無。"]', '诗', 'shi', '', NULL, '途中憶兒女之作 馬雲奇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('630d6306-b7f8-4998-9dcf-7bfa01928423', '至淡河同前之作', '至淡河同前之作', '7ed21649-2789-460b-95dc-74a71e463407', '唐', '["念爾兼辭國，緘愁欲渡河；到來河更闊，應爲涕流多。"]', '["念爾兼辞国，緘愁欲渡河；到来河更闊，應爲涕流多。"]', '诗', 'shi', '', NULL, '至淡河同前之作 馬雲奇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9c2848d-4e07-48f6-b088-df255899a11b', '被蕃軍中拘係之作', '被蕃軍中拘係之作', '7ed21649-2789-460b-95dc-74a71e463407', '唐', '["何事逐漂蓬，悠悠過鑿空！世窮途運榮（蹇），戰苦不成功。","泪滴東流水，心遥北翥鴻。","可能忠孝節，長遣門閫（困）西戎。","。"]', '["何事逐漂蓬，悠悠過鑿空！世窮途運榮（蹇），戰苦不成功。","泪滴东流水，心遥北翥鴻。","可能忠孝節，长遣门閫（困）西戎。","。"]', '诗', 'shi', '', NULL, '被蕃軍中拘係之作 馬雲奇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bd5933b-ff5e-47bc-ac25-0656ff8457df', '諸公破落官蕃中製作', '諸公破落官蕃中製作', '7ed21649-2789-460b-95dc-74a71e463407', '唐', '["別來心事幾悠悠；恨續長波曉夜流。","欲知起望相思意，看取山雲一段愁。"]', '["別来心事幾悠悠；恨續长波晓夜流。","欲知起望相思意，看取山云一段愁。"]', '诗', 'shi', '', NULL, '諸公破落官蕃中製作 馬雲奇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f295b590-92a8-490a-a408-d1f8e6a23ac3', '贈樂使君', '贈乐使君', '7ed21649-2789-460b-95dc-74a71e463407', '唐', '["知君桃李遍成蹊，故託喬林此處棲。","雖然灌木凌雲秀，會有寒鵶夜夜啼。","（〖1〗以上十三首詩從伯二五五五殘卷中錄出。","第一首下題名馬雲奇。","因爲這些詩格調相似，其中有多首詠及被吐蕃拘繫之事，故可定爲一人作品。","這個殘卷中還有五十九首伕名詩〖已編入第二卷〗，也是唐代中期我國國內民族戰爭中被吐蕃拘繫的敦煌漢族人所寫。","這些詩，過去未見著錄，《全唐詩》也沒有收入。","有三生前在巴黎圖書館將這一殘卷全文錄出，以後又作過整理加工，惜未最後定稿。","現據舒學同志的整理稿校對後輯入本卷。","〖2〗馬雲奇的生平目前雖無資料可查，但從這十三首的內容來看，尤其是從第一首《懷素師草書歌》所寫的懷素情況來看，詩的寫作時間與卷二那五十九首伕名詩大致相近，即在公元七五八--七八一年吐蕃逐漸侵吞河隴地區，而西州、沙州尚爲唐軍堅守之時。","（對馬雲奇詩及卷二無名氏殘詩集的作者近年有些學者提出了不同看法。","現摘錄柴劍虹、潘重規的文章如次，以供參考。","〖3〗）（柴劍虹《敦煌伯二五五五卷「馬雲奇詩」辨》〖刊《中華文史論叢》一九八四年第二輯〗認爲，伯二五五五卷中馬雲奇的詩只有《懷素師草書歌》一首，其餘十二首與另外五十九首一樣，均是一位佚名的落蕃人所作。","他指出，該卷第一部分正面抄唐人詩一百五十六首，文兩篇，背面抄詩三十二首，應是唐人詩文選集殘卷。","從抄寫情況看，正面顯係一人筆跡。","那五十九首坆名詩抄寫格式稍異，大多數詩題完整，且高出一格抄，內容又緊密銜接，作者自抄的可能性很大。","背面所抄，署名馬雲奇的只有《懷素師草書歌》一首，此詩詩題低兩格抄，署名又和詩題空兩格，且用大字抄寫。","《白雲歌》等十二首抄於此詩之左，並無署名，而且馬上改變了抄寫格式，字體也縮小了一倍，詩題頂格。","這十二首詩從抄寫格式到內容、風格均與馬雲奇《懷素師草書歌》迥異，卻與寫卷正面那五十九首佚名詩連貫一氣。","他將兩組詩相比較後，認爲有兩點值得注意：第一，作者身世相同，詩的內容一致；第二，有些詩句極爲相仿，似出一人之手，兩組詩可能爲同一人所作。","他並推測這兩組詩的作者，可能即爲緊接前五十九首詩抄錄劉商《胡笳十八拍》後又自加一拍的「落蕃人毛押牙」。","關於馬雲奇，柴劍虹考證其《懷素師草書歌》應作於大曆六年冬至九年春之間。","並推測其可能到過河西一帶，蘇聯藏敦煌殘卷中有岑參《敦煌馬太守後亭歌》，這位馬太守是否馬雲奇，尚有待確定。","〖4〗潘重規《敦煌唐人陷蕃詩集殘卷作者的新探測》〖刊一九八五年六月出版的《漢學研究》第三卷第一期〗一文，爲作者在巴黎國家圖書館東方稿本部披閱敦煌原卷後寫成，也認爲馬雲奇是陷蕃詩集作者之一的說法是錯誤的。","潘文指出伯二五五五卷鈔寫詩文很多，也很雜亂。","馬雲奇《懷素師草書歌》後是沒有作者姓名的《白雲歌》等詩，前者字體較大，後者較小，並非同一人所書。","因此，不可根據前一首詩的作者，便牽連以下沒有作者姓名的詩篇歸屬爲同一人作品。","潘文進而考察了懷素的生平，考定其生於開元二十五年〖七三七〗。","馬雲奇詩云：「懷素纔年三十餘，不出湖南學草書。","」可推知此詩作於早年未出湖南時，馬的年齡顯然超過懷素。","敦煌陷蕃在建中二年，其時馬雲奇應已是六十以上的老翁。","但仔細抽繹十二首陷蕃詩及另一組五十九首作品，作者應是盛年的男兒，詩中全沒有流露老翁的口吻。","因而確定《白雲歌》以下十二首不可能是馬雲奇所作。","同時，潘文也推測七十餘首陷蕃詩的作者可能是「落蕃人毛押牙〖衙〗」。","））。"]', '["知君桃李遍成蹊，故託喬林此处棲。","雖然灌木凌云秀，會有寒鵶夜夜啼。","（〖1〗以上十三首诗從伯二五五五殘卷中錄出。","第一首下題名马云奇。","因爲這些诗格調相似，其中有多首詠及被吐蕃拘繫之事，故可定爲一人作品。","這個殘卷中還有五十九首伕名诗〖已編入第二卷〗，也是唐代中期我国国內民族戰爭中被吐蕃拘繫的敦煌漢族人所寫。","這些诗，過去未见著錄，《全唐诗》也沒有收入。","有三生前在巴黎圖书館將這一殘卷全文錄出，以後又作過整理加工，惜未最後定稿。","現據舒学同志的整理稿校对後輯入本卷。","〖2〗马云奇的生平目前雖無資料可查，但從這十三首的內容来看，尤其是從第一首《懷素師草书歌》所寫的懷素情況来看，诗的寫作时间與卷二那五十九首伕名诗大致相近，即在公元七五八--七八一年吐蕃逐漸侵吞河隴地區，而西州、沙州尚爲唐軍堅守之时。","（对马云奇诗及卷二無名氏殘诗集的作者近年有些学者提出了不同看法。","現摘錄柴劍虹、潘重規的文章如次，以供參考。","〖3〗）（柴劍虹《敦煌伯二五五五卷「马云奇诗」辨》〖刊《中华文史論叢》一九八四年第二輯〗認爲，伯二五五五卷中马云奇的诗只有《懷素師草书歌》一首，其餘十二首與另外五十九首一樣，均是一位佚名的落蕃人所作。","他指出，該卷第一部分正面抄唐人诗一百五十六首，文兩篇，背面抄诗三十二首，應是唐人诗文選集殘卷。","從抄寫情況看，正面显係一人笔跡。","那五十九首坆名诗抄寫格式稍異，大多數诗題完整，且高出一格抄，內容又緊密銜接，作者自抄的可能性很大。","背面所抄，署名马云奇的只有《懷素師草书歌》一首，此诗诗題低兩格抄，署名又和诗題空兩格，且用大字抄寫。","《白云歌》等十二首抄於此诗之左，並無署名，而且马上改变了抄寫格式，字體也縮小了一倍，诗題頂格。","這十二首诗從抄寫格式到內容、风格均與马云奇《懷素師草书歌》迥異，卻與寫卷正面那五十九首佚名诗連貫一氣。","他將兩組诗相比較後，認爲有兩点值得注意：第一，作者身世相同，诗的內容一致；第二，有些诗句極爲相仿，似出一人之手，兩組诗可能爲同一人所作。","他並推測這兩組诗的作者，可能即爲緊接前五十九首诗抄錄劉商《胡笳十八拍》後又自加一拍的「落蕃人毛押牙」。","关於马云奇，柴劍虹考證其《懷素師草书歌》應作於大曆六年冬至九年春之间。","並推測其可能到過河西一带，蘇聯藏敦煌殘卷中有岑參《敦煌马太守後亭歌》，這位马太守是否马云奇，尚有待確定。","〖4〗潘重規《敦煌唐人陷蕃诗集殘卷作者的新探測》〖刊一九八五年六月出版的《漢学研究》第三卷第一期〗一文，爲作者在巴黎国家圖书館东方稿本部披閱敦煌原卷後寫成，也認爲马云奇是陷蕃诗集作者之一的说法是錯誤的。","潘文指出伯二五五五卷鈔寫诗文很多，也很杂亂。","马云奇《懷素師草书歌》後是沒有作者姓名的《白云歌》等诗，前者字體較大，後者較小，並非同一人所书。","因此，不可根據前一首诗的作者，便牽連以下沒有作者姓名的诗篇归屬爲同一人作品。","潘文進而考察了懷素的生平，考定其生於开元二十五年〖七三七〗。","马云奇诗云：「懷素纔年三十餘，不出湖南学草书。","」可推知此诗作於早年未出湖南时，马的年齡显然超過懷素。","敦煌陷蕃在建中二年，其时马云奇應已是六十以上的老翁。","但仔細抽繹十二首陷蕃诗及另一組五十九首作品，作者應是盛年的男兒，诗中全沒有流露老翁的口吻。","因而確定《白云歌》以下十二首不可能是马云奇所作。","同时，潘文也推測七十餘首陷蕃诗的作者可能是「落蕃人毛押牙〖衙〗」。","））。"]', '诗', 'shi', '', NULL, '贈樂使君 馬雲奇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bc3755e-b428-4b67-8cf1-6857cb409407', '冬出敦煌郡入退渾國朝發馬圈之作', '冬出敦煌郡入退渾国朝發马圈之作', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["西行過馬圈，北望近陽關。","迴首見城郭，黯然林樹間。","野烟暝村墅，初是慘寒山。","步步鍼（緘）愁色，迢迢惟夢還。"]', '["西行過马圈，北望近陽关。","迴首见城郭，黯然林樹间。","野烟暝村墅，初是慘寒山。","步步鍼（緘）愁色，迢迢惟梦還。"]', '诗', 'shi', '', NULL, '冬出敦煌郡入退渾國朝發馬圈之作 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bee2b4b7-bcfd-43b2-aecd-9c3b6c9a694a', '至墨離海奉懷敦煌知己', '至墨離海奉懷敦煌知己', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["朝行傍海涯，暮宿幕爲家。","千山空皓雪，萬里盡黃沙。","戎俗途將近，知音道已賒。","迴瞻雲嶺外，揮涕獨咨嗟。"]', '["朝行傍海涯，暮宿幕爲家。","千山空皓雪，万里尽黄沙。","戎俗途將近，知音道已賒。","迴瞻云嶺外，揮涕独咨嗟。"]', '诗', 'shi', '', NULL, '至墨離海奉懷敦煌知己 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84c1a0b9-9ed3-469a-9743-7505cd200201', '冬日書情', '冬日书情', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["殊鄉寂寞使人悲，異域留連不暇歸。","萬里山河非舊國，一川戎俗是新知。","寒天落景光陰促，雪海穹廬物色稀。","爲客終朝長下泣，誰憐曉夕老容儀。"]', '["殊乡寂寞使人悲，異域留連不暇归。","万里山河非旧国，一川戎俗是新知。","寒天落景光陰促，雪海穹廬物色稀。","爲客終朝长下泣，誰怜晓夕老容儀。"]', '诗', 'shi', '', NULL, '冬日書情 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b117f24-432a-4e59-b1d8-ace91acb96de', '登山奉懷知己', '登山奉懷知己', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["閑步陟高崗，相思淚數行。","陣雲橫北塞，煞（原作「𭣦」）氣暝南荒。","極目悲無限，樵心恨未遑。","黯然鄉國處，空見路茫茫。","。"]', '["闲步陟高崗，相思泪數行。","陣云橫北塞，煞（原作「𭣦」）氣暝南荒。","極目悲無限，樵心恨未遑。","黯然乡国处，空见路茫茫。","。"]', '诗', 'shi', '', NULL, '登山奉懷知己 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9af724a5-782c-4862-9795-a89c704fe5b5', '夏中忽見飛雪之作', '夏中忽见飞雪之作', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["三冬自北來，九夏未南迴，青溪雖郁郁，白雲尚皚皚。","海闇山恒暝，愁雲霧不開，唯余鄉國意，朝夕思難裁（原作「栽」）。"]', '["三冬自北来，九夏未南迴，青溪雖郁郁，白云尚皚皚。","海闇山恒暝，愁云霧不开，唯余乡国意，朝夕思难裁（原作「栽」）。"]', '诗', 'shi', '', NULL, '夏中忽見飛雪之作 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02ea8feb-8f55-47be-8d65-33ea4bd8d76b', '夏（原作「冬」）日野望', '夏（原作「冬」）日野望', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["出戶過河梁，登高試望鄉。","雲隨愁處斷，川逐思彌長。","晚吹低藂草，遥山落夕陽。","徘徊噎不語，空使淚沾裳。"]', '["出戶過河梁，登高試望乡。","云隨愁处斷，川逐思彌长。","晚吹低藂草，遥山落夕陽。","徘徊噎不語，空使泪沾裳。"]', '诗', 'shi', '', NULL, '夏（原作「冬」）日野望 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23285c3e-ed77-404a-b9e3-c9c3d4f6f465', '夏日途中即事', '夏日途中即事', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["何事鎮駈駈？馳驂傍海隅。","溪邊論宿處，澗下指飡厨。","萬里山河異，千般物色殊。","愁來竟不語，馬上但長吁。"]', '["何事鎮駈駈？驰驂傍海隅。","溪邊論宿处，澗下指飡厨。","万里山河異，千般物色殊。","愁来竟不語，马上但长吁。"]', '诗', 'shi', '', NULL, '夏日途中即事 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4cf0583-4e72-43c8-bff4-66df70a1ff9e', '青海臥疾之作 一', '青海臥疾之作 一', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["數日穹廬臥疾時，百方投藥力將微。","驚魂漫漫迷山際，怯魄悠悠傍海涯。","旋知命與浮雲合，可嘆身同朝露晞。","男兒到此須甘分，何假含啼枕上悲！。"]', '["數日穹廬臥疾时，百方投藥力將微。","驚魂漫漫迷山際，怯魄悠悠傍海涯。","旋知命與浮云合，可嘆身同朝露晞。","男兒到此須甘分，何假含啼枕上悲！。"]', '诗', 'shi', '', NULL, '青海臥疾之作 一 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d4d45e4-c86a-43ff-b8dc-c8245cc70fd0', '青海臥疾之作 二', '青海臥疾之作 二', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["邂逅遇迍蒙，人情詎見通？","昔時曾虎步，即日似禽籠。","有命如朝露，天依類斷蓬。","緬懷知我者，榮辱杳難同。"]', '["邂逅遇迍蒙，人情詎见通？","昔时曾虎步，即日似禽籠。","有命如朝露，天依類斷蓬。","緬懷知我者，榮辱杳难同。"]', '诗', 'shi', '', NULL, '青海臥疾之作 二 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49b3eb43-2c02-4a01-938a-f18dc752fe28', '秋夜', '秋夜', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["一夜秋聲傍海多，五更寒色早來過。","自然覊旅腸堪斷，況復猜嫌被網羅。","。"]', '["一夜秋声傍海多，五更寒色早来過。","自然覊旅腸堪斷，況复猜嫌被網羅。","。"]', '诗', 'shi', '', NULL, '秋夜 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5b6f006-5259-4f22-a2f5-42580244ddb0', '青海望敦煌之作', '青海望敦煌之作', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["西北指流沙，東南路轉遐。","獨晴留海畔，歸望阻天涯。","九夏呈芳草，三時有雪花。","未能刷（原作「{帀刂}」）羽去，空此羨城鵶。"]', '["西北指流沙，东南路轉遐。","独晴留海畔，归望阻天涯。","九夏呈芳草，三时有雪花。","未能刷（原作「{帀刂}」）羽去，空此羨城鵶。"]', '诗', 'shi', '', NULL, '青海望敦煌之作 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca0a77c8-cc4f-43b5-8bd3-15e2a092ccab', '首秋聞雁幷懷敦煌知己', '首秋闻雁幷懷敦煌知己', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["戎庭節物由來早，倐忽霜秋被寒草。","旅雁噰噰□□□，覊人夜夜心如擣。","與君離別恨經年，何事音書遂黯然。","腸斷祇今□□□，知西北泣雲烟。"]', '["戎庭節物由来早，倐忽霜秋被寒草。","旅雁噰噰□□□，覊人夜夜心如擣。","與君離別恨經年，何事音书遂黯然。","腸斷祇今□□□，知西北泣云烟。"]', '诗', 'shi', '', NULL, '首秋聞雁幷懷敦煌知己 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4573161-4108-4a5c-9047-01999836d277', '秋中雨雪', '秋中雨雪', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["䟃𧽼雨雪下長川，浩蕩風波近海□。"]', '["䟃𧽼雨雪下长川，浩蕩风波近海□。"]', '诗', 'shi', '', NULL, '秋中雨雪 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bbd60e1-28cf-4a3b-ae30-7e48efe08a54', '臨水聞雁', '臨水闻雁', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["□來臨水弔愁容，忽覩愁容淚滿胸。","肝膽隳離凡幾度，雲山阻□況千重。","（闕字，項補「隔」。","）心殊語異情難識，東步西馳意不從。","覊紲祇今腸自斷，更聞哀雁叫噰噰。"]', '["□来臨水弔愁容，忽覩愁容泪满胸。","肝膽隳離凡幾度，云山阻□況千重。","（闕字，項補「隔」。","）心殊語異情难識，东步西驰意不從。","覊紲祇今腸自斷，更闻哀雁叫噰噰。"]', '诗', 'shi', '', NULL, '臨水聞雁 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e2ef05b-1d4b-487f-b074-56917b2d0637', '秋中霖雨', '秋中霖雨', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["寒雨霖霖竟不停，覊愁寂寂夜何寧？","山遥塞闊阻鄉國，草白風悲感客情。","西瞻瀚海腸堪斷，東望咸秦思轉盈。","才薄孰知無所用，獨嗟戎俗滯微名。"]', '["寒雨霖霖竟不停，覊愁寂寂夜何寧？","山遥塞闊阻乡国，草白风悲感客情。","西瞻瀚海腸堪斷，东望咸秦思轉盈。","才薄孰知無所用，独嗟戎俗滯微名。"]', '诗', 'shi', '', NULL, '秋中霖雨 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b426457-5aa7-4e8a-91a5-24464c4dead8', '夢到沙州奉懷殿下', '梦到沙州奉懷殿下', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["一從淪陷自天涯，數度恓（原作「栖」）惶怨別家。","將謂飄零長失路，誰知運合至流沙。","浪漫有幸達人主，惟恨天才遇尚賒。","日夕恩波沾雨露，縱橫顧盼益光華。","光華遠近誰不羨，常思刷羽摶風便。","忽使三冬告別離，山河萬里誠難見。","昨來魂夢傍陽關，省到敦煌奉玉顏。","舞席歌樓似登陟，綺筳花柳記躋攀。","總緣宿昔承言笑，此夜論心豈蹔閑。","睡裏不知迴早晚，覺時只覺泪斑斑。"]', '["一從淪陷自天涯，數度恓（原作「栖」）惶怨別家。","將謂飄零长失路，誰知運合至流沙。","浪漫有幸達人主，惟恨天才遇尚賒。","日夕恩波沾雨露，縱橫顧盼益光华。","光华远近誰不羨，常思刷羽摶风便。","忽使三冬告別離，山河万里誠难见。","昨来魂梦傍陽关，省到敦煌奉玉顏。","舞席歌楼似登陟，綺筳花柳記躋攀。","總緣宿昔承言笑，此夜論心豈蹔闲。","睡裏不知迴早晚，覺时只覺泪斑斑。"]', '诗', 'shi', '', NULL, '夢到沙州奉懷殿下 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5848dbc6-1e20-4e4c-9a4b-db4e0dc314e3', '秋夜望月 一', '秋夜望月 一', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["皎皎山頭月欲低，月猒覊愁睡轉迷。","忽覺淚流痕尚在，不知夢裏向誰啼。"]', '["皎皎山头月欲低，月猒覊愁睡轉迷。","忽覺泪流痕尚在，不知梦裏向誰啼。"]', '诗', 'shi', '', NULL, '秋夜望月 一 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3eebb63-b26a-4b57-a67e-97e9d98bf575', '秋夜望月 二', '秋夜望月 二', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["愁眠枕上泪痕多，況復寒更月色過。","與君萬里難相見，不然一度夢中羅。"]', '["愁眠枕上泪痕多，況复寒更月色過。","與君万里难相见，不然一度梦中羅。"]', '诗', 'shi', '', NULL, '秋夜望月 二 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa055b9a-c639-4113-aa9a-203e5ee55bce', '秋（原作「夏」）日非所書情', '秋（原作「夏」）日非所书情', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["自從去歲別流沙，獨恨今秋歸望賒。","將謂西南窮地角，誰言東北到天涯。","山河遠近多穹帳，戎俗迢觀少物華。","六月尚聞飛雪片，三春豈見有烟花。","凌晨倏閃奔雷電，薄暮斯須歛霽霞，傍對崇山形屹屹，前臨巨壑勢呀呀。","昨來覊思憂如擣，即日愁腸亂似麻。","爲客已遭迍否事，不知何計得還家。"]', '["自從去歲別流沙，独恨今秋归望賒。","將謂西南窮地角，誰言东北到天涯。","山河远近多穹帳，戎俗迢观少物华。","六月尚闻飞雪片，三春豈见有烟花。","凌晨倏閃奔雷電，薄暮斯須歛霽霞，傍对崇山形屹屹，前臨巨壑勢呀呀。","昨来覊思憂如擣，即日愁腸亂似麻。","爲客已遭迍否事，不知何計得還家。"]', '诗', 'shi', '', NULL, '秋（原作「夏」）日非所書情 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94ab29b0-062c-4fa6-ba6b-205ec986e920', '憶故人 一', '憶故人 一', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["別君彼此兩平安，別後恓惶凡幾般。","雖然更寄新書去，憶時捻取舊詩看。"]', '["別君彼此兩平安，別後恓惶凡幾般。","雖然更寄新书去，憶时捻取旧诗看。"]', '诗', 'shi', '', NULL, '憶故人 一 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e4474bf-6792-4a6a-aa17-45346e9734d0', '憶故人 二', '憶故人 二', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["一更獨坐淚成河，半夜想思愁轉多。","左右不聞君語笑，以橫只見唱戎歌。"]', '["一更独坐泪成河，半夜想思愁轉多。","左右不闻君語笑，以橫只见唱戎歌。"]', '诗', 'shi', '', NULL, '憶故人 二 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f394308-23e0-4d88-9555-ac1197a0e22a', '夜度赤嶺懷諸知己', '夜度赤嶺懷諸知己', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["山行夜誠實寐，拂曉遂登高。","迴首望知己，思君心郁陶。","不聞龍虎嘯，但見豺狼號。","寒氣凝如練，秋風勁似刀。","深溪多渌水，斷岸饒黃蒿。","驛使□靡歇，人疲馬亦勞。","獨嗟時不利，詩筆雖（原作「唯」）然操。","更憶綢繆者，何當慰我曹。"]', '["山行夜誠實寐，拂晓遂登高。","迴首望知己，思君心郁陶。","不闻龙虎嘯，但见豺狼號。","寒氣凝如練，秋风勁似刀。","深溪多渌水，斷岸饒黄蒿。","驛使□靡歇，人疲马亦勞。","独嗟时不利，诗笔雖（原作「唯」）然操。","更憶綢繆者，何當慰我曹。"]', '诗', 'shi', '', NULL, '夜度赤嶺懷諸知己 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b7e1161-fd94-4d71-82e9-b172a76f35a3', '晚次白水古戍見枯骨之作', '晚次白水古戍见枯骨之作', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["深山古戍寂無人，崩壁荒丘接鬼鄰。","意氣丹誠□□□，惟餘白骨變灰塵。","漢家封壘徒千所，失守時更歷幾春。","此日覊愁腸自斷，□□到此轉悲辛（原作「新」）。"]', '["深山古戍寂無人，崩壁荒丘接鬼鄰。","意氣丹誠□□□，惟餘白骨变灰塵。","漢家封壘徒千所，失守时更歷幾春。","此日覊愁腸自斷，□□到此轉悲辛（原作「新」）。"]', '诗', 'shi', '', NULL, '晚次白水古戍見枯骨之作 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a80f55b-a84c-45f4-8286-635796ddf950', '晚秋至臨蕃被禁之作', '晚秋至臨蕃被禁之作', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["一到荒城恨轉深，數朝長嘆意雖任。","昔日三軍雄鎮地，今時百（白）草遍城陰。","隤墉窮巷無人跡，獨樹孤墳有鳥吟。","邂逅流移千里外，誰念恓（原作「栖」）惶一片心。"]', '["一到荒城恨轉深，數朝长嘆意雖任。","昔日三軍雄鎮地，今时百（白）草遍城陰。","隤墉窮巷無人跡，独樹孤墳有鸟吟。","邂逅流移千里外，誰念恓（原作「栖」）惶一片心。"]', '诗', 'shi', '', NULL, '晚秋至臨蕃被禁之作 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('935687a0-584b-4aec-8bba-f666a199a126', '晚秋登城之作 一', '晚秋登城之作 一', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["孤城落日一登臨，感激戎庭萬里心。","鄉國雲山遮不見，風光慘澹益愁深。","漂流空嘆東溪水，倏忽仍嗟西嶺陰。","留滯只今寒暑變，誰憐客子獨悲吟。"]', '["孤城落日一登臨，感激戎庭万里心。","乡国云山遮不见，风光慘澹益愁深。","漂流空嘆东溪水，倏忽仍嗟西嶺陰。","留滯只今寒暑变，誰怜客子独悲吟。"]', '诗', 'shi', '', NULL, '晚秋登城之作 一 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ced75eb6-a564-44db-b0e6-a4bbdffb7485', '晚秋登城之作 二', '晚秋登城之作 二', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["東山日色片光殘，西嶺雲各暝草寒。","谷口穹廬遥邐迤，磎邊牛馬暮盤跚。","目前愁見川至窄，望處心迷興不寬。","鄉國未知何所在，路逢相識問看看。"]', '["东山日色片光殘，西嶺云各暝草寒。","谷口穹廬遥邐迤，磎邊牛马暮盤跚。","目前愁见川至窄，望处心迷兴不寬。","乡国未知何所在，路逢相識问看看。"]', '诗', 'shi', '', NULL, '晚秋登城之作 二 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d9e824c-d542-4f6a-b3f1-2af8f51aeb24', '秋夜聞風水', '秋夜闻风水', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["夜來枕席喧風水，忽坐長嘆恨無已，爲客愁多在九秋，況復淪流更千里。"]', '["夜来枕席喧风水，忽坐长嘆恨無已，爲客愁多在九秋，況复淪流更千里。"]', '诗', 'shi', '', NULL, '秋夜聞風水 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a770a703-e847-4d96-b89f-996b4a31dd4f', '望敦煌', '望敦煌', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["數迴瞻望敦煌道，千里茫茫盡白草。","男兒留滯蹔時間，不應便向戎庭老。"]', '["數迴瞻望敦煌道，千里茫茫尽白草。","男兒留滯蹔时间，不應便向戎庭老。"]', '诗', 'shi', '', NULL, '望敦煌 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bfdc643-8b73-4bc2-b744-370e7632325b', '晚秋覊情', '晚秋覊情', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["悄焉獨立思疇昔，忽爾傷心泪旋滴。","常時遊涉事文華，今日覊縲困戎敵。","知音好識竟何在，黯然已矣山河隔，吊影慙魂嗟一身，夕往朝朝（來）絕三益。","非論邂逅離朋友，抑亦淪濟彫羽翮。","自憐銷瘦衣漸寬，誰念恓惶心轉窄。","近來殊俗盈衢路，尚見蒿萊遍街陌，屋宇摧殘無箇存，猶是唐家舊踪跡。","城邊谷口色蒼茫，木落霜飛風析（淅）瀝。","凌晨煞氣半天紅，薄暮寒雲滿山白。","覊紲時深情憤怒，漂泊鄉遥心感激。","不憂懦節向戎夷，只恨更長愁寂寂。"]', '["悄焉独立思疇昔，忽爾傷心泪旋滴。","常时游涉事文华，今日覊縲困戎敵。","知音好識竟何在，黯然已矣山河隔，吊影慙魂嗟一身，夕往朝朝（来）絕三益。","非論邂逅離朋友，抑亦淪濟彫羽翮。","自怜銷瘦衣漸寬，誰念恓惶心轉窄。","近来殊俗盈衢路，尚见蒿萊遍街陌，屋宇摧殘無箇存，猶是唐家旧踪跡。","城邊谷口色蒼茫，木落霜飞风析（淅）瀝。","凌晨煞氣半天紅，薄暮寒云满山白。","覊紲时深情憤怒，漂泊乡遥心感激。","不憂懦節向戎夷，只恨更长愁寂寂。"]', '诗', 'shi', '', NULL, '晚秋覊情 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d193c4c5-ccde-4960-960e-45b3639e8c2e', '困中登山', '困中登山', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["戎庭悶且閑，誰復解愁顏。","步步或登嶺，悠悠時往還。","野禽噪河曲，村犬吠林間。","西北望君處，躊踷日暝山。"]', '["戎庭悶且闲，誰复解愁顏。","步步或登嶺，悠悠时往還。","野禽噪河曲，村犬吠林间。","西北望君处，躊踷日暝山。"]', '诗', 'shi', '', NULL, '困中登山 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e9bc072-ea36-4a84-8526-abd8b52c0057', '有恨久囚', '有恨久囚', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["人易千般去，余嗟獨未還。","空知泣山月，寧覺鬢蒼斑。"]', '["人易千般去，余嗟独未還。","空知泣山月，寧覺鬢蒼斑。"]', '诗', 'shi', '', NULL, '有恨久囚 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73c79244-cc31-43a2-80a8-6267e8b7d69e', '冬夜非所', '冬夜非所', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["長夜閉荒城，更深恨轉盈。","星濟數道赤，月出半山明。","不聞村犬吠，空聽虎狼聲。","愁臥眠雖着，時時夢裏驚。"]', '["长夜閉荒城，更深恨轉盈。","星濟數道赤，月出半山明。","不闻村犬吠，空听虎狼声。","愁臥眠雖着，时时梦裏驚。"]', '诗', 'shi', '', NULL, '冬夜非所 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0c58c20-7458-4d58-bc1f-6356c60d54f3', '忽有故人相問以詩代書達知己兩首', '忽有故人相问以诗代书達知己兩首', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, '忽有故人相問以詩代書達知己兩首 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75bb6ce0-a44e-410c-aa23-55756f6df010', '忽有故人相問以詩代書達知己兩首 一', '忽有故人相问以诗代书達知己兩首 一', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["忽聞數子訪覊人，問着感言是德鄰。","與君咫尺不相見，空知日夕淚沾巾。"]', '["忽闻數子訪覊人，问着感言是德鄰。","與君咫尺不相见，空知日夕泪沾巾。"]', '诗', 'shi', '', NULL, '忽有故人相問以詩代書達知己兩首 一 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60111969-42a9-43d5-b879-76318d8b1273', '忽有故人相問以詩代書達知己兩首 二', '忽有故人相问以诗代书達知己兩首 二', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["自閉荒城恨有餘，未知君意復何如？非論阻礙難相見，亦恐猜慊不寄書。"]', '["自閉荒城恨有餘，未知君意复何如？非論阻礙难相见，亦恐猜慊不寄书。"]', '诗', 'shi', '', NULL, '忽有故人相問以詩代書達知己兩首 二 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dc60e5c-6dbc-43bc-9dd6-528ab3a212f7', '得信酬迴', '得信酬迴', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["人迴忽得信，具委書中情。","覊思頓雖豁，憶君心轉盈。","自憐飄泊者，邂逅閉荒城。","欲識肝腸斷，更深聽叫聲。"]', '["人迴忽得信，具委书中情。","覊思頓雖豁，憶君心轉盈。","自怜飄泊者，邂逅閉荒城。","欲識肝腸斷，更深听叫声。"]', '诗', 'shi', '', NULL, '得信酬迴 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4240a32-199c-479d-8885-12984bfcc0c0', '聞城哭聲有作', '闻城哭声有作', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["昨聞河畔哭哀哀，見說分離凡幾迴。","昔別長男居異域，今殤小子瘞泉臺。","覊愁對此腸堪斷，客舍聞之心轉摧。","漂泊自然無限苦，況復存亡有去來。"]', '["昨闻河畔哭哀哀，见说分離凡幾迴。","昔別长男居異域，今殤小子瘞泉台。","覊愁对此腸堪斷，客舍闻之心轉摧。","漂泊自然無限苦，況复存亡有去来。"]', '诗', 'shi', '', NULL, '聞城哭聲有作 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a2d9455-ff6a-433d-a9d5-e4eae7c69053', '除夜', '除夜', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["荒城何獨淚澘然，聞說今宵（原作「霄」）是改年。","親故睽携長已矣，幽縲寂寞鎮愁煎。","更深腸絕誰人念，夜永心傷空自憐。","爲恨漂零無計力，空知日夕仰穹天。"]', '["荒城何独泪澘然，闻说今宵（原作「霄」）是改年。","親故睽携长已矣，幽縲寂寞鎮愁煎。","更深腸絕誰人念，夜永心傷空自怜。","爲恨漂零無計力，空知日夕仰穹天。"]', '诗', 'shi', '', NULL, '除夜 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('355b0eeb-afcd-4677-a198-9ab96bdfd70e', '春宵（原作「霄」）有懷', '春宵（原作「霄」）有懷', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["獨坐春宵（原作「霄」）月見高，月下思君心郁陶。","躊躇不覺三更盡，空見豺狼數遍號。"]', '["独坐春宵（原作「霄」）月见高，月下思君心郁陶。","躊躇不覺三更尽，空见豺狼數遍號。"]', '诗', 'shi', '', NULL, '春宵（原作「霄」）有懷 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69c943a6-a8e9-47ae-8fd8-86d88637ee34', '久憾縲紲之作', '久憾縲紲之作', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["一從命駕赴戎鄉，幾度躬先亘法梁。","吐納共欽澎湃注，縱（原作「踪」）橫競揖慧風颺。","今時有恨同蘭艾，即日無辜比冶長。","黠虜莫能分玉石，終朝誰念淚沾裳。","。"]', '["一從命駕赴戎乡，幾度躬先亘法梁。","吐納共欽澎湃注，縱（原作「踪」）橫競揖慧风颺。","今时有恨同蘭艾，即日無辜比冶长。","黠虜莫能分玉石，終朝誰念泪沾裳。","。"]', '诗', 'shi', '', NULL, '久憾縲紲之作 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3aee7aef-570f-45a7-b346-d1ff60cfb1eb', '非所寄王都護姨夫', '非所寄王都護姨夫', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["敦煌數度訪來人，握手千回問懿親。","蓬轉已聞過海畔，莎居見說傍河津。","戎庭事事皆違意，虜口朝朝計苦辛。","縲紲儻逢恩降日，宿心言豁（原作「豁」）在他辰。"]', '["敦煌數度訪来人，握手千回问懿親。","蓬轉已闻過海畔，莎居见说傍河津。","戎庭事事皆違意，虜口朝朝計苦辛。","縲紲儻逢恩降日，宿心言豁（原作「豁」）在他辰。"]', '诗', 'shi', '', NULL, '非所寄王都護姨夫 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d304f6a1-9dda-45e6-bf26-53b802315f77', '哭押牙四寂', '哭押牙四寂', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["哀哉存歿苦難量，共恨淪流處異鄉。","可嘆生涯光景促，旋嗟死路夜何長！空令肝膽摧林竹，每使心魂痛渭陽。","縲紲時深腸自斷，更聞凶變淚沾裳。"]', '["哀哉存歿苦难量，共恨淪流处異乡。","可嘆生涯光景促，旋嗟死路夜何长！空令肝膽摧林竹，每使心魂痛渭陽。","縲紲时深腸自斷，更闻凶变泪沾裳。"]', '诗', 'shi', '', NULL, '哭押牙四寂 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8500887d-6a36-499b-a92d-f537290b8f80', '□□', '□□', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["白日走風沙，黃昏飛雪花。","愁雲闇□畔，寒色暝天涯。","縲紲今將久，歸期恨路賒（原作「㖠」）。","時時眠夢裏，往往見還家。"]', '["白日走风沙，黄昏飞雪花。","愁云闇□畔，寒色暝天涯。","縲紲今將久，归期恨路賒（原作「㖠」）。","时时眠梦裏，往往见還家。"]', '诗', 'shi', '', NULL, '□□ 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc2e8a04-c10f-4b19-a7ae-80620d30dd35', '感藂草初生', '感藂草初生', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["覊客絕知聞，急難阻投杖。","泪與泉俱流，愁將草齊長。","縲紲淹歲年，歸期唯夢想。","春色縱芳菲，片心終郁怏。"]', '["覊客絕知闻，急难阻投杖。","泪與泉俱流，愁將草齊长。","縲紲淹歲年，归期唯梦想。","春色縱芳菲，片心終郁怏。"]', '诗', 'shi', '', NULL, '感藂草初生 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25c2efd7-faa5-4b26-963b-8b6eac1fcc62', '春日覊情', '春日覊情', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["鄉山臨海岸，別業近天堄。","地接龍塠北，川連雁塞西。","童年方剃削，弱冠導羣迷。","儒釋雙披（原作「柀」）翫，聲名獨見躋。","須緣隨墾請，今乃恨暌携。","寂寂空愁坐，遲遲落日低。","觸槐常有志，折檻爲無蹊。","薄暮荒城外，依稀聞遠鷄。","。"]', '["乡山臨海岸，別業近天堄。","地接龙塠北，川連雁塞西。","童年方剃削，弱冠導羣迷。","儒釋雙披（原作「柀」）翫，声名独见躋。","須緣隨墾請，今乃恨暌携。","寂寂空愁坐，遲遲落日低。","觸槐常有志，折檻爲無蹊。","薄暮荒城外，依稀闻远鷄。","。"]', '诗', 'shi', '', NULL, '春日覊情 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f0687c4-7fce-4931-9246-4f3855dbd527', '□□', '□□', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["恨到荒城一閉關，鄉園阻隔萬重山。","咫尺音書猶不達，夢魂何處得歸還。"]', '["恨到荒城一閉关，乡园阻隔万重山。","咫尺音书猶不達，梦魂何处得归還。"]', '诗', 'shi', '', NULL, '□□ 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d7b1f88-33d2-4b96-93e4-b524381c42cb', '□□', '□□', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["憤悶屢縱橫，愁深百計生。","相思凡幾度，慷慨至三更。","虜塞饒白刾，戎鄉多紫荆。","關山爾許遠，魂夢若爲行。"]', '["憤悶屢縱橫，愁深百計生。","相思凡幾度，慷慨至三更。","虜塞饒白刾，戎乡多紫荆。","关山爾許远，魂梦若爲行。"]', '诗', 'shi', '', NULL, '□□ 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f137fcf6-bc4e-4811-8295-996d48d3d1c4', '晚秋 一', '晚秋 一', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["戎庭縲紲向窮秋，寒暑更遷歲欲周。","斑斑淚下皆成血，片片雲來盡帶愁，朝朝心逐東溪水，夜夜魂隨西月流。","數度恓惶猶未了，一生榮樂可能休。"]', '["戎庭縲紲向窮秋，寒暑更遷歲欲周。","斑斑泪下皆成血，片片云来尽带愁，朝朝心逐东溪水，夜夜魂隨西月流。","數度恓惶猶未了，一生榮乐可能休。"]', '诗', 'shi', '', NULL, '晚秋 一 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7d67e74-af4a-41db-896a-bcc83bb7e01f', '晚秋 二', '晚秋 二', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["天涯地角一何長，雁塞龍塠萬里疆。","每恨淪流經數載，更嗟縲紲泣千行。"]', '["天涯地角一何长，雁塞龙塠万里疆。","每恨淪流經數載，更嗟縲紲泣千行。"]', '诗', 'shi', '', NULL, '晚秋 二 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70a42a5f-4e1b-4845-9c73-114ad9d94734', '晚秋 三', '晚秋 三', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["縲紲戎庭恨有餘，蠶知君意復何如？一介耻無蘇子節，數回羞寄李陵書。"]', '["縲紲戎庭恨有餘，蠶知君意复何如？一介耻無蘇子節，數回羞寄李陵书。"]', '诗', 'shi', '', NULL, '晚秋 三 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f3fd8ef-1897-4446-9fa0-cd5134bfc792', '晚秋 四', '晚秋 四', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["髪爲多愁白，心緣久客悲。","更遭縲紲事，因此改容儀。"]', '["髪爲多愁白，心緣久客悲。","更遭縲紲事，因此改容儀。"]', '诗', 'shi', '', NULL, '晚秋 四 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb7d6cd3-092b-4da3-a10d-e699182119c9', '晚秋 五', '晚秋 五', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["春來漸覺沒心情，愁見豺狼夜叫聲；君但遠聽腸應斷，況僕覊縲在此城。"]', '["春来漸覺沒心情，愁见豺狼夜叫声；君但远听腸應斷，況僕覊縲在此城。"]', '诗', 'shi', '', NULL, '晚秋 五 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d95a0663-55a3-4f11-ad0e-79fad6fb56ee', '晚秋 六', '晚秋 六', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["日月千回數，君名萬遍呼。"]', '["日月千回數，君名万遍呼。"]', '诗', 'shi', '', NULL, '晚秋 六 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1d29876-b6a7-4f77-8054-48f918b1f4c2', '晚秋 七', '晚秋 七', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["白日歡情少，黃昏愁轉多。"]', '["白日歡情少，黄昏愁轉多。"]', '诗', 'shi', '', NULL, '晚秋 七 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbdffc1e-d6ae-4d78-8b66-760fb8b0149a', '逢故人之作', '逢故人之作', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["故人相見汾酒龍鐘，總爲情懷昔日濃。","隨頭盡見新白髪，何曾有箇舊顏容！。"]', '["故人相见汾酒龙鐘，總爲情懷昔日濃。","隨头尽见新白髪，何曾有箇旧顏容！。"]', '诗', 'shi', '', NULL, '逢故人之作 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a28374b-df67-4c03-97b8-eb16bc314212', '題故人所居', '題故人所居', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["與君昔離別，星歲爲三周；今日覯顏色，蒼然雙鬢秋。","茅居枕河滸，耕鑿傍山丘。","往往登憇逕，時時或飯牛。","一身尚栖屑，庶身安無憂？","相見未言語，唏吁先淚流。"]', '["與君昔離別，星歲爲三周；今日覯顏色，蒼然雙鬢秋。","茅居枕河滸，耕鑿傍山丘。","往往登憇逕，时时或飯牛。","一身尚栖屑，庶身安無憂？","相见未言語，唏吁先泪流。"]', '诗', 'shi', '', NULL, '題故人所居 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d26bb0e-3608-45ab-ba54-96b1a431d139', '非所夜聞笛', '非所夜闻笛', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["夜聞羌（原作「嗟」）笛吹，愁雜豺狼□。","涕淚落如雨，肝腸痛似刀。","更深新月落，坐久明星高。","感激不遑寐，連宵（原作「霄」）思我曹。"]', '["夜闻羌（原作「嗟」）笛吹，愁杂豺狼□。","涕泪落如雨，肝腸痛似刀。","更深新月落，坐久明星高。","感激不遑寐，連宵（原作「霄」）思我曹。"]', '诗', 'shi', '', NULL, '非所夜聞笛 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ecd0d25-b3ab-462a-b7e7-680721620c5a', '感興臨蕃馴雁', '感兴臨蕃馴雁', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["感兹馴雁色蒼蒼，徘徊顧步貌昂昂。","不見銜蘆避繒繳，空聞落翮困堤塘。","差池爲失衡（原作「衝」）陽伴，邂逅飄零虜塞傍。","引頸長鳴望雲路，何時刷羽接歸行。"]', '["感兹馴雁色蒼蒼，徘徊顧步貌昂昂。","不见銜蘆避繒繳，空闻落翮困堤塘。","差池爲失衡（原作「衝」）陽伴，邂逅飄零虜塞傍。","引頸长鳴望云路，何时刷羽接归行。"]', '诗', 'shi', '', NULL, '感興臨蕃馴雁 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d4a8d67-b776-425c-b10d-3edcf3d4a8a0', '閨情 一', '閨情 一', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["千回萬轉夢難成，萬遍千回夢里驚；總爲相思愁不寐，縱然愁寐忽天明。"]', '["千回万轉梦难成，万遍千回梦里驚；總爲相思愁不寐，縱然愁寐忽天明。"]', '诗', 'shi', '', NULL, '閨情 一 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf0dd458-397c-44dd-b767-5df1feae9334', '閨情 二', '閨情 二', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["百度看星月，千回望五更。","自知無夜分，乞顧早天明。","（〖1〗以上五十九首詩，與卷一所著錄的馬雲奇詩一道鈔寫在伯二五五五殘卷上，按其內容和編次，當是一人所寫，可惜這個作者的姓名已不可考知。","從詩的內容看來，這個作者很可能是一位身遭吐蕃拘禁的敦煌使臣。","這些詩所表現的時間和地點，約在唐代宗大曆元年〖七六五〗凉州陷於吐蕃到德宗建）（中二年〖七八一〗敦煌淪陷之間。","作者在冬日從敦煌馬圈口堰出發，出使吐谷渾，經過墨離海，次年夏到青海，却不幸被拘禁，失去了人身自由；又經過臨水，度赤嶺，次白水戍，到達被吐蕃佔據的臨蕃。","他所經歷的時間，正是吐蕃極盛、河隴淪陷，安西、北庭與中原音訊斷絕之時，因此詩中所反映的思想狀況，代表了當時西北邊塞廣大文人士子的心情。","同時，這些詩實際上又是當時河隴地區的紀行詩，詩中所描述的邊塞地區的自然風貌、游牧地帶的典型景物以及被吐蕃攻陷後的邊鎮守捉的荒涼景象，在別的唐人邊塞詩中均不多見，因此，它們無論在歷史，或文學史，或民族文化交流的研究上，都有着不可忽視的寶貴價值。","〖有關伯二五五五殘詩卷，可參看柴劍虹《敦煌唐人詩文選集殘卷〖伯二五五五〗補錄》，見《文學遺產》一九八三年第四期。","〗）。"]', '["百度看星月，千回望五更。","自知無夜分，乞顧早天明。","（〖1〗以上五十九首诗，與卷一所著錄的马云奇诗一道鈔寫在伯二五五五殘卷上，按其內容和編次，當是一人所寫，可惜這個作者的姓名已不可考知。","從诗的內容看来，這個作者很可能是一位身遭吐蕃拘禁的敦煌使臣。","這些诗所表現的时间和地点，約在唐代宗大曆元年〖七六五〗凉州陷於吐蕃到德宗建）（中二年〖七八一〗敦煌淪陷之间。","作者在冬日從敦煌马圈口堰出發，出使吐谷渾，經過墨離海，次年夏到青海，却不幸被拘禁，失去了人身自由；又經過臨水，度赤嶺，次白水戍，到達被吐蕃佔據的臨蕃。","他所經歷的时间，正是吐蕃極盛、河隴淪陷，安西、北庭與中原音訊斷絕之时，因此诗中所反映的思想狀況，代表了當时西北邊塞廣大文人士子的心情。","同时，這些诗實際上又是當时河隴地區的紀行诗，诗中所描述的邊塞地區的自然风貌、游牧地带的典型景物以及被吐蕃攻陷後的邊鎮守捉的荒涼景象，在別的唐人邊塞诗中均不多见，因此，它們無論在歷史，或文学史，或民族文化交流的研究上，都有着不可忽視的寶貴價值。","〖有关伯二五五五殘诗卷，可參看柴劍虹《敦煌唐人诗文選集殘卷〖伯二五五五〗補錄》，见《文学遺產》一九八三年第四期。","〗）。"]', '诗', 'shi', '', NULL, '閨情 二 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('283fc635-8449-46c0-954f-3c3342c9f29c', '王昭君怨諸詞人連句（伯二七四八）一首', '王昭君怨諸词人連句（伯二七四八）一首', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["掖庭嬌幸在蛾眉，争用黃金寫艷姿。","始言恩寵由君意，誰謂容顏信畫師。","微軀一自入深宮，春華幾度落秋風。","君恩不惜便（更）衣處，妾貌應殊畫壁中。","聞道和親將我敞（撇），選貌披圖遍宮掖。","圖中容貌既不如，選後君王空悔惜。","始知王意本相親，自恨丹青每誤身。","昔是宮中薄命妾，今成塞外斷腸人。","九重恩愛應長謝，萬里關山愁遠嫁。","飛來北地不勝春，月照南庭空度夜。","夜中含涕獨嬋娟，遥念君邊與朔邊。","毳幕不同羅帳日，氈裘非復錦衾年。","長安高闕三千里，一望能令一心死。","秋來懷抱既不堪，況復南飛雁聲起。"]', '["掖庭嬌幸在蛾眉，争用黄金寫艷姿。","始言恩寵由君意，誰謂容顏信畫師。","微軀一自入深宮，春华幾度落秋风。","君恩不惜便（更）衣处，妾貌應殊畫壁中。","闻道和親將我敞（撇），選貌披圖遍宮掖。","圖中容貌既不如，選後君王空悔惜。","始知王意本相親，自恨丹青每誤身。","昔是宮中薄命妾，今成塞外斷腸人。","九重恩愛應长謝，万里关山愁远嫁。","飞来北地不勝春，月照南庭空度夜。","夜中含涕独嬋娟，遥念君邊與朔邊。","毳幕不同羅帳日，氈裘非复錦衾年。","长安高闕三千里，一望能令一心死。","秋来懷抱既不堪，況复南飞雁声起。"]', '诗', 'shi', '', NULL, '王昭君怨諸詞人連句（伯二七四八）一首 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58ef8d29-bd0b-4539-97c7-d6612ead3a36', '謁法門寺真身五十韻（伯三四四五）一首', '謁法门寺真身五十韻（伯三四四五）一首', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["瞻禮喜成悲，傷着（嗟）不遇師。","矌因修曩劫，火寂掩俱尼（尸）。","神光分皎皎，雁塔起巍巍。","弘願無偏儻，從後請不疑。","人天重敬禮，神鬼悉交馳。","入海人難覩，騰波世莫窺。","供僧添聖福，稱象等毫釐。","鐵網牽沙岸，金甌出水湄。","輪王欣却得，將帥盡忘疲。","震日國絕大，岐陽地不卑。","累朝曾出現，近代盛修持。","萬遍磨不磷，千回湼不緇。","任從將火試，幾見陷金錘。","皓色豈能幷，晶光盡總虧。","真身無點𭼩（黶），珪璧有瑕雌（疵）。","安福樓前現，天涯海畔知。","懿宗親禮處，軍（君）主見同時。","截舌還能語，剜精復舊肥。","石光呈瑞質，木有寶燈儀。","塔主重修建，檀那各捨資。","才興運人力，早已感神祇。","一夜風雷吼，五更砂石吹。","不勞人力置，自有聖賢爲。","海得龍王護，藥叉將主司。","聖燈瞻處有，光相應心祈。","鼓樂喧天地，幡花海路歧。","秦王偏敬仰，皇后重心慈。","禮佛躬親到，齋僧偏極綏。","教坊呈御製，內外奏宮詞。","馬壯金鞍促，人輕玉勒移。","到來心躍躍，回首意遲遲。","睿旨遥瞻禮，皇情雅合規。","只凴香火力，消得國家危。","禱祝風（烽）煙息，猶希稼穡滋。","金經雕豈易，寶偈顯難思。","工匠勞心力，宸聰亦手胝。","衆緣沾士庶，萬卷放僧尼。","芝草生高壠，醴泉清滿池。","紅霓呈瑞色，白鶴唳嘉奇。","真相非生滅，凡情每自欺。","茫茫迷旨趣，劫劫擬何之。","達即全無體，玄微只在茲。","縱饒心稍轉，又被業追隨。","願智應難滿，勝絕寧每期。","不言同哽虎，罕遇䫉（類）盲龜。","像法承衣蔭，聲光以漸衰。","盛筵難際會，逢善莫推辭。","學寡漸黃絹，才荒誤色絲。","感恩頻灑淚，泣諷五言詩。","。"]', '["瞻禮喜成悲，傷着（嗟）不遇師。","矌因修曩劫，火寂掩俱尼（尸）。","神光分皎皎，雁塔起巍巍。","弘願無偏儻，從後請不疑。","人天重敬禮，神鬼悉交驰。","入海人难覩，腾波世莫窺。","供僧添聖福，稱象等毫釐。","鐵網牽沙岸，金甌出水湄。","輪王欣却得，將帥尽忘疲。","震日国絕大，岐陽地不卑。","累朝曾出現，近代盛修持。","万遍磨不磷，千回湼不緇。","任從將火試，幾见陷金錘。","皓色豈能幷，晶光尽總虧。","真身無点𭼩（黶），珪璧有瑕雌（疵）。","安福楼前現，天涯海畔知。","懿宗親禮处，軍（君）主见同时。","截舌還能語，剜精复旧肥。","石光呈瑞質，木有寶灯儀。","塔主重修建，檀那各捨資。","才兴運人力，早已感神祇。","一夜风雷吼，五更砂石吹。","不勞人力置，自有聖賢爲。","海得龙王護，藥叉將主司。","聖灯瞻处有，光相應心祈。","鼓乐喧天地，幡花海路歧。","秦王偏敬仰，皇后重心慈。","禮佛躬親到，斋僧偏極綏。","教坊呈御製，內外奏宮词。","马壯金鞍促，人轻玉勒移。","到来心躍躍，回首意遲遲。","睿旨遥瞻禮，皇情雅合規。","只凴香火力，消得国家危。","禱祝风（烽）煙息，猶希稼穡滋。","金經雕豈易，寶偈显难思。","工匠勞心力，宸聰亦手胝。","衆緣沾士庶，万卷放僧尼。","芝草生高壠，醴泉清满池。","紅霓呈瑞色，白鹤唳嘉奇。","真相非生滅，凡情每自欺。","茫茫迷旨趣，劫劫擬何之。","達即全無體，玄微只在茲。","縱饒心稍轉，又被業追隨。","願智應难满，勝絕寧每期。","不言同哽虎，罕遇䫉（類）盲龟。","像法承衣蔭，声光以漸衰。","盛筵难際會，逢善莫推辞。","学寡漸黄絹，才荒誤色絲。","感恩頻灑泪，泣諷五言诗。","。"]', '诗', 'shi', '', NULL, '謁法門寺真身五十韻（伯三四四五）一首 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dee14858-f9c9-4219-ac9b-750a1a109c8a', '無題（斯五五五八）一首', '無題（斯五五五八）一首', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["池臺樓觀非吾宅，百年還同一宿客；無常忽至即分籬（離），各自東西如路陌。","唯有冤家不相放，罪福前途相執當；冥官依業斷形（刑）名，遮莫王公及宰相。","生鬬英雄死論福，貴販（賤）更無別地獄。","天堂不是選家門，但使回心修作福。","君不見閻浮流轉暫時間，何須苦欲求名利；徒勞積業自綊（挾）身，隨陷三途覓富貴。","過去王侯數百千，若個久住得長年；良賤有生皆有死，一朝命盡總虛然。","空來空去皈本體，直爲迷情不開解。","貪多畏小不知休，總是阿鼻地獄債。","切見愚癡世上人，金（今）生不惜未來身；朝朝暮暮多愁苦，積寶如山猶許（訴）貧。","唯富唯悕（恡）轉更貪，子細尋思幾許堪；多求積貯蒙遼（繚）亂，死去只得一錢含。","一去冥冥百不知，忽然與世即分離；萬物怨（宛）然無一分，唯有善惡並相隨。","一切恩情今隔斷，何得哭泣相呼唤！生死異路當頭行，各自歸家更覓伴。","。"]', '["池台楼观非吾宅，百年還同一宿客；無常忽至即分籬（離），各自东西如路陌。","唯有冤家不相放，罪福前途相執當；冥官依業斷形（刑）名，遮莫王公及宰相。","生鬬英雄死論福，貴販（賤）更無別地獄。","天堂不是選家门，但使回心修作福。","君不见閻浮流轉暫时间，何須苦欲求名利；徒勞積業自綊（挾）身，隨陷三途覓富貴。","過去王侯數百千，若個久住得长年；良賤有生皆有死，一朝命尽總虛然。","空来空去皈本體，直爲迷情不开解。","貪多畏小不知休，總是阿鼻地獄債。","切见愚癡世上人，金（今）生不惜未来身；朝朝暮暮多愁苦，積寶如山猶許（訴）貧。","唯富唯悕（恡）轉更貪，子細尋思幾許堪；多求積貯蒙遼（繚）亂，死去只得一錢含。","一去冥冥百不知，忽然與世即分離；万物怨（宛）然無一分，唯有善惡並相隨。","一切恩情今隔斷，何得哭泣相呼唤！生死異路當头行，各自归家更覓伴。","。"]', '诗', 'shi', '', NULL, '無題（斯五五五八）一首 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63283489-7140-4cc4-beab-b3243bbb304a', '敦煌廿詠（並序） 一、三危山詠', '敦煌廿詠（並序） 一、三危山詠', 'c7ced870-6d07-4fbc-984f-ea37d4c94f56', '唐', '["三危[七]鎮羣望，岫崿凌穹蒼。","萬古不毛髪，四時含雪霜。","巖連九隴險，地竄三苗鄉。","風雨暗溪谷，令人心自傷。"]', '["三危[七]鎮羣望，岫崿凌穹蒼。","万古不毛髪，四时含雪霜。","巖連九隴險，地竄三苗乡。","风雨暗溪谷，令人心自傷。"]', '诗', 'shi', '', NULL, '敦煌廿詠（並序） 一、三危山詠 敦煌人作品[一] shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b7b7d99-6581-4b45-b43e-d7defa1432cb', '敦煌廿詠（並序） 二、白龍堆詠', '敦煌廿詠（並序） 二、白龙堆詠', 'c7ced870-6d07-4fbc-984f-ea37d4c94f56', '唐', '["傳道神沙異，喧寒[也自鳴][八]。","[勢]疑天鼓[九]動，殷似地雷驚。","九[削棱還峻]，人躋刃不平。","更尋[一○]掊井處，時[見白龍行]。"]', '["傳道神沙異，喧寒[也自鳴][八]。","[勢]疑天鼓[九]动，殷似地雷驚。","九[削棱還峻]，人躋刃不平。","更尋[一○]掊井处，时[见白龙行]。"]', '诗', 'shi', '', NULL, '敦煌廿詠（並序） 二、白龍堆詠 敦煌人作品[一] shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24f02f29-53d6-4eb3-bfe4-5baa60950a94', '敦煌廿詠（並序） 三、莫高窟詠[二]', '敦煌廿詠（並序） 三、莫高窟詠[二]', 'c7ced870-6d07-4fbc-984f-ea37d4c94f56', '唐', '["雪嶺干青漢，雲樓架碧空，重開千佛剎[一二]，旁出四天宮。","瑞鳥含珠影，靈花吐蕙藂（叢）。","洗心游勝境，從此去塵蒙。","。"]', '["雪嶺干青漢，云楼架碧空，重开千佛剎[一二]，旁出四天宮。","瑞鸟含珠影，靈花吐蕙藂（叢）。","洗心游勝境，從此去塵蒙。","。"]', '诗', 'shi', '', NULL, '敦煌廿詠（並序） 三、莫高窟詠[二] 敦煌人作品[一] shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a4643b8-2991-41db-b627-ce76f522a290', '敦煌廿詠（並序） 四、貳師泉詠', '敦煌廿詠（並序） 四、貳師泉詠', 'c7ced870-6d07-4fbc-984f-ea37d4c94f56', '唐', '["賢哉李廣利，爲將討匈奴。","路指[一三]三危迥，山連萬里枯。","抽刀刺石壁，發矢落金烏。","志感飛泉湧，能領士馬[甦][一四]。"]', '["賢哉李廣利，爲將討匈奴。","路指[一三]三危迥，山連万里枯。","抽刀刺石壁，發矢落金烏。","志感飞泉湧，能領士马[甦][一四]。"]', '诗', 'shi', '', NULL, '敦煌廿詠（並序） 四、貳師泉詠 敦煌人作品[一] shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('645a308e-8543-48b5-a675-1211614e9c61', '敦煌廿詠（並序） 五、渥洼池天馬詠', '敦煌廿詠（並序） 五、渥洼池天马詠', 'c7ced870-6d07-4fbc-984f-ea37d4c94f56', '唐', '["渥洼爲小海，伊昔獻龍媒。","花裏牽絲去，雲間曳練來。","勝驤走[一五]天闕，滅沒下章臺。","一入重泉底，千金市不迴[一六]。"]', '["渥洼爲小海，伊昔獻龙媒。","花裏牽絲去，云间曳練来。","勝驤走[一五]天闕，滅沒下章台。","一入重泉底，千金市不迴[一六]。"]', '诗', 'shi', '', NULL, '敦煌廿詠（並序） 五、渥洼池天馬詠 敦煌人作品[一] shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d51aae04-acd9-4134-b255-51be47bbdc9a', '敦煌廿詠（並序） 六、陽關戍詠', '敦煌廿詠（並序） 六、陽关戍詠', 'c7ced870-6d07-4fbc-984f-ea37d4c94f56', '唐', '["萬里通西域，千秋尚有名。","平沙迷舊路，眢井引前程。","馬色[一七]無人間，晨鷄吏不聽。"]', '["万里通西域，千秋尚有名。","平沙迷旧路，眢井引前程。","马色[一七]無人间，晨鷄吏不听。"]', '诗', 'shi', '', NULL, '敦煌廿詠（並序） 六、陽關戍詠 敦煌人作品[一] shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0e1c583-e8a3-436a-a3db-7284ae811aa1', '敦煌廿詠（並序） 七、水精堂詠', '敦煌廿詠（並序） 七、水精堂詠', 'c7ced870-6d07-4fbc-984f-ea37d4c94f56', '唐', '["陽關臨絕漠，中有水精堂。","暗磧鋪銀地，平沙散玉羊。","體明同夜月，色淨含[一八]秋霜。","可則棄胡塞[一九]，終歸還帝鄉。"]', '["陽关臨絕漠，中有水精堂。","暗磧鋪銀地，平沙散玉羊。","體明同夜月，色淨含[一八]秋霜。","可則棄胡塞[一九]，終归還帝乡。"]', '诗', 'shi', '', NULL, '敦煌廿詠（並序） 七、水精堂詠 敦煌人作品[一] shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a642e67a-afa9-4c28-8ec8-a291e6951110', '敦煌廿詠（並序） 八、玉女泉詠', '敦煌廿詠（並序） 八、玉女泉詠', 'c7ced870-6d07-4fbc-984f-ea37d4c94f56', '唐', '["用（周）人祭滛（瑤）水，黍稷信非馨。","西豹追河伯，蛟龍遂隱形。","紅粧隨洛浦，綠鬢逐浮萍。","尚有銷金冶，何曾玉女靈。"]', '["用（周）人祭滛（瑤）水，黍稷信非馨。","西豹追河伯，蛟龙遂隐形。","紅粧隨洛浦，綠鬢逐浮萍。","尚有銷金冶，何曾玉女靈。"]', '诗', 'shi', '', NULL, '敦煌廿詠（並序） 八、玉女泉詠 敦煌人作品[一] shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6fc1403-cc00-4c66-8f59-4b030005dd9f', '敦煌廿詠（並序） 九、瑟瑟詠[二○]', '敦煌廿詠（並序） 九、瑟瑟詠[二○]', 'c7ced870-6d07-4fbc-984f-ea37d4c94f56', '唐', '["瑟瑟焦山下，悠悠採幾年。","爲珠懸寶髻[二一]，作璞間金鈿。","色入青霄裏，光浮黑磧邊。","世人偏重此，誰念楚材賢。"]', '["瑟瑟焦山下，悠悠採幾年。","爲珠懸寶髻[二一]，作璞间金鈿。","色入青霄裏，光浮黑磧邊。","世人偏重此，誰念楚材賢。"]', '诗', 'shi', '', NULL, '敦煌廿詠（並序） 九、瑟瑟詠[二○] 敦煌人作品[一] shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5546aa12-cf16-4683-aa3a-8aafc279f41a', '敦煌廿詠（並序） 十、李廟詠', '敦煌廿詠（並序） 十、李廟詠', 'c7ced870-6d07-4fbc-984f-ea37d4c94f56', '唐', '["昔時[二二]興聖帝，遺廟在敦煌。","叱咤雄千古，英威静一方。","牧童歌塚上，狐兔穴墳傍。","晉史傳韜略，留名播五涼。"]', '["昔时[二二]兴聖帝，遺廟在敦煌。","叱咤雄千古，英威静一方。","牧童歌塚上，狐兔穴墳傍。","晉史傳韜略，留名播五涼。"]', '诗', 'shi', '', NULL, '敦煌廿詠（並序） 十、李廟詠 敦煌人作品[一] shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c16caf8-8249-466e-bebc-da5c0bb937b1', '敦煌廿詠（並序） 十一、貞女臺詠[二三]', '敦煌廿詠（並序） 十一、貞女台詠[二三]', 'c7ced870-6d07-4fbc-984f-ea37d4c94f56', '唐', '["貞女誰家女？","孤標坐[二四]此臺。","青蛾隨月轉[二五]，紅粉向花開。","二八無人識，千秋已作灰。","潔身終不嫁，非爲乏良媒。"]', '["貞女誰家女？","孤標坐[二四]此台。","青蛾隨月轉[二五]，紅粉向花开。","二八無人識，千秋已作灰。","潔身終不嫁，非爲乏良媒。"]', '诗', 'shi', '', NULL, '敦煌廿詠（並序） 十一、貞女臺詠[二三] 敦煌人作品[一] shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b069a77-e2b1-4faa-877c-3815300144d8', '敦煌廿詠（並序） 十二、安城祅詠[二六]', '敦煌廿詠（並序） 十二、安城祅詠[二六]', 'c7ced870-6d07-4fbc-984f-ea37d4c94f56', '唐', '["版築安城日，神祠與此興。","一州祈景祚，萬類仰休徵。","蘋藻來（釆）無乏，精靈若有憑。","更看雲祭處，朝夕酒如繩（澠）。"]', '["版築安城日，神祠與此兴。","一州祈景祚，万類仰休徵。","蘋藻来（釆）無乏，精靈若有憑。","更看云祭处，朝夕酒如繩（澠）。"]', '诗', 'shi', '', NULL, '敦煌廿詠（並序） 十二、安城祅詠[二六] 敦煌人作品[一] shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41757dd8-3bbb-4763-b8a4-53ad001585c9', '敦煌廿詠（並序） 十三、墨池詠', '敦煌廿詠（並序） 十三、墨池詠', 'c7ced870-6d07-4fbc-984f-ea37d4c94f56', '唐', '["昔人精篆素，盡妙許張芝。","草聖雄千古，芳名冠一時。","舒箋行鳥迹，研墨染魚緇。","長想臨池處，興來聊詠詩。"]', '["昔人精篆素，尽妙許張芝。","草聖雄千古，芳名冠一时。","舒箋行鸟迹，研墨染鱼緇。","长想臨池处，兴来聊詠诗。"]', '诗', 'shi', '', NULL, '敦煌廿詠（並序） 十三、墨池詠 敦煌人作品[一] shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('beecc6e1-1682-4a49-9a03-c86501e35bd4', '敦煌廿詠（並序） 十四、半壁樹詠', '敦煌廿詠（並序） 十四、半壁樹詠', 'c7ced870-6d07-4fbc-984f-ea37d4c94f56', '唐', '["半壁生奇木，盤根到水涯。","高柯寵（籠）宿霧，密葉隱朝霞。","二月含青翠，三秋帶紫花。","森森神樹下，祈賽不應賒。"]', '["半壁生奇木，盤根到水涯。","高柯寵（籠）宿霧，密葉隐朝霞。","二月含青翠，三秋带紫花。","森森神樹下，祈賽不應賒。"]', '诗', 'shi', '', NULL, '敦煌廿詠（並序） 十四、半壁樹詠 敦煌人作品[一] shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd207664-89ca-4b33-adfa-0cd38f372b56', '敦煌廿詠（並序） 十五、三攢草詠', '敦煌廿詠（並序） 十五、三攢草詠', 'c7ced870-6d07-4fbc-984f-ea37d4c94f56', '唐', '["池草三[二七]攢別，能芳二月[春]。","渌（綠）苔生[二八]水嫩[二九]，翠色出泥新[三○]。","弄[三一]舞飡花蝶，潛驚觸釣鱗。","芳菲觀不厭，留興待詩人。"]', '["池草三[二七]攢別，能芳二月[春]。","渌（綠）苔生[二八]水嫩[二九]，翠色出泥新[三○]。","弄[三一]舞飡花蝶，潛驚觸釣鱗。","芳菲观不厭，留兴待诗人。"]', '诗', 'shi', '', NULL, '敦煌廿詠（並序） 十五、三攢草詠 敦煌人作品[一] shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11dddae7-85fc-491c-8a2f-7cb4ef7c736a', '敦煌廿詠（並序） 十六、賀拔堂詠', '敦煌廿詠（並序） 十六、賀拔堂詠', 'c7ced870-6d07-4fbc-984f-ea37d4c94f56', '唐', '["英雄傳賀拔，割據王[三二]敦煌。","五郡徵般匠，千金造寢堂。","綺檐安獸瓦，粉壁架鴻[三三]梁。"]', '["英雄傳賀拔，割據王[三二]敦煌。","五郡徵般匠，千金造寢堂。","綺檐安獸瓦，粉壁架鴻[三三]梁。"]', '诗', 'shi', '', NULL, '敦煌廿詠（並序） 十六、賀拔堂詠 敦煌人作品[一] shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aeaf2ad5-abad-4d11-afbf-018e5f285f0e', '敦煌廿詠（並序） 十七、望京門詠', '敦煌廿詠（並序） 十七、望京门詠', 'c7ced870-6d07-4fbc-984f-ea37d4c94f56', '唐', '["郭門望京處，樓上啟重闉。","水北通西域，橋東路入秦。","黃沙吐雙徑[三四]，白草生[三五]三春。","不見中華使，翩翩起虜塵。"]', '["郭门望京处，楼上啟重闉。","水北通西域，橋东路入秦。","黄沙吐雙徑[三四]，白草生[三五]三春。","不见中华使，翩翩起虜塵。"]', '诗', 'shi', '', NULL, '敦煌廿詠（並序） 十七、望京門詠 敦煌人作品[一] shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9711d6f5-569b-48c1-b3c0-7d5c37e34893', '敦煌廿詠（並序） 十八、相似樹詠', '敦煌廿詠（並序） 十八、相似樹詠', 'c7ced870-6d07-4fbc-984f-ea37d4c94f56', '唐', '["兩樹夾招提，三春引影低。","葉中微有字，階下已成蹊。","含氣同修短，分條德且齊。","不容凡鳥坐，應欲俟棲。"]', '["兩樹夾招提，三春引影低。","葉中微有字，階下已成蹊。","含氣同修短，分條德且齊。","不容凡鸟坐，應欲俟棲。"]', '诗', 'shi', '', NULL, '敦煌廿詠（並序） 十八、相似樹詠 敦煌人作品[一] shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('694dc15d-1d26-45cb-96d4-7ec6c4c2d9d7', '敦煌廿詠（並序） 十九、鑿壁井詠', '敦煌廿詠（並序） 十九、鑿壁井詠', 'c7ced870-6d07-4fbc-984f-ea37d4c94f56', '唐', '["嘗聞鑿壁井，茲水最爲靈。","色帶三春渌，芳傳一味清。","玄言稱上善，圖錄著高名。","德重勝銖兩，諸流量[三六]且輕。","。"]', '["嘗闻鑿壁井，茲水最爲靈。","色带三春渌，芳傳一味清。","玄言稱上善，圖錄著高名。","德重勝銖兩，諸流量[三六]且轻。","。"]', '诗', 'shi', '', NULL, '敦煌廿詠（並序） 十九、鑿壁井詠 敦煌人作品[一] shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c8ec13f-3747-4e24-9c24-b49274e01b3f', '敦煌廿詠（並序） 二十、分流泉詠', '敦煌廿詠（並序） 二十、分流泉詠', 'c7ced870-6d07-4fbc-984f-ea37d4c94f56', '唐', '["地湧澄泉美，環城本自奇。","一源分異派，兩道入湯池。","波上青蘋合，洲前翠柳垂。","況逢佳景處，從此遂忘疲。"]', '["地湧澄泉美，环城本自奇。","一源分異派，兩道入湯池。","波上青蘋合，洲前翠柳垂。","況逢佳景处，從此遂忘疲。"]', '诗', 'shi', '', NULL, '敦煌廿詠（並序） 二十、分流泉詠 敦煌人作品[一] shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7b349ca-0bae-41a1-9347-e09dc2aa1f43', '敦煌廿詠（並序） [附]題隱士詠[三七]', '敦煌廿詠（並序） [附]題隐士詠[三七]', 'c7ced870-6d07-4fbc-984f-ea37d4c94f56', '唐', '["青溪逐水薫漁樵，策杖褰衣屢驀橋。","鳥坐春池雙影近，人呼幽谷兩聲遥。","祥煙五色飛仙電，瑞草千藂（叢）間藥苗。","河畔曲肱而取飲，嫌煩且棄樹中瓢。","（[一]以上詩凡六寫本，其原編號及校次如下：原卷〖伯二七四八〗、甲卷〖伯三九二九〗、乙卷〖伯二九八三〗、丙卷〖伯三八七○〗。","卷末多《題隱士詠》一首，幷有「咸通十二年十一月廿日學生劉文端寫記」一行。","丁卷〖斯六一六七〗、戊卷〖伯二六九○〗僅存第一首，不校。","甲卷題作「敦煌古蹟廿詠」，乙卷「廿詠」作「二十詠」。","[二]「三危」，甲、乙、丁三卷作「峗山」。","[三]原卷無「向」字，依乙、丙、丁三卷補。","[四]「二」，甲卷作「三」。","[五]「短」下原卷有「見」字，依乙、丙、丁三卷刪。","[六]乙、丙、丁二卷無「矣」字。","[七]「三危」，甲、乙、丁三卷作「峗山」。","[八]原卷殘缺處，元用甲、乙、丙、丁四卷補之。","凡校補字，均括以[]，如[也自鳴]和以下括弧內均是。","[九]「鼓」，甲、乙兩卷作「轂」。","[一○]「尋」，甲卷作「看」。","[一一]詩題丁卷作「靈巖莫高窟詠」。","[一二]「剎」，原卷作「日」，依甲、乙、丙、丁四卷改。","[一三]「指」，甲卷作「至」。","[一四]「甦」字原闕，據甲、乙兩卷補。","丙、丁卷「甦」作「蘇」。","[一五]「走」原作「奏」，依甲、乙、丙、丁四卷改。","[一六]「迴」，乙卷作「還」。","[一七]「色」，甲卷作「素」。","[一八]「含」，丁卷作「合」。","[一九]「塞」原作「賽」，依丙、丁卷改。","[二○]詩題丙、丁兩卷標作「瑟瑟監詠」。","[二一]此句甲卷作「爲懸寶蓋髪」。","[二二]甲卷有三處異文：第一句「昔時」作「昔日」，第二句「遺廟」作「唯廟」，第六句「墳傍」作「其傍」。","[二三]「臺」，甲卷作「樓」。","[二四]「坐」原作「作」，依甲、丙、丁三卷改。","[二五]「轉」，甲、丙兩卷作「盡」。","）（[二六]甲卷有兩處異文，第二句「與此」作「以此」，第三句「一州」作「州縣」。","[二七]「三」原作「一」，依甲、丙、丁三卷改。","[二八]「春渌苔生」四字原缺，依甲、丙、丁三卷補。","[二九]「嫩」原作「嬾」，依丁卷改。","[三○]「新」原作「連」，依甲、丙、丁三卷改。","[三一]「弄」，甲、丙、丁三卷作「散」。","[三二]「王」原作「往」，依丙、丁兩卷改。","[三三]「鴻」，丙、丁兩卷作「虹」。","[三四]「徑」，丙、丁兩卷作「堠」。","[三五]「生」原作「空」，依甲、丙、丁三卷改。","[三六]「量」原作「兩」，依甲、丙、丁三卷改。","[三七]《題隱士詠》原載丙卷末，兹亦移錄附於後。","）。"]', '["青溪逐水薫漁樵，策杖褰衣屢驀橋。","鸟坐春池雙影近，人呼幽谷兩声遥。","祥煙五色飞仙電，瑞草千藂（叢）间藥苗。","河畔曲肱而取饮，嫌煩且棄樹中瓢。","（[一]以上诗凡六寫本，其原編號及校次如下：原卷〖伯二七四八〗、甲卷〖伯三九二九〗、乙卷〖伯二九八三〗、丙卷〖伯三八七○〗。","卷末多《題隐士詠》一首，幷有「咸通十二年十一月廿日学生劉文端寫記」一行。","丁卷〖斯六一六七〗、戊卷〖伯二六九○〗僅存第一首，不校。","甲卷題作「敦煌古蹟廿詠」，乙卷「廿詠」作「二十詠」。","[二]「三危」，甲、乙、丁三卷作「峗山」。","[三]原卷無「向」字，依乙、丙、丁三卷補。","[四]「二」，甲卷作「三」。","[五]「短」下原卷有「见」字，依乙、丙、丁三卷刪。","[六]乙、丙、丁二卷無「矣」字。","[七]「三危」，甲、乙、丁三卷作「峗山」。","[八]原卷殘缺处，元用甲、乙、丙、丁四卷補之。","凡校補字，均括以[]，如[也自鳴]和以下括弧內均是。","[九]「鼓」，甲、乙兩卷作「轂」。","[一○]「尋」，甲卷作「看」。","[一一]诗題丁卷作「靈巖莫高窟詠」。","[一二]「剎」，原卷作「日」，依甲、乙、丙、丁四卷改。","[一三]「指」，甲卷作「至」。","[一四]「甦」字原闕，據甲、乙兩卷補。","丙、丁卷「甦」作「蘇」。","[一五]「走」原作「奏」，依甲、乙、丙、丁四卷改。","[一六]「迴」，乙卷作「還」。","[一七]「色」，甲卷作「素」。","[一八]「含」，丁卷作「合」。","[一九]「塞」原作「賽」，依丙、丁卷改。","[二○]诗題丙、丁兩卷標作「瑟瑟監詠」。","[二一]此句甲卷作「爲懸寶蓋髪」。","[二二]甲卷有三处異文：第一句「昔时」作「昔日」，第二句「遺廟」作「唯廟」，第六句「墳傍」作「其傍」。","[二三]「台」，甲卷作「楼」。","[二四]「坐」原作「作」，依甲、丙、丁三卷改。","[二五]「轉」，甲、丙兩卷作「尽」。","）（[二六]甲卷有兩处異文，第二句「與此」作「以此」，第三句「一州」作「州縣」。","[二七]「三」原作「一」，依甲、丙、丁三卷改。","[二八]「春渌苔生」四字原缺，依甲、丙、丁三卷補。","[二九]「嫩」原作「嬾」，依丁卷改。","[三○]「新」原作「連」，依甲、丙、丁三卷改。","[三一]「弄」，甲、丙、丁三卷作「散」。","[三二]「王」原作「往」，依丙、丁兩卷改。","[三三]「鴻」，丙、丁兩卷作「虹」。","[三四]「徑」，丙、丁兩卷作「堠」。","[三五]「生」原作「空」，依甲、丙、丁三卷改。","[三六]「量」原作「兩」，依甲、丙、丁三卷改。","[三七]《題隐士詠》原載丙卷末，兹亦移錄附於後。","）。"]', '诗', 'shi', '', NULL, '敦煌廿詠（並序） [附]題隱士詠[三七] 敦煌人作品[一] shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abf3d806-da7e-4bb3-8e80-3000bec03428', '敦煌（伯五○○七）三首 □□（原卷此首詩題作《敦煌》。）', '敦煌（伯五○○七）三首 □□（原卷此首诗題作《敦煌》。）', 'c7ced870-6d07-4fbc-984f-ea37d4c94f56', '唐', '["萬頃平田四畔沙，漢朝城壘屬蕃家。","歌謠再復歸唐國，道舞春風楊柳花。","仕女上（尚）□天寶髻，水流依舊種桑麻。","雄軍往往施鼙鼓，鬬將徒勞獫狁誇。"]', '["万頃平田四畔沙，漢朝城壘屬蕃家。","歌謠再复归唐国，道舞春风楊柳花。","仕女上（尚）□天寶髻，水流依旧種桑麻。","雄軍往往施鼙鼓，鬬將徒勞獫狁誇。"]', '诗', 'shi', '', NULL, '敦煌（伯五○○七）三首 □□（原卷此首詩題作《敦煌》。） 敦煌人作品[一] shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6aec44b9-a998-487f-9001-88841d7ed5ff', '敦煌（伯五○○七）三首 壽昌', '敦煌（伯五○○七）三首 壽昌', 'c7ced870-6d07-4fbc-984f-ea37d4c94f56', '唐', '["會稽磧畔亦疆場，迥出平田築壽昌。","沙幕霧深鳴□雁，草枯猶未及重陽。","狐裘上（尚）冷搜紅髓，絺葛那堪臥□霜。","鄒曾不行文墨少，移楓徒哭說西王。"]', '["會稽磧畔亦疆場，迥出平田築壽昌。","沙幕霧深鳴□雁，草枯猶未及重陽。","狐裘上（尚）冷搜紅髓，絺葛那堪臥□霜。","鄒曾不行文墨少，移楓徒哭说西王。"]', '诗', 'shi', '', NULL, '敦煌（伯五○○七）三首 壽昌 敦煌人作品[一] shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('417d296f-52cb-49b9-8419-ef18c9b6ea3e', '敦煌（伯五○○七）三首 僕固天王乾符三年四月廿四日打破伊州……（此缺數字）錄打劫酒泉後却□斷（下缺）', '敦煌（伯五○○七）三首 僕固天王乾符三年四月廿四日打破伊州……（此缺數字）錄打劫酒泉後却□斷（下缺）', 'c7ced870-6d07-4fbc-984f-ea37d4c94f56', '唐', '["爲言回鶻倚兇（下缺）（〖1〗以上詩三首，都作於唐大中二年〖公元八四八年〗張義潮起義以後。","「歌謠再復歸唐國」，即詠此事。","第三首詩題有歷史價值。","僕固天王殆即北庭廻鶻首領僕固俊。","此詩應是當時當地人所作，所以稱他爲「天王」。","乾符三年〖八七六〗打破伊州事，不見史書記載。","可惜詩題殘缺，詩文僅存六字，以致意義不夠明顯。","這時候，僕固俊受張義潮的指揮，打敗了吐蕃不久。","這次〖八七六〗打伊州，想他是受張義潮的命令的。","）。"]', '["爲言回鶻倚兇（下缺）（〖1〗以上诗三首，都作於唐大中二年〖公元八四八年〗張義潮起義以後。","「歌謠再复归唐国」，即詠此事。","第三首诗題有歷史價值。","僕固天王殆即北庭廻鶻首領僕固俊。","此诗應是當时當地人所作，所以稱他爲「天王」。","乾符三年〖八七六〗打破伊州事，不见史书記載。","可惜诗題殘缺，诗文僅存六字，以致意義不夠明显。","這时候，僕固俊受張義潮的指揮，打敗了吐蕃不久。","這次〖八七六〗打伊州，想他是受張義潮的命令的。","）。"]', '诗', 'shi', '', NULL, '敦煌（伯五○○七）三首 僕固天王乾符三年四月廿四日打破伊州……（此缺數字）錄打劫酒泉後却□斷（下缺） 敦煌人作品[一] shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('164c3f4a-c71a-4048-a772-3f5f9e7eae67', '敦煌唐人詩集殘卷考釋', '敦煌唐人诗集殘卷考釋', 'a383a0cc-17da-41ff-b0e3-a31351d82522', '唐', '["右詩五十九首，鈔寫在伯二五五五卷，按其內容和編次，當是一個作者的詩集，可惜這個作者的姓名不可考了。","這五十九首詩所表現的時間和地點，是在某一年的冬天，作者被吐蕃所俘虜，從敦煌經過陽關的南面進入退渾國界，便折向東南行，第二年夏天到達青海。","在青海附近好像停留了一個較短的時期，到了秋天，又經過赤嶺、白水被挾到臨蕃。","在臨蕃，大約住了一年多的時間（從第二年秋住到第四年春）。","作者被吐蕃俘虜的年代，是可以根據上述行程作推測的。","從敦煌入退渾國，又經赤嶺到臨蕃，這些地方，正值短時期的被吐蕃侵擾或占據。","所以作詩的年代，不應早於走元七六○年放棄安西四鎮以前，也不能晚的七八五年敦煌陷蕃以後。","作者最後所經過和被囚繫的地方：赤嶺、白水和臨蕃，都在隴西郡的鄯城，赤嶺一向是唐蕃交界上互市的地方，還立有交界碑。","白水是唐兵駐守的地方，叫做綏戎職。","可是作者在白水看到的是「漢家封壘徒千所，失守時更歷幾春。","」「今時百草遍城陰，隤墉窮巷無人迹，獨樹狐墳有鳥吟」，則又應該是在鄯城陷蕃的時候。","按公元七四一年吐蕃曾攻陷鄯城的振武軍，七六三年，隴州全部陷入吐蕃。","所以，若作進一步的推求，這些詩頗有可能是七四一--七六三的二十二年間之內或稍前時代的作品。","作者「夢到沙州奉懷殿下」一詩很重要，也很難解。","因爲在封建時代對所「奉懷」的稱「殿下」不應是對將軍或主帥的稱呼，也不可能是皇帝，難解就在這個地方。","考《新唐書》卷八十《太宗諸子列傳》和卷二百十六《吐蕃列傳》，信安王李禕曾在七二七--九年間，奉詔與「河西隴右」諸軍攻吐蕃，拓地至千里，因此，我頗疑猜作者所奉懷的殿下，就是信安王李禕。","這一推測如不錯，則作者被俘的年代，度該是七二七--七六三年中間。","作者的身世，據《春日羈情》詩說「童身方剃削，弱冠導羣迷。","儒釋雙披玩，聲名獨見躋」。","《晚秋羈情》詩又說「悄焉獨立思疇昔，忽爾傷心淚旋滴。","常時游涉事文華，今日羈縲困戎敵」。","可見是一個學通儒釋，頗有文華的人，所以能夠被來到沙州的這位「殿下」「李禕」所賞識，叫他做了僧官或隨從官員。","但不幸被吐蕃所俘虜。","被俘的原因不明白，由於同時被俘的人不少，可能是以地方人民和僧道的代表資格，去與吐蕃軍議和，因而被虜的。","作者到了臨蕃好久，才知道被囚繫的當中有他幾個老朋友，只是「咫尺不相見」。","也是爲了「非論阻礙難相見，亦恐嫌猜不寄書」。","還有敦煌的一個押牙四寂，却不幸死在那裏了。","作者的思想並不高超，只是哭愁、哭病、思念家鄉，幾乎在每首詩裏都要「斷腸」。","在這樣的情況之下，雖說偶爾流露出了「觸槐常有志」的話，但接着就說「折檻爲無蹊」，所希望的只是逃跑，或者「縲絏儻逢恩降日」。","對朋友則坦直的說出「一介耻無蘇子節，數回羞寄李陵書」的話。","從這些表現，可以推斷作者只是一個軟弱文人（或僧人），並沒有什麼較明顯的民族思想和氣節。","但是就唐代吐蕃史料的缺乏來說，這些詩却有很高的史料价值。","可是，這個詩集爲什麼又傳到敦煌呢？","因此，頗疑作者終于脫離了吐蕃的縲絏，回到敦煌。","或者是信安王李禕等在恢復了鄯城失地（石堡城）的時候，把他們解放出來。","右詩十三首，格調均相似，除第一首外，又皆咏落蕃事，故可定爲一人作品。","第一首下題馬雲奇名。","作者殆即馬雲奇。","馬雲奇的年代和事迹無考。","把第一首《懷素師草書歌》和李白的《草書歌行》（《分類補注李太白詩》卷八）相比較，可以推斷他是開元、天寶年間人，他的落蕃是在公元七八七年安西、北庭陷蕃以前，而不是在以後。","馬雲奇的詩格較高，風節亦烈。","當他被吐蕃拘繫的時候，他時常想到他和敵人的鬬争。","他惋惜的是「戰苦不成功」，所以懷念祖國以外，還常想「可能盡忠節，長遣困西戎」。","他的思想和節操似比前一佚名落蕃人高一等。","原載《中華文史論叢》一九八四年第二輯。"]', '["右诗五十九首，鈔寫在伯二五五五卷，按其內容和編次，當是一個作者的诗集，可惜這個作者的姓名不可考了。","這五十九首诗所表現的时间和地点，是在某一年的冬天，作者被吐蕃所俘虜，從敦煌經過陽关的南面進入退渾国界，便折向东南行，第二年夏天到達青海。","在青海附近好像停留了一個較短的时期，到了秋天，又經過赤嶺、白水被挾到臨蕃。","在臨蕃，大約住了一年多的时间（從第二年秋住到第四年春）。","作者被吐蕃俘虜的年代，是可以根據上述行程作推測的。","從敦煌入退渾国，又經赤嶺到臨蕃，這些地方，正值短时期的被吐蕃侵擾或占據。","所以作诗的年代，不應早於走元七六○年放棄安西四鎮以前，也不能晚的七八五年敦煌陷蕃以後。","作者最後所經過和被囚繫的地方：赤嶺、白水和臨蕃，都在隴西郡的鄯城，赤嶺一向是唐蕃交界上互市的地方，還立有交界碑。","白水是唐兵駐守的地方，叫做綏戎職。","可是作者在白水看到的是「漢家封壘徒千所，失守时更歷幾春。","」「今时百草遍城陰，隤墉窮巷無人迹，独樹狐墳有鸟吟」，則又應該是在鄯城陷蕃的时候。","按公元七四一年吐蕃曾攻陷鄯城的振武軍，七六三年，隴州全部陷入吐蕃。","所以，若作進一步的推求，這些诗頗有可能是七四一--七六三的二十二年间之內或稍前时代的作品。","作者「梦到沙州奉懷殿下」一诗很重要，也很难解。","因爲在封建时代对所「奉懷」的稱「殿下」不應是对將軍或主帥的稱呼，也不可能是皇帝，难解就在這個地方。","考《新唐书》卷八十《太宗諸子列傳》和卷二百十六《吐蕃列傳》，信安王李禕曾在七二七--九年间，奉詔與「河西隴右」諸軍攻吐蕃，拓地至千里，因此，我頗疑猜作者所奉懷的殿下，就是信安王李禕。","這一推測如不錯，則作者被俘的年代，度該是七二七--七六三年中间。","作者的身世，據《春日羈情》诗说「童身方剃削，弱冠導羣迷。","儒釋雙披玩，声名独见躋」。","《晚秋羈情》诗又说「悄焉独立思疇昔，忽爾傷心泪旋滴。","常时游涉事文华，今日羈縲困戎敵」。","可见是一個学通儒釋，頗有文华的人，所以能夠被来到沙州的這位「殿下」「李禕」所賞識，叫他做了僧官或隨從官員。","但不幸被吐蕃所俘虜。","被俘的原因不明白，由於同时被俘的人不少，可能是以地方人民和僧道的代表資格，去與吐蕃軍議和，因而被虜的。","作者到了臨蕃好久，才知道被囚繫的當中有他幾個老朋友，只是「咫尺不相见」。","也是爲了「非論阻礙难相见，亦恐嫌猜不寄书」。","還有敦煌的一個押牙四寂，却不幸死在那裏了。","作者的思想並不高超，只是哭愁、哭病、思念家乡，幾乎在每首诗裏都要「斷腸」。","在這樣的情況之下，雖说偶爾流露出了「觸槐常有志」的話，但接着就说「折檻爲無蹊」，所希望的只是逃跑，或者「縲絏儻逢恩降日」。","对朋友則坦直的说出「一介耻無蘇子節，數回羞寄李陵书」的話。","從這些表現，可以推斷作者只是一個軟弱文人（或僧人），並沒有什麼較明显的民族思想和氣節。","但是就唐代吐蕃史料的缺乏来说，這些诗却有很高的史料价值。","可是，這個诗集爲什麼又傳到敦煌呢？","因此，頗疑作者終于脫離了吐蕃的縲絏，回到敦煌。","或者是信安王李禕等在恢复了鄯城失地（石堡城）的时候，把他們解放出来。","右诗十三首，格調均相似，除第一首外，又皆咏落蕃事，故可定爲一人作品。","第一首下題马云奇名。","作者殆即马云奇。","马云奇的年代和事迹無考。","把第一首《懷素師草书歌》和李白的《草书歌行》（《分類補注李太白诗》卷八）相比較，可以推斷他是开元、天寶年间人，他的落蕃是在公元七八七年安西、北庭陷蕃以前，而不是在以後。","马云奇的诗格較高，风節亦烈。","當他被吐蕃拘繫的时候，他时常想到他和敵人的鬬争。","他惋惜的是「戰苦不成功」，所以懷念祖国以外，還常想「可能尽忠節，长遣困西戎」。","他的思想和節操似比前一佚名落蕃人高一等。","原載《中华文史論叢》一九八四年第二輯。"]', '诗', 'shi', '', NULL, '敦煌唐人詩集殘卷考釋 王重民 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ba8d1b3-343e-471a-8b4c-d45e67c09e7a', '自序', '自序', '751b0caa-11f0-4d67-8c19-9134219d87de', '唐', '["李唐以文學第士，尤重聲律，碩儒俊彥，罔不規斯道，三百年間，詩人千計，騰聲飛實，郁郁彬彬，故論詩者必稱李唐焉。","自昔唐人選集，有殷璠（《河嶽英靈集》，丹陽進士殷璠撰，分上中下三卷，凡二十四家詩。","）元結（《篋中集》，元結次山編，一卷，凡七人，詩二十四首。","）高正臣（《高氏三宴詩集》三卷，所載皆因人會宴之詩，以一會爲一卷，與宴者凡二十一人。","）芮挺章（《國秀集》三卷，芮挺章編，凡九十人，詩二百二十篇。","實八十五人，詩二百十一首。","）令狐楚（《御覽詩》一卷，一名《唐歌詩》，一名《選進集》，一名《元和御覽》，凡三十家，詩二百八十九首。","）高仲武（《中興間氣集》二卷，高仲武編，凡二十六人，詩一百四十首。","實存一百二十二首。","）姚合（《極玄集》，姚合編，凡二十一家，詩百首。","實存九十九首。","）諸家，顧拘於朋從，或偏一體，或囿一方。","而張爲《主客》（《主客圖》一卷，張爲撰，凡八十四家詩。","）之作，乃更離章摘句，一詩之不獲悉闚，罔論詳該。","宋明稍事蒐輯，《英華》《類苑》，（《文苑英華》一千卷，宋太平興國七年，李昉、扈蒙、徐鉉、宋白等奉敕編。","《唐詩類苑》二百卷，明張之象纂。","）篇什粗備，然而期分類從，終不見一代一家體要；其散逸秘本，放失集外者，且未能廣事搜求，脫漏泰半，後世惜之。","逮有清康熙盛朝，朝野右文，裒輯之風特著；翰林院羣彥，奉命啟芸閣之珍藏，殫精校讐，年餘而成《全唐詩》九百卷，（康熙四十四年三月十九日始，四十五年十月初一日書成。","）都詩四萬八千九百首。","自唐開國以迄五代，凡有所作，靡不苛索專集，旁稽野史，雖隻句莫遺，而後百世鉅觀，斯克厥成，其有功藝文，不謂大且備乎！然其軼在桑島，湮於金石，又有非當時諸公所能及者。","天明中，（天明，日本光格天皇年號，共八年，當清乾隆四十六年至五十三年。","）日人上毛河世寧，（即市河寬齋，字子静，號半江，上毛野國人。","）曾羅彼邦舊籍，參采《千載佳句》、《文鏡秘府》諸書，撰《全唐詩逸》三卷，（《全唐詩逸》三卷，凡百二十餘家詩，前有淡海竺常序。","）雖斷篇零章，不無搜玉之功，鮑清溪既刊入《知不足齋叢書》矣。","余每展斯帙，深慨彼邦人士治學之勤，乃欲本河氏所作，網羅中土遺佚。","匝月之內，先成《全唐詩作者通檢》一卷，然後披覽羣書，逮於金石，竭期年之力，得詩如干首，分爲如干卷，名曰《全唐詩補逸》；揚萬世之英靈，彰一朝之翰藻，斯亦差堪自慰者矣。","至詮次體例，多承舊制；惟詩前小傳之餘，略加案語，詩中原註而外，間益校文。","其若有官銜可稽、歲月可循者，並前賢題跋、諸家考據之屬，胥附篇末，庶幾讀者得資參證焉。","丙子（一九三六）季冬，常熟孫望識。","。"]', '["李唐以文学第士，尤重声律，碩儒俊彥，罔不規斯道，三百年间，诗人千計，腾声飞實，郁郁彬彬，故論诗者必稱李唐焉。","自昔唐人選集，有殷璠（《河嶽英靈集》，丹陽進士殷璠撰，分上中下三卷，凡二十四家诗。","）元結（《篋中集》，元結次山編，一卷，凡七人，诗二十四首。","）高正臣（《高氏三宴诗集》三卷，所載皆因人會宴之诗，以一會爲一卷，與宴者凡二十一人。","）芮挺章（《国秀集》三卷，芮挺章編，凡九十人，诗二百二十篇。","實八十五人，诗二百十一首。","）令狐楚（《御覽诗》一卷，一名《唐歌诗》，一名《選進集》，一名《元和御覽》，凡三十家，诗二百八十九首。","）高仲武（《中兴间氣集》二卷，高仲武編，凡二十六人，诗一百四十首。","實存一百二十二首。","）姚合（《極玄集》，姚合編，凡二十一家，诗百首。","實存九十九首。","）諸家，顧拘於朋從，或偏一體，或囿一方。","而張爲《主客》（《主客圖》一卷，張爲撰，凡八十四家诗。","）之作，乃更離章摘句，一诗之不獲悉闚，罔論詳該。","宋明稍事蒐輯，《英华》《類苑》，（《文苑英华》一千卷，宋太平兴国七年，李昉、扈蒙、徐鉉、宋白等奉敕編。","《唐诗類苑》二百卷，明張之象纂。","）篇什粗備，然而期分類從，終不见一代一家體要；其散逸秘本，放失集外者，且未能廣事搜求，脫漏泰半，後世惜之。","逮有清康熙盛朝，朝野右文，裒輯之风特著；翰林院羣彥，奉命啟芸閣之珍藏，殫精校讐，年餘而成《全唐诗》九百卷，（康熙四十四年三月十九日始，四十五年十月初一日书成。","）都诗四万八千九百首。","自唐开国以迄五代，凡有所作，靡不苛索專集，旁稽野史，雖隻句莫遺，而後百世鉅观，斯克厥成，其有功藝文，不謂大且備乎！然其軼在桑島，湮於金石，又有非當时諸公所能及者。","天明中，（天明，日本光格天皇年號，共八年，當清乾隆四十六年至五十三年。","）日人上毛河世寧，（即市河寬斋，字子静，號半江，上毛野国人。","）曾羅彼邦旧籍，參采《千載佳句》、《文镜秘府》諸书，撰《全唐诗逸》三卷，（《全唐诗逸》三卷，凡百二十餘家诗，前有淡海竺常序。","）雖斷篇零章，不無搜玉之功，鲍清溪既刊入《知不足斋叢书》矣。","余每展斯帙，深慨彼邦人士治学之勤，乃欲本河氏所作，網羅中土遺佚。","匝月之內，先成《全唐诗作者通檢》一卷，然後披覽羣书，逮於金石，竭期年之力，得诗如干首，分爲如干卷，名曰《全唐诗補逸》；揚万世之英靈，彰一朝之翰藻，斯亦差堪自慰者矣。","至詮次體例，多承旧制；惟诗前小傳之餘，略加案語，诗中原註而外，间益校文。","其若有官銜可稽、歲月可循者，並前賢題跋、諸家考據之屬，胥附篇末，庶幾读者得資參證焉。","丙子（一九三六）季冬，常熟孫望識。","。"]', '诗', 'shi', '', NULL, '自序 孫望輯錄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3794013b-98f7-44ba-bde0-cd0826ec4cfa', '遊仙篇', '游仙篇', '41078f43-3397-4c9a-bcab-09744260e078', '唐', '["絳宮珠闕敞仙家，蜺裳羽旆自淩霞。","碧落晨飄紫芝蓋，黃庭夕轉綵雲車。","周旋宇宙殊非遠，窵望蓬壺停翠幰。","千齡一日未言[賒]（{目佘}），億歲嬰孩誰謂晚？","逶迤鳯舞時相向，變囀鸞歌引清唱。","金漿既取玉杯斟，玉酒還用金膏釀。","駐逈遊天域，排空[聊]憩息。","宿志慕三元，翹心祈五色。","[仙]儲本性諒難求，聖迹奇術秘[玄]（元）猷。","願[允]丹[誠]賜靈藥，方期久視御隆周。","（見趙紹祖《金石續鈔》卷一）（〖1〗案石刻題作《雜言遊仙篇》，下署「御製，奉宸大夫臣薛曜書。","」〖2〗趙紹祖《金石續鈔》跋尾：「末句云：『方期久視御隆周。","』則此詩久視元年作而刻之於石者也。","武氏此詩不見於他書，而今古金石家亦未有著於錄者，故存之。","」〖3〗又按詩中日，原作●；天，原作●；聖，原作●；附注中臣，原作●，均武后所製新字。","〖4〗此詩又見收於武億《偃師金石遺文記》卷上、乾隆《偃師縣志》卷二七武億撰《金石錄》上〖此即將前列武億書收入〗、孫星衍《續古文苑》卷四、王昶《金石萃編》卷六三，另畢沅《中州金石記》亦著錄，但未錄原文。","上列各本，錄文）（稍有出入，校如次：「窵望」，上列四書皆作「寫望」；「{目佘}」四書皆作「賒」，今據改；「相向」，武億錄作「相尚」；「聊憇息」之「聊」字，「仙儲」之「仙」字，《金石續鈔》原缺，據尚書補；「本性」之「性」字，武億及王昶錄本皆缺；「玄猷」之「玄」字，《金石續鈔》作「元」，武億錄作「玄」，《金石萃編》及《續古文苑》皆注明爲廟諱，故據改；「願允丹誠」之「允」、「誠」二字，諸本皆缺，惟《續古文苑》不缺，今據補。","）。"]', '["絳宮珠闕敞仙家，蜺裳羽旆自淩霞。","碧落晨飄紫芝蓋，黄庭夕轉綵云车。","周旋宇宙殊非远，窵望蓬壺停翠幰。","千齡一日未言[賒]（{目佘}），億歲嬰孩誰謂晚？","逶迤鳯舞时相向，变囀鸾歌引清唱。","金漿既取玉杯斟，玉酒還用金膏釀。","駐逈游天域，排空[聊]憩息。","宿志慕三元，翹心祈五色。","[仙]儲本性諒难求，聖迹奇術秘[玄]（元）猷。","願[允]丹[誠]賜靈藥，方期久視御隆周。","（见趙紹祖《金石續鈔》卷一）（〖1〗案石刻題作《杂言游仙篇》，下署「御製，奉宸大夫臣薛曜书。","」〖2〗趙紹祖《金石續鈔》跋尾：「末句云：『方期久視御隆周。","』則此诗久視元年作而刻之於石者也。","武氏此诗不见於他书，而今古金石家亦未有著於錄者，故存之。","」〖3〗又按诗中日，原作●；天，原作●；聖，原作●；附注中臣，原作●，均武后所製新字。","〖4〗此诗又见收於武億《偃師金石遺文記》卷上、乾隆《偃師縣志》卷二七武億撰《金石錄》上〖此即將前列武億书收入〗、孫星衍《續古文苑》卷四、王昶《金石萃編》卷六三，另畢沅《中州金石記》亦著錄，但未錄原文。","上列各本，錄文）（稍有出入，校如次：「窵望」，上列四书皆作「寫望」；「{目佘}」四书皆作「賒」，今據改；「相向」，武億錄作「相尚」；「聊憇息」之「聊」字，「仙儲」之「仙」字，《金石續鈔》原缺，據尚书補；「本性」之「性」字，武億及王昶錄本皆缺；「玄猷」之「玄」字，《金石續鈔》作「元」，武億錄作「玄」，《金石萃編》及《續古文苑》皆注明爲廟諱，故據改；「願允丹誠」之「允」、「誠」二字，諸本皆缺，惟《續古文苑》不缺，今據補。","）。"]', '诗', 'shi', '', NULL, '遊仙篇 武則天 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b0ae5b9-9af9-4ed8-9b3f-0d38d60c76f2', '南安夕陽山真寂寺題詩', '南安夕陽山真寂寺題诗', '96501b87-8402-4005-82bc-230fa1c0d2df', '唐', '["惟愛禪林秋月空，誰能歸去宿龍宮。","夜深聞法餐甘露，喜在蓮花法界中。","（見明檇李陳懋仁撰《泉南雜志》卷上。","）（按陳懋仁，字無功，所著《泉南雜志》錄唐人詩若干首，謂「《萬首唐人絕句》中於吾郡及泉州有未收者，余錄其詩於左。","如此備補遺。","」又原詩題注曰：「居邸時遁於此」，蓋謂李忱曾遁居真寂寺也。","又詩末注曰：「見《泉州府志》」。","）。"]', '["惟愛禪林秋月空，誰能归去宿龙宮。","夜深闻法餐甘露，喜在蓮花法界中。","（见明檇李陳懋仁撰《泉南杂志》卷上。","）（按陳懋仁，字無功，所著《泉南杂志》錄唐人诗若干首，謂「《万首唐人絕句》中於吾郡及泉州有未收者，余錄其诗於左。","如此備補遺。","」又原诗題注曰：「居邸时遁於此」，蓋謂李忱曾遁居真寂寺也。","又诗末注曰：「见《泉州府志》」。","）。"]', '诗', 'shi', '', NULL, '南安夕陽山真寂寺題詩 宣宗皇帝李忱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6765d742-50e8-4186-873b-d9349f65790e', '排衙石詩刻（幷序）', '排衙石诗刻（幷序）', '877437b6-387a-4543-b86a-b3b8c77ee162', '唐', '["□□□□□□□，□南一劍定長鯨。","□□□□□□□，□帝匡扶立正聲。","□□□□□□□，□輝争不伏神明。","□□□□□□□，□建瑶壇玉京。","□□□□□□□，□□常爇不曾停。","□□□□□□□，□□恆傳寶藏經。","□□□□□□□，□□今爲顯真靈。","□□□□□□□，□□□來鎮上清。","（見《兩浙金石志》。","）（見《兩浙金石志》卷四。","《六藝之一錄》卷一一○收此詩，第二句「□南」作「東南」，第六句「伏神明」作「仗神明」。","）（〖1〗阮元《兩浙金石志》跋：「右詩刻在錢唐縣鳯凰山排衙石上。","前刻新的序十行，行書，徑一寸，文多磨滅。","序後一行僅存王字，當是武肅系銜。","詩則七言八韻，共九行，十六句，上半截亦闕。","按《咸淳臨安志》云：『舊傳錢武肅王鑿山，見怪石排列兩行，如從衛拱立趨向，因名排衙石，及刻詩石上。","』即謂此也，惜其文未載。","《十國春秋》云：『武肅暇時，命諸子諷誦詩賦，或以所製詩賜丞相將吏，亦間能書寫畫墨竹，然不以呫嗶廢正務。","』是武肅性躭吟咏，此刻可以窺見一斑。","其書亦剛勁有法度。","」）。"]', '["□□□□□□□，□南一劍定长鯨。","□□□□□□□，□帝匡扶立正声。","□□□□□□□，□輝争不伏神明。","□□□□□□□，□建瑶壇玉京。","□□□□□□□，□□常爇不曾停。","□□□□□□□，□□恆傳寶藏經。","□□□□□□□，□□今爲显真靈。","□□□□□□□，□□□来鎮上清。","（见《兩浙金石志》。","）（见《兩浙金石志》卷四。","《六藝之一錄》卷一一○收此诗，第二句「□南」作「东南」，第六句「伏神明」作「仗神明」。","）（〖1〗阮元《兩浙金石志》跋：「右诗刻在錢唐縣鳯凰山排衙石上。","前刻新的序十行，行书，徑一寸，文多磨滅。","序後一行僅存王字，當是武肅系銜。","诗則七言八韻，共九行，十六句，上半截亦闕。","按《咸淳臨安志》云：『旧傳錢武肅王鑿山，见怪石排列兩行，如從衛拱立趨向，因名排衙石，及刻诗石上。","』即謂此也，惜其文未載。","《十国春秋》云：『武肅暇时，命諸子諷誦诗賦，或以所製诗賜丞相將吏，亦间能书寫畫墨竹，然不以呫嗶廢正務。","』是武肅性躭吟咏，此刻可以窺见一斑。","其书亦剛勁有法度。","」）。"]', '诗', 'shi', '', NULL, '排衙石詩刻（幷序） 錢鏐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b7cf60e-ce5a-4b6a-8fe7-2d0327072cf5', '遼東侍宴山夜臨秋同賦臨韻應詔', '遼东侍宴山夜臨秋同賦臨韻應詔', '23e9e4ff-a165-447c-a60d-51ce4ee39fb8', '唐', '["涿野軒皇陳，丹浦帝堯心。","彎弧射封豕，解網縱前禽。","慿高御爽節，流月揚清陰。","霧匝長城險，雲歸渤澥深。","飜垗入層漢，落雁警遥岑。","露條疏更響，涼蟬寂不吟。","三韓初静亂，八桂始披襟。","商飚泛輕武，自澗引衣簮。","酒漾投川醁，歌傳芳樹音。","邊烽良永□，麾旆竦成林。"]', '["涿野軒皇陳，丹浦帝堯心。","彎弧射封豕，解網縱前禽。","慿高御爽節，流月揚清陰。","霧匝长城險，云归渤澥深。","飜垗入層漢，落雁警遥岑。","露條疏更响，涼蟬寂不吟。","三韓初静亂，八桂始披襟。","商飚泛轻武，自澗引衣簮。","酒漾投川醁，歌傳芳樹音。","邊烽良永□，麾旆竦成林。"]', '诗', 'shi', '', NULL, '遼東侍宴山夜臨秋同賦臨韻應詔 褚遂良 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9162ac10-62a4-4245-8515-b3f28ed16219', '春日侍宴望海應詔', '春日侍宴望海應詔', '23e9e4ff-a165-447c-a60d-51ce4ee39fb8', '唐', '["從軍渡蓬海，萬里正蒼蒼。","縈波迴地軸，激浪上天潢。","夕雲類鵬徙，春濤疑蓋張。","天吳静無際，金駕儼成行。","戈船凌白日，鞭石[耿]（秋）虹梁。","電舉[朝]（潮）宗外，風驅韓貊鄉。","之罘初播雨，遼碣始分光。","麾城湛□□，□□□□□。","同文漸邊服，入塞佇歌倡。","（據《翰林學士集》校改。","）。"]', '["從軍渡蓬海，万里正蒼蒼。","縈波迴地軸，激浪上天潢。","夕云類鵬徙，春濤疑蓋張。","天吳静無際，金駕儼成行。","戈船凌白日，鞭石[耿]（秋）虹梁。","電舉[朝]（潮）宗外，风驱韓貊乡。","之罘初播雨，遼碣始分光。","麾城湛□□，□□□□□。","同文漸邊服，入塞佇歌倡。","（據《翰林学士集》校改。","）。"]', '诗', 'shi', '', NULL, '春日侍宴望海應詔 褚遂良 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2c60919-22f8-45ae-ac93-4f22ac37520d', '奉和行經破薛舉戰地應詔', '奉和行經破薛舉戰地應詔', '23e9e4ff-a165-447c-a60d-51ce4ee39fb8', '唐', '["王功先美化，帝略蘊戎昭。","魚驪（友人蔣禮來同志謂當作魚麗，本《左傳》。","）入丹浦，龍戰起鳴條。","長劍星光落，高旗月影搖。","（《翰林學士集》此句缺「摇」字。","）昔往摧勍寇，今巡奏短簫。","旌門麗霜景，帳殿含秋飇。","□池水未結，（「□池」，《翰林學士集》作「□沲」，上字下半殘存，疑爲「河」字。","）官渡柳初凋。","邊烽夕霧卷，關陳曉雲銷。","鴻名兼轍跡，至聖俯唐堯。","睿藻煙霞焕，天聲宮羽調。","平分共飲德，率土更聞韶。","（以上三詩載《武林往哲遺著》。","）（以上三詩皆出日本尾張國真福寺藏唐卷子本《翰林學士集》。","此集清末田貴陽陳田攜歸影刻傳世。","）。"]', '["王功先美化，帝略蘊戎昭。","鱼驪（友人蔣禮来同志謂當作鱼丽，本《左傳》。","）入丹浦，龙戰起鳴條。","长劍星光落，高旗月影搖。","（《翰林学士集》此句缺「摇」字。","）昔往摧勍寇，今巡奏短簫。","旌门丽霜景，帳殿含秋飇。","□池水未結，（「□池」，《翰林学士集》作「□沲」，上字下半殘存，疑爲「河」字。","）官渡柳初凋。","邊烽夕霧卷，关陳晓云銷。","鴻名兼轍跡，至聖俯唐堯。","睿藻煙霞焕，天声宮羽調。","平分共饮德，率土更闻韶。","（以上三诗載《武林往哲遺著》。","）（以上三诗皆出日本尾張国真福寺藏唐卷子本《翰林学士集》。","此集清末田貴陽陳田携归影刻傳世。","）。"]', '诗', 'shi', '', NULL, '奉和行經破薛舉戰地應詔 褚遂良 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8219776-bf6d-4493-a5a1-dc82ecc5dbcd', '湘潭偶題詩', '湘潭偶題诗', '23e9e4ff-a165-447c-a60d-51ce4ee39fb8', '唐', '["遠山酋萃（友人蔣禮垗同志謂當作「𡺚崒」。","）翠凝烟，爛漫桐花二月天。","游徧九衢燈火夜，歸來月挂海棠前。","（此詩載《槐廬叢書》、《金石錄補》卷二十二。","《全唐詩續補遺》卷一據《佘山詩話》錄此詩，今刪去。","首句「酋萃」二字，《佘山詩話》正作「𡺚崒」，與蔣說合。","明陳繼儒《妮古錄》卷一謂宋咸淳中邑令趙必穆於池中得斷碑，上刻此詩。","首句二字亦作「𡺚崒」。","錄此詩後云「餘皆莫辨」。","）（〖1〗《槐廬叢書》、《金石錄補》按此爲褚遂良貶潭州都督時所作。","）。"]', '["远山酋萃（友人蔣禮垗同志謂當作「𡺚崒」。","）翠凝烟，爛漫桐花二月天。","游徧九衢灯火夜，归来月挂海棠前。","（此诗載《槐廬叢书》、《金石錄補》卷二十二。","《全唐诗續補遺》卷一據《佘山诗話》錄此诗，今刪去。","首句「酋萃」二字，《佘山诗話》正作「𡺚崒」，與蔣说合。","明陳繼儒《妮古錄》卷一謂宋咸淳中邑令趙必穆於池中得斷碑，上刻此诗。","首句二字亦作「𡺚崒」。","錄此诗後云「餘皆莫辨」。","）（〖1〗《槐廬叢书》、《金石錄補》按此爲褚遂良貶潭州都督时所作。","）。"]', '诗', 'shi', '', NULL, '湘潭偶題詩 褚遂良 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c4fc132-1779-443b-b35a-00d4a7ad42df', '春旦直疏', '春旦直疏', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["春夜猶自長，高窗來月明。","耿耿不能寐，振衣步前楹。","懷抱蹔無擾，自覺形神清。","遐想太古事，俯察今世情。","淳薄何不同，運數之所成。","歎息萬重隔，已聞晨雞鳴。","迴看東南隅，□□□□□。","誰知忘機者，寂泊存其精。","（見《分門纂類唐歌詩》殘本第一冊《天地山川類》十三頁。","）（見五卷本《王無功文集》卷二，第十三句「迴看」作「迴首」。","）。"]', '["春夜猶自长，高窗来月明。","耿耿不能寐，振衣步前楹。","懷抱蹔無擾，自覺形神清。","遐想太古事，俯察今世情。","淳薄何不同，運數之所成。","歎息万重隔，已闻晨雞鳴。","迴看东南隅，□□□□□。","誰知忘機者，寂泊存其精。","（见《分门纂類唐歌诗》殘本第一冊《天地山川類》十三頁。","）（见五卷本《王無功文集》卷二，第十三句「迴看」作「迴首」。","）。"]', '诗', 'shi', '', NULL, '春旦直疏 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a400257-d1bc-487f-9d5c-dbd3c5fcf8a4', '句', '句', '522c9056-4b41-4c80-b2fa-76ef9124b427', '唐', '["丹青飾成慶，玉帛擅專諸。","（見《資治通鑑》卷一九一《唐紀七》武德七年六月壬戌下胡三省注。","）（見《資治通鑑考異》卷九。","）（〖1〗《資治通鑑》胡三省注引《實錄》云：「元吉見秦王有大功，每懷妬害，言論醜惡，譖害日甚。","每謂建成曰：『當爲大哥手刃之。","』建成性頗仁厚，初止之。","元吉數言不已，建成後亦許之。","元吉因令速發，遂與建成各募壯士，多匿罪人，賞賜之，圖行不軌。","其記室榮九思爲詩以剌之曰：『丹青飾成慶，玉帛擅專諸。","』而弗悟也。","」）。"]', '["丹青飾成慶，玉帛擅專諸。","（见《資治通鑑》卷一九一《唐紀七》武德七年六月壬戌下胡三省注。","）（见《資治通鑑考異》卷九。","）（〖1〗《資治通鑑》胡三省注引《實錄》云：「元吉见秦王有大功，每懷妬害，言論醜惡，譖害日甚。","每謂建成曰：『當爲大哥手刃之。","』建成性頗仁厚，初止之。","元吉數言不已，建成後亦許之。","元吉因令速發，遂與建成各募壯士，多匿罪人，賞賜之，圖行不軌。","其記室榮九思爲诗以剌之曰：『丹青飾成慶，玉帛擅專諸。","』而弗悟也。","」）。"]', '诗', 'shi', '', NULL, '句 榮九思 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a980a3b-ebe7-4b94-91eb-e88ac3ac567f', '漳州新城秋宴', '漳州新城秋宴', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["地險行臺壯，天清景幕新。","鴻飛青嶂杳，鷺點碧波真。","風肅天如水，霜高月散銀。","嬋娟争潑眼，廉潔正成隣。","東湧滄溟玉，西呈翠巘珍。","畫船拖素練，朱榭映紅雲。","琥珀盃方酌，鮫綃席未塵。","秦簫吹引鳯，鄒律奏生春。","縹{糹耳少}纖歌遏，婆娑妙舞神。","會知冥漠處，百怪惱精魂。"]', '["地險行台壯，天清景幕新。","鴻飞青嶂杳，鷺点碧波真。","风肅天如水，霜高月散銀。","嬋娟争潑眼，廉潔正成隣。","东湧滄溟玉，西呈翠巘珍。","畫船拖素練，朱榭映紅云。","琥珀盃方酌，鮫綃席未塵。","秦簫吹引鳯，鄒律奏生春。","縹{糹耳少}纖歌遏，婆娑妙舞神。","會知冥漠处，百怪惱精魂。"]', '诗', 'shi', '', NULL, '漳州新城秋宴 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('736276bd-a0a1-4beb-8838-284b41d5bd99', '曉發佛潭橋', '晓發佛潭橋', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["朝暾催上道，兔魄欲西沈。","去雁長空沒，飛花曲徑深。","事沿橋樹往，詩落海鷗吟。","馬鬣嘶風聳，龍旂閃電臨。","峯攢仙掌巧，露重將袍陰。","農唤耕春早，僧迎展拜欽。","看看葵日麗，照破艷陽心。","（以上二詩見沈定均《漳州府志·藝文志》）。"]', '["朝暾催上道，兔魄欲西沈。","去雁长空沒，飞花曲徑深。","事沿橋樹往，诗落海鷗吟。","马鬣嘶风聳，龙旂閃電臨。","峯攢仙掌巧，露重將袍陰。","農唤耕春早，僧迎展拜欽。","看看葵日丽，照破艷陽心。","（以上二诗见沈定均《漳州府志·藝文志》）。"]', '诗', 'shi', '', NULL, '曉發佛潭橋 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97b73f2b-b409-4e1d-8827-ea76d363ee6a', '句', '句', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["參軍許天正，是用紀邦勛。","（按《全唐詩》卷四五許天正《和陳元光平潮寇詩》。","題注曰：「元光贈詩云『參軍許天正，是用紀邦勛。","』天正和之。","」）。"]', '["參軍許天正，是用紀邦勛。","（按《全唐诗》卷四五許天正《和陳元光平潮寇诗》。","題注曰：「元光贈诗云『參軍許天正，是用紀邦勛。","』天正和之。","」）。"]', '诗', 'shi', '', NULL, '句 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('784de624-96ba-47ce-afe3-a10681eef3dd', '歸閒詩二十韵', '归閒诗二十韵', '4ac09639-b8c7-4546-926e-87c359308eeb', '唐', '["漳北遥開郡，泉南久罷屯。","歸尋初旅寓，喜作舊鄉鄰。","好鳥鳴簷竹，村黎愛幕臣。","土音今聽慣，民俗始知淳。","烽火無傳警，江山已淨塵。","天開一歲暖，花發四時春。","雜卉三冬綠，嘉禾兩度新。","俚歌聲靡曼，秫酒味溫醇。","錦苑來丹荔，清波出素鱗。","芭蕉金剖潤，龍眼玉生津。","蜜取花間[露]（液），柑藏樹上珍。","醉宜藷蔗瀝，睡穩木棉[茵]（溫）。","茉莉香籬落，榕陰浹里闉。","雪霜偏避地，風景獨推閩。","辭國來諸屬，於兹締六親。","追隨情語好，問餽[歲]（幾）時頻。","相訪朝和夕，渾忘越與秦。","功成在炎域，事定有閒身。","詞賦聊酬和，才名任隱淪。","呼童多種植，長是此方人。"]', '["漳北遥开郡，泉南久罷屯。","归尋初旅寓，喜作旧乡鄰。","好鸟鳴簷竹，村黎愛幕臣。","土音今听慣，民俗始知淳。","烽火無傳警，江山已淨塵。","天开一歲暖，花發四时春。","杂卉三冬綠，嘉禾兩度新。","俚歌声靡曼，秫酒味溫醇。","錦苑来丹荔，清波出素鱗。","芭蕉金剖潤，龙眼玉生津。","蜜取花间[露]（液），柑藏樹上珍。","醉宜藷蔗瀝，睡穩木棉[茵]（溫）。","茉莉香籬落，榕陰浹里闉。","雪霜偏避地，风景独推閩。","辞国来諸屬，於兹締六親。","追隨情語好，问餽[歲]（幾）时頻。","相訪朝和夕，渾忘越與秦。","功成在炎域，事定有閒身。","词賦聊酬和，才名任隐淪。","呼童多種植，长是此方人。"]', '诗', 'shi', '', NULL, '歸閒詩二十韵 丁儒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae318279-80da-405d-be06-9fc2143c6f1a', '冬日到泉郡次九龍江與諸公唱和[十三韻]', '冬日到泉郡次九龙江與諸公唱和[十三韻]', '4ac09639-b8c7-4546-926e-87c359308eeb', '唐', '["迢遞千重險，崎嶇一路通。","山深迷白日，林冬豁蒼穹。","正值嚴冬際，渾如春晝中。","泉醴開名郡，江清穩臥龍。","天涯寒不至，地角氣偏融。","橘列丹青樹，槿抽錦繡叢。","秋餘甘菊艷，歲迫麗春紅。","麥隴披藍遠，榕庄拔翠雄。","減衣遊別塢，赤脚走邨童。","日出喧鳥鵲，沙晴落雁鴻。","池澌含晚照，嶺黛徹寒空。","風景無終始，乾坤有異同。","但思鄉國迥，薄暮起心[忡]（冲）。","（以上二詩見《漳州府志》引《白石丁氏譜》。","二詩據清刻《白石丁氏譜》校改。","）。"]', '["迢遞千重險，崎嶇一路通。","山深迷白日，林冬豁蒼穹。","正值嚴冬際，渾如春晝中。","泉醴开名郡，江清穩臥龙。","天涯寒不至，地角氣偏融。","橘列丹青樹，槿抽錦繡叢。","秋餘甘菊艷，歲迫丽春紅。","麦隴披藍远，榕庄拔翠雄。","減衣游別塢，赤脚走邨童。","日出喧鸟鵲，沙晴落雁鴻。","池澌含晚照，嶺黛徹寒空。","风景無終始，乾坤有異同。","但思乡国迥，薄暮起心[忡]（冲）。","（以上二诗见《漳州府志》引《白石丁氏譜》。","二诗據清刻《白石丁氏譜》校改。","）。"]', '诗', 'shi', '', NULL, '冬日到泉郡次九龍江與諸公唱和[十三韻] 丁儒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68013d99-8214-4455-a01b-864702ad92b5', '', '', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["（案《全唐詩》無王梵志詩，生平事跡不可考。","《太平廣記》所載，神誕不可信。","劉復《燉煌掇瑣》據巴黎國家圖書館藏二七一八號燉煌卷子錄出梵志詩一卷，另以三二六六號殘卷校之。","今即自劉本錄出，而取鄭振鐸本《梵志詩拾遺》補其缺。","〖王梵志詩卷子原爲三卷，上所云即其首卷，二卷今佚，三卷胡適藏之。","關本《拾遺》，即三卷中一部分。","〗此外余又見唐釋皎然《詩式》及宋陳巖肖《庚溪詩話》引梵志詩各一首，今幷錄附於後。","〖張錫厚《王梵志詩校輯》卷四云與伯二七一八卷同一系統的敦煌卷子共有十二本。","今即據其所錄，幷參據今人增校意見，作出校記。","今人校訂意見皆據郭在貽《王梵志詩彙校》。","〗）。"]', '["（案《全唐诗》無王梵志诗，生平事跡不可考。","《太平廣記》所載，神誕不可信。","劉复《燉煌掇瑣》據巴黎国家圖书館藏二七一八號燉煌卷子錄出梵志诗一卷，另以三二六六號殘卷校之。","今即自劉本錄出，而取鄭振鐸本《梵志诗拾遺》補其缺。","〖王梵志诗卷子原爲三卷，上所云即其首卷，二卷今佚，三卷胡適藏之。","关本《拾遺》，即三卷中一部分。","〗此外余又见唐釋皎然《诗式》及宋陳巖肖《庚溪诗話》引梵志诗各一首，今幷錄附於後。","〖張錫厚《王梵志诗校輯》卷四云與伯二七一八卷同一系統的敦煌卷子共有十二本。","今即據其所錄，幷參據今人增校意见，作出校記。","今人校訂意见皆據郭在貽《王梵志诗彙校》。","〗）。"]', '诗', 'shi', '', NULL, ' 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f0e6218-6122-4aec-b2ad-1d2087312a03', '一', '一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["兄弟須和順，叔姪莫輕欺。","財物同[箱櫃]，（二字據諸本補。","）[房]中莫畜私。","（「房」字，據伯三五五八、伯三六五六卷補。","「畜」，伯二八四二卷作「蓄」。","）。"]', '["兄弟須和順，叔姪莫轻欺。","財物同[箱櫃]，（二字據諸本補。","）[房]中莫畜私。","（「房」字，據伯三五五八、伯三六五六卷補。","「畜」，伯二八四二卷作「蓄」。","）。"]', '诗', 'shi', '', NULL, '一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('798cf745-b669-4fb3-b0e6-4bcb02567380', '二', '二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["夜眠須在後，起則每須先。","家中懃檢校，衣食莫令偏。"]', '["夜眠須在後，起則每須先。","家中懃檢校，衣食莫令偏。"]', '诗', 'shi', '', NULL, '二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('041d246a-3b2e-4a83-91c9-2e60952dc3a1', '三', '三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["兄弟相憐愛，同生莫異居。","爲人欲得別，（「人」，伯三六五六卷作「若」。","）此則是兵奴。","。"]', '["兄弟相怜愛，同生莫異居。","爲人欲得別，（「人」，伯三六五六卷作「若」。","）此則是兵奴。","。"]', '诗', 'shi', '', NULL, '三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c43baa05-5165-41b3-855e-92d5ae4e8824', '四', '四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["好事須相讓，惡事莫相堆。","（「堆」，伯二八四二卷作「推」。","）{亻|口/工}（鄭校本作「但」。","）能辨此意，禍去福招來。","（「招來」，斯三三九三卷作「將來」。","）。"]', '["好事須相讓，惡事莫相堆。","（「堆」，伯二八四二卷作「推」。","）{亻|口/工}（鄭校本作「但」。","）能辨此意，禍去福招来。","（「招来」，斯三三九三卷作「將来」。","）。"]', '诗', 'shi', '', NULL, '四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50b07a6f-713e-4b02-a0ef-86bd5d006a79', '五', '五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["昔日田真「分」，（「分」，據伯三五五八卷補。","）庭荆當即衰。","平章却不異，其樹復還滋。","（「復」伯三七一六、伯三六五六卷作「重」。","）。"]', '["昔日田真「分」，（「分」，據伯三五五八卷補。","）庭荆當即衰。","平章却不異，其樹复還滋。","（「复」伯三七一六、伯三六五六卷作「重」。","）。"]', '诗', 'shi', '', NULL, '五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94fa414b-00aa-442b-bef0-792d90e76a8a', '六', '六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["孔懷須敬重，同氣並連枝。","不見恆山鳥，孔子惡聞離。"]', '["孔懷須敬重，同氣並連枝。","不见恆山鸟，孔子惡闻離。"]', '诗', 'shi', '', NULL, '六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cec898e4-2ece-4b12-b416-c18289f4d2ac', '七', '七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["兄弟寶難得，（「寶」，張錫厚錄作「實」。","）他人不可嗔。","（「嗔」，伯三五五八、斯三三九三卷作「親」。","）{亻|口/工}（關校本作但。","）尋莊子語，手足斷難論。","（「斷」，伯三五五八卷作「但」。","）。"]', '["兄弟寶难得，（「寶」，張錫厚錄作「實」。","）他人不可嗔。","（「嗔」，伯三五五八、斯三三九三卷作「親」。","）{亻|口/工}（关校本作但。","）尋莊子語，手足斷难論。","（「斷」，伯三五五八卷作「但」。","）。"]', '诗', 'shi', '', NULL, '七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a305166-2a40-4dec-a0e6-fbe0ab689a53', '八', '八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["尊人相逐出，子莫向前行。","識事須相逢，（「須相逢」，伯三六五六、伯二八四二卷作「相逢見」。","）情知乏禮生。"]', '["尊人相逐出，子莫向前行。","識事須相逢，（「須相逢」，伯三六五六、伯二八四二卷作「相逢见」。","）情知乏禮生。"]', '诗', 'shi', '', NULL, '八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5da398d8-1483-4cc5-92e4-b21933933647', '九', '九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["尊人共客語，側立在傍聽。","莫向前頭鬧，喧亂作鵶鳴。"]', '["尊人共客語，側立在傍听。","莫向前头鬧，喧亂作鵶鳴。"]', '诗', 'shi', '', NULL, '九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bba21f14-67d5-4200-8574-618d281a4502', '十', '十', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["主人無床枕，坐旦捉㺃（鄭本作「狗」。","）狐。","（「狐」，項楚校作「親」。","）莫學痛才漢，（「痛才漢」，伯三七一六、伯三六五六、伯三三九三卷作「庸才漢」，伯二八四二卷作「用庸漢」。","）無事棄他門。","（「棄他門」，伯三六五六卷作「去他門」，伯二八四二卷作「尋他朋」。","）。"]', '["主人無床枕，坐旦捉㺃（鄭本作「狗」。","）狐。","（「狐」，項楚校作「親」。","）莫学痛才漢，（「痛才漢」，伯三七一六、伯三六五六、伯三三九三卷作「庸才漢」，伯二八四二卷作「用庸漢」。","）無事棄他门。","（「棄他门」，伯三六五六卷作「去他门」，伯二八四二卷作「尋他朋」。","）。"]', '诗', 'shi', '', NULL, '十 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ead8e10-f2bc-45fe-a978-9b826648b4d0', '十一', '十一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["立身行孝道，有事莫爲●。","（「有事」，伯三五五八、伯三七一六卷作「省事」。","）行使長無過，（「行使」，伯三六五六卷作「但使」，伯三七一六卷作「但知」，斯三三九三卷作「但能」。","）耶孃高枕眠。","。"]', '["立身行孝道，有事莫爲●。","（「有事」，伯三五五八、伯三七一六卷作「省事」。","）行使长無過，（「行使」，伯三六五六卷作「但使」，伯三七一六卷作「但知」，斯三三九三卷作「但能」。","）耶孃高枕眠。","。"]', '诗', 'shi', '', NULL, '十一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c0619b5-684a-447f-8aac-08df0dd32ebb', '十二', '十二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["耶孃行不正，不事任依從。","（「不事」，伯三七一六、斯三三九三卷作「萬事」。","）打駡但知默，（「默」，伯二八四二卷作「恩」。","）無應即是能。"]', '["耶孃行不正，不事任依從。","（「不事」，伯三七一六、斯三三九三卷作「万事」。","）打駡但知默，（「默」，伯二八四二卷作「恩」。","）無應即是能。"]', '诗', 'shi', '', NULL, '十二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d495c18-c699-42d9-b303-d41bfd54ce1e', '十三', '十三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["尊人嗔約束，共語莫江降。","（「江降」，伯三七一六卷作「江絳」，伯三六五六卷作「{馬工}{馬降}」，張錫厚疑應作「𤢐𤝷」。","）縱有些些理，無煩說矩（鄭校本云似應作短長。","〖「矩長」，伯三七一六卷作「短長」。","〗）。"]', '["尊人嗔約束，共語莫江降。","（「江降」，伯三七一六卷作「江絳」，伯三六五六卷作「{马工}{马降}」，張錫厚疑應作「𤢐𤝷」。","）縱有些些理，無煩说矩（鄭校本云似應作短长。","〖「矩长」，伯三七一六卷作「短长」。","〗）。"]', '诗', 'shi', '', NULL, '十三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da4ad4b3-38e0-45f5-9e16-1e28fc342ddb', '十四', '十四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["有事須相問，平章莫自專。","和同相用語，莫取婦兒言。"]', '["有事須相问，平章莫自專。","和同相用語，莫取婦兒言。"]', '诗', 'shi', '', NULL, '十四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c72be849-6592-49e8-88a8-8f7a56c74b97', '十五', '十五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["耶孃年七十，不得遠東西。","出後傾危起，（「起」，伯三五五八、伯三七一六、斯三三九三卷作「去」。","）元知兒故違。","（「故違」，伯三六五六卷作「固違」。","）。"]', '["耶孃年七十，不得远东西。","出後傾危起，（「起」，伯三五五八、伯三七一六、斯三三九三卷作「去」。","）元知兒故違。","（「故違」，伯三六五六卷作「固違」。","）。"]', '诗', 'shi', '', NULL, '十五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee1014b0-3efa-464c-9bc6-c5ac01f395e3', '十六', '十六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["耶孃絕年邁，不得離傍邊。","曉夜專看待，（「看待」，伯三六五六卷作「看侍」。","）仍須省睡眠。","（「省睡眠」，斯三三九三卷作「更省眠」。","）。"]', '["耶孃絕年邁，不得離傍邊。","晓夜專看待，（「看待」，伯三六五六卷作「看侍」。","）仍須省睡眠。","（「省睡眠」，斯三三九三卷作「更省眠」。","）。"]', '诗', 'shi', '', NULL, '十六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cf8b360-b00d-43b2-a23c-5a99a71f3dc5', '十七', '十七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["四大乖和起，諸方請療醫。","（「請」，伯三五五八、伯三七一六、伯三六五六卷作「早」。","）長病煎湯藥，求神覓好師。"]', '["四大乖和起，諸方請療醫。","（「請」，伯三五五八、伯三七一六、伯三六五六卷作「早」。","）长病煎湯藥，求神覓好師。"]', '诗', 'shi', '', NULL, '十七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bfc26cf-a8cc-4c8f-a3a5-0ba26460da1d', '十八', '十八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["親中除父母，兄弟更無過。","有莫相輕賤，無時始認他。"]', '["親中除父母，兄弟更無過。","有莫相轻賤，無时始認他。"]', '诗', 'shi', '', NULL, '十八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82dd5162-0198-4e46-b85c-5649faaaca61', '十九', '十九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["主人相屈至，客莫先入門。","若是尊人處，臨時自朾門。","（「朾」，伯三六五六卷作「打」。","）。"]', '["主人相屈至，客莫先入门。","若是尊人处，臨时自朾门。","（「朾」，伯三六五六卷作「打」。","）。"]', '诗', 'shi', '', NULL, '十九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adf1f8d1-dc4b-4b3c-b8ba-6b7465a90c46', '二十', '二十', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["親家會賓客，在席有尊卑。","諸人未下筯，不得在前椅。","（一本作㨳）。","。"]', '["親家會賓客，在席有尊卑。","諸人未下筯，不得在前椅。","（一本作㨳）。","。"]', '诗', 'shi', '', NULL, '二十 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18710b54-4136-4448-9a55-380eacb711cc', '二一', '二一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["親還同席坐，[知]卑莫上頭（此句原本脫一字，一本作「知卑莫上頭」）。","（「知」，據伯三五五八、伯三七一六、伯三六五六卷補。","）忽然人{火在}責，（「{火在}」，斯三三九三卷作「怪」，伯三五五八卷作「乖」。","）可不衆中羞。"]', '["親還同席坐，[知]卑莫上头（此句原本脫一字，一本作「知卑莫上头」）。","（「知」，據伯三五五八、伯三七一六、伯三六五六卷補。","）忽然人{火在}責，（「{火在}」，斯三三九三卷作「怪」，伯三五五八卷作「乖」。","）可不衆中羞。"]', '诗', 'shi', '', NULL, '二一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f124341-5aa2-4b41-8152-bebbb519c90b', '二二', '二二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["尊人立莫坐，賜坐莫背人。","存坐無方便，（「存坐」，伯三六五六卷作「罇坐」，張錫厚擬作「蹲坐」。","郭祖怡謂「存」爲「𨀛」省形存聲字。","）席上被人嗔。"]', '["尊人立莫坐，賜坐莫背人。","存坐無方便，（「存坐」，伯三六五六卷作「罇坐」，張錫厚擬作「蹲坐」。","郭祖怡謂「存」爲「𨀛」省形存声字。","）席上被人嗔。"]', '诗', 'shi', '', NULL, '二二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a120593-720e-4811-a28b-b869a9c8bc84', '二三', '二三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["尊人對客飲，卓立莫東西。","（「卓立」，斯三三九三卷作「側立」。","）使唤須依命，弓身莫不齊。","（「弓身」，伯三五五八、伯三六五六、斯四六六九卷作「躬身」。","）。"]', '["尊人对客饮，卓立莫东西。","（「卓立」，斯三三九三卷作「側立」。","）使唤須依命，弓身莫不齊。","（「弓身」，伯三五五八、伯三六五六、斯四六六九卷作「躬身」。","）。"]', '诗', 'shi', '', NULL, '二三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b9190d8-ef3e-467a-a2df-9493b043d99a', '二四', '二四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["尊人與須（一本作「酒」。","）喫，即把莫推辭。","性少由方便，圓隔（一本作「融」。","）莫遣（一本作「遺」。","）知。"]', '["尊人與須（一本作「酒」。","）喫，即把莫推辞。","性少由方便，圓隔（一本作「融」。","）莫遣（一本作「遺」。","）知。"]', '诗', 'shi', '', NULL, '二四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6317a13a-865d-4deb-84c4-91924df9c4dc', '二五', '二五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["尊人同席飲，不問莫多言。","縱有文章好，留將餘處宣。"]', '["尊人同席饮，不问莫多言。","縱有文章好，留將餘处宣。"]', '诗', 'shi', '', NULL, '二五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf46c0bf-72a4-484b-8fc5-0a70cd6552be', '二六', '二六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["巡來莫多飲，性少自須監。","勿使聞狼相，（一本作「使勿聞狼狽」。","）交他諸客嫌。"]', '["巡来莫多饮，性少自須監。","勿使闻狼相，（一本作「使勿闻狼狽」。","）交他諸客嫌。"]', '诗', 'shi', '', NULL, '二六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50614bd2-a7ca-4f3c-b421-65ad0af0dc63', '二七', '二七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["坐見人來起，尊親盡遠迎。","無論貧與富，一概惣須平。"]', '["坐见人来起，尊親尽远迎。","無論貧與富，一概惣須平。"]', '诗', 'shi', '', NULL, '二七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cc79b4d-9303-4ea0-a028-2b6030252028', '二八', '二八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["黃金未是寶，學問勝珠珍。","丈夫無伎藝，（「伎藝」，伯三六五六、斯四六六九作「才藝」。","）虛霑一世人。"]', '["黄金未是寶，学问勝珠珍。","丈夫無伎藝，（「伎藝」，伯三六五六、斯四六六九作「才藝」。","）虛霑一世人。"]', '诗', 'shi', '', NULL, '二八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0e1b5a6-e6c2-4554-a336-6b18b9baab73', '二九', '二九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["養子莫徒使，先教懃讀書。","說朝乘駟馬，還得似相如。"]', '["養子莫徒使，先教懃读书。","说朝乘駟马，還得似相如。"]', '诗', 'shi', '', NULL, '二九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccd476fd-193d-4ddf-b089-0aad483a8164', '三十', '三十', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["欲得兒孫孝，無過教及身。","一朝千度打，有罪更須嗔。"]', '["欲得兒孫孝，無過教及身。","一朝千度打，有罪更須嗔。"]', '诗', 'shi', '', NULL, '三十 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee4a0058-8dbe-444e-9e79-3f8750357df8', '三一', '三一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["養兒從少打，（「少」，伯三五五八、伯三七一六、伯三六五六卷作「小」。","）莫道憐不笞。","長大欺父母，後迴（一本作「悔」。","）定無魚。","（一本作「疑」。","）。"]', '["養兒從少打，（「少」，伯三五五八、伯三七一六、伯三六五六卷作「小」。","）莫道怜不笞。","长大欺父母，後迴（一本作「悔」。","）定無鱼。","（一本作「疑」。","）。"]', '诗', 'shi', '', NULL, '三一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca2e1181-24cb-43ce-a61a-993cbc991f5c', '三二', '三二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["男年七十八，（一本作「十七八」。","）莫遣倚街衢。","若不行奸盗，相構即榻（一本作「摺」）蒲。","（「榻蒲」，張錫厚改作「樗蒲」。","）。"]', '["男年七十八，（一本作「十七八」。","）莫遣倚街衢。","若不行奸盗，相構即榻（一本作「摺」）蒲。","（「榻蒲」，張錫厚改作「樗蒲」。","）。"]', '诗', 'shi', '', NULL, '三二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddf504a5-d2bf-4bda-b8c2-f1769dd3828a', '三三', '三三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["有兒欲娶婦，須擇大家兒。","縱使無姿首，終成有禮儀。","（「終成」，伯三六五六、斯四六六九卷作「終身」。","）。"]', '["有兒欲娶婦，須擇大家兒。","縱使無姿首，終成有禮儀。","（「終成」，伯三六五六、斯四六六九卷作「終身」。","）。"]', '诗', 'shi', '', NULL, '三三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51621698-02f0-4aad-bde6-e22b8812a090', '三四', '三四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["有女欲嫁娶，不用絕高門。","但得身超後，（「超」，戴密微校作「紹」。","「後」，項楚校作「俊」。","）銀財惣莫論。"]', '["有女欲嫁娶，不用絕高门。","但得身超後，（「超」，戴密微校作「紹」。","「後」，項楚校作「俊」。","）銀財惣莫論。"]', '诗', 'shi', '', NULL, '三四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fe89a03-4b76-4a45-911b-537ddf8e1474', '三五', '三五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["欲得依（一本作「於」。","）身吉。","無過作是非。","（一本作「莫作非」）。","但知牢閉口，禍去阿你（一本作埿。","）來。","（「阿你來」，斯二七一○、斯三三九三、伯四○九四卷作「阿寧來」，伯三五五八、伯三六五六卷作「自然離」。","）。"]', '["欲得依（一本作「於」。","）身吉。","無過作是非。","（一本作「莫作非」）。","但知牢閉口，禍去阿你（一本作埿。","）来。","（「阿你来」，斯二七一○、斯三三九三、伯四○九四卷作「阿寧来」，伯三五五八、伯三六五六卷作「自然離」。","）。"]', '诗', 'shi', '', NULL, '三五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6046728-b612-4778-925c-95523fc47ae5', '三六', '三六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["飲酒妨生敬，（一本作「計」。","）榻（一本作樗。","）蒲必破家。","但看此等色，不久作窮查。","（本作「茶」。","）。"]', '["饮酒妨生敬，（一本作「計」。","）榻（一本作樗。","）蒲必破家。","但看此等色，不久作窮查。","（本作「茶」。","）。"]', '诗', 'shi', '', NULL, '三六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e3bc977-d2b8-4bc9-b264-e2d63f9e3e47', '三七', '三七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["見惡須藏掩，知賢中華讚陽。","（「唯」，伯三五五八作「爲」。","「陽」，項楚校作「揚」。","）但（一本作「若」。","）能依此語，祕密立身方。"]', '["见惡須藏掩，知賢中华讚陽。","（「唯」，伯三五五八作「爲」。","「陽」，項楚校作「揚」。","）但（一本作「若」。","）能依此語，祕密立身方。"]', '诗', 'shi', '', NULL, '三七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('496fa7b1-6314-48f1-a674-ed48bbee0270', '三八', '三八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["借物莫交索，用了送還他。","損失酬高價，求（一本作我。","）嗔得也磨。","（「也磨」，伯三五五八、斯二七一○、伯四○九四卷作「也摩」，斯四六六九卷作「夜摩」。","）。"]', '["借物莫交索，用了送還他。","損失酬高價，求（一本作我。","）嗔得也磨。","（「也磨」，伯三五五八、斯二七一○、伯四○九四卷作「也摩」，斯四六六九卷作「夜摩」。","）。"]', '诗', 'shi', '', NULL, '三八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf29d3f4-8a04-48fa-8f61-d8b39048e64e', '三九', '三九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["借物索不得，貸錢不肯還，","頻來論即鬥。（「論即鬥」，郭祖怡校作「即鬥論」。）"]', '["借物索不得，貸錢不肯還，","頻来論即鬥。（「論即鬥」，郭祖怡校作「即鬥論」。）"]', '诗', 'shi', '', NULL, '三九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca3c37a7-772c-430c-9c7f-5fd9f951c6f0', '四十', '四十', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["隣並須來往，借取共交通。","急緩相慿仗，人生莫不從。","。"]', '["隣並須来往，借取共交通。","急緩相慿仗，人生莫不從。","。"]', '诗', 'shi', '', NULL, '四十 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c2332aa-beaa-465a-adca-56b0eccfa1c6', '四一', '四一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["長幼同歡（一本作「欽」。","）敬，稱尊莫不尊。","（一本作「遵」。","）（「稱尊」，斯四六六九、伯四○九四卷作「知尊」。","「莫不遵」，斯四六六九作「莫不從」。","）且能行禮樂，鄉里自稱人。"]', '["长幼同歡（一本作「欽」。","）敬，稱尊莫不尊。","（一本作「遵」。","）（「稱尊」，斯四六六九、伯四○九四卷作「知尊」。","「莫不遵」，斯四六六九作「莫不從」。","）且能行禮乐，乡里自稱人。"]', '诗', 'shi', '', NULL, '四一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a629dbb8-1e3a-4b59-916f-338e56dee9f7', '四二', '四二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["停（一本作「庭」。","）客勿叱狗{右上加卄}，對客莫頻眉。","供給千餘自，（「自」，斯三三九三、斯四六六九卷作「日」。","）臨時請不饑。","（「臨時」，伯三六五六卷作「臨歧」，伯三七一六卷作「臨政」。","）。"]', '["停（一本作「庭」。","）客勿叱狗{右上加卄}，对客莫頻眉。","供給千餘自，（「自」，斯三三九三、斯四六六九卷作「日」。","）臨时請不饑。","（「臨时」，伯三六五六卷作「臨歧」，伯三七一六卷作「臨政」。","）。"]', '诗', 'shi', '', NULL, '四二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6ce4853-b423-4b66-9233-c4a054bf8eeb', '四三', '四三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["親客號不疎，（「號不疏」，伯三六五九、斯四六六九卷作「無疏伴」。","）建唤則須唤。","（「建唤則須唤」，伯三七一六卷作「來即閗須唤」，伯三五五八、伯三六五六、斯三三九三作「唤即盡須唤」。","）食食甯且休，只可待他散。"]', '["親客號不疎，（「號不疏」，伯三六五九、斯四六六九卷作「無疏伴」。","）建唤則須唤。","（「建唤則須唤」，伯三七一六卷作「来即閗須唤」，伯三五五八、伯三六五六、斯三三九三作「唤即尽須唤」。","）食食甯且休，只可待他散。"]', '诗', 'shi', '', NULL, '四三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8adb1f9-a24b-4e9d-a042-97644eca6b12', '四四', '四四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["爲客不呼客，（「不」，伯三六五六卷作「莫」。","）去必主人嗔。","欲得能行事，無過莫避人。"]', '["爲客不呼客，（「不」，伯三六五六卷作「莫」。","）去必主人嗔。","欲得能行事，無過莫避人。"]', '诗', 'shi', '', NULL, '四四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d4125a6-37aa-4f87-92f5-cfa925fbc5e8', '四五', '四五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["逢人須歛手，避道莫前盪。","（一本作「湯」。","）忽若相衝着，（「忽若」，斯三三九三卷作「忽然」。","）他{弓|一/虫}（鄭本作强。","）必自傷。"]', '["逢人須歛手，避道莫前盪。","（一本作「湯」。","）忽若相衝着，（「忽若」，斯三三九三卷作「忽然」。","）他{弓|一/虫}（鄭本作强。","）必自傷。"]', '诗', 'shi', '', NULL, '四五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c94a2244-f51b-46c5-88db-cf1b01607dc0', '四六', '四六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["惡口深乖禮，條中却沒文。","若能不駡詈，即便是賢人。","（「即便是」，伯三七一六卷作「即是大」，伯三六五六卷作「却便是」。","）。"]', '["惡口深乖禮，條中却沒文。","若能不駡詈，即便是賢人。","（「即便是」，伯三七一六卷作「即是大」，伯三六五六卷作「却便是」。","）。"]', '诗', 'shi', '', NULL, '四六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05adbd3d-d50e-4cbf-881e-bf958afc87ea', '四七', '四七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["見貴當須避，知强遠利他。","（「利」，伯三五五八、伯三六五六卷作「離」。","）高飛能去綱（按當作「網」。","）豈得值低羅。"]', '["见貴當須避，知强远利他。","（「利」，伯三五五八、伯三六五六卷作「離」。","）高飞能去綱（按當作「網」。","）豈得值低羅。"]', '诗', 'shi', '', NULL, '四七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('820fd09c-d21c-435b-ac7b-e246cae81e70', '四八', '四八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["結交須擇善，非識（一本作諳。","）莫與心。","若知管鮑志，還共不分金。","。"]', '["結交須擇善，非識（一本作諳。","）莫與心。","若知管鲍志，還共不分金。","。"]', '诗', 'shi', '', NULL, '四八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('235ecefe-2e1b-4252-9519-a2ac900fad6f', '四九', '四九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["惡人相遠離，善者近相知。","縱使大無雨，陰雲（一本作「雲陰」。","）自潤衣。"]', '["惡人相远離，善者近相知。","縱使大無雨，陰云（一本作「云陰」。","）自潤衣。"]', '诗', 'shi', '', NULL, '四九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0d92d10-3ccb-4ef8-ac41-f930597c521e', '五十', '五十', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["有德之（一本作「人」。","）心下，無才意即高。","但看行濫物，若箇是堅（鄭本作「堅」。","）牢。"]', '["有德之（一本作「人」。","）心下，無才意即高。","但看行濫物，若箇是堅（鄭本作「堅」。","）牢。"]', '诗', 'shi', '', NULL, '五十 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('935f4051-5a97-4f50-88d9-812bb9c8a9e2', '五一', '五一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["典使頻多擾，（「典使」，伯三七一六、伯三六五六卷作「典吏」。","）從少（一本作饒。","）必莫嗔。","但知多與酒，火{卄又}不欺人。","（「火{卄又}」，伯三七一六卷作「㺳火」，伯四○九四卷作「火芆」，張錫厚意當作「火艾」。","）。"]', '["典使頻多擾，（「典使」，伯三七一六、伯三六五六卷作「典吏」。","）從少（一本作饒。","）必莫嗔。","但知多與酒，火{卄又}不欺人。","（「火{卄又}」，伯三七一六卷作「㺳火」，伯四○九四卷作「火芆」，張錫厚意當作「火艾」。","）。"]', '诗', 'shi', '', NULL, '五一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b9a90be-a15f-4ec2-9b86-36856bf2a78d', '五二', '五二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["惡人相觸悮，（鄭本作「誤」。","）彼（一本作「被」。","）駡必從饒。","喻若薗中匪，（「匪」，伯三五五八、伯三七一六、伯三六五六卷作「韭」。","）由如得雨澆。"]', '["惡人相觸悮，（鄭本作「誤」。","）彼（一本作「被」。","）駡必從饒。","喻若薗中匪，（「匪」，伯三五五八、伯三七一六、伯三六五六卷作「韭」。","）由如得雨澆。"]', '诗', 'shi', '', NULL, '五二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87029902-7ddb-4faa-89bf-216d6c207350', '五三', '五三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["駡妻早是惡，打婦更無知。","索强斯得客，可是丈夫兒。"]', '["駡妻早是惡，打婦更無知。","索强斯得客，可是丈夫兒。"]', '诗', 'shi', '', NULL, '五三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('036881bb-dd18-4d64-a422-f03c9f3bd3d0', '五四', '五四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["有勢不煩意，（「煩意」，伯三七一六卷作「須倚」。","）欺他必自危。","但看木裏火，出則自燒伊。"]', '["有勢不煩意，（「煩意」，伯三七一六卷作「須倚」。","）欺他必自危。","但看木裏火，出則自燒伊。"]', '诗', 'shi', '', NULL, '五四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa9b5bd1-f70d-41da-b13e-96cc4dea229d', '五五', '五五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["貧親須拯濟，富眷不煩饒。","（「煩」，伯三六五六爲作「須」。","）情知蘇蜜味，何用更添高。","（「高」，伯三五五八、伯三七一六、斯二七一○卷作「膏」，伯四○九四卷作「餻」。","）。"]', '["貧親須拯濟，富眷不煩饒。","（「煩」，伯三六五六爲作「須」。","）情知蘇蜜味，何用更添高。","（「高」，伯三五五八、伯三七一六、斯二七一○卷作「膏」，伯四○九四卷作「餻」。","）。"]', '诗', 'shi', '', NULL, '五五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b579402-909a-4aa6-bec6-fac43e2e9143', '五六', '五六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["有錢莫掣⿰忄霍，（「⿰忄霍」，伯三七一六、伯三六五六卷作「攉」。","）不得是（一本作「事」。","）奢華。","鄉裏人儜惡，差科必破家。"]', '["有錢莫掣⿰忄霍，（「⿰忄霍」，伯三七一六、伯三六五六卷作「攉」。","）不得是（一本作「事」。","）奢华。","乡裏人儜惡，差科必破家。"]', '诗', 'shi', '', NULL, '五六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c836e8d1-6fd1-44de-bec4-a32a2c4c238f', '五七', '五七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["他貧不得笑，他弱不得欺。","但看人頭數，即須受□□。","（「但看」二句，伯三六五六卷作「太公未遇日，猶自獨釣魚」。","末句，項錄作「即須受逢迎」。","）。"]', '["他貧不得笑，他弱不得欺。","但看人头數，即須受□□。","（「但看」二句，伯三六五六卷作「太公未遇日，猶自独釣鱼」。","末句，項錄作「即須受逢迎」。","）。"]', '诗', 'shi', '', NULL, '五七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bab04345-db9f-4bdf-b919-1353e2312ecb', '五八', '五八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["逢迎莫不安，□□欠二爪。","（「逢迎」二句，伯三七一六卷作「莫不安瓜肉，魚吞在腹裏」。","）□魚在腸裏，善（鄭本作喜。","）惡有千般。","（「□魚」二句，斯五七九四卷作「善惡數千般，人心難可知」。","）。"]', '["逢迎莫不安，□□欠二爪。","（「逢迎」二句，伯三七一六卷作「莫不安瓜肉，鱼吞在腹裏」。","）□鱼在腸裏，善（鄭本作喜。","）惡有千般。","（「□鱼」二句，斯五七九四卷作「善惡數千般，人心难可知」。","）。"]', '诗', 'shi', '', NULL, '五八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32a47d4f-ec5a-4a2f-94b6-c83d268718ce', '五九', '五九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["在鄉須下意，爲客莫高心。","相見作先拜，膝下沒黃金。","（「沒」，伯三七一六卷作「投」。","）。"]', '["在乡須下意，爲客莫高心。","相见作先拜，膝下沒黄金。","（「沒」，伯三七一六卷作「投」。","）。"]', '诗', 'shi', '', NULL, '五九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f23ef3e5-4d48-495e-a700-6e1199f24996', '六十', '六十', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["貧人莫簡棄，有客最須呼。","但惠封瘡藥，何愁不奉珠。"]', '["貧人莫簡棄，有客最須呼。","但惠封瘡藥，何愁不奉珠。"]', '诗', 'shi', '', NULL, '六十 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c30d8702-405f-4e38-ad56-0ae39d53c6e4', '六一', '六一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["得言請莫說，有語不須傳。","見事如不見，終身無過{彳|天天/心}。"]', '["得言請莫说，有語不須傳。","见事如不见，終身無過{彳|天天/心}。"]', '诗', 'shi', '', NULL, '六一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4a88175-653e-4da7-8810-504245f73419', '六二', '六二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["無心莫充保，（「無心」，伯三六五六卷作「無親」。","）無事莫作媒。","（「無事」，伯三七一六卷作「無女」。","）雖悉鄉人意，（「悉」，伯三五五八、伯三六五六、斯三三九三卷作「失」，斯二七一○卷作「識」。","）終身無害災。"]', '["無心莫充保，（「無心」，伯三六五六卷作「無親」。","）無事莫作媒。","（「無事」，伯三七一六卷作「無女」。","）雖悉乡人意，（「悉」，伯三五五八、伯三六五六、斯三三九三卷作「失」，斯二七一○卷作「識」。","）終身無害災。"]', '诗', 'shi', '', NULL, '六二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65c41b95-5ceb-417b-ad6e-18b8b601311e', '六三', '六三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["雙陸智人戲，園碁出專能。","（「園」，伯三六五六卷作「圍」。","）解時終不惡，（「時」，斯三三九三卷作「事」。","）久後與仙通。"]', '["雙陸智人戲，园碁出專能。","（「园」，伯三六五六卷作「圍」。","）解时終不惡，（「时」，斯三三九三卷作「事」。","）久後與仙通。"]', '诗', 'shi', '', NULL, '六三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f319620-f368-4f9e-a9ad-569a93b22b43', '六四', '六四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["逢争不須看，見打莫前僞。","（「僞」，伯三六五六卷作「爲」。","）{扌|厶/貝}即追友勝，（「{扌|厶/貝}」，伯三七一六、伯三六五六作「捐」。","項楚校作「損」。","）證能惣不知。","（「證能」，伯三五五八、伯三七一六、伯三六五六、斯二七一○卷作「能勝」。","）。"]', '["逢争不須看，见打莫前僞。","（「僞」，伯三六五六卷作「爲」。","）{扌|厶/貝}即追友勝，（「{扌|厶/貝}」，伯三七一六、伯三六五六作「捐」。","項楚校作「損」。","）證能惣不知。","（「證能」，伯三五五八、伯三七一六、伯三六五六、斯二七一○卷作「能勝」。","）。"]', '诗', 'shi', '', NULL, '六四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('270c57f8-3512-4dbb-b5fa-2d0ab86b9289', '六五', '六五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["立身存篤信，（「存」，斯三三九三卷作「在」。","）景行勝將金。","在處人携接，諳知無負心。","。"]', '["立身存篤信，（「存」，斯三三九三卷作「在」。","）景行勝將金。","在处人携接，諳知無負心。","。"]', '诗', 'shi', '', NULL, '六五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8582de38-2ed1-4582-8e88-3b93694746b1', '六六', '六六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["有恩須報上，得濟莫孤恩。","但看千里井，誰爲重來尋。"]', '["有恩須報上，得濟莫孤恩。","但看千里井，誰爲重来尋。"]', '诗', 'shi', '', NULL, '六六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('382812d7-8b9e-4636-8cff-bd020bee427f', '六七', '六七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["知恩須報恩，有恩莫不更。","（「更」，伯三五五八、伯三七一六、伯三六五六卷作「報」。","）[更]在枯井中，（「更」字據伯三五五八卷補。","）誰能重來救。"]', '["知恩須報恩，有恩莫不更。","（「更」，伯三五五八、伯三七一六、伯三六五六卷作「報」。","）[更]在枯井中，（「更」字據伯三五五八卷補。","）誰能重来救。"]', '诗', 'shi', '', NULL, '六七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc580bd8-e14e-4375-9554-f1365a68357b', '六八', '六八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["元得地恩重，（「元」，伯三六五六卷作「先」。","）酬償勿使輕。","一湌何所直，感賀百千傾。","（「百千傾」，斯三三九三卷作「百千金」，伯三七一六卷作「金百傾」，伯三六五六作「百金傾」。","）。"]', '["元得地恩重，（「元」，伯三六五六卷作「先」。","）酬償勿使轻。","一湌何所直，感賀百千傾。","（「百千傾」，斯三三九三卷作「百千金」，伯三七一六卷作「金百傾」，伯三六五六作「百金傾」。","）。"]', '诗', 'shi', '', NULL, '六八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32acdafd-8557-41b2-a060-aceeb93bf5c4', '六九', '六九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["蒙人惠一恩，終身酬不極。","若濟桒（鄭本作桑。","）下飢，扶論可惜力。","（「論」，伯三七一六卷作「輪」。","）。"]', '["蒙人惠一恩，終身酬不極。","若濟桒（鄭本作桑。","）下飢，扶論可惜力。","（「論」，伯三七一六卷作「輪」。","）。"]', '诗', 'shi', '', NULL, '六九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1d392a6-b139-44e3-aa4d-b7c96951e1a2', '七十', '七十', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["得他一束絹，還他一束羅。","計時應大重，（「大」，斯三三九三卷作「有」。","）直爲歲年多。"]', '["得他一束絹，還他一束羅。","計时應大重，（「大」，斯三三九三卷作「有」。","）直爲歲年多。"]', '诗', 'shi', '', NULL, '七十 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('892c720e-c300-42eb-b7c4-6158eb1a0f84', '七一', '七一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["貸人五𥐿米，（「𥐿米」，伯三七一六卷作「斗」。","）送還一碩粟。","（「碩」，伯三五五八、伯四○九四卷作「石」。","）算時應有餘，剩者充臼直。"]', '["貸人五𥐿米，（「𥐿米」，伯三七一六卷作「斗」。","）送還一碩粟。","（「碩」，伯三五五八、伯四○九四卷作「石」。","）算时應有餘，剩者充臼直。"]', '诗', 'shi', '', NULL, '七一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f18e9a4c-edd6-49a1-a31b-19cacdfcdbee', '七二', '七二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["世間難捨割，無過財色深。","丈夫須遠命，割斷闇迷心。"]', '["世间难捨割，無過財色深。","丈夫須远命，割斷闇迷心。"]', '诗', 'shi', '', NULL, '七二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c7f7fe4-a87d-45c9-acb8-a63ed9ecc226', '七三', '七三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["煞生最罪重，（「最罪重」，伯三五五八、伯三六五六卷作「罪最重」，伯三七一六卷作「罪甚重」。","）喫肉亦非輕。","欲得身長命，無過點續朋。","（「朋」，伯三七一六卷作「明」。","）。"]', '["煞生最罪重，（「最罪重」，伯三五五八、伯三六五六卷作「罪最重」，伯三七一六卷作「罪甚重」。","）喫肉亦非轻。","欲得身长命，無過点續朋。","（「朋」，伯三七一六卷作「明」。","）。"]', '诗', 'shi', '', NULL, '七三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c48f3d1c-8ca8-4772-a781-66c54d0bb333', '七四', '七四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["偷盗須無命，（「須」，伯三七一六、伯三六五六卷作「雖」。","）侵欺罪更多。","將他物己用，思量得夜魔。","（「夜魔」，伯三七一六卷作「也磨」，斯二七一○卷作「也磨」。","）。"]', '["偷盗須無命，（「須」，伯三七一六、伯三六五六卷作「雖」。","）侵欺罪更多。","將他物己用，思量得夜魔。","（「夜魔」，伯三七一六卷作「也磨」，斯二七一○卷作「也磨」。","）。"]', '诗', 'shi', '', NULL, '七四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('836a0c7f-7c69-48a9-b45e-d0ce4d9b2006', '七五', '七五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["邪淫及妄語，知非惣勿作。","但之依道行，（「之」，伯三五五八、伯三六五六卷作「知」。","）萬里無迷錯。"]', '["邪淫及妄語，知非惣勿作。","但之依道行，（「之」，伯三五五八、伯三六五六卷作「知」。","）万里無迷錯。"]', '诗', 'shi', '', NULL, '七五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc179525-b637-4f6a-bc25-184d7a7b70bd', '七六', '七六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["喫肉多病報，知者不須湌。","一朝無諫地，（「諫」，伯三六五六卷作「間」。","）受罪始知難。"]', '["喫肉多病報，知者不須湌。","一朝無諫地，（「諫」，伯三六五六卷作「间」。","）受罪始知难。"]', '诗', 'shi', '', NULL, '七六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('387221fb-3a7e-41b9-bc46-739dfdd646bd', '七七', '七七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["飲酒是癡報，如人落糞坑。","情知有不争，（「争」，伯三五五八、伯三七一六卷作「淨」。","）豈合岸頭行。","（「合」，伯三七一六卷作「不」。","）。"]', '["饮酒是癡報，如人落糞坑。","情知有不争，（「争」，伯三五五八、伯三七一六卷作「淨」。","）豈合岸头行。","（「合」，伯三七一六卷作「不」。","）。"]', '诗', 'shi', '', NULL, '七七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb9703f1-247a-4edd-87ac-c3a93460bc9e', '七八', '七八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["造酒罪甚重，酒肉俱不輕。","若人不信語，（「語」，伯三七一六、斯二七一○卷作「義」。","）撿取《日槃經》。","（「日」，伯三七一六、伯三六五六卷作「湼」。","）。"]', '["造酒罪甚重，酒肉俱不轻。","若人不信語，（「語」，伯三七一六、斯二七一○卷作「義」。","）撿取《日槃經》。","（「日」，伯三七一六、伯三六五六卷作「湼」。","）。"]', '诗', 'shi', '', NULL, '七八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba0c061b-ef8b-4300-8c0c-92e6e51e63dc', '七九', '七九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["見埿須避道，莫入污却鞋。","（「污却鞋」，斯二七一○、斯三三九三卷作「汗脚鞋」。","）若知己有罪，莫破戒持齋。"]', '["见埿須避道，莫入污却鞋。","（「污却鞋」，斯二七一○、斯三三九三卷作「汗脚鞋」。","）若知己有罪，莫破戒持斋。"]', '诗', 'shi', '', NULL, '七九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('847fe556-19f6-46d0-982b-511cfecff1e2', '八十', '八十', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["相交莫嫉妬，相勸莫蛆儜。","一日無常去，王前罷手行。","（「罷」，項楚校作「擺」。","）。"]', '["相交莫嫉妬，相勸莫蛆儜。","一日無常去，王前罷手行。","（「罷」，項楚校作「擺」。","）。"]', '诗', 'shi', '', NULL, '八十 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b4846e0-cc7d-41b4-8b5d-3532220299f3', '八一', '八一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["見病須慈遐，（「須慈遐」，伯三六五六卷作「須慈慜」，伯三五五八、斯二七一○、斯三三九三、伯四○九四卷作「慈須愍」。","）諸方速療醫。","（「速療」，伯三五五八卷作「早爲」，伯三六五六卷作「速爲」。","）若能行此行，大是不思議。","。"]', '["见病須慈遐，（「須慈遐」，伯三六五六卷作「須慈慜」，伯三五五八、斯二七一○、斯三三九三、伯四○九四卷作「慈須愍」。","）諸方速療醫。","（「速療」，伯三五五八卷作「早爲」，伯三六五六卷作「速爲」。","）若能行此行，大是不思議。","。"]', '诗', 'shi', '', NULL, '八一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9c0ab11-2782-4f8f-a423-d42532ce2680', '八二', '八二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["經記須平直，心中莫側斜。","些些徵取利，可可苦他家。"]', '["經記須平直，心中莫側斜。","些些徵取利，可可苦他家。"]', '诗', 'shi', '', NULL, '八二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a3e0739-22af-4638-9a28-94fbfec1b0ec', '八三', '八三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["布施生生富，（「富」，斯三三九三卷作「福」。","）慳貪世世貧。","若人苦慳惜，却却受辛懃。","（「却却」，戴密微、項楚校作「劫劫」。","）。"]', '["布施生生富，（「富」，斯三三九三卷作「福」。","）慳貪世世貧。","若人苦慳惜，却却受辛懃。","（「却却」，戴密微、項楚校作「劫劫」。","）。"]', '诗', 'shi', '', NULL, '八三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c543c2b0-b82d-49a0-8061-98cc3a0d710e', '八四', '八四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["忍辱生端正，多嗔作毒虵。","若人不儜惡，必得上三車。"]', '["忍辱生端正，多嗔作毒虵。","若人不儜惡，必得上三车。"]', '诗', 'shi', '', NULL, '八四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56e986d2-9a19-478e-8d29-f280e7cb3f43', '八五', '八五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["尋常懃念善，（「善」，伯三七一六、斯三三九三卷作「佛」。","）晝夜受書經。","（「受」，伯三五五八卷作「愛」。","）心裏無蛆儜，何愁佛不成。"]', '["尋常懃念善，（「善」，伯三七一六、斯三三九三卷作「佛」。","）晝夜受书經。","（「受」，伯三五五八卷作「愛」。","）心裏無蛆儜，何愁佛不成。"]', '诗', 'shi', '', NULL, '八五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05dc0fb3-dcb5-46ce-889a-6094b3a5fd62', '八六', '八六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["六時長禮懺，日暮廣燒香。","十齋莫使闕，有力煞三場。","（「三場」，伯三六五六卷作「三長」。","）。"]', '["六时长禮懺，日暮廣燒香。","十斋莫使闕，有力煞三場。","（「三場」，伯三六五六卷作「三长」。","）。"]', '诗', 'shi', '', NULL, '八六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e81d739-d6bb-45c0-9ec6-958fc3512992', '八七', '八七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["持戒須含忍，長齋不得嗔。","莫隨風火性，參羞悮（鄭本作「誤」。","）煞人。","（「羞」，斯三三九三卷作「差」。","）。"]', '["持戒須含忍，长斋不得嗔。","莫隨风火性，參羞悮（鄭本作「誤」。","）煞人。","（「羞」，斯三三九三卷作「差」。","）。"]', '诗', 'shi', '', NULL, '八七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0a0ae54-fbf7-4405-840e-9e6a0cd1f4d6', '八八', '八八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["逢師須安拜，（「禮拜」，伯三七一六卷作「頂禮」。","）過道向前行。","（「過」，伯三六五六卷作「遇」。","「行」，伯三七一六、伯三六五六卷作「參」。","）莫生多別相，（「多別相」，伯三六五六卷作「離別想」。","項楚校「多」爲「分」。","）見過不知南。","（「知南」，伯三七一六、伯三六五六卷作「和南」。","伯三五五八卷此句作「相見過不知」。","）。"]', '["逢師須安拜，（「禮拜」，伯三七一六卷作「頂禮」。","）過道向前行。","（「過」，伯三六五六卷作「遇」。","「行」，伯三七一六、伯三六五六卷作「參」。","）莫生多別相，（「多別相」，伯三六五六卷作「離別想」。","項楚校「多」爲「分」。","）见過不知南。","（「知南」，伯三七一六、伯三六五六卷作「和南」。","伯三五五八卷此句作「相见過不知」。","）。"]', '诗', 'shi', '', NULL, '八八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('551dce14-03f9-4506-876f-4b6f93afdae9', '八九', '八九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["聞鐘身須側，臥轉莫前眠。","（「前」，伯三六五六卷作「纏」。","）萬一無常去，免至獄門邊。","（「邊」，伯三六五六卷作「前」。","）。"]', '["闻鐘身須側，臥轉莫前眠。","（「前」，伯三六五六卷作「纏」。","）万一無常去，免至獄门邊。","（「邊」，伯三六五六卷作「前」。","）。"]', '诗', 'shi', '', NULL, '八九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd921cba-e509-44f1-952c-e68db03360c2', '九十', '九十', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["師僧來乞食，必莫惜家嘗。","（「嘗」，伯三六五六卷作「常」。","）布施無邊福，來生不少糧。"]', '["師僧来乞食，必莫惜家嘗。","（「嘗」，伯三六五六卷作「常」。","）布施無邊福，来生不少糧。"]', '诗', 'shi', '', NULL, '九十 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25959296-7450-4c6a-a409-9ae8bd905113', '九一', '九一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["家貧從力貸，不得嬾乖傭。","（「傭」，伯四○九四卷作「慵」。","）但知懃作福，衣食自然豐。"]', '["家貧從力貸，不得嬾乖傭。","（「傭」，伯四○九四卷作「慵」。","）但知懃作福，衣食自然豐。"]', '诗', 'shi', '', NULL, '九一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95d86c9a-f2c7-4667-9af2-0189edd9a0b1', '九二', '九二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["惡事惣須棄，（「棄」，伯三六五六、伯四○九四卷作「去」。","）善事莫相違。","知意求妙法，必得見如來。","（按以上爲原卷王梵志詩第一卷。","）。"]', '["惡事惣須棄，（「棄」，伯三六五六、伯四○九四卷作「去」。","）善事莫相違。","知意求妙法，必得见如来。","（按以上爲原卷王梵志诗第一卷。","）。"]', '诗', 'shi', '', NULL, '九二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d744878a-dcd3-4d05-a253-e9fdfb613f28', '九三', '九三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["吾有十畝田，種在南山坡。","青松四五樹，綠豆西三窠。"]', '["吾有十畝田，種在南山坡。","青松四五樹，綠豆西三窠。"]', '诗', 'shi', '', NULL, '九三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a36bda0-f070-4832-9eba-99e742ef27aa', '九四', '九四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["熱即池中浴，涼便岸上歌。","遨遊自取足，誰能奈我何？","（以上二首，應合爲一首。","）。"]', '["熱即池中浴，涼便岸上歌。","遨游自取足，誰能奈我何？","（以上二首，應合爲一首。","）。"]', '诗', 'shi', '', NULL, '九四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cf4678a-6b75-44a7-87e5-156ffc27e576', '九五', '九五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["我見那漢死，肚裏熱如火。","不是惜那漢，恐畏還到我。"]', '["我见那漢死，肚裏熱如火。","不是惜那漢，恐畏還到我。"]', '诗', 'shi', '', NULL, '九五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04ffdb8a-91e0-44dd-ba56-85bb9aef20a9', '九六', '九六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["我有一方便，價值百疋練。","相打長伏弱，（「長伏」，原卷作「長取」，張錫厚改爲「常服」。","）至死不入縣。"]', '["我有一方便，價值百疋練。","相打长伏弱，（「长伏」，原卷作「长取」，張錫厚改爲「常服」。","）至死不入縣。"]', '诗', 'shi', '', NULL, '九六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b61afa8b-10f4-4870-b142-9041ab40ea39', '九七', '九七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["共受虛假身，共稟太虛氣。","死去雖更生，迴來盡不記。","以此好尋思，萬事淡無味。","慰俗不如心，時時一倒醉。","。"]', '["共受虛假身，共稟太虛氣。","死去雖更生，迴来尽不記。","以此好尋思，万事淡無味。","慰俗不如心，时时一倒醉。","。"]', '诗', 'shi', '', NULL, '九七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd0763cd-9c1f-40c4-8ffb-29614d4e32fa', '九八', '九八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["草屋足風塵，牀無破氈臥。","客來且唤入，地鋪稿薦坐。","家裏元無炭，柳麻且吹火。","白酒瓦鉢藏，（「藏」，項楚校作「盛」。","）鐺子兩脚破。","鹿脯三四條，石鹽五六課。","（「課」，項楚、蔣紹愚校作「顆」。","）看客只甯馨，從你痛笑我。","（案以上六首錄自鄭振鐸本拾遺。","爲王梵志詩原卷第三卷。","惜不全。","）。"]', '["草屋足风塵，牀無破氈臥。","客来且唤入，地鋪稿薦坐。","家裏元無炭，柳麻且吹火。","白酒瓦鉢藏，（「藏」，項楚校作「盛」。","）鐺子兩脚破。","鹿脯三四條，石鹽五六課。","（「課」，項楚、蔣紹愚校作「顆」。","）看客只甯馨，從你痛笑我。","（案以上六首錄自鄭振鐸本拾遺。","爲王梵志诗原卷第三卷。","惜不全。","）。"]', '诗', 'shi', '', NULL, '九八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c83c1d06-560e-4719-928a-8ea5d4731f03', '九九', '九九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["欺誑得錢君莫羨，得了却是輸他便。","來生報答甚分明，只是换頭不識面。"]', '["欺誑得錢君莫羨，得了却是輸他便。","来生報答甚分明，只是换头不識面。"]', '诗', 'shi', '', NULL, '九九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc5faf54-35f7-4c2f-844f-2876144058c0', '一○○', '一○○', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["多置莊田廣修宅，四鄰買盡猶嫌窄。"]', '["多置莊田廣修宅，四鄰買尽猶嫌窄。"]', '诗', 'shi', '', NULL, '一○○ 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5456768-67b0-4599-939b-7df6c3bc60f8', '一○一', '一○一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["造作莊田猶未已，堂上哭聲身已死。","哭人盡是分錢人，口哭元來心裏喜。"]', '["造作莊田猶未已，堂上哭声身已死。","哭人尽是分錢人，口哭元来心裏喜。"]', '诗', 'shi', '', NULL, '一○一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d915039c-dff6-4b2c-a6e4-a61c36581646', '一○二', '一○二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["衆生頭兀兀，堂住無明窟。","心裏爲欺謾，口中佯念佛。"]', '["衆生头兀兀，堂住無明窟。","心裏爲欺謾，口中佯念佛。"]', '诗', 'shi', '', NULL, '一○二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88c2de9f-080c-4132-ae80-ae67c4cf2cf8', '一○三', '一○三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["世無百年人，強作千年調。","（《分門古今類事》卷三引《南史》引此詩，「強」作「擬」，「年」作「歲」，「打」作「以」，「限」作「關」。","）打鐵作門限，鬼見拍手笑。"]', '["世無百年人，強作千年調。","（《分门古今類事》卷三引《南史》引此诗，「強」作「擬」，「年」作「歲」，「打」作「以」，「限」作「关」。","）打鐵作门限，鬼见拍手笑。"]', '诗', 'shi', '', NULL, '一○三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0fafdfa-ee43-4aff-95e3-9a272137545e', '一○四', '一○四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["勸君休殺命，背面披生嗔。","喫他他喫汝，循環作主人。"]', '["勸君休殺命，背面披生嗔。","喫他他喫汝，循环作主人。"]', '诗', 'shi', '', NULL, '一○四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3c94dcf-3b9c-418c-a77d-0e875287713e', '一○五', '一○五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["他人騎大馬，我獨跨驢子。","回顧擔柴漢，心下較些子。"]', '["他人騎大马，我独跨驢子。","回顧擔柴漢，心下較些子。"]', '诗', 'shi', '', NULL, '一○五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3e3a577-c1d8-4f77-9b56-67c1196876bd', '一○六', '一○六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["家有梵志詩，生死免入獄。","不論有益事，且得耳根熟。"]', '["家有梵志诗，生死免入獄。","不論有益事，且得耳根熟。"]', '诗', 'shi', '', NULL, '一○六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e75895f4-e2c9-43bd-b4f6-a46834f38975', '一○七', '一○七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["白紙書屏風，客來即與讀。","空飯手捻鹽，亦勝設酒肉。","（案以上八首並載費袞《梁谿漫志》卷十。","今從知不足齋本錄出之。","以上九首除「他人騎大馬」一首外，皆見《雲溪友議》卷下。","「欺誑得錢君莫羨」一首，《全唐詩續補遺》卷二據《鑑誡錄》卷十收錄，今刪去。","異文錄如次：二句「得了却」作「究竟還」，三句作「不信但看槽上驢」，四句「换」作「改」。","）（〖1〗費袞《梁谿漫志》卷十：「山谷以茅季偉事。","親引梵志『飜襪』之句，人喜道之。","予嘗見梵志數頌，詞樸而理到，今於此。","其一曰：『欺誑得錢君莫羨。","……』又曰：……」）。"]', '["白紙书屏风，客来即與读。","空飯手捻鹽，亦勝設酒肉。","（案以上八首並載費袞《梁谿漫志》卷十。","今從知不足斋本錄出之。","以上九首除「他人騎大马」一首外，皆见《云溪友議》卷下。","「欺誑得錢君莫羨」一首，《全唐诗續補遺》卷二據《鑑誡錄》卷十收錄，今刪去。","異文錄如次：二句「得了却」作「究竟還」，三句作「不信但看槽上驢」，四句「换」作「改」。","）（〖1〗費袞《梁谿漫志》卷十：「山谷以茅季偉事。","親引梵志『飜襪』之句，人喜道之。","予嘗见梵志數頌，词樸而理到，今於此。","其一曰：『欺誑得錢君莫羨。","……』又曰：……」）。"]', '诗', 'shi', '', NULL, '一○七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c817eb30-f7a9-488a-868b-4f4e5c54802b', '一○八', '一○八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["梵志翻著襪，人皆道是錯。","乍可剌你眼，不可隱我脚。","（《全唐詩續補遺》卷二據《詩話總龜後集》四三引山谷語收此詩。","文字同，今刪去。","《林間錄》卷下引此詩，「乍可」作「寧可」。","）。"]', '["梵志翻著襪，人皆道是錯。","乍可剌你眼，不可隐我脚。","（《全唐诗續補遺》卷二據《诗話總龟後集》四三引山谷語收此诗。","文字同，今刪去。","《林间錄》卷下引此诗，「乍可」作「寧可」。","）。"]', '诗', 'shi', '', NULL, '一○八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d710a6df-6ef0-40d9-8280-875f4ce41edc', '一○九', '一○九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["城外土饅頭，餡草在城裏。","一人喫一個，莫嫌沒滋味。","（此詩又見《冷齋夜話》卷十、《苕溪漁隱叢話前集》卷五六、《詩話總龜》卷三九引《東坡詩話》、《雲臥紀譚》等書。","）（以上二首黃庭堅引梵志詩。","）（〖1〗案以上諸詩，鄭振鐸輯本並收之。","）。"]', '["城外土饅头，餡草在城裏。","一人喫一個，莫嫌沒滋味。","（此诗又见《冷斋夜話》卷十、《苕溪漁隐叢話前集》卷五六、《诗話總龟》卷三九引《东坡诗話》、《云臥紀譚》等书。","）（以上二首黄庭堅引梵志诗。","）（〖1〗案以上諸诗，鄭振鐸輯本並收之。","）。"]', '诗', 'shi', '', NULL, '一○九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2ee8c1d-b8b9-4855-9890-9cca7b6d3f1d', '道情詩', '道情诗', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["我昔未生時，冥冥無所知。","天公強生我，生我復何爲？","無衣使我寒，無食使我飢。","還你天公我，還我未生時。","（此首唐釋皎然《詩式》卷一《跌宕格二品·駭俗》中引之，鄭輯本未收。","）（〖1〗《全唐詩編劇補遺》卷二據《雲溪友議》收此詩，今刪去。","異文錄如次：首句作「天公未生我」，三句「强」作「忽」，五句「使」作「遣」，六句「使」作「遣」，六句「使」作「令」，七句「你」作「爾」。","）。"]', '["我昔未生时，冥冥無所知。","天公強生我，生我复何爲？","無衣使我寒，無食使我飢。","還你天公我，還我未生时。","（此首唐釋皎然《诗式》卷一《跌宕格二品·駭俗》中引之，鄭輯本未收。","）（〖1〗《全唐诗編劇補遺》卷二據《云溪友議》收此诗，今刪去。","異文錄如次：首句作「天公未生我」，三句「强」作「忽」，五句「使」作「遣」，六句「使」作「遣」，六句「使」作「令」，七句「你」作「爾」。","）。"]', '诗', 'shi', '', NULL, '道情詩 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23a08063-1768-4410-8b46-8156e9826964', '倖門（題擬）', '倖门（題擬）', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["倖門如鼠穴，也須留一箇。","若還都塞了，好處却穿破。","（此首見陳巖肖《庚溪詩話》卷下。","鄭輯本亦未收。","）（〖1〗陳巖肖《庚溪詩話》卷下：「王梵志詩曰：『倖門如鼠穴，……好處却穿破。","』此言近乎曹相國所謂以獄市爲寄也。","」〖2〗《太平廣記》卷八十二引《史遺》：「王梵志，衛州黎陽人也。","黎陽城東十五里，有王德祖，當隋文帝時，家有林檎樹，生癭大如斗。","經三年，朽爛，德祖見之，乃剖其皮，遂見一孩兒抱胎而□。","德祖收養之。","至七歲，能語，曰：『誰人育我？復何姓名？』德祖具以實語之，因名林木梵天，〖「因名林木梵天」，明鈔本《太平廣記》作「因曰：『雙木曰梵，名曰梵天。","』」語意稍長。","〗後改曰梵志。","曰：『王家育我，可姓王也。","』梵志乃作詩示人，甚有義旨。","」〖3〗楊慎《升庵詩話》卷四引唐釋道世《法苑珠林》：「梵志出家，白首而歸，鄰人見之，曰：『昔人尚存乎？","』梵志曰：『吾猶昔人，非昔人也。","』」按丁福保《歷代詩話續編》亦載之，見第十三冊「吾猶昔人」條。","）。"]', '["倖门如鼠穴，也須留一箇。","若還都塞了，好处却穿破。","（此首见陳巖肖《庚溪诗話》卷下。","鄭輯本亦未收。","）（〖1〗陳巖肖《庚溪诗話》卷下：「王梵志诗曰：『倖门如鼠穴，……好处却穿破。","』此言近乎曹相国所謂以獄市爲寄也。","」〖2〗《太平廣記》卷八十二引《史遺》：「王梵志，衛州黎陽人也。","黎陽城东十五里，有王德祖，當隋文帝时，家有林檎樹，生癭大如斗。","經三年，朽爛，德祖见之，乃剖其皮，遂见一孩兒抱胎而□。","德祖收養之。","至七歲，能語，曰：『誰人育我？复何姓名？』德祖具以實語之，因名林木梵天，〖「因名林木梵天」，明鈔本《太平廣記》作「因曰：『雙木曰梵，名曰梵天。","』」語意稍长。","〗後改曰梵志。","曰：『王家育我，可姓王也。","』梵志乃作诗示人，甚有義旨。","」〖3〗楊慎《升庵诗話》卷四引唐釋道世《法苑珠林》：「梵志出家，白首而归，鄰人见之，曰：『昔人尚存乎？","』梵志曰：『吾猶昔人，非昔人也。","』」按丁福保《歷代诗話續編》亦載之，见第十三冊「吾猶昔人」條。","）。"]', '诗', 'shi', '', NULL, '倖門（題擬） 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e96ca118-ac7e-4998-8a4f-675549667ec1', '早春泛鏡湖', '早春泛镜湖', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["漾舟喜湖廣，湖廣趣非一。","愉目野載蕪，清心山更出。","孤烟晝藏火，薄暮朝開日。","但愛春光遲，不覺舟行疾。","歸雁空間盡，流鶯花際失。","遠情自此多，景霽風物和。","蘆人收晚釣，棹女弄春歌。","野外寒事少，湖間芳意多。","雜花因爛熳，暄柳日逶迤。","爲客頓逢此，於思柰若何？","（此詩見《永樂大典》卷二二六七「六模」「湖」字「鏡湖」條。","〖二函二十冊〗）。"]', '["漾舟喜湖廣，湖廣趣非一。","愉目野載蕪，清心山更出。","孤烟晝藏火，薄暮朝开日。","但愛春光遲，不覺舟行疾。","归雁空间尽，流鶯花際失。","远情自此多，景霽风物和。","蘆人收晚釣，棹女弄春歌。","野外寒事少，湖间芳意多。","杂花因爛熳，暄柳日逶迤。","爲客頓逢此，於思柰若何？","（此诗见《永乐大典》卷二二六七「六模」「湖」字「镜湖」條。","〖二函二十冊〗）。"]', '诗', 'shi', '', NULL, '早春泛鏡湖 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f0b5f47-9d4a-459c-8b03-ba673e8abe2d', '題謝處士山齋', '題謝处士山斋', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["那有唐年客，青山獨閉門。","雲泉一少事，琴史皆忘喧。","在濬人猶縶，遷喬友未言。","不知幽谷草，何意老王孫？","（此詩見《永樂大典》卷二五三九「七皆」「齋」字「山齋」條。","〖三函三十冊〗）。"]', '["那有唐年客，青山独閉门。","云泉一少事，琴史皆忘喧。","在濬人猶縶，遷喬友未言。","不知幽谷草，何意老王孫？","（此诗见《永乐大典》卷二五三九「七皆」「斋」字「山斋」條。","〖三函三十冊〗）。"]', '诗', 'shi', '', NULL, '題謝處士山齋 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7975ccaa-8e57-4376-891d-d5c7ae7259e1', '過中書元舍人山齋', '過中书元舍人山斋', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["元侯松子賓，寓此掖垣職。","移疾多暇豫，孤齋恣閑息。","修逕接大野，重巒跨南北。","具物芬榮時，登攀各可極。","林間百鳥變，郊外千花織。","秦嶺似雲橫，周原如黛飾。","洛中昔遊衍，常聞故園憶。","清言盡場圃，嘉話數耘植。","夢想恒載馳，松篁若舊識。","酒情忽無限，琴意忻有得。","更閱青谿詩，逾勵丹霞食。","貴者日已遠，幸君惠容色。","朅來休潁陽，任予孤且直。","（同前見《大典》卷二五三九。","）。"]', '["元侯松子賓，寓此掖垣職。","移疾多暇豫，孤斋恣闲息。","修逕接大野，重巒跨南北。","具物芬榮时，登攀各可極。","林间百鸟变，郊外千花织。","秦嶺似云橫，周原如黛飾。","洛中昔游衍，常闻故园憶。","清言尽場圃，嘉話數耘植。","梦想恒載驰，松篁若旧識。","酒情忽無限，琴意忻有得。","更閱青谿诗，逾勵丹霞食。","貴者日已远，幸君惠容色。","朅来休潁陽，任予孤且直。","（同前见《大典》卷二五三九。","）。"]', '诗', 'shi', '', NULL, '過中書元舍人山齋 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c849e12-8ed1-4b84-a5cc-96b050853f8e', '嵩南山九里舊鵲村作', '嵩南山九里旧鵲村作', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["弊廬接箕潁，北望嵩山隅。","兹嶺雄且秀，綵翠橫天衢。","家世事靈嶽，嵒棲安敢渝。","從俗因迹化，歸静知心愚。","上違先人訓，下憐菲薄軀。","自問何功業，謬與賢俊俱。","執覊翊龍羽，秉筆遊鴻都。","尸禄負諸己，日使田園蕪。","常恐白雲意，溘盡黃埃塗。","妙年負恩德，欲去何踟蹰？","明主本尚道，黃屋均蓬壺。","飲惠可冥分，歸事燒金鑪。","（此詩見《永樂大典》卷三五八○「九真」「村」字「舊鵲村」條。","〖五函五十冊〗）。"]', '["弊廬接箕潁，北望嵩山隅。","兹嶺雄且秀，綵翠橫天衢。","家世事靈嶽，嵒棲安敢渝。","從俗因迹化，归静知心愚。","上違先人訓，下怜菲薄軀。","自问何功業，謬與賢俊俱。","執覊翊龙羽，秉笔游鴻都。","尸禄負諸己，日使田园蕪。","常恐白云意，溘尽黄埃塗。","妙年負恩德，欲去何踟蹰？","明主本尚道，黄屋均蓬壺。","饮惠可冥分，归事燒金鑪。","（此诗见《永乐大典》卷三五八○「九真」「村」字「旧鵲村」條。","〖五函五十冊〗）。"]', '诗', 'shi', '', NULL, '嵩南山九里舊鵲村作 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0536ef8e-a65a-486f-a71a-46c8a919ece9', '敬和吏部韋郎中庭前朱槿之作', '敬和吏部韋郎中庭前朱槿之作', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["日給當輪滿，星郎伏奏旋。","猶紆起草思，更有落花篇。","氣與香衣雜，光侵畫壁然。","徒聞賦君子，無以和神仙。","（此詩見《分門纂類唐歌詩》殘本第六冊《草木蟲魚類》卷五。","）。"]', '["日給當輪满，星郎伏奏旋。","猶紆起草思，更有落花篇。","氣與香衣杂，光侵畫壁然。","徒闻賦君子，無以和神仙。","（此诗见《分门纂類唐歌诗》殘本第六冊《草木蟲鱼類》卷五。","）。"]', '诗', 'shi', '', NULL, '敬和吏部韋郎中庭前朱槿之作 宋之問 shi');
